def _nc_items(s):
    out = {}
    for p in s.split(","):
        p = p.strip()
        m = re.match(r"(\w+) (\d+)$", p)
        if m:
            out[m.group(1)] = int(m.group(2))
    return out


def nceny_main(logp):
    """nceny (noc 15/16.10, decyzje Jeffa 15.10 TAK; galaz w-toku/noc-ceny): (A) kusze wedlug luku tej samej sily - Armoury/src/XbowPrice.cs.
    Wejscie: log Armoury (czytany strumieniowo). Log bez paczki: INFO, bez wyjatku."""
    rep = Report()
    if not logp or not os.path.isfile(logp):
        rep.add("NC-0: log Armoury", f"brak pliku {logp}", "podaj <Armoury-*.log>", None)
        rep.show()
        return 0
    xs, xd, ws, errs = [], {}, {}, {}
    fs, fd, sd, td, tow, own, lordpie, folk, gwf = [], {}, {}, {}, {}, {}, {}, {}, {}
    cs, cd = [], {}
    b2start, b3start = [], []
    with open(logp, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\n"))
            s = m.group(2) if m else ln.rstrip("\n")
            if s.startswith(NC_XS):
                xs.append(s)
            elif s.startswith(NC_XD):
                d = num(r"dzien (\d+)", s)
                if d is not None:
                    xd[d] = s
            elif s.startswith("Warsztaty: dzien "):
                mm = NC_WS.match(s)
                if mm:
                    ws[int(mm.group(1))] = _nc_items(mm.group(2))
            elif s.startswith(NC_FS):
                fs.append(s)
            elif s.startswith(NC_FD):
                d = num(r"dzien (\d+)", s)
                if d is not None:
                    fd[d] = s
            elif s.startswith("Zamienniki jedzenia (B2): start sesji | "):
                b2start.append(s)
            elif s.startswith("Lordowie a drogie jedzenie (B3): start sesji | "):
                b3start.append(s)
            elif s.startswith(NC_SD):
                d = num(r"dzien (\d+)", s)
                if d is not None:
                    sd[d] = s
            elif s.startswith(NC_TD):
                d = num(r"dzien (\d+)", s)
                if d is not None:
                    td[d] = s
            elif s.startswith("Towary: dzien "):
                mm = NC_TOW.match(s)
                if mm:
                    d, g = int(mm.group(1)), mm.group(2)
                    w = num(r"(?:^|; )wsie (\d+)", mm.group(4), default=0)
                    tow.setdefault(g, {})[d] = (int(mm.group(3)), w)
                    if g == "grain":
                        gwf[d] = num(r"(?:^|; )wsie \d+ \(wheat_farm (\d+)", mm.group(4))
                    mo = NC_TOW_OWN.search(s)
                    if mo:
                        own.setdefault(g, {})[d] = num(r"miasta (\d+)", mo.group(1), default=0)
                    if g == "pie":
                        lp = NC_TOW_LORD.search(s)
                        lordpie[d] = int(lp.group(1)) if lp else 0
            elif s.startswith(NC_CS):
                cs.append(s)
            elif s.startswith(NC_CD):
                d = num(r"dzien (\d+)", s)
                if d is not None:
                    cd[d] = s
            elif s.startswith("Kiesa ludu: dzien "):
                mm = NC_FOLK.match(s)
                if mm:
                    folk[int(mm.group(1))] = int(mm.group(2))
            elif s.startswith("ERROR in "):
                for k in ("XbowPrice", "VillageFruit", "FoodSubstitute", "FoodThrift", "CompanionPay"):
                    if s.startswith("ERROR in " + k):
                        errs[k] = errs.get(k, 0) + 1
    print(f"plik: {logp} | A: linii startu {len(xs)}, linii doby {len(xd)}, linii Warsztaty {len(ws)} | B: start owocow {len(fs)}, doby owocow {len(fd)}, zamiennikow {len(sd)}, B3 {len(td)}")
    # ---------------- A: kusze wedlug luku
    if not xs and not xd:
        rep.add("NC-0: kusze wedlug luku - linia startu", "brak linii", "INFO (wersja sprzed paczki nceny)", None)
    else:
        st = xs[-1] if xs else ""
        on = bool(re.search(r"\| x[\d.]+ ceny luku tej samej sily", st)) and "klucz XbowLikeBow TAK" in st
        rep.add("NC-0: kusze wedlug luku - linia startu, przeliczenie czynne", st[len(NC_XS):][:200] if st else "brak linii startu (sa linie doby)",
                "linia jest, klucz XbowLikeBow TAK, przeliczenie czynne (x... ceny luku)", bool(st) and on)
        if on:
            nb = num(NC_X_BOWS.pattern, st)
            rep.add("NC-1: lukow w tabeli", f"{nb}", "16-22 (19 +-3)", nb is not None and 16 <= nb <= 22)
            md = NC_X_DONE.search(st)
            done = int(md.group(1)) if md else 0
            rep.add("NC-2: kusz przeliczonych", f"{done} z {md.group(2) if md else '?'} na handel", ">= 8", done >= 8)
            rows = {r.group(1): r for r in NC_X_ROW.finditer(st)}
            bad = [f"{k} x{r.group(11)}" for k, r in rows.items() if not (1.70 <= float(r.group(11)) <= 1.80)]
            rep.add("NC-3: cena przeliczonej kuszy / cena luku tej sily", f"wierszy {len(rows)}, poza widelkami {len(bad)}" + (f" ({', '.join(bad[:5])})" if bad else ""),
                    "kazda 1.70-1.80", len(rows) > 0 and not bad)
            f = rows.get("crossbow_f"); a = rows.get("crossbow_a")
            fv = int(f.group(3)) if f else None; av = int(a.group(3)) if a else None
            rep.add("NC-4: crossbow_f / crossbow_a po zmianie", f"crossbow_f {f.group(2) + '->' + f.group(3) if f else 'brak'}, crossbow_a {a.group(2) + '->' + a.group(3) if a else 'brak'}",
                    "crossbow_f 100-130 d, crossbow_a 18-28 d", fv is not None and av is not None and 100 <= fv <= 130 and 18 <= av <= 28)
            mt = NC_X_TOP.search(st)
            rr = float(mt.group(4)) if mt and mt.group(4) != "-" else None
            rep.add("NC-5: najmocniejsza kusza / najmocniejszy luk", f"{mt.group(1)} {mt.group(2)} d / {mt.group(3)} d = x{mt.group(4)}" if mt else "brak",
                    "x2.0-3.0", rr is not None and 2.0 <= rr <= 3.0)
            rep_ids = [k for k in rows if "repeating" in k]
            ms = NC_X_SAME.search(st)
            rep.add("NC-6: kusze powtarzalne bez zmian", f"przeliczone powtarzalne {len(rep_ids)}; bez zmian {ms.group(1) if ms else '?'} [{(ms.group(2) or '')[:120] if ms else ''}]",
                    "0 przeliczonych powtarzalnych", len(rep_ids) == 0)
            stum = num(NC_STUM.pattern, st, default=0)
            rep.add("NC-7: potkniecia (linia startu) / ERROR in XbowPrice", f"potkniecia {stum}, ERROR {errs.get('XbowPrice', 0)}", "0 / 0", stum == 0 and errs.get("XbowPrice", 0) == 0)
            rep.add("NC-8: kuznia gracza i zakupy wedlug sily", "kuznia: " + ("tak" if "tieru rownowaznego tak" in st else "nie") + ", zakupy: " + ("tak" if "wedlug sily tak" in st else "nie"),
                    "obie tak", "tieru rownowaznego tak" in st and "wedlug sily tak" in st)
        # A dzien
        ai = 0; lbs = 0.0; men = 0; dstum = 0
        for d, s in xd.items():
            mm = NC_XD_RE.search(s)
            if mm:
                n = int(mm.group(1)); ai += n; men += int(mm.group(3))
                if n > 0 and mm.group(2) != "-":
                    lbs += n * int(mm.group(2))
            dstum += num(NC_STUM.pattern, s, default=0)
        avg = lbs / ai if ai else 0
        rep.add("NC-9: kusze kupione przez AI (suma dob) i srednie funty", f"dob {len(xd)}, AI {ai} szt. (srednio {avg:.0f} funtow), ludzie gracza {men}, potkniecia doby {dstum}",
                "AI > 0, srednio >= 160 funtow (bez wyboru wedlug sily ok. 90), potkniecia 0", (ai > 0 and avg >= 160 and dstum == 0) if len(xd) >= 5 else None)
        if ws:
            zero = [d for d, v in sorted(ws.items()) if v.get("Crossbow", 0) <= 0]
            xb = sum(v.get("Crossbow", 0) for v in ws.values()) / len(ws)
            bw = sum(v.get("Bow", 0) for v in ws.values()) / len(ws)
            rep.add("NC-10: warsztaty - kusze kazdej doby", f"dob {len(ws)}, bez kusz {len(zero)}" + (f" (np. {zero[:5]})" if zero else "") + f"; srednio kusz {xb:.0f}/d, lukow {bw:.0f}/d (przed: kusze 32-70, luki ok. 437)",
                    "0 dob bez kusz (luki - INFO, nie mniej niz 80% sprzed zmiany)", len(zero) == 0)
    # ---------------- B: placek i marchew
    if not fs and not fd and not sd and not td:
        rep.add("NC-11: owoce wsi / zamienniki / B3 - linie", "brak linii", "INFO (wersja sprzed czesci B)", None)
    else:
        st = fs[-1] if fs else ""
        mf = NC_FS_RE.search(st)
        on = "| CZYNNE |" in st
        if mf:
            wf, ol, lj, tr = (int(mf.group(i)) for i in range(1, 5))
            rep.add("NC-11: owoce wsi - linia startu (wsie wedlug typu)", f"wheat_farm {wf}, olive_trees {ol}, lumberjack {lj} + trapper {tr}; " + st[len(NC_FS):][:120],
                    "CZYNNE, wheat_farm >= 100, olive_trees >= 10, drwale + trzebiciele >= 40, potkniecia 0",
                    on and wf >= 100 and ol >= 10 and lj + tr >= 40 and num(NC_STUM.pattern, st, default=1) == 0)
        else:
            rep.add("NC-11: owoce wsi - linia startu", st[len(NC_FS):][:160] if st else "brak linii startu", "CZYNNE z liczbami wsi", False if st and "WYLACZONE" not in st else None)
        mins = {"carrot": 150, "apple": 150, "orange": 25, "honey": 15}
        res, oks = [], []
        for g, lim in mins.items():
            dd = tow.get(g, {})
            days = sorted(dd)[1:] if len(dd) > 1 else sorted(dd)
            vals = sorted(dd[d][1] for d in days)
            med = vals[len(vals) // 2] if vals else None
            res.append(f"{g} {med if med is not None else '-'} (prog {lim})")
            oks.append(med is not None and med >= lim)
        rep.add("NC-12: plon wsi (Towary: produkcja ... wsie W, mediana dob bez pierwszej)", ", ".join(res), "carrot >= 150, apple >= 150, orange >= 25, honey >= 15",
                all(oks) if any(tow.get(g) for g in mins) else None)
        gv = [(d, v) for d, v in sorted(gwf.items()) if v is not None]
        if gv:
            rep.add("NC-12b: zboze farm zboza (Towary: grain ... wsie (wheat_farm N); INFO - owoce to plon dodatkowy, zboze bez zmian)",
                    f"pierwsza doba {gv[0][0]}: {gv[0][1]}, ostatnia {gv[-1][0]}: {gv[-1][1]} (log Jeffa 108945 bez paczki: 6959)", "INFO (bez spadku z powodu owocow; zima tnie)", None)
        oc = own.get("carrot", {}); oa = own.get("apple", {})
        if oc and oa:
            dl = max(oc); span = dl - min(oc)
            rep.add("NC-13: marchew i jablka na targach miast (posiadacze, ostatnia doba)", f"doba {dl} (po {span} dobach): carrot w miastach {oc[dl]}, apple {oa.get(dl, 0)}",
                    "> 0 obu po >= 7 dobach", (oc[dl] > 0 and oa.get(dl, 0) > 0) if span >= 7 else None)
        b2s = [s for s in b2start]
        rep.add("NC-23: zamienniki - linia startu sesji", b2s[-1][len("Zamienniki jedzenia (B2): start sesji | "):][:200] if b2s else "brak linii",
                "klucz FoodSubstituteWhenShort TAK, latka wpiety, zrodel >= 10, potkniecia 0",
                (("klucz FoodSubstituteWhenShort TAK" in b2s[-1] and "latka wpiety" in b2s[-1] and num(r"zrodel (\d+)", b2s[-1], default=0) >= 10 and num(NC_STUM.pattern, b2s[-1], default=1) == 0)) if b2s else None)
        b3s = [s for s in b3start]
        rep.add("NC-24: syty lord - linia startu sesji", b3s[-1][len("Lordowie a drogie jedzenie (B3): start sesji | "):][:200] if b3s else "brak linii",
                "klucz AiFoodSkipsDear TAK, modeli zalatanych >= 1, potkniecia 0",
                ("klucz AiFoodSkipsDear TAK" in b3s[-1] and num(r"zalatanych (\d+)", b3s[-1], default=0) >= 1 and num(NC_STUM.pattern, b3s[-1], default=1) == 0) if b3s else None)
        fst = max([num(r"potkniecia sesji (\d+)", s, default=0) for s in fd.values()] or [0])
        rep.add("NC-14: owoce wsi - potkniecia / ERROR in VillageFruit", f"potkniecia sesji (najwiecej) {fst}, ERROR {errs.get('VillageFruit', 0)}", "0 / 0",
                fst == 0 and errs.get("VillageFruit", 0) == 0)
        # B2
        if sd:
            ds = sorted(sd)
            zero, stum, mv = [], 0, []
            for d in ds[1:]:
                mm = NC_SD_MOVE.search(sd[d]); p = int(mm.group(1)) if mm else 0
                mv.append(p)
                if p <= 0:
                    zero.append(d)
            for s in sd.values():
                mm = NC_STUM2.search(s)
                if mm:
                    stum += int(mm.group(1))
            on2 = "| CZYNNE (" in sd[ds[-1]]
            sh = NC_SD_SHORT.search(sd[ds[-1]])
            rep.add("NC-15: zamienniki - przesuniety budzet kazdej doby, potkniecia / ERROR", f"dob {len(ds)}, bez przesuniecia {len(zero)}" + (f" (np. {zero[:5]})" if zero else "")
                    + f", srednio {sum(mv) / len(mv) if mv else 0:.0f}/d; miast z brakiem (ostatnia doba) {sh.group(1) if sh else '?'}; potkniecia {stum}, ERROR {errs.get('FoodSubstitute', 0)}",
                    "CZYNNE, P > 0 kazdej doby (poza pierwsza), 0 / 0", on2 and not zero and stum == 0 and errs.get("FoodSubstitute", 0) == 0 and len(ds) > 1)
            chk = [NC_SD_CHK.search(sd[d]) for d in ds]
            chk = [c for c in chk if c]
            if chk:
                n_chk = sum(int(c.group(1)) for c in chk); n_over = sum(int(c.group(2)) for c in chk); top = max(float(c.group(3)) for c in chk)
                o_cut = sum(int(c.group(4)) for c in chk); o_all = sum(int(c.group(5)) for c in chk)
                rep.add("NC-15b: zamienniki - kontrola limitu (wszystkie zrodla osady razem <= 0.5 nadwyzki polki zamiennika, po ofercie ludu)",
                        f"dob {len(chk)}: zamiennikow z dopisem {n_chk}, przekroczen {n_over}, najwiecej {top:.1f}% nadwyzki; oferta ludu zmniejszyla nadwyzke {o_cut}, zjadla {o_all}",
                        "przekroczen 0, najwiecej <= 50.5%", n_over == 0 and top <= 50.5)
            else:
                rep.add("NC-15b: zamienniki - kontrola limitu", "brak liczb kontroli w liniach doby", "INFO (wersja sprzed poprawki 16.10)", None)
            mi = NC_SD_IDX.search(sd[ds[-1]])
            idx = {}
            if mi:
                for part in mi.group(1).split(", "):
                    pp = part.rsplit(" ", 1)
                    if len(pp) == 2:
                        try:
                            idx[pp[0]] = float(pp[1])
                        except ValueError:
                            pass
            span = ds[-1] - ds[0]
            a = idx.get("apple")
            rep.add("NC-16a: indeks owocow (apple, mediana miast, ostatnia doba)", f"{a} po {span} dobach (przed: 9.95)", "<= 6.0 (bieg >= 10 dob)",
                    (a is not None and a <= 6.0) if span >= 10 else None)
            sub = {g: idx.get(g) for g in ("bread", "meat", "cheese")}
            rep.add("NC-16b: indeks zamiennikow (bread, meat, cheese - mediana miast)", ", ".join(f"{g} {v}" for g, v in sub.items()), "kazdy <= 3.0",
                    all(v is not None and v <= 3.0 for v in sub.values()) if span >= 10 else None)
            rep.add("NC-16c: indeks placka i miodu (INFO)", f"pie {idx.get('pie')} (przed 2.15), honey {idx.get('honey')}, Eggs {idx.get('Eggs')}, grain {idx.get('grain')}, fish {idx.get('fish')}",
                    "INFO (pie <= 2.2)", None)
        else:
            rep.add("NC-15: zamienniki - linie doby", "brak linii", "INFO (wersja sprzed B2)", None)
        # B3
        if td:
            D = T = L = DL = TL = 0; stum = 0
            for s in td.values():
                mm = NC_TD_RE.search(s)
                if mm:
                    D += int(mm.group(1)); DL += int(mm.group(2)); T += int(mm.group(3)); TL += int(mm.group(4)); L += int(mm.group(5))
                m2 = NC_STUM2.search(s)
                if m2:
                    stum += int(m2.group(1))
            rep.add("NC-17: syty lord nie przeplaca - zamienione na tansze, potkniecia / ERROR", f"dob {len(td)}: drogich {D} (lordow {DL}), zamienionych {T} (lordow {TL}), zostawionych {L}; potkniecia {stum}, ERROR {errs.get('FoodThrift', 0)}",
                    "T > 0, 0 / 0", T > 0 and stum == 0 and errs.get("FoodThrift", 0) == 0)
        if lordpie:
            vals = [lordpie[d] for d in sorted(lordpie)[1:]] or list(lordpie.values())
            rep.add("NC-18: placek - lordowie kupili na dobe (INFO)", f"srednio {sum(vals) / len(vals):.0f} (przed 235)", "INFO (< 235)", None)
        if folk:
            vals = [folk[d] for d in sorted(folk)[1:]] or list(folk.values())
            rep.add("NC-19: kiesa ludu - zaplacone przez lud miast na dobe (INFO)", f"srednio {sum(vals) / len(vals):.0f}", "INFO (+5..+20% wobec biegu bez B2)", None)
    # ---------------- C: towarzysze
    if not cs and not cd:
        rep.add("NC-20: towarzysze - linia startu", "brak linii", "INFO (wersja sprzed czesci C)", None)
    else:
        st = cs[-1] if cs else ""
        hooked = "czynnik wpiety" in st and "cena wpieta" in st
        agree = "- ZGODNE" in st
        stum = num(NC_STUM.pattern, st, default=1) if st else 1
        sc = re.search(r"samosprawdzenie \((czynnik: \w+, zold: [\w-]+, cena: [\w-]+)\)", st)
        rep.add("NC-20: towarzysze - start sesji (latki i samosprawdzenie)", ((sc.group(1) + " | ") if sc else "") + (st[len(NC_CS):][:260] if st else "brak linii startu (sa linie doby)"),
                "czynnik i cena wpiete, samosprawdzenie ZGODNE, potkniecia 0", bool(st) and hooked and agree and stum == 0)
        hs, ours, rs, ws, lv, mss, dst = [], [], [], [], [], [], 0
        for d, s in sorted(cd.items()):
            mm = NC_CD_RE.search(s)
            if mm:
                hs.append(int(mm.group(1)))
                if mm.group(5) != "-":
                    ours.append(int(mm.group(5)))
                if mm.group(9) != "-":
                    rs.append(float(mm.group(9)))
                if mm.group(8) != "-":
                    ws.append(float(mm.group(8)))
            l2 = NC_CD_LV.search(s)
            if l2 and l2.group(1) != "-":
                lv.append(int(l2.group(1)))
            m3 = NC_CD_MS.search(s)
            if m3:
                mss.append(float(m3.group(1)))
            m4 = NC_STUM2.search(s)
            if m4:
                dst += int(m4.group(1))
        med = lambda l: sorted(l)[len(l) // 2] if l else None
        H, B, R = med(hs), med(ours), med(rs)
        # przeglad calosci 20.10: przy CompanionWageByLevel (dopisek CW w linii doby) cena = 20 dni zoldu z tabeli wedlug poziomu (poz. 19 = 23 d), nie zoldu BK
        # (ok. 99 d) - nasza/BK spada do ok. 0.05; prog dolny wtedy 0.02
        cw = any("zold wedlug poziomu tak" in s for s in cd.values())
        rlo = 0.02 if cw else 0.1
        rep.add("NC-21: towarzysze - linia doby (wedrowcy, nasza cena, nasza/BK)", f"dob {len(cd)}: wedrowcy mediana {H}, nasza cena mediana {B}, nasza/BK mediana {R}{' (zold wedlug poziomu CW)' if cw else ''}; potkniecia {dst}, ERROR {errs.get('CompanionPay', 0)}",
                f"wedrowcy >= 10, nasza > 0, nasza/BK {rlo}-0.6, 0 / 0",
                (H is not None and H >= 10 and B is not None and B > 0 and R is not None and rlo <= R <= 0.6 and dst == 0 and errs.get("CompanionPay", 0) == 0) if cd else None)
        rep.add("NC-22: towarzysze - zold i poziom (INFO), czas linii doby", f"zold/d mediana {med(ws)}, poziom mediana {med(lv)}, czas linii doby najwiecej {max(mss) if mss else '-'} ms",
                "INFO (" + ("zold z tabeli CW wedlug poziomu, poz. 19 = 23 d" if cw else "postac ROT ok. 90 d/d") + "; czas < 100 ms)", None)
    rep.show()
    return 0


# ------------------------------------------------------------ kiesa2 (15.10, decyzja Jeffa "napraw to, najwyzej zwieksz podatki"; Armoury/src/TownFolk.Hoard.cs)
K2_HEAD = "Podatek od nadwyzki ludu (kiesa2): "
K2_DAY = re.compile(r"Podatek od nadwyzki ludu \(kiesa2\): dzien (\d+) \| stawka ([\d.]+)%/d .*?\| pobrano (\d+) z (\d+) osad \(miasta (\d+), zamki (\d+); rodow (\d+)\): "
                    r"W (\d+) / R (\d+) / P (\d+) / podzamcza (\d+) \| do glow rodow (\d+) \(w tym gracz (\d+)\), do kas miast (\d+), do kas zamkow (\d+) "
                    r"\(w tym bez zywego pana (\d+)\)")
K2_W = re.compile(r"kiesa W \(miasta (\d+) i podzamcza (\d+)\) przed / po (\d+) / (\d+), poziom normalny W (\d+)")
K2_CTL = re.compile(r"kontrola: pobrano - do panow - do kas (-?\d+), ponizej poziomu normalnego po poborze (\d+)")
K2_STUM = re.compile(r"\| potkniecia (\d+) \(sesja (\d+)\)\.?$")
K2_HELD = re.compile(r"wstrzymane w oblezeniu (\d+) \((\d+)\)")
K2_COV = re.compile(r"danina P1 / M4 pokryla stawke: (\d+) klaso-osad")
K2_OBG = (re.compile(r"podatek od nadwyzki ludu \(kiesa2\) kiesy ludu -> glowy rodow (\d+)"),
          re.compile(r"podatek od nadwyzki ludu \(kiesa2\) z kies ludu (\d+)"),
          re.compile(r"podatek od nadwyzki ludu \(kiesa2\) z kies podzamczy (\d+)"))
K2_KL = re.compile(r"kontrola: zmiana kies (-?\d+) = wplywy (\d+) - wydatki (\d+), r = (-?\d+|-)")
K2_SKARB = re.compile(r"Skarbce: dzien (\d+) - (.+?)( \(WOJNA\))?: skarbiec (-?\d+).*?wojsko rodow (\d+) ludzi")


def kiesa2_main(logp):
    """kiesa2 (15.10, decyzja Jeffa "napraw to, najwyzej zwieksz podatki"; Armoury/src/TownFolk.Hoard.cs): podatek pana od nadwyzki oszczednosci ludu.
    Wejscie: log Armoury (czytany strumieniowo). K2-0 linia startu sesji (klucz tak), K2-1 linia doby w kazdej dobie kiesy czynnej, K2-2 potkniecia
    i ERROR in TownFolk.Hoard 0, K2-3 kiesa W wobec poziomu normalnego: a) srednia ostatnich 28 dob <= 3.0 x poziom normalny (bieg >= 182 dob),
    b) ostatnie 28 dob wobec 28 dob sprzed 364 dob +-10% (bieg >= 392 dob), c) przebieg (INFO); K2-4 pobrany podatek > 0, K2-5 ksiega bez rozjazdu:
    pobrano = do panow + do kas, nic ponizej poziomu normalnego, "Obieg" (glowy rodow, kasy miast, kasy zamkow) = linia doby, kontrola kies "Kiesa ludu"
    r = 0; K2-6 komu i ile na dobe (INFO), K2-7 miara W5-7 - druzyny lordow krolestw w wojnie, srednia ostatnich 28 dob (INFO).
    Log bez paczki: INFO, bez wyjatku."""
    rep = Report()
    if not logp or not os.path.isfile(logp):
        rep.add("K2-0: log Armoury", f"brak pliku {logp}", "podaj <Armoury-*.log>", None)
        rep.show()
        return 0
    starts, days, kl, obg, errs = [], {}, {}, {}, 0
    war = {}
    with open(logp, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\n"))
            s = m.group(2) if m else ln.rstrip("\n")
            if s.startswith(K2_HEAD):
                if s.startswith(K2_HEAD + "start sesji"):
                    starts.append(s)
                else:
                    d = num(r"dzien (\d+)", s)
                    if d is not None:
                        days[d] = s
            elif s.startswith("Kiesa ludu: dzien "):
                d = num(r"dzien (\d+)", s)
                if d is not None and "| CZYNNA |" in s:
                    mm = K2_KL.search(s)
                    kl[d] = mm.group(4) if mm else None
            elif s.startswith("Obieg: dzien "):
                d = num(r"dzien (\d+)", s)
                if d is not None and "(kiesa2)" in s:
                    obg[d] = tuple((int(p.search(s).group(1)) if p.search(s) else None) for p in K2_OBG)
            elif s.startswith("Skarbce: dzien "):
                mm = K2_SKARB.match(s)
                if mm and mm.group(3):
                    dd = int(mm.group(1))
                    war[dd] = war.get(dd, 0) + int(mm.group(5))
            elif s.startswith("ERROR in TownFolk.Hoard"):
                errs += 1
    print(f"plik: {logp} | linii startu {len(starts)}, linii doby {len(days)}, dob kiesy czynnej {len(kl)}, linii Obieg z kiesa2 {len(obg)}")
    if not starts and not days:
        rep.add("K2-0: linia startu (podatek od nadwyzki ludu)", "brak linii", "INFO (wersja sprzed kiesa2)", None)
        rep.show()
        return 0
    st = starts[-1] if starts else ""
    on = "klucz Folk Hoard Tax tak" in st
    rep.add("K2-0: linia startu (podatek od nadwyzki ludu)", st[len(K2_HEAD):][:240] if st else "brak linii startu (sa linie doby)",
            "linia jest, klucz tak", (bool(st) and on) if (on or not st) else None)
    if not on and not days:
        rep.add("K2-1..K2-7", "klucz Folk Hoard Tax wylaczony - bez linii doby", "INFO", None)
        rep.show()
        return 0
    # K2-1 doby
    miss = sorted(d for d in kl if d not in days and d > min(kl))
    rep.add("K2-1: linia doby w kazdej dobie kiesy czynnej", f"dob {len(days)}, dob kiesy czynnej {len(kl)}, brak linii w {len(miss)}" + (f" (np. {miss[:5]})" if miss else ""),
            "0 brakow (poza pierwsza doba logu)", len(miss) == 0 and len(days) > 0)
    # K2-2 potkniecia
    stum = 0
    for s in days.values():
        mm = K2_STUM.search(s)
        if mm:
            stum += int(mm.group(1))
    rep.add("K2-2: potkniecia kiesa2 / ERROR in TownFolk.Hoard", f"potkniecia {stum}, ERROR {errs}", "0 / 0", stum == 0 and errs == 0)
    # liczby doby
    rows = {}
    for d, s in sorted(days.items()):
        a = K2_DAY.search(s)
        w = K2_W.search(s)
        c = K2_CTL.search(s)
        h = K2_HELD.search(s)
        cv = K2_COV.search(s)
        if not a or not w or not c:
            continue
        rows[d] = dict(rate=float(a.group(2)), take=int(a.group(3)), places=int(a.group(4)), clans=int(a.group(7)),
                       cls=[int(a.group(i)) for i in range(8, 12)], lord=int(a.group(12)), player=int(a.group(13)), town=int(a.group(14)),
                       castle=int(a.group(15)), nolord=int(a.group(16)), w0=int(w.group(3)), w1=int(w.group(4)), norm=int(w.group(5)),
                       diff=int(c.group(1)), below=int(c.group(2)), held=int(h.group(1)) if h else 0, cov=int(cv.group(1)) if cv else 0)
    if not rows:
        rep.add("K2-3..K2-6: liczby linii doby", f"linii doby {len(days)}, rozpoznanych 0", "format linii doby", False)
        rep.show()
        return 0
    ds = sorted(rows)
    span = ds[-1] - ds[0] + 1
    ratio = {d: (rows[d]["w1"] / rows[d]["norm"]) if rows[d]["norm"] > 0 else None for d in ds}

    def avg_ratio(lo, hi):
        v = [ratio[d] for d in ds if lo <= d <= hi and ratio[d] is not None]
        return (sum(v) / len(v)) if v else None
    last = avg_ratio(ds[-1] - 27, ds[-1])
    first = avg_ratio(ds[0], ds[0] + 27)
    rep.add("K2-3a: kiesa W / poziom normalny - srednia ostatnich 28 dob", f"{last:.2f} (pierwsze 28 dob {first:.2f}; dob {span})" if last is not None and first is not None else "-",
            "<= 3.0 (bieg >= 182 dob)", (last <= 3.0) if (last is not None and span >= 182) else None)
    if span >= 392:
        prev = avg_ratio(ds[-1] - 364 - 27, ds[-1] - 364)
        ch = (last / prev - 1) if (prev and last is not None) else None
        rep.add("K2-3b: kiesa W / poziom normalny - ostatnie 28 dob wobec 28 dob sprzed 364 dob", f"{last:.2f} wobec {prev:.2f} ({ch * 100:+.1f}%)" if ch is not None else "-",
                "+-10%", (abs(ch) <= 0.10) if ch is not None else None)
    else:
        rep.add("K2-3b: kiesa W / poziom normalny - stabilnosc rok do roku", f"bieg {span} dob", "INFO (bieg < 392 dob)", None)
    step = max(1, len(ds) // 8)
    path = ", ".join(f"d{d - ds[0] + 1}: W {rows[d]['w1'] / 1e6:.2f} mln = {ratio[d]:.2f}x" for d in ds[::step] if ratio[d] is not None)
    rep.add("K2-3c: przebieg kiesy W (miasta i podzamcza) wobec poziomu normalnego", path[:400], "INFO", None)
    # K2-4 pobrany podatek
    tot = sum(rows[d]["take"] for d in ds)
    paid = sum(1 for d in ds if rows[d]["take"] > 0)
    rep.add("K2-4: pobrany podatek od nadwyzki", f"razem {tot} w {paid} z {len(ds)} dob ({tot / len(ds):.0f}/d)", "> 0", tot > 0)
    # K2-5 ksiega
    bad = [d for d in ds if rows[d]["diff"] != 0]
    below = sum(rows[d]["below"] for d in ds)
    om, on_ = [], 0
    for d in ds:
        o = obg.get(d)
        if o is None or None in o:
            continue
        on_ += 1
        if o != (rows[d]["lord"], rows[d]["town"], rows[d]["castle"]):
            om.append(d)
    rbad = [d for d in ds if kl.get(d) not in (None, "0", "-")]
    rep.add("K2-5: ksiega - pobrano = do panow + do kas, nic ponizej poziomu normalnego, Obieg = linia doby, kontrola kies r = 0",
            f"rozjazd w {len(bad)} dobach, ponizej poziomu {below}, Obieg rozny w {len(om)} z {on_} dob" + (f" {om[:3]}" if om else "")
            + f", r != 0 w {len(rbad)} dobach" + (f" {rbad[:3]}" if rbad else ""),
            "0 / 0 / 0 / 0", not bad and below == 0 and not om and not rbad and on_ > 0)
    # K2-6 komu i ile
    n = len(ds)
    lord = sum(rows[d]["lord"] for d in ds); town = sum(rows[d]["town"] for d in ds); castle = sum(rows[d]["castle"] for d in ds)
    cls = [sum(rows[d]["cls"][i] for d in ds) for i in range(4)]
    rep.add("K2-6: komu i ile na dobe (INFO)", f"panowie {lord / n:.0f}/d (gracz {sum(rows[d]['player'] for d in ds) / n:.0f}), kasy miast {town / n:.0f}/d, kasy zamkow {castle / n:.0f}/d"
            f" (bez zywego pana {sum(rows[d]['nolord'] for d in ds) / n:.0f}); od klas W {cls[0] / n:.0f} / R {cls[1] / n:.0f} / P {cls[2] / n:.0f} / podzamcza {cls[3] / n:.0f};"
            f" pierwsza doba {rows[ds[0]]['take']}, ostatnia {rows[ds[-1]]['take']}; wstrzymane w oblezeniu {sum(rows[d]['held'] for d in ds)}; danina pokryla stawke"
            f" srednio {sum(rows[d]['cov'] for d in ds) / n:.1f} klaso-osad/d", "INFO", None)
    # K2-7 W5-7
    wd = sorted(d for d in war if ds[0] <= d <= ds[-1])
    if wd:
        w28 = wd[-28:]
        rep.add("K2-7: miara W5-7 - druzyny lordow krolestw w wojnie (INFO)", f"{sum(war[d] for d in w28) / len(w28) / 1e3:.1f} tys. (srednia ostatnich {len(w28)} dob)",
                "INFO (cel Jeffa 85 tys.)", None)
    else:
        rep.add("K2-7: miara W5-7 (INFO)", "brak linii Skarbce w oknie", "INFO", None)
    rep.show()
    return 0


# ------------------------------------------------------------ obieg2 (15.10, decyzja Jeffa "kasa sie zbiera u ludu ... lordowie i krolestwa zostana bez kasy";
# "pamietaj o pozyczkach"; Armoury/src/TownFolk.Guard.cs, TownFolk.Loans.cs, TownFolk.Luxury.cs)
OBG2_START = "Obieg ludu (obieg2): start sesji"
O2_GUARD = "Straznik obiegu (obieg2): dzien "
O2_VILL = "Podatek od nadwyzki wsi (obieg2): dzien "
O2_LOANS = "Pozyczki od ludu (obieg2): dzien "
O2_G = re.compile(r"swiat wczoraj (\d+|-): lud (\d+|-) \(([\d.]+%|-);.*?lordowie (\d+|-) \(([\d.]+%|-);.*?korony (\d+|-) \(([\d.]+%|-)\)"
                  r" \| poziom normalny ludu (\d+) .*?kiesy z potrzeba (\d+) .*?= ([\d.]+|-) x poziom normalny; pasmo ([\d.]+)-([\d.]+) x"
                  r".*?\| mnoznik ([\d.]+) \(([^;]*);.*?\| stawka doby ([\d.]+)%/d .*?sufit doby (\d+|-) = max\([\d.]+% swiata (\d+|-);")
O2_GTAX = re.compile(r"podatek od nadwyzki dzis: miasta i zamki (\d+) \(kiesa2 (\d+) \+ korony (\d+)\), wsie (\d+), razem (\d+); do glow rodow (\d+), do kas miast (\d+),"
                     r" do kas zamkow (\d+), do skarbcow koron (\d+)")
O2_GIN = re.compile(r"doplyw ludu od konca poprzedniej doby (-?\d+|-), EMA (-?\d+|-)")
O2_STUM = re.compile(r"\| potkniecia (\d+) \(sesja (\d+)\)\.?$")
O2_V = re.compile(r"\| pobrano (\d+): do glow rodow (\d+) \(w tym gracz (\d+)\), do kas miast (\d+), do kas zamkow (\d+) \(w tym bez zywego pana (\d+)\), do skarbcow koron (\d+)")
O2_VK = re.compile(r"kiesy wsi przed / po (\d+) / (\d+), poziom normalny (\d+) \(kiesy / poziom ([\d.]+|-)\)")
O2_VCTL = re.compile(r"kontrola: pobrano - do panow - do kas - do koron (-?\d+), ponizej poziomu normalnego po poborze (\d+)")
O2_VSKIP = re.compile(r"wies w rabunku albo spladrowana (\d+), osada macierzysta oblezona (\d+) \((\d+)\), bez osady macierzystej (\d+)")
O2_L = re.compile(r"zawarte w dobie (-?\d+) \([^)]*\): (\d+) zl u (\d+) rodow \(z kies miast (\d+), podzamczy (\d+), wsi (\d+)\); kandydaci \(wojna, kiesa rodziny ponizej rezerwy\) (\d+),"
                  r" z miejscem w pulapie (\d+)")
O2_LBLK = re.compile(r"bez pozyczki: zakaz po niesplacie (\d+), zaleglosc albo zajecie w Banku (\d+), limit (\d+), lud lenn bez nadwyzki (\d+)")
O2_LD = re.compile(r"\| dzis: odsetki (\d+|-) .*?splacone (\d+) .*?rody z niepelna rata w pokoju (\d+), niesplacone \(umorzone po \d+ dobach\) (\d+) zl u (\d+) rodow")
O2_LDEBT = re.compile(r"\| dlug rodow u ludu (\d+|-) \(rodow (\d+), osad (\d+).*?\| dlug rodow w Banku (\d+|-) \(rodow (\d+)\)")
O2_LCTL = re.compile(r"kontrola: dlug - \(wczoraj \+ zawarte \+ odsetki - splacone - umorzone - przepadle\) (-?\d+|-)")
O2_OBG = {"vlord": re.compile(r"podatek od nadwyzki wsi \(obieg2\) kiesy wsi -> glowy rodow (\d+)"),
          "lent": re.compile(r"pozyczki od ludu \(obieg2\) kiesy ludu i wsi -> glowy rodow (\d+)"),
          "repaid": re.compile(r"splaty pozyczek od ludu \(obieg2\) glowy rodow -> kiesy ludu i wsi (\d+)"),
          "crown": re.compile(r"czesc korony podatku od nadwyzki \(obieg2\) kiesy ludu i wsi -> skarbce (\d+)"),
          "vtake": re.compile(r"podatek od nadwyzki wsi \(obieg2\) do panow, kas i koron (\d+)")}
O2_OBG_VTC = re.compile(r"podatek od nadwyzki wsi \(obieg2\) z kies wsi (\d+)")
O2_ZB = re.compile(r", kupione z oferty (\d+) zl \(")
O2_ZBC = re.compile(r"podzamcza \(P5\): z nadwyzka \d+, chciane \d+ zl, kupione (\d+) zl")
O2_ZBV = re.compile(r"wsie \(P5\): z nadwyzka \d+, chciane \d+ zl, kupione (\d+) zl")
O2_ZBW = re.compile(r"cena graniczna wedlug zasobnosci ludu \(obieg2\) (tak|nie).*?oferta w kategoriach ponad bazowa (\d+) zl w (\d+) wierszach, kupione z niej (\d+) zl;"
                    r" podzamcza i wsie \(P5\) kupily ponad bazowa (\d+) zl")
O2_BASE_LUX = 79100   # test 4 lata wersja 54 (d1100-1458): kupione z oferty miast 56.6 tys./d + podzamcza 1.8 tys./d + wsie P5 20.8 tys./d


def _o2i(s):
    try:
        return int(s)
    except (TypeError, ValueError):
        return None


def obieg2_main(logp, basep=None):
    """obieg2 (15.10, decyzja Jeffa "kasa sie zbiera u ludu lub mieszczan ... ekonomia sie zawali", "pamietaj o pozyczkach"; Armoury/src/TownFolk.Guard.cs,
    TownFolk.Loans.cs, TownFolk.Luxury.cs): podatek od nadwyzki kies wsi, straznik calego obiegu, pozyczki od ludu, cena graniczna zbytkow wedlug zasobnosci.
    Wejscie: log Armoury (strumieniowo); --baza-doby <log Armoury biegu bazowego> - zakupy zbytku przed (bez - stala z testu 4 lata wersja 54, 79.1 tys./d).
    OB2-0 linia startu (klucze tak), OB2-1 linie doby (straznik, wsie, pozyczki) w kazdej dobie kiesy czynnej, OB2-2 potkniecia i ERROR 0,
    OB2-3a lud / poziom normalny nie ponad pasmem (srednia ostatnich 28 dob, bieg >= 182 doby; ponizej pasma - INFO w wartosci), OB2-3b lordowie + korony >= lud (to samo okno), OB2-3c przebieg udzialow (INFO),
    OB2-4a kiesy wsi bez trwalego wzrostu (ostatnie 28 dob wobec 28 dob sprzed 182 dob <= +10%, bieg >= 210 dob), OB2-4b kiesy wsi / poziom normalny wsi <= 3.0,
    OB2-5 ksiega bez rozjazdu (wsie: pobrano = do panow + kas + koron, nic ponizej poziomu; Obieg = linie; pozyczki: Obieg = linia, kontrola dlugu 0; Kiesa ludu r = 0),
    OB2-6a zakupy zbytku (miasta + podzamcza + wsie) > przed, OB2-6b kupione dzieki cenie wedlug zasobnosci > 0, OB2-7 pozyczki od ludu w wojnie (kandydaci > 0 -> zawarte > 0),
    OB2-8 sufit doby straznika (podatek doby <= sufit + 1%) - brak wstrzasu, OB2-9 komu i ile (INFO), OB2-10 miara W5-7 (INFO). Log bez paczki: INFO, bez wyjatku."""
    rep = Report()
    if not logp or not os.path.isfile(logp):
        rep.add("OB2-0: log Armoury", f"brak pliku {logp}", "podaj <Armoury-*.log>", None)
        rep.show()
        return 0
    starts, gl, vl, ll, obg, kl, zb, errs = [], {}, {}, {}, {}, {}, {}, 0
    k2c = {}
    war = {}
    with open(logp, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\n"))
            s = m.group(2) if m else ln.rstrip("\n")
            if s.startswith(OBG2_START):
                starts.append(s)
            elif s.startswith(O2_GUARD):
                d = num(r"dzien (\d+)", s)
                if d is not None:
                    gl[d] = s
            elif s.startswith(O2_VILL):
                d = num(r"dzien (\d+)", s)
                if d is not None:
                    vl[d] = s
            elif s.startswith(O2_LOANS):
                d = num(r"dzien (\d+)", s)
                if d is not None:
                    ll[d] = s
            elif s.startswith("Obieg: dzien "):
                d = num(r"dzien (\d+)", s)
                if d is not None and "(obieg2)" in s:
                    o = {k: (int(p.search(s).group(1)) if p.search(s) else None) for k, p in O2_OBG.items()}
                    vt = O2_OBG_VTC.findall(s)
                    o["vtown"] = int(vt[0]) if len(vt) > 0 else None
                    o["vcastle"] = int(vt[1]) if len(vt) > 1 else None
                    obg[d] = o
            elif s.startswith("Kiesa ludu: dzien "):
                d = num(r"dzien (\d+)", s)
                if d is not None and "| CZYNNA |" in s:
                    mm = K2_KL.search(s)
                    kl[d] = mm.group(4) if mm else None
            elif s.startswith("Zbytki ludu (P3-P5): dzien "):
                d = num(r"dzien (\d+)", s)
                if d is not None:
                    a, c, v, w = O2_ZB.search(s), O2_ZBC.search(s), O2_ZBV.search(s), O2_ZBW.search(s)
                    zb[d] = (int(a.group(1)) if a else 0, int(c.group(1)) if c else 0, int(v.group(1)) if v else 0,
                             (int(w.group(4)) + int(w.group(5))) if w else None, (int(w.group(2)) if w else None))
            elif s.startswith("Podatek od nadwyzki ludu (kiesa2): dzien "):
                d = num(r"dzien (\d+)", s)
                if d is not None:
                    k2c[d] = num(r"do skarbcow koron z miast i zamkow (\d+)", s, int, 0)
            elif s.startswith("Skarbce: dzien "):
                mm = K2_SKARB.match(s)
                if mm and mm.group(3):
                    dd = int(mm.group(1))
                    war[dd] = war.get(dd, 0) + int(mm.group(5))
            elif s.startswith("ERROR in TownFolk.Guard") or s.startswith("ERROR in TownFolk.Loans") or s.startswith("ERROR in ClanBudget.FolkLoan"):
                errs += 1
    print(f"plik: {logp} | linii startu {len(starts)}, straznika {len(gl)}, wsi {len(vl)}, pozyczek {len(ll)}, dob kiesy czynnej {len(kl)}, Obieg z obieg2 {len(obg)}")
    if not starts and not gl and not vl and not ll:
        rep.add("OB2-0: linia startu obieg2", "brak linii", "INFO (wersja sprzed obieg2)", None)
        rep.show()
        return 0
    st = starts[-1] if starts else ""
    keys = {k: (f"({k}) tak" in st) for k in ("Folk Hoard Villages", "Folk Circulation Guard", "Folk Loans", "Folk Ladder Ceiling By Wealth", "Folk Hoard Tax")}
    allon = all(keys.values())
    rep.add("OB2-0: linia startu (klucze obieg2)", (st[len(OBG2_START):][:260] if st else "brak linii startu (sa linie doby)"),
            "linia jest, klucze tak", bool(st) and allon)
    # OB2-1 linie doby
    if kl:
        d0 = min(kl)
        mg = sorted(d for d in kl if d > d0 and keys["Folk Circulation Guard"] and d not in gl)
        mv = sorted(d for d in kl if d > d0 and keys["Folk Hoard Villages"] and d not in vl)
        ml = sorted(d for d in kl if d > d0 and keys["Folk Loans"] and d not in ll)
        rep.add("OB2-1: linie doby (straznik / wsie / pozyczki) w kazdej dobie kiesy czynnej",
                f"brak: straznik {len(mg)}, wsie {len(mv)}, pozyczki {len(ml)} (dob kiesy {len(kl)})" + (f" np. {(mg + mv + ml)[:4]}" if mg or mv or ml else ""),
                "0 / 0 / 0 (poza pierwsza doba logu)", not mg and not mv and not ml)
    else:
        rep.add("OB2-1: linie doby", "brak linii 'Kiesa ludu' CZYNNA", "INFO", None)
    # OB2-2 potkniecia
    sg = sum(int(O2_STUM.search(s).group(1)) for s in (gl.values() if gl else vl.values()) if O2_STUM.search(s))
    sl = sum(int(O2_STUM.search(s).group(1)) for s in ll.values() if O2_STUM.search(s))
    rep.add("OB2-2: potkniecia obieg2 / ERROR (TownFolk.Guard, TownFolk.Loans, ClanBudget.FolkLoan)", f"straznik i wsie {sg}, pozyczki {sl}, ERROR {errs}", "0 / 0 / 0",
            sg == 0 and sl == 0 and errs == 0)
    # OB2-3 udzialy
    g = {}
    for d, s in gl.items():
        a = O2_G.search(s)
        t = O2_GTAX.search(s)
        if not a or not t:
            continue
        world = _o2i(a.group(1))
        g[d] = dict(world=world, folk=_o2i(a.group(2)), lords=_o2i(a.group(4)), crowns=_o2i(a.group(6)), N=int(a.group(8)), P=int(a.group(9)),
                    ratio=float(a.group(10)) if a.group(10) != "-" else None, lo=float(a.group(11)), hi=float(a.group(12)), m=float(a.group(13)), move=a.group(14),
                    rate=float(a.group(15)), cap=_o2i(a.group(16)), tax=int(t.group(5)), lord=int(t.group(6)), town=int(t.group(7)), castle=int(t.group(8)),
                    crown=int(t.group(9)), vtake=int(t.group(4)), k2=int(t.group(2)), k2c=int(t.group(3)))
    ds = sorted(g)
    if ds:
        span = ds[-1] - ds[0] + 1
        last = [g[d] for d in ds[-28:] if g[d]["ratio"] is not None]
        lo, hi = g[ds[-1]]["lo"], g[ds[-1]]["hi"]
        avg = sum(x["ratio"] for x in last) / len(last) if last else None
        # noc 16.10 (N7, klucz FolkGuardNoMemory): przy regule bez pamieci mnoznik = clamp(1 + 8 x (P/N - 1.5), 0.25, max) - rownowaga zalezy od doplywu, pasmo starej
        # reguly nie jest celem; prog: lud nie ponad punktem nasycenia 1.5 + (max - 1) / 8 (tam straznik przestaje dokrecac), pasmo - INFO w wartosci
        nmd = [d for d in ds[-28:] if g[d]["move"].startswith("bez pamieci")]
        if nmd and 2 * len(nmd) >= len(ds[-28:]):
            gmax = num(r"; granice [\d.]+-([\d.]+)\)", gl[ds[-1]], float) or 10.0
            sat = 1.5 + (gmax - 1.0) / 8.0
            pos = "-" if avg is None else ("w pasmie starej reguly" if lo <= avg <= hi else ("ponizej pasma" if avg < lo else ("ponad pasmem, ponizej nasycenia" if avg <= sat else "PONAD nasyceniem")))
            rep.add("OB2-3a: lud / poziom normalny ludu - srednia ostatnich 28 dob (N7 bez pamieci: nasycenie straznika)", f"{avg:.3f} - {pos} (nasycenie {sat:.3f} przy max {gmax:.2f};"
                    f" pasmo {lo:.2f}-{hi:.2f}; dob {span}, z regula bez pamieci {len(nmd)})" if avg is not None else "-",
                    "nie ponad nasycenie: <= 1.5 + (max - 1) / 8 + 5% (bieg >= 182 dob)", (avg <= sat * 1.05) if (avg is not None and span >= 182) else None)
        else:
            pos = "-" if avg is None else ("w pasmie" if lo <= avg <= hi else ("ponizej pasma - lud nie gromadzi, straznik schodzi do 0.25 x" if avg < lo else "PONAD pasmem"))
            rep.add("OB2-3a: lud / poziom normalny ludu - srednia ostatnich 28 dob (pasmo straznika)", f"{avg:.3f} - {pos} (pasmo {lo:.2f}-{hi:.2f}; dob {span})" if avg is not None else "-",
                    "nie ponad pasmo: <= gorna granica + 5% (bieg >= 182 dob)", (avg <= hi * 1.05) if (avg is not None and span >= 182) else None)
        sh = [x for x in (g[d] for d in ds[-28:]) if x["world"] and x["folk"] is not None and x["lords"] is not None and x["crowns"] is not None]
        if sh:
            fl = sum(x["folk"] / x["world"] for x in sh) / len(sh)
            lc = sum((x["lords"] + x["crowns"]) / x["world"] for x in sh) / len(sh)
            rep.add("OB2-3b: lordowie + korony wobec ludu - udzial w zlocie swiata, srednia ostatnich 28 dob", f"lordowie + korony {100 * lc:.1f}%, lud {100 * fl:.1f}%",
                    ">= (bieg >= 182 dob)", (lc >= fl) if span >= 182 else None)
        step = max(1, len(ds) // 8)
        path = "; ".join(f"d{d - ds[0] + 1}: lud {100 * g[d]['folk'] / g[d]['world']:.1f}% lordowie {100 * g[d]['lords'] / g[d]['world']:.1f}% korony {100 * g[d]['crowns'] / g[d]['world']:.1f}%"
                         f" (x{g[d]['ratio'] if g[d]['ratio'] is not None else 0:.2f}, m {g[d]['m']:.2f})"
                         for d in ds[::step] if g[d]["world"] and g[d]["folk"] is not None and g[d]["lords"] is not None and g[d]["crowns"] is not None)
        rep.add("OB2-3c: przebieg udzialow (lud / lordowie / korony, lud wobec poziomu normalnego, mnoznik)", path[:600], "INFO", None)
    else:
        rep.add("OB2-3: udzialy", f"linii straznika {len(gl)}, rozpoznanych 0", "format linii straznika", False if gl else None)
    # OB2-4 wsie
    v = {}
    for d, s in vl.items():
        a, k, c = O2_V.search(s), O2_VK.search(s), O2_VCTL.search(s)
        if not a or not k or not c:
            continue
        v[d] = dict(take=int(a.group(1)), lord=int(a.group(2)), town=int(a.group(4)), castle=int(a.group(5)), crown=int(a.group(7)), g1=int(k.group(2)),
                    norm=int(k.group(3)), ratio=float(k.group(4)) if k.group(4) != "-" else None, diff=int(c.group(1)), below=int(c.group(2)))
    vd = sorted(v)
    if vd:
        vspan = vd[-1] - vd[0] + 1

        def vavg(a_, b_, key):
            xs = [v[d][key] for d in vd if a_ <= d <= b_ and v[d][key] is not None]
            return sum(xs) / len(xs) if xs else None
        if vspan >= 210:
            now = vavg(vd[-1] - 27, vd[-1], "g1")
            before = vavg(vd[-1] - 182 - 27, vd[-1] - 182, "g1")
            ch = (now / before - 1) if (now is not None and before) else None
            rep.add("OB2-4a: kiesy wsi - ostatnie 28 dob wobec 28 dob sprzed 182 dob", f"{now / 1e6:.2f} mln wobec {before / 1e6:.2f} mln ({100 * ch:+.1f}%)" if ch is not None else "-",
                    "<= +10%", (ch <= 0.10) if ch is not None else None)
        else:
            rep.add("OB2-4a: kiesy wsi - trwaly wzrost", f"bieg {vspan} dob", "INFO (bieg < 210 dob)", None)
        rv = vavg(vd[-1] - 27, vd[-1], "ratio")
        rep.add("OB2-4b: kiesy wsi / poziom normalny wsi - srednia ostatnich 28 dob", f"{rv:.2f} (pierwsza doba {v[vd[0]]['ratio']})" if rv is not None else "-",
                "<= 3.0 (bieg >= 182 dob)", (rv <= 3.0) if (rv is not None and vspan >= 182) else None)
    else:
        rep.add("OB2-4: kiesy wsi", f"linii wsi {len(vl)}, rozpoznanych 0", "format linii wsi", False if vl else None)
    # OB2-5 ksiega
    bad = []
    vbad = [d for d in vd if v[d]["diff"] != 0]
    vbelow = sum(v[d]["below"] for d in vd)
    om = []
    for d in vd:
        o = obg.get(d)
        if not o:
            continue
        if (o["vlord"], o["vtake"], o["vtown"], o["vcastle"]) != (v[d]["lord"], v[d]["take"], v[d]["town"], v[d]["castle"]):
            om.append(("wsie", d))
    for d in ds:
        o = obg.get(d)
        if o and o["crown"] is not None and o["crown"] != g[d]["crown"]:
            om.append(("korony", d))
        if d in k2c and k2c[d] != g[d]["k2c"]:
            om.append(("kiesa2-korony", d))
    lrows = {}
    for d, s in ll.items():
        a, b_, c, e = O2_L.search(s), O2_LD.search(s), O2_LCTL.search(s), O2_LDEBT.search(s)
        if not a or not b_:
            continue
        lrows[d] = dict(lday=int(a.group(1)), lent=int(a.group(2)), clans=int(a.group(3)), cand=int(a.group(7)), roomn=int(a.group(8)), repaid=int(b_.group(2)),
                        missed=int(b_.group(3)), written=int(b_.group(4)), defaults=int(b_.group(5)), ctl=c.group(1) if c else None,
                        debt=_o2i(e.group(1)) if e else None, bank=_o2i(e.group(4)) if e else None)
    lm = []
    for d, r in lrows.items():
        o = obg.get(r["lday"])
        if o and o["lent"] is not None and o["lent"] != r["lent"]:
            lm.append(("zawarte", r["lday"]))
        o2 = obg.get(d)
        if o2 and o2["repaid"] is not None and o2["repaid"] != r["repaid"]:
            lm.append(("splacone", d))
    lctl = [d for d, r in lrows.items() if r["ctl"] not in (None, "-", "0", "-0") and abs(int(r["ctl"])) > 1]
    rbad = [d for d in sorted(kl) if kl.get(d) not in (None, "0", "-")]
    rep.add("OB2-5: ksiega obieg2 - wsie (pobrano = panowie + kasy + korony, nic ponizej poziomu), Obieg = linie (wsie, korony, pozyczki), kontrola dlugu, Kiesa ludu r = 0",
            f"wsie rozjazd {len(vbad)} dob, ponizej poziomu {vbelow}; Obieg rozny {len(om) + len(lm)} (linii Obieg z obieg2 {len(obg)})" + (f" {(om + lm)[:3]}" if om or lm else "")
            + f"; kontrola dlugu != 0 w {len(lctl)} dobach; r != 0 w {len(rbad)} dobach" + (f" {rbad[:3]}" if rbad else ""),
            "0 / 0 / 0 / 0 / 0", not vbad and vbelow == 0 and not om and not lm and not lctl and not rbad)
    # OB2-6 zbytki
    zd = sorted(zb)
    if zd:
        tot = [zb[d][0] + zb[d][1] + zb[d][2] for d in zd]
        avg = sum(tot) / len(tot)
        base, bsrc = O2_BASE_LUX, "stala z testu 4 lata wersja 54 (d1100-1458)"
        if basep and os.path.isfile(basep):
            bt = []
            with open(basep, encoding="utf-8", errors="replace") as fh:
                for ln in fh:
                    mm = TS.match(ln.rstrip("\n"))
                    s = mm.group(2) if mm else ln.rstrip("\n")
                    if s.startswith("Zbytki ludu (P3-P5): dzien "):
                        a, c, vv = O2_ZB.search(s), O2_ZBC.search(s), O2_ZBV.search(s)
                        bt.append((int(a.group(1)) if a else 0) + (int(c.group(1)) if c else 0) + (int(vv.group(1)) if vv else 0))
            if bt:
                base, bsrc = sum(bt) / len(bt), f"bieg bazowy {os.path.basename(basep)} ({len(bt)} dob)"
        rep.add("OB2-6a: zakupy zbytku z oszczednosci (miasta + podzamcza + wsie) na dobe", f"{avg:.0f} wobec przed {base:.0f} ({bsrc})", "> przed", avg > base)
        wide = [zb[d][3] for d in zd if zb[d][3] is not None]
        rep.add("OB2-6b: kupione dzieki cenie granicznej wedlug zasobnosci (miasta + P5)", f"{sum(wide)} zl w {len(wide)} dobach ({sum(wide) / max(1, len(wide)):.0f}/d)" if wide else "brak pola w linii",
                "> 0", (sum(wide) > 0) if wide else None)
    else:
        rep.add("OB2-6: zakupy zbytku", "brak linii 'Zbytki ludu (P3-P5)'", "INFO", None)
    # OB2-7 pozyczki
    if lrows:
        ld = sorted(lrows)
        lent = sum(lrows[d]["lent"] for d in ld); cand = sum(lrows[d]["cand"] for d in ld)
        roomn = sum(lrows[d]["roomn"] for d in ld)
        rep.add("OB2-7: pozyczki od ludu w wojnie (kandydaci z miejscem -> zawarte)", f"zawarte {lent} zl ({lent / len(ld):.0f}/d), kandydaci {cand}, z miejscem {roomn},"
                f" splacone {sum(lrows[d]['repaid'] for d in ld)}, umorzone {sum(lrows[d]['written'] for d in ld)} u {sum(lrows[d]['defaults'] for d in ld)} rodow;"
                f" dlug u ludu na koniec {lrows[ld[-1]]['debt']}, w Banku {lrows[ld[-1]]['bank']}",
                "> 0, gdy rody z miejscem w pulapie", (lent > 0) if roomn > 0 else None)
    else:
        rep.add("OB2-7: pozyczki od ludu", "brak linii", "INFO", None)
    # OB2-8 sufit doby
    if ds:
        over = [d for d in ds if g[d]["cap"] and g[d]["tax"] > 1.01 * g[d]["cap"] + 1]
        first = next((d for d in ds if g[d]["tax"] > 0), None)
        rep.add("OB2-8: podatek doby <= sufit straznika (bez wstrzasu)", f"ponad sufit {len(over)} dob" + (f" {over[:3]}" if over else "")
                + (f"; pierwsza doba z podatkiem d{first - ds[0] + 1}: {g[first]['tax']} przy suficie {g[first]['cap']}" if first else "; podatku brak"),
                "0 dob", not over)
        n = len(ds)
        rep.add("OB2-9: komu i ile na dobe (INFO)", f"razem {sum(g[d]['tax'] for d in ds) / n:.0f}/d (miasta i zamki {sum(g[d]['k2'] + g[d]['k2c'] for d in ds) / n:.0f}, wsie "
                f"{sum(g[d]['vtake'] for d in ds) / n:.0f}): glowy rodow {sum(g[d]['lord'] for d in ds) / n:.0f}, kasy miast {sum(g[d]['town'] for d in ds) / n:.0f}, kasy zamkow "
                f"{sum(g[d]['castle'] for d in ds) / n:.0f}, skarbce koron {sum(g[d]['crown'] for d in ds) / n:.0f}; mnoznik pierwszy {g[ds[0]]['m']:.2f}, ostatni {g[ds[-1]]['m']:.2f};"
                f" stawka ostatnia {g[ds[-1]]['rate']:.3f}%/d", "INFO", None)
    wd = sorted(d for d in war if (not ds) or ds[0] <= d <= ds[-1])
    if wd:
        w28 = wd[-28:]
        rep.add("OB2-10: miara W5-7 - druzyny lordow krolestw w wojnie (INFO)", f"{sum(war[d] for d in w28) / len(w28) / 1e3:.1f} tys. (srednia ostatnich {len(w28)} dob)",
                "INFO (cel Jeffa 85 tys.)", None)
    else:
        rep.add("OB2-10: miara W5-7 (INFO)", "brak linii Skarbce w oknie", "INFO", None)
    rep.show()
    return 0


# ------------------------------------------------------------ korona2 (15.10, Jeff "korony pozyczaja od miast czemu nie" - 'Tak, dodaj'; Armoury/src/TownFolk.CrownLoans.cs,
# TownFolk.Guard.cs GuardCrownReserve): pozyczki koron od miast i mieszczan do zapasu wojny + czesc korony podatku od nadwyzki do zapasu korony
KR2_START = "Pozyczki koron (korona2): start sesji"
KR2_HEAD = "Pozyczki koron (korona2): dzien "
KR2_DAY = re.compile(r"Pozyczki koron \(korona2\): dzien (?P<d>\d+) \| pozyczki (?P<on>CZYNNE|wylaczone): zawarte (?P<lent>\d+) zl u (?P<lentN>\d+) krolestw .*?;"
                     r" krolestw w wojnie (?P<war>\d+), ze skarbcem ponizej zapasu wojny (?P<cand>\d+) \(luka razem (?P<gap>-?\d+|-)\); bez pozyczki: zakaz po niesplacie"
                     r" (?P<ban>\d+), pomiar wplywow < \d+ dob (?P<warm>\d+), limit (?P<lim>\d+), miasta bez nadwyzki (?P<nosrc>\d+) \| splaty: z wplywow dnia (?P<pinc>\d+),"
                     r" z wolnego zlota ponad zapas wojny i dlugi (?P<pstock>\d+), razem (?P<paid>\d+) .*?\| niesplacone \(umorzone po \d+ dobach w pokoju\) (?P<wr>\d+) zl u"
                     r" (?P<wrN>\d+) krolestw .*?\| dlug koron u miast (?P<debt>-?\d+) \(krolestw (?P<debtK>\d+), .*?\), limit krolestw z dlugiem (?P<limAll>-?\d+|-),"
                     r" dlug / limit najwyzej (?P<worst>[\d.]+), zakazow (?P<bans>\d+) \| kontrola: dlug - \(wczoraj \+ zawarte \+ odsetki - splacone - umorzone - przepadle\)"
                     r" (?P<ctl>-?\d+|-), skarbiec po pozyczce ponad zapas wojny (?P<above>\d+) .*?\| czesc korony podatku od nadwyzki do zapasu \(A, Folk Guard Crown To Reserve"
                     r" (?P<res>tak|nie)\): dzis (?P<resT>\d+) z (?P<crownT>\d+) zl .*?\| potkniecia (?P<st>\d+) \(sesja (?P<sts>\d+)\)")
KR2_OBG = re.compile(r"pozyczki koron od miast \(korona2\) kasy miast i kiesy mieszczan -> skarbce (\d+), splaty pozyczek koron \(korona2\) skarbce -> kasy miast i kiesy mieszczan (\d+)")
KR2_GUARD = re.compile(r"Straznik obiegu \(obieg2\): dzien (\d+) \| swiat wczoraj (\d+): .*?, korony (\d+) \(")
KR2_ERR = ("ERROR in TownFolk.CrownLoans", "ERROR in TownFolk.Guard.GuardCrownReserve", "ERROR in SyncData.Korona2", "ERROR in TownFolk.ExportKorona2",
           "ERROR in TownFolk.ImportKorona2")
KR2_SHARE_MIN = 0.18     # udzial koron w zlocie swiata po >= 182 dobach (cel FolkGuardCrownTarget 0.22 minus 4 pkt luzu)
KR2_DEBT_WORLD = 0.05    # dlug koron u miast najwyzej 5% zlota swiata (wolne zloto miast i mieszczan ponad zapasy to ok. 4% - test D)


def korona2_main(logp):
    """korona2 (15.10, Jeff "korony pozyczaja od miast czemu nie"; Armoury/src/TownFolk.CrownLoans.cs, TownFolk.Guard.cs): pozyczki koron od miast i mieszczan
    i czesc korony podatku od nadwyzki do zapasu korony. Wejscie: log Armoury (strumieniowo). KR2-0 linia startu (klucze tak), KR2-1 linia doby w kazdej dobie
    korony (165), KR2-2 potkniecia i ERROR 0, KR2-3 ksiega bez rozjazdu (kontrola dlugu |r| <= 1, skarbiec po pozyczce nie ponad zapas wojny, Obieg = linia),
    KR2-4 dlug ograniczony (dlug / limit <= 1.05, dlug <= 5% zlota swiata), KR2-5 udzial koron >= 18% (srednia ostatnich 28 dob, bieg >= 182 dob),
    KR2-6 pozyczki i splaty (INFO), KR2-7 czesc korony do zapasu (INFO), KR2-8 przebieg udzialu koron i dlugu (INFO). Log bez paczki: INFO, bez wyjatku."""
    rep = Report()
    if not logp or not os.path.isfile(logp):
        rep.add("KR2-0: log Armoury", f"brak pliku {logp}", "podaj <Armoury-*.log>", None)
        rep.show()
        return 0
    starts, kd, bad, obg, gs, k165, errs = [], {}, [], {}, {}, set(), 0
    with open(logp, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\n"))
            s = m.group(2) if m else ln.rstrip("\n")
            if s.startswith(KR2_START):
                starts.append(s)
            elif s.startswith(KR2_HEAD):
                a = KR2_DAY.search(s)
                if a:
                    g = a.groupdict()
                    x = {k: _o2i(v) for k, v in g.items() if k not in ("on", "res", "worst")}
                    x.update(on=g["on"] == "CZYNNE", res=g["res"] == "tak", worst=float(g["worst"]))
                    x["gap"] = x["gap"] or 0
                    kd[x["d"]] = x
                else:
                    bad.append(s[:120])
            elif s.startswith("Straznik obiegu (obieg2): dzien "):
                a = KR2_GUARD.search(s)
                if a:
                    gs[int(a.group(1))] = (int(a.group(2)), int(a.group(3)))
            elif s.startswith("Korona: wplywy dnia (165): dzien "):
                d = num(r"dzien (\d+)", s)
                if d is not None:
                    k165.add(d)
            elif s.startswith("Obieg: dzien "):
                a = KR2_OBG.search(s)
                if a:
                    d = num(r"dzien (\d+)", s)
                    if d is not None:
                        obg[d] = (int(a.group(1)), int(a.group(2)))
            elif s.startswith(KR2_ERR):
                errs += 1
    print(f"plik: {logp} | linii startu {len(starts)}, linii doby {len(kd)} (nierozpoznanych {len(bad)}), dob 165 {len(k165)}, Obieg z korona2 {len(obg)},"
          f" linii straznika {len(gs)}")
    if not starts and not kd:
        rep.add("KR2-0: linia startu korona2", "brak linii", "INFO (wersja sprzed korona2)", None)
        rep.show()
        return 0
    st = starts[-1] if starts else ""
    keys = {k: (f"({k}) tak" in st) for k in ("Crown Town Loans", "Folk Guard Crown To Reserve")}
    rep.add("KR2-0: linia startu (klucze Crown Town Loans, Folk Guard Crown To Reserve)", (st[len(KR2_START):][:240] if st else "brak linii startu (sa linie doby)"),
            "linia jest, klucze tak", bool(st) and all(keys.values()))
    ds = sorted(kd)
    if k165:
        d0 = min(k165)
        miss = sorted(d for d in k165 if d > d0 and d not in kd)
        rep.add("KR2-1: linia doby korona2 w kazdej dobie korony (165)", f"brak {len(miss)} z {len(k165)}" + (f" np. {miss[:4]}" if miss else "")
                + (f"; nierozpoznanych linii {len(bad)} np. {bad[0]}" if bad else ""), "0 (poza pierwsza doba logu), nierozpoznanych 0", not miss and not bad)
    else:
        rep.add("KR2-1: linia doby", f"linii doby {len(kd)}, brak linii 165", "INFO", None)
    stum = sum(x["st"] for x in kd.values())
    rep.add("KR2-2: potkniecia korona2 / ERROR (TownFolk.CrownLoans, GuardCrownReserve, zapis)", f"potkniecia {stum}, ERROR {errs}", "0 / 0", stum == 0 and errs == 0)
    if ds:
        ctl = [(d, kd[d]["ctl"]) for d in ds if kd[d]["ctl"] is not None]
        badc = [(d, c) for d, c in ctl if abs(c) > 1]
        above = sum(kd[d]["above"] for d in ds)
        od = [d for d in ds if d - 1 in obg]   # "Obieg: dzien d" niesie liczby tiku, w ktorym linie 165 i korona2 maja dzien d + 1
        bado = [d for d in od if obg[d - 1] != (kd[d]["lent"], kd[d]["paid"])]
        rep.add("KR2-3: ksiega bez rozjazdu (kontrola dlugu, skarbiec po pozyczce ponad zapas wojny, Obieg = linia)",
                f"dob z kontrola {len(ctl)}, |r| > 1: {len(badc)}" + (f" np. {badc[:3]}" if badc else "") + f"; ponad zapas wojny {above}; Obieg rozny od linii {len(bado)} z {len(od)}"
                + (f" np. d{bado[0]} Obieg {obg[bado[0] - 1]} linia {(kd[bado[0]]['lent'], kd[bado[0]]['paid'])}" if bado else ""),
                "0 / 0 / 0", not badc and above == 0 and not bado)
        worst = max(kd[d]["worst"] for d in ds)
        agg = [kd[d]["debt"] / kd[d]["limAll"] for d in ds if kd[d]["limAll"] and kd[d]["limAll"] > 0]
        aggm = max(agg) if agg else 0.0
        dmax = max(ds, key=lambda d: kd[d]["debt"])
        wd = gs.get(dmax + 1, gs.get(dmax, (0, 0)))[0]
        frac = kd[dmax]["debt"] / wd if wd else None
        rep.add("KR2-4: dlug koron u miast ograniczony (dlug razem / limit krolestw z dlugiem, dlug / zloto swiata)",
                f"dlug / limit razem najwyzej {aggm:.3f} (jedno krolestwo najwyzej {worst:.3f} - odsetki w wojnie i utrata miast podnosza, INFO); najwiekszy dlug"
                f" {kd[dmax]['debt']} (d{dmax}, krolestw {kd[dmax]['debtK']})" + (f" = {100 * frac:.2f}% zlota swiata" if frac is not None else ""),
                f"<= 1.05 i <= {100 * KR2_DEBT_WORLD:.0f}% swiata", aggm <= 1.05 and (frac is None or frac <= KR2_DEBT_WORLD))
    gd = sorted(gs)
    if gd:
        span = gd[-1] - gd[0] + 1
        last = [gs[d][1] / gs[d][0] for d in gd[-28:] if gs[d][0] > 0]
        avg = sum(last) / len(last) if last else None
        rep.add("KR2-5: udzial koron w zlocie swiata - srednia ostatnich 28 dob", (f"{100 * avg:.1f}% (dob {span})" if avg is not None else "-"),
                f">= {100 * KR2_SHARE_MIN:.0f}% (bieg >= 182 dob)", (avg >= KR2_SHARE_MIN) if (avg is not None and span >= 182) else None)
    else:
        rep.add("KR2-5: udzial koron", "brak linii straznika obiegu", "INFO", None)
    if ds:
        n = len(ds)
        cd = [d for d in ds if kd[d]["cand"] > 0]
        rep.add("KR2-6: pozyczki i splaty koron (INFO)",
                f"zawarte {sum(kd[d]['lent'] for d in ds)} zl w {sum(1 for d in ds if kd[d]['lent'] > 0)} dobach; splacone {sum(kd[d]['paid'] for d in ds)} (z wplywow"
                f" {sum(kd[d]['pinc'] for d in ds)}, z wolnego zlota {sum(kd[d]['pstock'] for d in ds)}); umorzone {sum(kd[d]['wr'] for d in ds)}; dob z kandydatami {len(cd)}"
                f" (luka srednio {sum(kd[d]['gap'] for d in cd) / max(1, len(cd)):.0f}); bez pozyczki (sumy dob): zakaz {sum(kd[d]['ban'] for d in ds)}, pomiar"
                f" {sum(kd[d]['warm'] for d in ds)}, limit {sum(kd[d]['lim'] for d in ds)}, miasta bez nadwyzki {sum(kd[d]['nosrc'] for d in ds)}", "INFO", None)
        rep.add("KR2-7: czesc korony podatku od nadwyzki do zapasu korony (INFO)",
                f"do zapasu {sum(kd[d]['resT'] for d in ds)} z {sum(kd[d]['crownT'] for d in ds)} zl czesci korony ({sum(1 for d in ds if kd[d]['resT'] > 0)} z {n} dob),"
                f" srednio {sum(kd[d]['resT'] for d in ds) / n:.0f}/d", "INFO", None)
        step = max(1, n // 8)
        path = "; ".join(f"d{d - ds[0] + 1}: dlug {kd[d]['debt'] / 1e3:.0f} tys. ({kd[d]['debtK']} kr.)"
                         + (f", korony {100 * gs[d][1] / gs[d][0]:.1f}%" if d in gs and gs[d][0] else "") for d in ds[::step])
        rep.add("KR2-8: przebieg dlugu koron i udzialu koron (INFO)", path[:600], "INFO", None)
    rep.show()
    return 0


# ------------------------------------------------------------ nmisje (noc 15/16.10, bledy misji z sesji Jeffa 15.10; Armoury/src/MissionTeams.cs)
NM_HEAD = "Druzyny w misji (NM): "
NM_LINE = re.compile(r"Druzyny w misji \(NM\): misja (\w+) \(bitwa na mapie (TAK|NIE)\) \| agenci bez druzyny \(Team\.Invalid\) pominieci: "
                     r"alarm (\d+), rozbici (\d+), ucieczka (\d+), blok (\d+), zabicia (\d+) \(roznych ludzi (\d+)(?:, pierwszy (.*?))?\) "
                     r"\| ucieczka tylko w bitwie \(WoundedFleeBattlesOnly (TAK|NIE)\): wstrzymani rozbici (\d+), ucieczka (\d+) "
                     r"\| odwroty wyslane \(roznych ludzi\): rozbici (\d+), ucieczka (\d+) \(wywolan: rozbici (\d+), ucieczka (\d+)\) "
                     r"\| potkniecia: alarm (\d+), rozbici (\d+), ucieczka (\d+), blok (\d+), zabicia (\d+) \(sesja (\d+), linia misji (\d+)\)\.$")
NM_ERR = ("ERROR in HideoutAlarm", "ERROR in BrokenMen", "ERROR in FleeTheField", "ERROR in GuardMaster.Tick", "ERROR in BattlefieldLaw.CountKill")


def nmisje_main(logp):
    """nmisje (noc 15/16.10; Armoury/src/MissionTeams.cs, HideoutAlarm, BrokenMen, FieldCraft, GuardMaster, BattlefieldLaw.CountKill): druzyny w misji
    (agenci z Team.Invalid pomijani, potkniecia liczone) i ucieczka rannych tylko w bitwie na mapie (klucz WoundedFleeBattlesOnly).
    Wejscie: log Armoury (czytany strumieniowo). NM-0 linia startu (klucz TAK), NM-1 ERROR in HideoutAlarm / BrokenMen / FleeTheField /
    GuardMaster.Tick / BattlefieldLaw.CountKill = 0, NM-2 linie misji rozpoznane (brak linii = INFO: autotest nie gra misji), NM-3 potkniecia w liniach
    misji = 0, NM-4 kryjowka - widzowie pojedynku pominieci (INFO), NM-5 misja poza bitwa na mapie przy kluczu TAK - odwroty wyslane 0, NM-6 bitwa na
    mapie - wstrzymani 0 (ranni dalej uciekaja), NM-7 pierwszy agent bez druzyny wedlug rodzaju misji (INFO). Log bez paczki: INFO, bez wyjatku."""
    rep = Report()
    if not logp or not os.path.isfile(logp):
        rep.add("NM-0: log Armoury", f"brak pliku {logp}", "podaj <Armoury-*.log>", None)
        rep.show()
        return 0
    starts, rows, bad, notes = [], [], [], []
    errs = {k: 0 for k in NM_ERR}
    with open(logp, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\n"))
            s = m.group(2) if m else ln.rstrip("\n")
            if s.startswith(NM_HEAD):
                if s.startswith(NM_HEAD + "start sesji"):
                    starts.append(s)
                elif s.startswith(NM_HEAD + "misja "):
                    mm = NM_LINE.match(s)
                    if mm:
                        g = mm.groups()
                        rows.append(dict(kind=g[0], battle=g[1] == "TAK", skip=[int(x) for x in g[2:7]], people=int(g[7]), first=g[8] or "",
                                         key=g[9] == "TAK", held=(int(g[10]), int(g[11])), pushed=(int(g[12]), int(g[13])),
                                         calls=(int(g[14]), int(g[15])), stum=[int(x) for x in g[16:21]], sess=int(g[21])))
                    else:
                        bad.append(s)
                else:
                    notes.append(s)
            elif s.startswith("ERROR in "):
                for k in NM_ERR:
                    if s.startswith(k):
                        errs[k] += 1
                        break
    print(f"plik: {logp} | linii startu {len(starts)}, linii misji {len(rows) + len(bad)} (rozpoznanych {len(rows)}), innych linii NM {len(notes)}")
    # NM-0 start
    st = starts[-1] if starts else ""
    on = "klucz WoundedFleeBattlesOnly TAK" in st
    if st:
        rep.add("NM-0: linia startu (druzyny w misji)", st[len(NM_HEAD):][:240], "linia jest, klucz WoundedFleeBattlesOnly TAK", True if on else None)
    else:
        rep.add("NM-0: linia startu (druzyny w misji)", "brak linii", "INFO (wersja sprzed nmisje albo log bez kampanii)", None)
    # NM-1 bledy
    n_err = sum(errs.values())
    rep.add("NM-1: ERROR w miejscach z pytaniem 'czy wrog'", ", ".join(f"{k[len('ERROR in '):]} {v}" for k, v in errs.items()), "0 (log 15.10 10-56-30: 31)",
            n_err == 0)
    # NM-2 linie misji
    if not rows and not bad:
        rep.add("NM-2: linie misji 'Druzyny w misji (NM)'", "brak linii", "INFO (autotest nie gra misji - sprawdzenie w grze: kryjowka z pojedynkiem, turniej)", None)
        rep.show()
        return 0
    kinds = {}
    for r in rows:
        kinds[r["kind"]] = kinds.get(r["kind"], 0) + 1
    rep.add("NM-2: linie misji rozpoznane", f"{len(rows)} z {len(rows) + len(bad)} (" + ", ".join(f"{k} {v}" for k, v in sorted(kinds.items())) + ")"
            + (f"; nierozpoznana np.: {bad[0][:160]}" if bad else ""), "wszystkie rozpoznane", len(bad) == 0)
    # NM-3 potkniecia
    stum = [0] * 5
    for r in rows:
        for i in range(5):
            stum[i] += r["stum"][i]
    rep.add("NM-3: potkniecia w liniach misji", f"alarm {stum[0]}, rozbici {stum[1]}, ucieczka {stum[2]}, blok {stum[3]}, zabicia {stum[4]}"
            + (f"; linii '3. potkniecie' {len(notes)}" if notes else ""), "0", sum(stum) == 0)
    # NM-4 kryjowka
    hide = [r for r in rows if r["kind"] == "kryjowka"]
    if hide:
        hp = sum(r["people"] for r in hide)
        rep.add("NM-4: kryjowka - agenci bez druzyny pominieci", f"misji {len(hide)}, roznych ludzi razem {hp}, alarm {sum(r['skip'][0] for r in hide)}"
                f", rozbici {sum(r['skip'][1] for r in hide)}", "INFO (pojedynek z hersztem: widzowie pominieci, potkniecia 0 w NM-3)", None)
    else:
        rep.add("NM-4: kryjowka - agenci bez druzyny pominieci", "brak misji kryjowki", "INFO", None)
    # NM-5 poza bitwa na mapie przy kluczu TAK
    out = [r for r in rows if not r["battle"] and r["key"]]
    if out:
        push = sum(r["pushed"][0] + r["pushed"][1] for r in out)
        held = (sum(r["held"][0] for r in out), sum(r["held"][1] for r in out))
        rep.add("NM-5: poza bitwa na mapie (turniej, arena, bojka) - odwroty wyslane", f"misji {len(out)}, odwroty {push}; wstrzymani rozbici {held[0]}, ucieczka {held[1]}",
                "odwroty 0 (klucz WoundedFleeBattlesOnly TAK)", push == 0)
    else:
        rep.add("NM-5: poza bitwa na mapie - odwroty wyslane", "brak misji poza bitwa z kluczem TAK", "INFO", None)
    # NM-6 bitwa na mapie
    bat = [r for r in rows if r["battle"]]
    if bat:
        held = sum(r["held"][0] + r["held"][1] for r in bat)
        push = (sum(r["pushed"][0] for r in bat), sum(r["pushed"][1] for r in bat))
        calls = (sum(r["calls"][0] for r in bat), sum(r["calls"][1] for r in bat))
        rep.add("NM-6: bitwa na mapie - wstrzymani", f"misji {len(bat)}, wstrzymani {held}; odwroty (roznych ludzi) rozbici {push[0]}, ucieczka {push[1]}"
                f" (wywolan: rozbici {calls[0]}, ucieczka {calls[1]})",
                "wstrzymani 0 (w bitwie ranni uciekaja jak dotad)", held == 0)
    else:
        rep.add("NM-6: bitwa na mapie - wstrzymani", "brak misji bitwy", "INFO", None)
    # NM-7 kto jest bez druzyny
    firsts = {}
    for r in rows:
        if r["people"] > 0:
            firsts.setdefault(r["kind"], []).append(f"{r['people']} ({r['first']})")
    rep.add("NM-7: agenci bez druzyny wedlug rodzaju misji", "; ".join(f"{k}: " + ", ".join(v[:3]) for k, v in sorted(firsts.items())) or "0",
            "INFO (turniej > 0 - 'pierwszy' wskaze zrodlo agenta bez druzyny)", None)
    rep.show()
    return 0


# ------------------------------------------------------------ nskarbiec (noc 15/16.10, Jeff 15.10 16:05 "zloto bandytow / skarbiec kryjowki - TAK"; Armoury/src/OutlawLaw.cs StashDay/HoardLog, HideoutPurge.cs AiCleared/DoSearch, BeatenPurse.cs HideoutCarry)
NS_HEAD = "Skarbce kryjowek (nskarbiec): "
NS_SHARE = re.compile(r"\| dola tak \(udzial ([\d.]+) kiesy")
NS_BANDS = re.compile(r"\| band z kryjowka (\d+) z (\d+), dola dalo (\d+) \(pominiete: bitwa (\d+), zadanie (\d+), nieumarli (\d+), czeka na przeszukanie (\d+), "
                      r"pusta kiesa (\d+), kiesa ponizej zlotowki doli (\d+), w ticku gry (\d+)(?:, kiesa w calosci zapasem (\d+))?\)")
NS_PURSE = re.compile(r"\| kiesy band z kryjowka przed dola (\d+) zl, dola (\d+) zl")
NS_IN = re.compile(r"\| wplaty (\d+) zl \(dola (\d+), wejscia do kryjowek (\d+)(?:, przelewy gry do kryjowek (\d+) w (\d+))?\)")
NS_OUT = re.compile(r"\| wyplaty (\d+) zl \(kiesy startowe (\d+), sprzet (\d+), herszt BK (\d+), zycie w miastach (\d+), przeszukanie gracza (\d+) w (\d+), "
                    r"zwyciezca AI (\d+) w (\d+): wodzom (\d+), partiom (\d+), (?:miastom|osadom) (\d+)(?:, przelewy gry z kryjowek (\d+) w (\d+))?\)")
NS_STATE = re.compile(r"\| stan wczoraj (-|\d+) zl, dzis (\d+) zl w (\d+) kryjowkach z kasa z (\d+) \(z bandami (\d+): kasa (\d+) zl, z kasa co najmniej skarbiec (\d+); "
                      r"opuszczone z kasa (\d+): (\d+) zl\), skarbce razem do (\d+) zl, najwieksza (\d+) zl")
NS_CTL = re.compile(r"\| kontrola: k (-?\d+), r (-?\d+|-)")
NS_AI = re.compile(r"\| bitwy w kryjowkach bez gracza (\d+) \(oczyszczone (\d+)\)")
NS_MSG = re.compile(r"\| komunikaty: po bitwie (\d+) \(kiesy (\d+) zl\), po przeszukaniu (\d+)")
NS_STUM = re.compile(r"\| potkniecia (\d+) \(sesja (\d+)\)\.?$")
NS_ERR = ("ERROR in OutlawLaw.StashDay", "ERROR in OutlawLaw.HoardLog", "ERROR in HideoutPurge.AiCleared", "ERROR in HideoutPurge.DoSearch(komunikat)",
          "ERROR in HideoutPurge.HoardStart", "ERROR in BeatenPurse.HideoutCarry", "ERROR in OutlawLaw.OnGoldTraded")
# linia "Paser:" - kasy kryjowek (stary i nowy tekst): doplyw, odplyw, kiesy startowe nowych band X z Y, stan
NS_PASER = re.compile(r"kasy kryjowek: doplyw (\d+) zl .*?odplyw (\d+) zl \(kiesy startowe nowych band (\d+) z (\d+) zl.*?; stan (\d+) zl w (\d+) kryjowkach")
NS_PSW = (re.compile(r"\| razem (\d+) "), re.compile(r"kryjowki i inne (\d+) "), re.compile(r", bandy (\d+) \("))
NS_EV_SEARCH = re.compile(r"przeszukanie .*? - skarbiec (\d+) zl do gracza")
NS_EV_CARRY = re.compile(r"kiesy band do gracza (\d+) zl")
NS_EV_AI = re.compile(r"- skarbiec (\d+) zl -> (wodz|partia|miasto|osada|nic)")
NS_HP_SEARCH = re.compile(r"^HideoutPurge: przeszukano .* - zloto (\d+),")


def nskarbiec_paser(path):
    """Linie "Paser:" logu -> {doba: ((doplyw, odplyw, kiesy startowe dane, chciane, stan, kryjowek z kasa) albo None, kurek otwarty)} (strumieniowo)."""
    out = {}
    with open(path, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\n"))
            s = m.group(2) if m else ln.rstrip("\n")
            if not s.startswith("Paser: dzien "):
                continue
            d = num(r"Paser: dzien (\d+)", s)
            if d is None:
                continue
            mm = NS_PASER.search(s)
            out[d] = (tuple(int(x) for x in mm.groups()) if mm else None, "KUREK OTWARTY" in s)
    return out


def nskarbiec_main(logp, bdp=None):
    """nskarbiec (noc 15/16.10, Jeff 15.10 "zloto bandytow / skarbiec kryjowki - TAK"): skarbiec kryjowki = kasa kryjowki gry. Wejscie: log Armoury (strumieniowo),
    opcjonalnie --baza-doby <log Armoury bazy> (NK-8). NK-0 linia startu (klucze tak), NK-1 linia doby w kazdej dobie z linia "Paser:", NK-2 potkniecia
    i ERROR 0, NK-3 dola dzienna (kazda doba z kiesami band z kryjowka daje dole, dola / kiesy w [udzial - 0.02, udzial], w ticku gry 0), NK-4 kontrola k = 0
    (twardy - kazda nasza zmiana kas kryjowek ma kategorie), NK-5 kontrola r = 0 w kazdej dobie ze "stan wczoraj" (twardy - zmiany kas spoza naszych
    kategorii; przelewy gry GiveGoldAction - okup gracza, RealisticCaptivity, inne mody - to kategoria, nie r), NK-6 od doby 28 biegu kryjowki z bandami z kasa >= skarbiec srednio >= 0.5 (P - pierwszy prog), NK-7 stan kas kryjowek (INFO), NK-8 kiesy
    startowe nowych band z kas kryjowek, ostatnie 28 dob (INFO, wobec bazy), NK-9 zdarzenia gry gracza i AI (INFO), NK-10 "Pieniadz swiata" - bandy maleja,
    kryjowki rosna, suma bez skoku (INFO), NK-11 linia "Paser:" - stan(d) - stan(d-1) = doplyw - odplyw (twardy; kurek kryjowek otwarty - INFO).
    Log bez paczki: INFO, bez wyjatku."""
    rep = Report()
    if not logp or not os.path.isfile(logp):
        rep.add("NK-0: log Armoury", f"brak pliku {logp}", "podaj <Armoury-*.log>", None)
        rep.show()
        return 0
    starts, days, psw, errs = [], {}, {}, 0
    ev_search, ev_carry, ev_ai, hp_search = [], [], [], []
    with open(logp, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\n"))
            s = m.group(2) if m else ln.rstrip("\n")
            if s.startswith(NS_HEAD):
                rest = s[len(NS_HEAD):]
                if rest.startswith("start sesji"):
                    starts.append(s)
                elif rest.startswith("dzien "):
                    d = num(r"dzien (\d+)", rest)
                    if d is not None:
                        days[d] = s
                elif rest.startswith("przeszukanie "):
                    ev_search.append(s)
                elif rest.startswith("bitwa gracza w kryjowce "):
                    ev_carry.append(s)
                elif rest.startswith("kryjowka "):
                    ev_ai.append(s)
            elif s.startswith("Pieniadz swiata: dzien "):
                d = num(r"dzien (\d+)", s)
                if d is not None:
                    psw[d] = tuple((int(p.search(s).group(1)) if p.search(s) else None) for p in NS_PSW)
            elif s.startswith("HideoutPurge: przeszukano "):
                mm = NS_HP_SEARCH.match(s)
                if mm:
                    hp_search.append(int(mm.group(1)))
            elif s.startswith(NS_ERR):
                errs += 1
    paser = nskarbiec_paser(logp)
    print(f"plik: {logp} | linii startu {len(starts)}, linii doby {len(days)}, linii Paser {len(paser)}, zdarzen: przeszukania {len(ev_search)}, "
          f"po bitwie {len(ev_carry)}, zwyciezca AI {len(ev_ai)}")
    if not starts and not days:
        rep.add("NK-0: linia startu (skarbiec kryjowki)", "brak linii", "INFO (wersja sprzed nskarbiec)", None)
        rep.show()
        return 0
    # NK-0 start
    st = starts[-1] if starts else ""
    keys = ("Hideout Daily Stash tak", "Hideout Hoard To Ai Victor tak", "Hideout Gold Messages tak")
    rep.add("NK-0: linia startu (klucze skarbca kryjowki)", st[len(NS_HEAD):][:300] if st else "brak linii startu (sa linie doby)",
            "linia jest, klucze tak", all(k in st for k in keys) if st else None)
    # NK-1 linia doby w kazdej dobie z linia Paser
    pd = sorted(paser)
    miss = [d for d in pd if d not in days and d != pd[0]]
    rep.add("NK-1: linia doby w kazdej dobie z linia Paser", f"dob z linia {len(days)}, dob Paser {len(pd)}, brak w {len(miss)}" + (f" (np. {miss[:5]})" if miss else ""),
            "0 brakow (poza pierwsza doba logu)", len(miss) == 0 and len(days) > 0)
    # NK-2 potkniecia
    stum = 0
    for s in days.values():
        mm = NS_STUM.search(s)
        if mm:
            stum += int(mm.group(1))
    rep.add("NK-2: potkniecia skarbca / ERROR (StashDay, HoardLog, AiCleared, DoSearch, HoardStart, HideoutCarry, OnGoldTraded)", f"potkniecia {stum}, ERROR {errs}", "0 / 0",
            stum == 0 and errs == 0)
    # liczby doby
    rows = {}
    for d, s in sorted(days.items()):
        a, p, i_, o, t, c = NS_BANDS.search(s), NS_PURSE.search(s), NS_IN.search(s), NS_OUT.search(s), NS_STATE.search(s), NS_CTL.search(s)
        if not (a and p and i_ and o and t and c):
            continue
        ai, mg, sh = NS_AI.search(s), NS_MSG.search(s), NS_SHARE.search(s)
        rows[d] = dict(on="| dola tak" in s, share=float(sh.group(1)) if sh else None,
                       home=int(a.group(1)), all=int(a.group(2)), gave=int(a.group(3)), held=int(a.group(7)), tick=int(a.group(10)),
                       purse=int(p.group(1)), dola=int(p.group(2)), inn=int(i_.group(1)), ent=int(i_.group(3)),
                       gin=int(i_.group(4) or 0), ginN=int(i_.group(5) or 0), gout=int(o.group(13) or 0), goutN=int(o.group(14) or 0),
                       out=int(o.group(1)), start=int(o.group(2)), gear=int(o.group(3)), bk=int(o.group(4)), life=int(o.group(5)),
                       srch=int(o.group(6)), srchN=int(o.group(7)), ai=int(o.group(8)), aiN=int(o.group(9)),
                       aiL=int(o.group(10)), aiP=int(o.group(11)), aiT=int(o.group(12)),
                       y0=None if t.group(1) == "-" else int(t.group(1)), y1=int(t.group(2)), hg=int(t.group(3)), hall=int(t.group(4)),
                       h2=int(t.group(5)), z=int(t.group(6)), h3=int(t.group(7)), h4=int(t.group(8)), u=int(t.group(9)), ks=int(t.group(10)), mx=int(t.group(11)),
                       k=int(c.group(1)), r=None if c.group(2) == "-" else int(c.group(2)),
                       aib=int(ai.group(1)) if ai else 0, aic=int(ai.group(2)) if ai else 0,
                       m1=int(mg.group(1)) if mg else 0, cg=int(mg.group(2)) if mg else 0, m2=int(mg.group(3)) if mg else 0)
    if not rows:
        rep.add("NK-3..NK-11: liczby linii doby", f"linii doby {len(days)}, rozpoznanych 0", "format linii doby", False)
        rep.show()
        return 0
    ds = sorted(rows)
    d0 = ds[0]
    span = ds[-1] - d0 + 1
    on_ds = [d for d in ds if rows[d]["on"]]
    # NK-3 dola dzienna
    if on_ds:
        share = rows[on_ds[-1]]["share"] if rows[on_ds[-1]]["share"] is not None else 0.25
        nogive = [d for d in on_ds if rows[d]["home"] > 0 and rows[d]["purse"] > 0 and rows[d]["dola"] <= 0]
        sp = sum(rows[d]["purse"] for d in on_ds)
        sd = sum(rows[d]["dola"] for d in on_ds)
        q = (sd / sp) if sp > 0 else None
        tick = sum(rows[d]["tick"] for d in on_ds)
        n = len(on_ds)
        val = (f"dob {n}, bez doli przy kiesach {len(nogive)}" + (f" {nogive[:5]}" if nogive else "")
               + (f"; dola {sd} / kiesy przed dola {sp} = {q:.4f}" if q is not None else "; kiesy przed dola 0")
               + f"; w ticku gry {tick}; band z kryjowka srednio {sum(rows[d]['home'] for d in on_ds) / n:.0f} z {sum(rows[d]['all'] for d in on_ds) / n:.0f},"
               + f" dola dalo srednio {sum(rows[d]['gave'] for d in on_ds) / n:.0f}, czeka na przeszukanie {sum(rows[d]['held'] for d in on_ds)}")
        rep.add("NK-3: dola dzienna (kazda doba z kiesami daje dole, dola / kiesy, w ticku gry)", val,
                f"0 dob bez doli; dola / kiesy w [{share - 0.02:.2f}, {share:.2f}]; w ticku gry 0",
                len(nogive) == 0 and q is not None and (share - 0.02) <= q <= share + 1e-9 and tick == 0)
    else:
        rep.add("NK-3: dola dzienna", "dola wylaczona we wszystkich dobach (Hideout Daily Stash NIE)", "INFO", None)
    # NK-4 kontrola k
    badk = [(d, rows[d]["k"]) for d in ds if rows[d]["k"] != 0]
    rep.add("NK-4: kontrola k (kazda nasza zmiana kas kryjowek ma kategorie)", f"dob {len(ds)}, k != 0 w {len(badk)}" + (f" {badk[:5]}" if badk else ""),
            "0 dob (twardy)", len(badk) == 0)
    # NK-5 kontrola r
    rr = [d for d in ds if rows[d]["r"] is not None]
    badr = [(d, rows[d]["r"]) for d in rr if rows[d]["r"] != 0]
    rep.add("NK-5: kontrola r (zmiany kas kryjowek spoza naszych kategorii)",
            f"dob ze 'stan wczoraj' {len(rr)}, r != 0 w {len(badr)}" + (f": {badr[:8]} (suma {sum(x for _, x in badr)})" if badr else ""),
            "0 dob (twardy; r != 0 = zmiana kas kryjowek poza GiveGoldAction i poza naszymi kategoriami: gra albo inny mod - zrodlo do rozpoznania)", (len(badr) == 0) if rr else None)
    # NK-6 skarbce sie napelniaja
    late = [d for d in on_ds if d - d0 + 1 >= 28 and rows[d]["h2"] > 0]
    if late:
        rat = [rows[d]["h3"] / rows[d]["h2"] for d in late]
        avg = sum(rat) / len(rat)
        L6 = rows[late[-1]]
        rep.add("NK-6: skarbce sie napelniaja - kryjowki z bandami z kasa >= skarbiec (od doby 28 biegu)",
                f"srednio {avg:.2f}, ostatnia doba {rat[-1]:.2f} ({L6['h3']} z {L6['h2']}), min {min(rat):.2f}; dob {len(late)}",
                ">= 0.50 srednio (P - pierwszy prog, do korekty z pomiaru)", avg >= 0.5)
    else:
        rep.add("NK-6: skarbce sie napelniaja (od doby 28 biegu)", f"bieg {span} dob" + ("" if on_ds else ", dola wylaczona"), "INFO (bieg >= 28 dob z dola)", None)
    # NK-7 stan kas kryjowek
    def y_at(k):
        d = d0 + k - 1
        return rows[d]["y1"] if d in rows else None
    path = ", ".join(f"d{k}: {y_at(k)}" for k in (1, 7, 28, 56) if y_at(k) is not None)
    L = rows[ds[-1]]
    rep.add("NK-7: stan kas kryjowek (INFO)",
            f"{path}; ostatnia d{span}: {L['y1']} zl w {L['hg']} z {L['hall']} kryjowek, skarbce razem do {L['ks']}, z bandami {L['h2']} (kasa {L['z']}, z kasa >= skarbiec {L['h3']}),"
            f" opuszczone z kasa {L['h4']} ({L['u']} zl), najwieksza {L['mx']}", "INFO", None)
    # NK-8 kiesy startowe nowych band z kas kryjowek
    def start28(pp):
        kk = sorted(d for d in pp if pp[d][0])
        if not kk:
            return None
        w = [d for d in kk if d > kk[-1] - 28]
        return sum(pp[d][0][2] for d in w), sum(pp[d][0][3] for d in w), len(w)
    s8 = start28(paser)
    b8 = start28(nskarbiec_paser(bdp)) if bdp and os.path.isfile(bdp) else None
    if s8:
        val = f"{s8[0]} z {s8[1]} zl" + (f" ({100.0 * s8[0] / s8[1]:.1f}%)" if s8[1] else "") + f" w {s8[2]} dobach"
        base = (f"baza {b8[0]} z {b8[1]} zl" + (f" ({100.0 * b8[0] / b8[1]:.1f}%)" if b8[1] else "")) if b8 else \
            "bez bazy - przed paczka ok. 1% (sesja Jeffa 10-56-30: 0 z 292 zl; bieg 6 lat 20-17-37: 1636 z 178028 zl)"
        rep.add("NK-8: kiesy startowe nowych band z kas kryjowek (ostatnie 28 dob, INFO)", val, "INFO - oczekiwany wzrost; " + base, None)
    else:
        rep.add("NK-8: kiesy startowe nowych band z kas kryjowek", "brak linii Paser", "INFO", None)
    # NK-9 zdarzenia gry gracza i AI
    def amounts(lst, pat):
        v = []
        for s in lst:
            mm = pat.search(s)
            if mm:
                v.append(int(mm.group(1)))
        return v
    vs, vc, va = amounts(ev_search, NS_EV_SEARCH), amounts(ev_carry, NS_EV_CARRY), amounts(ev_ai, NS_EV_AI)
    day_srch = sum(rows[d]["srch"] for d in ds)
    day_ai = sum(rows[d]["ai"] for d in ds)
    rep.add("NK-9: zdarzenia - przeszukanie gracza, bitwa gracza w kryjowce, zwyciezca AI (INFO)",
            f"przeszukania {len(vs)} (skarbiec {sum(vs)} zl; linie HideoutPurge 'przeszukano' {len(hp_search)}: {sum(hp_search)} zl; w liniach doby {day_srch} zl"
            f" w {sum(rows[d]['srchN'] for d in ds)}); po bitwie {len(vc)} (kiesy band {sum(vc)} zl); zwyciezca AI {len(va)} (skarbiec {sum(va)} zl; w liniach doby"
            f" {day_ai} zl: wodzom {sum(rows[d]['aiL'] for d in ds)}, partiom {sum(rows[d]['aiP'] for d in ds)}, osadom (miasta, zamki, wsie) {sum(rows[d]['aiT'] for d in ds)});"
            f" bitwy w kryjowkach bez gracza {sum(rows[d]['aib'] for d in ds)} (oczyszczone {sum(rows[d]['aic'] for d in ds)}); przelewy gry do kryjowek"
            f" {sum(rows[d]['gin'] for d in ds)} zl w {sum(rows[d]['ginN'] for d in ds)}, z kryjowek {sum(rows[d]['gout'] for d in ds)} zl w {sum(rows[d]['goutN'] for d in ds)}"
            f" (okup gracza - linie 'Okupy (2.14)', RealisticCaptivity); komunikaty w liniach doby:"
            f" po bitwie {sum(rows[d]['m1'] for d in ds)}, po przeszukaniu {sum(rows[d]['m2'] for d in ds)}",
            "INFO (autotest: 0; gra Jeffa: przeszukanie = linia HideoutPurge)", None)
    # NK-10 Pieniadz swiata
    pk = sorted(d for d in psw if psw[d][0] is not None and psw[d][1] is not None and psw[d][2] is not None)
    if pk:
        a0, a1 = psw[pk[0]], psw[pk[-1]]
        rep.add("NK-10: Pieniadz swiata - bandy maleja, kryjowki i inne rosna, suma bez skoku (INFO)",
                f"dzien {pk[0]} -> {pk[-1]}: bandy {a0[2]} -> {a1[2]}, kryjowki i inne {a0[1]} -> {a1[1]}, razem {a0[0]} -> {a1[0]}"
                f" (bandy + kryjowki {a0[1] + a0[2]} -> {a1[1] + a1[2]})", "INFO", None)
    else:
        rep.add("NK-10: Pieniadz swiata", "brak linii", "INFO", None)
    # NK-11 linia Paser - bilans kas kryjowek
    pk2 = sorted(d for d in paser if paser[d][0])
    rs = []
    for a, b in zip(pk2, pk2[1:]):
        if b != a + 1:
            continue
        A, B = paser[a][0], paser[b][0]
        rs.append((b, (B[4] - A[4]) - (B[0] - B[1])))
    badp = [x for x in rs if x[1] != 0]
    tap = any(paser[d][1] for d in pk2)
    rep.add("NK-11: linia Paser - stan kas kryjowek = doplyw - odplyw (jak roz/nskarbiec/resid.py)",
            f"par dob {len(rs)}, r != 0 w {len(badp)}" + (f": {badp[:8]}" if badp else "") + ("; kurek kryjowek otwarty" if tap else ""),
            "0 dob (twardy; kurek kryjowek otwarty - INFO)", (len(badp) == 0) if (rs and not tap) else None)
    rep.show()
    return 0


# ------------------------------------------------------------ ndrobne (noc-drobne 16.10: OB6 oboz bez sily - Armoury SiegePhantomLift; AUD-P1-5 dorobka tytulow wsi BK - CrashScribe)
ND_START = re.compile(r"Oboz bez sily \(OB6\): start sesji \| klucz SiegePhantomLift (tak|nie), dob (\d+), ponizej (\d+) zdolnych do walki \| pomijane: .*?\(wpiete (\d+)/(\d+)([^)]*)\)")
ND_DAY = re.compile(r"Oboz bez sily \(OB6\): dzien (\d+) \| obozow ponizej (\d+) zdolnych do walki(?: \(albo sila obozu < \d+\))? (\d+)(?: \[(.*)\])? \| zdjete dzis (\d+) \(od sesji (\d+)\),"
                    r" druzyn odeslanych (\d+), oblezen nadal trwajacych po zdjeciu (\d+) \| pominiete: gracz (\d+), fabula ROT (\d+), Inni (\d+), w bitwie (\d+) \| potkniecia (\d+)"
                    r" \(sesja (\d+)\)(?: \| droga zapasowa (\d+))?\.")
ND_FB = re.compile(r"droga zapasowa RemoveSiegePartyInternal (wpieta|BRAK)")
ND_ROW = re.compile(r"([^;\[]+?) \(([^()\s]+)\): druzyn (\d+), zdrowi (\d+), ranni (\d+), sila (-?\d+), dob (\d+)(.*?)(?=; [^;]+? \([^()\s]+\): druzyn |$)")
ND_OB5_END = re.compile(r"Odsiecz \(OB5\) koniec: dzien (\d+) \| .*? \(([^,()\s]+), (?:stolica|miasto|zamek)\) .*\| wynik: (\S+) \(([^)]*)\)\.")


def ndrobne_main(logp, csp=None):
    """ndrobne (noc-drobne 16.10; Armoury/src/SiegePhantomLift.cs, CrashScribe/src/BkTitles.cs). Log Armoury (strumieniowo) i opcjonalnie --crashscribe
    <session-*.log>. OB6 - oboz bez sily (klucze SiegePhantomLift / SiegePhantomLiftDays / SiegePhantomMinMen): ND-0 linia startu sesji (klucz tak,
    wpiete 4/4 typy oblezen fabuly ROT), ND-1 potkniecia 0 w liniach doby i 0 'ERROR in SiegePhantomLift', ND-2 kazdy oboz w liniach doby: 'dob' <=
    SiegePhantomLiftDays i 'oblezen nadal trwajacych po zdjeciu' 0 w kazdej linii (brak linii doby - INFO: zwykly bieg nie ma obozu bez ludzi),
    ND-3 zdjete i pominiete (gracz / fabula ROT / Inni / w bitwie) razem (INFO), ND-4 zwiniete oblezenie twierdzy krolestwa sledzonej przez OB5 -
    linia 'Odsiecz (OB5) koniec' tej samej doby z wynikiem 'utrzymane' (brak zwiniec - INFO). AUD-P1-5 (z --crashscribe; klucz BkTitlesVillageFix):
    ND-5 linia dorobki 'Mends: tytuly BK (AUD-P1-5)': zostalo 0, nie dodane 0, potkniec 0 w kazdej linii (klucz false - INFO z nazwami; brak linii -
    INFO). Log bez paczki: INFO, bez wyjatku."""
    rep = Report()
    armp = logp if logp and os.path.isfile(logp) and not os.path.basename(logp).lower().startswith("session-") else None
    if csp is None and logp and os.path.basename(logp).lower().startswith("session-"):
        csp = logp
    starts, days, errs, ob5_end, ob5_seen, fbw = [], [], 0, [], set(), []
    if armp:
        with open(armp, encoding="utf-8", errors="replace") as fh:
            for ln in fh:
                if "OB6" not in ln and "SiegePhantomLift" not in ln and "Odsiecz (OB5)" not in ln:
                    continue
                m = TS.match(ln.rstrip("\r\n"))
                s = m.group(2) if m else ln.rstrip("\r\n")
                if s.startswith("ERROR in SiegePhantomLift"):
                    errs += 1
                    continue
                mm = ND_START.search(s)
                if mm:
                    starts.append(mm.groups())
                    mf = ND_FB.search(s)
                    fbw.append(mf.group(1) if mf else None)   # None = linia sprzed poprawek recenzji (bez drogi zapasowej)
                    continue
                mm = ND_DAY.search(s)
                if mm:
                    days.append(mm.groups())
                    continue
                if s.startswith("Odsiecz (OB5) poczatek: dzien "):
                    mm = re.search(r"\| .*? \(([^,()\s]+), (?:stolica|miasto|zamek)\) krolestwa", s)
                    if mm:
                        ob5_seen.add(mm.group(1))
                    continue
                mm = ND_OB5_END.search(s)
                if mm:
                    ob5_end.append((int(mm.group(1)), mm.group(2), mm.group(3), mm.group(4)))
        print(f"plik: {armp} | OB6: linii startu {len(starts)}, linii doby {len(days)}, ERROR {errs}; OB5 koniec {len(ob5_end)}")
        if not starts and not days:
            rep.add("ND-0: (OB6) linia startu 'Oboz bez sily (OB6): start sesji'", "brak linii", "INFO (log bez paczki noc-drobne)", None)
        else:
            st = starts[-1] if starts else None
            on = st is not None and st[0] == "tak"
            need = int(st[1]) if st else 3
            if st is None:
                rep.add("ND-0: (OB6) linia startu", "brak linii startu (sa linie doby)", "linia przy kazdym starcie sesji", False)
            elif not on:
                rep.add("ND-0: (OB6) linia startu", f"klucz SiegePhantomLift nie (linii {len(starts)})", "INFO (klucz wylaczony = stan 39f8fe72)", None)
            else:
                fbl = fbw[-1] if fbw else None
                rep.add("ND-0: (OB6) linia startu - klucz tak, typy oblezen fabuly ROT wpiete 4/4, droga zapasowa wpieta",
                        f"linii {len(starts)}; ostatnia: dob {st[1]}, ponizej {st[2]} zdolnych, wpiete {st[3]}/{st[4]}{st[5]}"
                        + f", droga zapasowa RemoveSiegePartyInternal {fbl if fbl else '- (linia bez pola)'}",
                        "klucz tak, wpiete 4/4 (ROT 8.1.8), droga zapasowa wpieta (gra 1.4.8)", st[3] == st[4] == "4" and fbl != "BRAK")
            stl = sum(int(g[12]) for g in days)
            rep.add("ND-1: (OB6) potkniecia w liniach doby i ERROR in SiegePhantomLift", f"potkniecia (suma dob) {stl}, ERROR {errs}", "0, 0", stl == 0 and errs == 0)
            if not days:
                rep.add("ND-2: (OB6) obozy bez sily - doby <= SiegePhantomLiftDays, oblezen trwajacych po zdjeciu 0", "brak linii doby (zaden oboz ponizej progu)",
                        "INFO (zwykly bieg nie ma obozu bez ludzi; test 6-letni - 1 przypadek)", None)
            else:
                rows, over = [], []
                for g in days:
                    for r in ND_ROW.finditer(g[3] or ""):
                        rows.append((int(g[0]), r.group(2), int(r.group(7)), r.group(8)))
                        if int(r.group(7)) > need:
                            over.append(f"d{g[0]} {r.group(1).strip()} ({r.group(2)}) dob {r.group(7)}")
                still = sum(int(g[7]) for g in days)
                rep.add("ND-2: (OB6) obozy bez sily - doby <= SiegePhantomLiftDays, oblezen trwajacych po zdjeciu 0",
                        f"linii doby {len(days)}, wierszy obozow {len(rows)}, ponad {need} dob {len(over)}" + (f" ({'; '.join(over[:4])})" if over else "")
                        + f", oblezen nadal trwajacych po zdjeciu (suma) {still}",
                        f"dob <= {need}, nadal trwajacych 0", not over and still == 0)
            lifted = sum(int(g[4]) for g in days)
            sk = [sum(int(g[i]) for g in days) for i in (8, 9, 10, 11)]
            last = days[-1] if days else None
            fbn = sum(int(g[14]) for g in days if g[14])
            why = {}
            for g in days:
                for r in ND_ROW.finditer(g[3] or ""):
                    mw = re.search(r", powod ([a-z ]+?)(?: \(|,|$)", r.group(8))
                    if mw:
                        why[mw.group(1)] = why.get(mw.group(1), 0) + 1
            rep.add("ND-3: (OB6) zdjete i pominiete (INFO)",
                    f"zdjete razem {lifted}, druzyn odeslanych {sum(int(g[6]) for g in days)}, w tym droga zapasowa (RemoveSiegePartyInternal) {fbn}"
                    + (f"; powod (wiersze obozow): {', '.join(f'{k} {v}' for k, v in sorted(why.items()))}" if why else "")
                    + f"; pominiete (doby-oboz): gracz {sk[0]}, fabula ROT {sk[1]}, Inni {sk[2]}, w bitwie {sk[3]}"
                    + (f"; ostatnia linia d{last[0]}: {(last[3] or '-')[:300]}" if last else ""), "INFO", None)
            lifts = []
            for g in days:
                for r in ND_ROW.finditer(g[3] or ""):
                    if ", ZDJETE" in r.group(8):
                        lifts.append((int(g[0]), r.group(2)))
            if not lifts:
                rep.add("ND-4: (OB6) zwiniete oblezenie - OB5 koniec 'utrzymane'", "brak zwiniec", "INFO", None)
            else:
                chk, bad = 0, []
                for d, sid in lifts:
                    if sid not in ob5_seen:
                        continue
                    chk += 1
                    e = [x for x in ob5_end if x[1] == sid and d - 1 <= x[0] <= d + 1]
                    if not e or e[-1][2] != "utrzymane":
                        bad.append(f"d{d} {sid}: " + (f"{e[-1][2]} ({e[-1][3]})" if e else "brak linii OB5 koniec"))
                rep.add("ND-4: (OB6) zwiniete oblezenie twierdzy krolestwa - OB5 koniec 'utrzymane' tej doby",
                        f"zwiniec {len(lifts)}, sledzonych przez OB5 {chk}, zle {len(bad)}" + (f" ({'; '.join(bad[:4])})" if bad else ""),
                        "kazde sledzone: 'utrzymane' (twierdza poza krolestwem / Inni - OB5 nie sledzi)", (len(bad) == 0) if chk else None)
    else:
        rep.add("ND-0..4: (OB6) log Armoury", f"brak ({logp})", "INFO (podaj <Armoury-*.log>)", None)
    # AUD-P1-5 z logu CrashScribe
    if csp and os.path.isfile(csp):
        vf = []
        with open(csp, encoding="utf-8", errors="replace") as fh:
            for ln in fh:
                if "AUD-P1-5" not in ln:
                    continue
                m = AU_VFIX.search(ln)
                if m:
                    vf.append(m.groups())
        print(f"plik: {csp} | AUD-P1-5: linii dorobki {len(vf)}")
        von = [v for v in vf if v[5] == "true"]
        if von:
            lv = von[-1]
            rep.add("ND-5: (AUD-P1-5) dorobka tytulow wsi BK - zostalo 0, nie dodane 0, potkniec 0",
                    f"linii {len(von)}; zostalo {[int(v[4]) for v in von]}, nie dodane {[int(v[2]) for v in von]}, potkniec {[int(v[7]) for v in von]}; ostatnia: przed {lv[0]},"
                    f" dorobione {lv[1]}, bez tytulu twierdzy {lv[3]}{lv[6][:240]}", "0, 0, 0 w kazdej linii",
                    all(int(v[4]) == 0 and int(v[2]) == 0 and int(v[7]) == 0 for v in von))
        elif vf:
            rep.add("ND-5: (AUD-P1-5) dorobka tytulow wsi BK", f"klucz BkTitlesVillageFix=false; {vf[-1][6][:240]}", "INFO (tylko nazwy)", None)
        else:
            rep.add("ND-5: (AUD-P1-5) dorobka tytulow wsi BK", "brak linii 'Mends: tytuly BK (AUD-P1-5)'", "INFO (log bez paczki albo czas gry nie ruszyl)", None)
    else:
        rep.add("ND-5: (AUD-P1-5) dorobka tytulow wsi BK", "bez logu CrashScribe", "INFO (--crashscribe <session-*.log>)", None)
    rep.show()
    return 0



# ------------------------------------------------------------ nharmony (15.10 noc, pulapka Harmony "czynnego modelu" - SmithWood; Armoury/src/PatchTarget.cs)
NH_HEAD = "Latki czynnego modelu (HT): "
NH_MODELS = re.compile(r"czynne modele: wpiete (\d+) z (\d+) \(na metodzie typu czynnego (\d+), przez klase deklarujaca (\d+)(?:: (.*?))?\), bez proby (\d+)")
NH_MNO = re.compile(r", NIE (\d+)(?:: (.*))?$")
NH_GUARD = re.compile(r"straznik Harmony (.+?): nasze proby (\d+), udane (\d+), NIE (\d+)")
NH_FIXED = re.compile(r"; poprawione na klase deklarujaca (\d+)(?:: (.*?))?(?:; nasze z typem|; dubel |; cudze z typem|$)")
NH_UNFIX = re.compile(r"; nasze z typem pochodnym bez poprawki (\d+)(?:: (.*?))?(?:; dubel |; cudze z typem|$)")
# poprawki po recenzji (uwagi 1 i 2): dubel latki i zdejmowanie latek (Unpatch) z typem pochodnym
NH_DUP = re.compile(r"; dubel (\d+)(?:: (.*?))?(?:; cudze z typem|$)")
NH_UNP = re.compile(r"^Unpatch z typem pochodnym: nasze poprawione (\d+)(?:: (.*?))?, nasze bez poprawki (\d+)(?:: (.*?))?, cudze (\d+)(?:: (.*))?$")
NH_FOREIGN = re.compile(r"; cudze z typem pochodnym (\d+)(?:: (.*?))?(?:; nasze z celem null|$)")
NH_STUM = re.compile(r"^potkniecia (\d+)\.?$")
NH_WOOD = re.compile(r"koszt drewna przy zapasie 50 kg (-?\d+|\?) \(oczekiwane 0\)")


def nharmony_main(logp, need=False):
    """nharmony (15.10 noc, pulapka Harmony "czynnego modelu" - drewno w kuzni; Armoury/src/PatchTarget.cs, galaz w-toku/noc-harmony). Wejscie: log Armoury.
    NH-0 straznik na PatchProcessor.Patch wpiety (linia przy starcie gry) i linia "Latki czynnego modelu (HT): start sesji" w kazdej sesji (klucz TAK);
    NH-1 czynne modele: wpiete N z R, N = R i R >= 8 (zestaw Jeffa 9) w kazdej sesji; NH-2 przez klase deklarujaca M (INFO, oczekiwane 1 - drewno);
    NH-3 straznik: nasze proby P = udane W, NIE 0, P > 0; NH-4 poprawione na klase deklarujaca K = 0 (K > 0 = DECYZJA: latka ozyla - linia szukania
    celu do przerobienia na PatchTarget.OfActive, sprawdzic zasada 4), z kluczem TAK nasze bez poprawki 0; NH-5 cudze z typem pochodnym (INFO);
    NH-6 samosprawdzenie drewna: koszt przy zapasie 50 kg = 0 w kazdej sesji, linia startu drewna bez BRAK / wyjatek; NH-7 potkniecia 0
    i ERROR in PatchTarget 0; NH-8 linie "po starcie": NIE i dubel 0 (poprawiona, Unpatch poprawiony, cudzy Unpatch = DECYZJA); NH-9 lancuchy
    modeli (INFO). Poprawki po recenzji: NH-0c format linii (dubel, Unpatch), NH-4c nasz Unpatch z typem pochodnym poprawiony 0 (> 0 = DECYZJA,
    bez poprawki przy kluczu TAK = NIE), NH-4d dubel 0 (> 0 = NIE), NH-5b cudzy Unpatch z typem pochodnym 0 (> 0 = DECYZJA).
    Log bez linii HT: INFO, bez wyjatku; need (--wymagaj-ht, autotest tej galezi): brak linii HT albo stary format = NIE.
    Poza logiem (recznie): BKROTLog.txt bez "Caught ArgumentException when patching"."""
    rep = Report()
    if not logp or not os.path.isfile(logp):
        rep.add("NH-0: log Armoury", f"brak pliku {logp}", "podaj <Armoury-*.log>", None)
        rep.show()
        return 0
    starts, guards, late, woods, wstarts = [], [], [], [], []
    errs = 0
    with open(logp, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\n"))
            s = m.group(2) if m else ln.rstrip("\n")
            if s.startswith(NH_HEAD):
                rest = s[len(NH_HEAD):]
                if rest.startswith("start sesji"):
                    starts.append(s)
                elif rest.startswith("straznik Harmony "):
                    guards.append(s)
                elif rest.startswith("po starcie - "):
                    late.append(s)
            elif s.startswith("Drewno w kuzni (kg) - samosprawdzenie:"):
                woods.append(s)
            elif s.startswith("Drewno w kuzni (kg): start sesji"):
                wstarts.append(s)
            elif s.startswith("ERROR in PatchTarget"):
                errs += 1
    print(f"plik: {logp} | linii straznika {len(guards)}, linii startu sesji {len(starts)}, linii 'po starcie' {len(late)}, samosprawdzen drewna {len(woods)}")
    if not starts and not guards:
        if need:
            rep.add("NH-0a: straznik na PatchProcessor.Patch (start gry)", "brak linii straznika", "linia jest (--wymagaj-ht: autotest tej galezi)", False)
            rep.add("NH-0b: linia startu sesji (HT) w kazdej sesji", "brak linii", ">= 1 (--wymagaj-ht)", False)
        else:
            rep.add("NH-0: linie HT (latki czynnego modelu)", "brak linii", "INFO (wersja sprzed HT; autotest tej galezi: --wymagaj-ht)", None)
        rep.show()
        return 0
    g = guards[-1] if guards else ""
    rep.add("NH-0a: straznik na PatchProcessor.Patch (start gry)", g[len(NH_HEAD):][:200] if g else "brak linii straznika",
            "linia jest, 'straznik Harmony wpiety'", bool(g) and g.startswith(NH_HEAD + "straznik Harmony wpiety"))
    on_all = all("| klucz PatchTargetGuard TAK" in s for s in starts)
    rep.add("NH-0b: linia startu sesji (HT) w kazdej sesji", f"linii {len(starts)}, klucz TAK we wszystkich: {'tak' if on_all else 'nie'}",
            ">= 1, klucz TAK", (len(starts) >= 1 and on_all) if (on_all or not starts) else None)
    if not starts:
        rep.show()
        return 0
    rows = []
    for s in starts:
        seg = s.split(" | ")
        mseg = next((x for x in seg if x.startswith("czynne modele: ")), "")
        gseg = next((x for x in seg if x.startswith("straznik Harmony ")), "")
        cseg = next((x for x in seg if x.startswith("lancuchy ")), "")
        sseg = next((x for x in seg if x.startswith("potkniecia ")), "")
        useg = next((x for x in seg if x.startswith("Unpatch z typem pochodnym: ")), "")
        a = NH_MODELS.match(mseg)
        b = NH_MNO.search(mseg)
        gg = NH_GUARD.match(gseg)
        fx = NH_FIXED.search(gseg)
        uf = NH_UNFIX.search(gseg)
        fo = NH_FOREIGN.search(gseg)
        st_ = NH_STUM.match(sseg)
        du = NH_DUP.search(gseg)
        un = NH_UNP.match(useg)
        rows.append(dict(
            ok=bool(a and b and gg),
            n=int(a.group(1)) if a else None, r=int(a.group(2)) if a else None, direct=int(a.group(3)) if a else None,
            via=int(a.group(4)) if a else None, vial=(a.group(5) or "") if a else "", none=int(a.group(6)) if a else None,
            no=int(b.group(1)) if b else None, nol=(b.group(2) or "") if b else "",
            gname=gg.group(1) if gg else "", p=int(gg.group(2)) if gg else None, w=int(gg.group(3)) if gg else None, gno=int(gg.group(4)) if gg else None,
            k=int(fx.group(1)) if fx else None, kl=(fx.group(2) or "") if fx else "",
            u=int(uf.group(1)) if uf else 0, ul=(uf.group(2) or "") if uf else "",
            c=int(fo.group(1)) if fo else None, cl=(fo.group(2) or "") if fo else "",
            chains=cseg, stum=int(st_.group(1)) if st_ else None, on="| klucz PatchTargetGuard TAK" in s,
            d=int(du.group(1)) if du else None, dl=(du.group(2) or "") if du else "",
            uf=int(un.group(1)) if un else None, ufl=(un.group(2) or "") if un else "", uu=int(un.group(3)) if un else 0,
            uul=(un.group(4) or "") if un else "", uc=int(un.group(5)) if un else 0, ucl=(un.group(6) or "") if un else ""))
    bad = [i + 1 for i, x in enumerate(rows) if not x["ok"]]
    if bad:
        rep.add("NH-1..NH-7: format linii startu sesji", f"nie do odczytu w sesjach {bad}", "kazda linia czytelna", False)
    rd = [x for x in rows if x["ok"]]
    if not rd:
        rep.show()
        return 0
    last = rd[-1]
    # NH-1
    ok1 = all(x["n"] == x["r"] and x["r"] >= 8 and x["no"] == 0 and x["none"] == 0 for x in rd)
    rep.add("NH-1: czynne modele - wpiete N z R (kazda sesja)",
            "; ".join(f"s{i + 1}: {x['n']} z {x['r']} (bez proby {x['none']}, NIE {x['no']})" for i, x in enumerate(rd))
            + (f" | NIE: {last['nol'][:300]}" if last["no"] else ""),
            "N = R, R >= 8 (zestaw Jeffa 9), bez proby 0, NIE 0", ok1)
    # NH-2
    rep.add("NH-2: przez klase deklarujaca (INFO)", f"{last['via']}" + (f": {last['vial'][:300]}" if last["vial"] else "") + f"; na metodzie typu czynnego {last['direct']}",
            "INFO (oczekiwane 1: drewno w kuzni BKSmithingModel -> DefaultSmithingModel)", None)
    # NH-3
    ok3 = all(x["gno"] == 0 and x["p"] == x["w"] and x["p"] > 0 for x in rd) and last["gname"] == "wpiety"
    rep.add("NH-3: straznik - nasze proby / udane / NIE", f"straznik {last['gname']}, proby {last['p']}, udane {last['w']}, NIE {last['gno']}"
            + (f" | {nh_gseg(starts[-1])}" if last["gno"] else ""), "wpiety, P = W > 0, NIE 0", ok3)
    # NH-4
    kmax = max((x["k"] or 0) for x in rd)
    rep.add("NH-4a: poprawione na klase deklarujaca", f"{kmax}" + (f": {last['kl'][:300]}" if last["kl"] else ""),
            "0 (> 0 = DECYZJA: martwa latka ozyla - przerobic linie szukania celu na PatchTarget.OfActive, sprawdzic ile pracy robi)",
            True if kmax == 0 else False, decide=kmax > 0)
    umax = max(x["u"] for x in rd)
    rep.add("NH-4b: nasze z typem pochodnym bez poprawki", f"{umax}" + (f": {last['ul'][:300]}" if last["ul"] else ""),
            "0 przy kluczu TAK (klucz NIE = INFO)", (umax == 0) if all(x["on"] for x in rd) else None)
    # NH-5
    rep.add("NH-5: cudze latki z typem pochodnym (INFO, bez zmian)", f"{last['c']}" + (f": {last['cl'][:300]}" if last["cl"] else ""), "INFO", None)
    # poprawki po recenzji: format (dubel, Unpatch), Unpatch nasz / cudzy, dubel
    new = [x for x in rd if x["d"] is not None and x["uf"] is not None]
    if need or new:
        rep.add("NH-0c: format linii HT (dubel, Unpatch - poprawki recenzji)", f"sesji z nowym formatem {len(new)} z {len(rd)}",
                "wszystkie (bez --wymagaj-ht stary format = INFO)", len(new) == len(rd))
    else:
        rep.add("NH-0c: format linii HT (dubel, Unpatch)", "stary format (bez pol dubel / Unpatch)", "INFO (wersja sprzed poprawek recenzji)", None)
    if new:
        ln_ = new[-1]
        ufmax = max(x["uf"] for x in new)
        uumax = max(x["uu"] for x in new)
        allon = all(x["on"] for x in new)
        if uumax > 0 and allon:
            ok4c, dec4c = False, False
        elif ufmax > 0:
            ok4c, dec4c = False, True
        elif uumax > 0:
            ok4c, dec4c = None, False
        else:
            ok4c, dec4c = True, False
        rep.add("NH-4c: nasz Unpatch z typem pochodnym", f"poprawione {ufmax}" + (f": {ln_['ufl'][:300]}" if ln_["ufl"] else "")
                + f"; bez poprawki {uumax}" + (f": {ln_['uul'][:200]}" if ln_["uul"] else ""),
                "0 (poprawione > 0 = DECYZJA: zdejmowanie dziala, linia szukania celu do przerobienia; bez poprawki > 0 przy kluczu TAK = NIE)",
                ok4c, decide=dec4c)
        dmax = max(x["d"] for x in new)
        rep.add("NH-4d: dubel - ta sama latka juz na celu (zerowana, biegnie 1x)", f"{dmax}" + (f": {ln_['dl'][:300]}" if ln_["dl"] else ""),
                "0 (> 0 = NIE: dwie linie szukania celu tej samej latki - jedna do usuniecia)", dmax == 0)
        ucmax = max(x["uc"] for x in new)
        rep.add("NH-5b: cudzy Unpatch z typem pochodnym (bez zmian)", f"{ucmax}" + (f": {ln_['ucl'][:300]}" if ln_["ucl"] else ""),
                "0 (> 0 = DECYZJA: taki Unpatch wylacza WSZYSTKIE latki tej metody, nasze tez, do nastepnej latki - czy poprawiac tez cudze)",
                True if ucmax == 0 else False, decide=ucmax > 0)
    # NH-6
    vals = []
    for s in woods:
        mm = NH_WOOD.search(s)
        vals.append(mm.group(1) if mm else "?")
    wbad = [s for s in wstarts if "BRAK" in s.split("| latki: ")[-1] or "wyjatek" in s.split("| latki: ")[-1]]
    if woods:
        rep.add("NH-6: drewno w kuzni - koszt przy zapasie 50 kg (samosprawdzenie, kazda sesja)", f"{vals}; linie startu drewna z BRAK / wyjatek {len(wbad)}",
                "0 w kazdej sesji (-1 = latka kosztu nie wolana), 0 linii z BRAK", all(v == "0" for v in vals) and not wbad)
    else:
        rep.add("NH-6: drewno w kuzni - samosprawdzenie", "brak linii", "INFO (klucz SmithWoodKg albo wersja sprzed)", None)
    # NH-7
    smax = max((x["stum"] or 0) for x in rd)
    rep.add("NH-7: potkniecia PatchTarget / ERROR in PatchTarget", f"potkniecia {smax}, ERROR {errs}", "0 / 0",
            smax == 0 and errs == 0 and all(x["stum"] is not None for x in rd))
    # NH-8
    lno = [s for s in late if s[len(NH_HEAD):].startswith("po starcie - NIE ") or "(dubel: " in s]
    lfix = [s for s in late if s[len(NH_HEAD):].startswith(("po starcie - poprawiona ", "po starcie - Unpatch poprawiony ", "po starcie - cudzy Unpatch "))]
    rep.add("NH-8a: linie 'po starcie' - NIE / dubel", f"{len(lno)}" + (f": {lno[0][len(NH_HEAD):][:240]}" if lno else ""), "0", len(lno) == 0)
    rep.add("NH-8b: linie 'po starcie' - poprawiona / Unpatch poprawiony / cudzy Unpatch", f"{len(lfix)}" + (f": {lfix[0][len(NH_HEAD):][:240]}" if lfix else ""),
            "0 (> 0 = DECYZJA jak NH-4a / NH-4c / NH-5b)", True if not lfix else False, decide=bool(lfix))
    # NH-9
    rep.add("NH-9: lancuchy modeli (INFO)", last["chains"][:400], "INFO", None)
    rep.show()
    return 0


def nh_gseg(s):
    seg = next((x for x in s.split(" | ") if x.startswith("straznik Harmony ")), "")
    return seg[:300]


# ------------------------------------------------------------ nsprzet (noc 15/16.10, Jeff 15.10 "rekrutuje ludzi, maja uzbrojenie, ktorego nie moga uzywac ... oddaj bron";
# galaz w-toku/noc-sprzet, Armoury/src/GearFit.cs + RecruitKit / VolunteerKit / GarrisonArmory / DragonUnmount, CrashScribe Mends.RealmWard)
NS_START = "GearFit (start sesji): "
NS_DAY = re.compile(r"^GearFit: dzien (\d+) \| ")
NS_REJ = re.compile(r"kandydatow odrzuconych (\d+) \(umiejetnosc (\d+), siodlo (\d+), kultura (\d+)\)")
NS_HAND = re.compile(r"szt\. (\d+), uzywalne (\d+), nieuzywalne (\d+) \(kupione -> notabl (\d+) za (\d+) zl, dobytek -> sakiewka ludzi (\d+) za (\d+) zl, "
                     r"na polke bez zaplaty (\d+)\), bez targu zostawione jak dotad (\d+)")
NSP_CTL = re.compile(r"do zbrojowni nieuzywalnych (\d+) \(ma byc 0\)")
# poprawki po recenzji (noc 15/16.10): braki ludzi gracza bez skutku (petla kupno -> skup), nadwyzki obcej kultury AI/zalog, dobytek zalog panu osady
NS_GAP = re.compile(r"\| braki ludzi gracza: kupione (\d+), kupione w \d+ dniach i nieuzyte \(wolne przy brakach albo sprzedane jako nadwyzka\) (\d+)")
NS_AIFOR = re.compile(r"sprzedane sztuki kultury, ktorej nie nosi nikt w partii: lordowie AI (\d+), zalogi (\d+)")
NS_LORD = re.compile(r"\(w tym x2 zalog bez sakiewki - panu osady (\d+) za (\d+) zl\)")
NS_PRE = re.compile(r"komplety DTE przed startem sesji bez filtra (\d+)")
NSP_STUM = re.compile(r"potkniecia (\d+) \(sesja (\d+)\)\.?$")
NS_FLOOR = re.compile(r"\| podloga broni \(GearFit[^)]*\): Twoi ludzie - bez broni po strazach (\d+), z polki (\d+) \(uzywalna (\d+), obca kultura (\d+), "
                      r"ponad umiejetnosc - ostatnia deska (\d+)\), nic w polce (\d+)")
NS_BARE = re.compile(r"Bitwa gracza \(sklad7b-p, start\): Twoich ludzi (\d+) - bez broni (\d+),")
NS_GUARD = re.compile(r"Bitwa gracza: straz nic z niczego przy spawnie - \S+ \(slot ([0-3]), druzyna gracza\)")
NS_VOL = re.compile(r"^Ochotnicy: dzien (\d+) - awanse z kupionym sprzetem (\d+)")
NS_WARD = re.compile(r"Straz unikatow: .*?(\d+) sztuk zza Waskiego Morza wroconych na polke, (\d+) potkniec \| zamiennik z polki \(GearFit\) (\d+), "
                     r"bez zamiennika \(slot pusty, podloga Armoury\) (\d+), ze wzorca \([^)]*\) (\d+)")
# GF-6: srednia "Ochotnicy: awanse z kupionym sprzetem" sprzed zmiany - bieg 6 lat (D:/Backup-Bannerlord/logs/2026-10-15-6lat/Armoury-2026-10-15_00-10-53.log,
# 212 dob: 134.5/d) i kampania Jeffa 15.10 (127 i 132/d) - 130; --baza-doby <log Armoury sprzed zmiany> liczy baze z tego logu
NS_VOL_BASE = 130.0
# czesc 2 (Jeff 15.10 a/b/c, Armoury/src/PlayerArmoryView.cs): zbrojownia gracza - czyje co jest
NS_ZB_START = "Zbrojownia gracza (15.10): start sesji"
NS_ZB_VIEW = re.compile(r"-> widoczne (\d+) \(oczekiwane (\d+); regula sprzed 15\.10: (\d+)\)")
NS_ZB_SWAP = re.compile(r"samosprawdzenie wymiany: zwrot (\S+) \(oczekiwane (\S+); regula sprzed 15\.10: (\S+)\), z wypartych (\d+) z (\d+), "
                        r"noszony wklad (\d+) \(oczekiwane 1\), czesci gracza w granicach (tak|NIE)")
NS_ZB_BUY = re.compile(r"^Sakiewka ludzi: gracz kupil od ludzi (\d+) szt\.")
NS_ZB_BACK = re.compile(r"; zwrot - wyparte \(stary sprzet ludzi\) (\d+), inne (\d+)\.?$")
NS_ZB_HORSE = re.compile(r"^Sakiewka ludzi: gracz w .* - nadwyzki (\d+) szt\. za (\d+) \(w tym konie (\d+) za (\d+)\)")
NS_ZB_ERR = ("ERROR in PlayerArmoryView", "ERROR in Escrow.Hold", "ERROR in QuartermasterLaw.PurgeUnusable", "ERROR in QuartermasterLaw.FitFor",
             "ERROR in Escrow.ProcessSwaps", "ERROR in Escrow.Release", "ERROR in MenPurse.OnEntered", "ERROR in MenPurse.OnDailyTickParty",
             "ERROR in MenPurse.SettlePlayerBook", "ERROR in MenUpgrade.ForPlayer")


class NsZbroj:
    """nsprzet czesc 2: linie zbrojowni gracza zbierane w tym samym przebiegu co czesc 1 (log 18 MB - jeden odczyt)."""
    def __init__(self):
        self.starts, self.errs, self.inv = [], 0, 0
        self.screens, self.hidden, self.buys, self.buys_after = 0, 0, 0, 0
        self.back_d, self.back_i, self.back_lines = 0, 0, 0
        self.sales, self.horses, self.horse_gold, self.nobuy = 0, 0, 0, 0

    def feed(self, s):
        if s.startswith(NS_ZB_START):
            self.starts.append(s)
        elif s.startswith("ERROR in "):
            if any(s.startswith(e) for e in NS_ZB_ERR):
                self.errs += 1
        elif s.startswith("Wymiana: NIEZMIENNIK"):
            if self.starts:
                self.inv += 1
        elif s.startswith("Wymiana: ekran zbrojowni - "):
            self.screens += 1
            if "(ukryty - widok tylko Twoje)" in s:
                self.hidden += 1
        elif s.startswith("Wymiana: ") and "; zwrot - wyparte" in s:
            mm = NS_ZB_BACK.search(s)
            if mm:
                self.back_lines += 1; self.back_d += int(mm.group(1)); self.back_i += int(mm.group(2))
        elif s.startswith("Sakiewka ludzi: gracz kupil od ludzi"):
            mm = NS_ZB_BUY.match(s)
            if mm and int(mm.group(1)) > 0:
                self.buys += 1
                if self.starts and "widok tylko Twoje tak (czynny tak)" in self.starts[-1]:
                    self.buys_after += 1
        elif s.startswith("Sakiewka ludzi: gracz w "):
            mm = NS_ZB_HORSE.match(s)
            if mm:
                self.sales += 1; self.horses += int(mm.group(3)); self.horse_gold += int(mm.group(4))
        elif s.startswith("Dozbrajanie: gracz w ") and " - bez zakupow:" in s:
            self.nobuy += 1

    def report(self, rep):
        st = self.starts[-1] if self.starts else ""
        if not st:
            rep.add("NS-10: linia 'Zbrojownia gracza (15.10): start sesji'", f"brak linii (otwarc zbrojowni {self.screens})", "INFO (wersja sprzed czesci 2)", None)
            return
        keys = ("widok tylko Twoje tak (czynny tak)", "zwrot starego sprzetu tak", "ludzie sprzedaja zbedne konie tak")
        off = [k for k in keys if k not in st]
        rep.add("NS-10: linia startu zbrojowni gracza (3 klucze, widok czynny)", f"linii {len(self.starts)}" + ("; klucze tak" if not off else "; NIE: " + ", ".join(off)),
                "3 klucze tak, widok czynny", not off)
        v = NS_ZB_VIEW.search(st)
        if v:
            rep.add("NS-11: samosprawdzenie widoku (5 szt.: noszone 2, Twoje 1)", f"widoczne {v.group(1)}, oczekiwane {v.group(2)} (regula sprzed 15.10: {v.group(3)})",
                    "widoczne == oczekiwane", v.group(1) == v.group(2))
        else:
            rep.add("NS-11: samosprawdzenie widoku", "brak pola w linii startu", "widoczne == oczekiwane", False)
        w = NS_ZB_SWAP.search(st)
        if w:
            ok = w.group(1) == w.group(2) and w.group(6) == "1" and w.group(7) == "tak" and (w.group(4) == w.group(5) or w.group(2) != "test_t2")
            rep.add("NS-12: samosprawdzenie wymiany (t2 noszone, t1 w zapasie, Twoj t4)",
                    f"zwrot {w.group(1)} (oczekiwane {w.group(2)}; sprzed 15.10 {w.group(3)}), z wypartych {w.group(4)} z {w.group(5)}, noszony wklad {w.group(6)}, w granicach {w.group(7)}",
                    "zwrot == oczekiwane, noszony 1, w granicach tak", ok)
        else:
            rep.add("NS-12: samosprawdzenie wymiany", "brak pola w linii startu", "zwrot == oczekiwane", False)
        rep.add("NS-13: ERROR zbrojowni gracza (PlayerArmoryView, Escrow, PurgeUnusable, FitFor, MenPurse wjazd/doba, MenUpgrade.ForPlayer)", f"{self.errs}", "0", self.errs == 0)
        rep.add("NS-14: 'Wymiana: NIEZMIENNIK' (czesc gracza, widok tylko Twoje)", f"{self.inv} po starcie", "0", self.inv == 0)
        if self.screens:
            rep.add("NS-15: okno zbrojowni - zapas ludzi ukryty, zakupy od ludzi przy widoku tylko Twoje",
                    f"otwarc {self.screens} (ukryty {self.hidden}), zakupow od ludzi > 0: {self.buys} (przy widoku czynnym {self.buys_after})",
                    "0 zakupow przy widoku czynnym", self.buys_after == 0)
        else:
            rep.add("NS-15: okno zbrojowni (widok tylko Twoje)", "okno nie otwarte w tym logu", "INFO (autotest nie otwiera zbrojowni)", None)
        if self.back_lines:
            need0 = "zwrot starego sprzetu tak" in st
            rep.add("NS-16: zwrot wymiany - wyparte (stary sprzet ludzi) / inne", f"linii {self.back_lines}: wyparte {self.back_d}, inne {self.back_i}",
                    "inne 0 (przy SwapReturnsTheirOldKit)" if need0 else "INFO (klucz wylaczony)", (self.back_i == 0) if need0 else None)
        else:
            rep.add("NS-16: zwrot wymiany", "brak wymiany z wkladem gracza w tym logu", "INFO (autotest nie wklada sprzetu)", None)
        rep.add("NS-17: konie w nadwyzkach ludzi gracza i dozbrajanie 'bez zakupow' (INFO)",
                f"wizyt z nadwyzkami {self.sales}: konie {self.horses} za {self.horse_gold}; linii 'bez zakupow' {self.nobuy}", "INFO", None)


def nsprzet_main(logp, csp, bdp):
    """nsprzet (noc 15/16.10; Armoury/src/GearFit.cs): sprzet WSZYSTKICH jednostek zgodny z umiejetnosciami i kultura + podloga broni w bitwie.
    Wejscie: log Armoury (strumieniowo), opcjonalnie --crashscribe <session-*.log> (NS-9) i --baza-doby <log Armoury sprzed zmiany> (NS-6).
    NS-0 linia startu (klucze Gear Fit Kits / Culture / Weapon Floor / Realm From Stores tak, wpiecia DTE i RealmWard CrashScribe tak),
    NS-1 wzorce: ponad umiejetnosc 0 (inaczej DECYZJA - sprawa SkillSinew / XML), NS-2 linia doby GearFit przy kazdej dobie z linia "Komplet rekruta: dzien",
    NS-3 kontrola "do zbrojowni nieuzywalnych 0" w kazdej dobie, NS-4 ksiega: nieuzywalne = x1 + x2 + x3 i szt. = uzywalne + nieuzywalne + bez targu,
    NS-5 potkniecia 0 i brak "ERROR in GearFit", NS-6 srednia "Ochotnicy: awanse z kupionym sprzetem" >= 50% bazy (DECYZJA ponizej), NS-7 udzial odrzucen
    (INFO), NS-8 bitwy gracza: "bez broni" <= "nic w polce" podlogi i zero linii "straz nic z niczego przy spawnie" dla slotow 0-3 druzyny gracza po starcie
    GearFit (bez bitew - INFO), NS-9 CrashScribe: w linii "Straz unikatow" zamiennik z polki + bez zamiennika + ze wzorca = sztuk zza morza (INFO bez logu).
    Log bez paczki: INFO, bez wyjatku."""
    rep = Report()
    if not logp or not os.path.isfile(logp):
        rep.add("NS-0: log Armoury", f"brak pliku {logp}", "podaj <Armoury-*.log>", None)
        rep.show()
        return 0
    starts, days, kom, vols, battles, errs = [], {}, set(), [], [], 0
    guard_after = 0
    seen_start = False
    zb = NsZbroj()   # czesc 2 (zbrojownia gracza) - ten sam przebieg
    with open(logp, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\n"))
            s = m.group(2) if m else ln.rstrip("\n")
            zb.feed(s)
            if s.startswith(NS_START):
                starts.append(s); seen_start = True
            elif s.startswith("GearFit: dzien "):
                mm = NS_DAY.match(s)
                if mm:
                    days[int(mm.group(1))] = s
            elif s.startswith("Komplet rekruta: dzien "):
                d = num(r"dzien (\d+)", s)
                if d is not None:
                    kom.add(d)
            elif s.startswith("Ochotnicy: dzien "):
                mm = NS_VOL.match(s)
                if mm:
                    vols.append(int(mm.group(2)))
            elif s.startswith("Bitwa gracza (sklad7b-p, start)"):
                battles.append(s)
            elif s.startswith("Bitwa gracza: straz nic z niczego przy spawnie") and seen_start:
                if NS_GUARD.search(s):
                    guard_after += 1
            elif s.startswith("ERROR in GearFit"):
                errs += 1
    print(f"plik: {logp} | linii startu {len(starts)}, linii doby {len(days)}, dob 'Komplet rekruta' {len(kom)}, linii Ochotnicy {len(vols)}, startow bitew {len(battles)}")
    if not starts and not days:
        rep.add("NS-0: linia startu GearFit", "brak linii", "INFO (wersja sprzed GearFit)", None)
        zb.report(rep)
        rep.show()
        return 0
    st = starts[-1] if starts else ""
    keys = ("Gear Fit Kits", "Gear Fit Culture", "Gear Fit Weapon Floor", "Gear Fit Floor Foreign", "Gear Fit Realm From Stores")
    off = [k for k in keys if (k + " tak") not in st]
    # "start sesji tak" (poprawka po recenzji): filtr kompletu t1 DTE czynny od OnSessionLaunched (GearFit.SessionStart); linia sprzed poprawki - bez pola
    wires = ("DTE GetRecruitEquipments tak", "podloga broni DoAssignAsync tak", "RealmWard z polki (CrashScribe) tak", "start sesji tak")
    miss = [w for w in wires if w not in st]
    rep.add("NS-0: linia startu (klucze i wpiecia)", ("klucze tak" if not off else "WYLACZONE: " + ", ".join(off)) + ("; wpiecia tak" if not miss else "; BRAK: " + ", ".join(miss)),
            "5 kluczy tak, 3 wpiecia i start sesji tak", bool(st) and not off and not miss)
    over = num(r"ponad umiejetnosc (\d+) \(ma byc 0\)", st) if st else None
    kin = num(r"\): (\d+) par", st) if st else None
    rep.add("NS-1: wzorce wojsk po prawach CS - sloty ponad umiejetnosc", f"{over} (par krewnych kultur {kin})", "0 (inaczej DECYZJA: SkillSinew / dane ROT)",
            (over == 0) if over is not None else None, decide=True)
    # NS-2 linia doby
    if kom:
        lo = min(kom)
        need = sorted(d for d in kom if d > lo)
        have = sum(1 for d in need if d in days or (d + 1) in days)
        rep.add("NS-2: linia 'GearFit: dzien' przy dobach z 'Komplet rekruta'", f"dob z kompletem (bez pierwszej) {len(need)}, z linia GearFit {have}, linii GearFit {len(days)}",
                "kazda doba", have == len(need) and len(days) > 0)
    else:
        rep.add("NS-2: linia 'GearFit: dzien'", f"linii {len(days)}, brak linii 'Komplet rekruta'", "INFO", None)
    ctl = sum(num(NSP_CTL.pattern, s, int, 0) or 0 for s in days.values())
    ctl_miss = sum(1 for s in days.values() if not NSP_CTL.search(s))
    rep.add("NS-3: kontrola 'do zbrojowni nieuzywalnych'", f"suma {ctl} w {len(days)} dobach (linii bez pola {ctl_miss})", "0", ctl == 0 and ctl_miss == 0 and len(days) > 0)
    bad, tot = [], [0] * 9
    for d, s in sorted(days.items()):
        h = NS_HAND.search(s)
        if not h:
            bad.append(d); continue
        v = [int(x) for x in h.groups()]
        for i, x in enumerate(v):
            tot[i] += x
        n, u, x, x1, g1, x2, g2, x3, k = v
        if x != x1 + x2 + x3 or n != u + x + k:
            bad.append(d)
    rep.add("NS-4: ksiega przekazania (nieuzywalne = x1 + x2 + x3; szt. = uzywalne + nieuzywalne + bez targu)",
            f"dob niezgodnych {len(bad)}" + (f" (np. {bad[:5]})" if bad else "") + f"; razem szt. {tot[0]}, uzywalne {tot[1]}, nieuzywalne {tot[2]} (notabl {tot[3]} za {tot[4]} zl, "
            f"sakiewka {tot[5]} za {tot[6]} zl, polka bez zaplaty {tot[7]}), bez targu {tot[8]}", "0 niezgodnych", len(bad) == 0 and len(days) > 0)
    stum = 0
    for s in days.values():
        mm = NSP_STUM.search(s)
        if mm:
            stum += int(mm.group(1))
    rep.add("NS-5: potkniecia GearFit / ERROR in GearFit", f"potkniecia {stum}, ERROR {errs}", "0 / 0", stum == 0 and errs == 0)
    # NS-6 awanse ochotnikow wobec bazy
    base, how = NS_VOL_BASE, "stala (bieg 6 lat 134.5/d, Jeff 127-132/d)"
    if bdp and os.path.isfile(bdp):
        bv = []
        with open(bdp, encoding="utf-8", errors="replace") as fh:
            for ln in fh:
                m = TS.match(ln.rstrip("\n"))
                s = m.group(2) if m else ln.rstrip("\n")
                mm = NS_VOL.match(s)
                if mm:
                    bv.append(int(mm.group(2)))
        if bv:
            base, how = sum(bv) / len(bv), f"--baza-doby ({len(bv)} dob)"
    if vols:
        avg = sum(vols) / len(vols)
        rep.add("NS-6: srednia 'Ochotnicy: awanse z kupionym sprzetem' wobec bazy", f"{avg:.1f}/d ({len(vols)} dob) wobec {base:.1f} ({how}) = {100.0 * avg / max(1e-9, base):.0f}%",
                ">= 50% (ponizej - DECYZJA: kandydaci t-1, ktorych zolnierz udzwignie)", avg >= 0.5 * base, decide=True)
    else:
        rep.add("NS-6: awanse ochotnikow", "brak linii Ochotnicy", "INFO", None)
    rj = [0, 0, 0, 0]
    for s in days.values():
        mm = NS_REJ.search(s)
        if mm:
            for i in range(4):
                rj[i] += int(mm.group(i + 1))
    if rj[0] > 0:
        rep.add("NS-7: odrzuceni kandydaci notabli (INFO)", f"{rj[0]}: umiejetnosc {100.0 * rj[1] / rj[0]:.0f}%, siodlo {100.0 * rj[2] / rj[0]:.0f}%, kultura {100.0 * rj[3] / rj[0]:.0f}%",
                "INFO", None)
    else:
        rep.add("NS-7: odrzuceni kandydaci notabli (INFO)", "0", "INFO", None)
    # NS-8 bitwy gracza
    fl = [s for s in battles if "| podloga broni (GearFit" in s]
    if fl:
        worse = []
        for s in fl:
            b = NS_BARE.search(s); f = NS_FLOOR.search(s)
            if not b or not f:
                worse.append("bez pol"); continue
            bare, none = int(b.group(2)), int(f.group(6))
            if bare > none:
                worse.append(f"bez broni {bare} > nic w polce {none}")
        rep.add("NS-8: bitwy gracza - bez broni tylko, gdy zbrojownia nie ma broni; straz 'nic z niczego' slotow 0-3 druzyny gracza",
                f"bitew {len(fl)}, niezgodnych {len(worse)}" + (f" ({worse[:3]})" if worse else "") + f"; linii strazy (sloty 0-3, gracz) po starcie GearFit {guard_after}",
                "0 niezgodnych, 0 linii strazy", not worse and guard_after == 0)
    else:
        rep.add("NS-8: bitwy gracza (podloga broni)", f"brak startow bitew z dopiskiem GearFit (startow bitew {len(battles)})", "INFO (autotest bez bitew gracza - ArmoryFit.cs:15)", None)
    # NS-9 CrashScribe
    if csp and os.path.isfile(csp):
        wl, wbad = 0, 0
        with open(csp, encoding="utf-8", errors="replace") as fh:
            for ln in fh:
                if "Straz unikatow:" not in ln:
                    continue
                mm = NS_WARD.search(ln)
                if not mm:
                    continue
                wl += 1
                k, stw, z, b, t = (int(x) for x in mm.groups())
                if z + b + t != k:
                    wbad += 1
        rep.add("NS-9: CrashScribe 'Straz unikatow' - zamiennik z polki + bez zamiennika + ze wzorca = zza morza", f"linii {wl}, niezgodnych {wbad}", "0 niezgodnych",
                (wbad == 0) if wl > 0 else None)
    else:
        rep.add("NS-9: CrashScribe 'Straz unikatow'", "brak --crashscribe", "INFO", None)
    # NS-18 (poprawka po recenzji, uwaga krytyczna): zakup braku ludzi gracza, ktorego nikt bez sztuki nie uzyje, wracal co dobe i szedl do kupca
    gb, gi, gmiss = 0, 0, 0
    for s in days.values():
        mm = NS_GAP.search(s)
        if not mm:
            gmiss += 1; continue
        gb += int(mm.group(1)); gi += int(mm.group(2))
    if gb > 0:
        rep.add("NS-18: braki ludzi gracza - kupione na brak i nieuzyte w 14 dniach (wolne przy brakach albo sprzedane jako nadwyzka)",
                f"kupione {gb}, nieuzyte {gi} (linii doby bez pola {gmiss})", "0 (wiecej - DECYZJA: petla kupno -> skup albo straty w bitwie; ids w linii doby)",
                gi == 0, decide=True)
    else:
        rep.add("NS-18: braki ludzi gracza (BuyPlayerGaps)", f"zakupow brakow 0 (linii doby bez pola {gmiss})", "INFO (autotest nie wjezdza druzyna do miasta)", None)
    af, gf, ln, lg, pre = 0, 0, 0, 0, None
    for s in days.values():
        mm = NS_AIFOR.search(s)
        if mm:
            af += int(mm.group(1)); gf += int(mm.group(2))
        mm = NS_LORD.search(s)
        if mm:
            ln += int(mm.group(1)); lg += int(mm.group(2))
    mm = NS_PRE.search(st) if st else None
    if mm:
        pre = int(mm.group(1))
    rep.add("NS-19: nadwyzki obcej kultury (AI / zalogi), dobytek zalog bez sakiewki panu osady, komplety DTE przed startem sesji (INFO)",
            f"sprzedane obcej kultury: lordowie AI {af}, zalogi {gf}; panu osady {ln} szt. za {lg} zl; przed startem sesji bez filtra {pre}", "INFO", None)
    zb.report(rep)   # czesc 2: NS-10..NS-17
    rep.show()
    return 0


