def nekon_main(logp):
    """nekon (noc 16.10, galaz noc-ekonomia: wegiel z waga gry, sol x3.5, futra x3, helmy plytowe jedna regula, bez kopalni BK w miastach, jednostka ladunku
    z zapisu, drewno kuzni w kg na ekranie i w naprawie). Wejscie: log Armoury (strumieniowo). NE-0 linia startu (klucze TAK, wegiel waga gry), NE-1 wegiel
    (bryla = waga gry, wegli z ladunku drewna = z wag, 4 przy 5 kg i 100 kg), NE-2 helmy plytowe (po: mediana t3 <= t4, k > 0), NE-3 jednostka ladunku (linia,
    potkniecia 0; MCM inny od kampanii - INFO), NE-4 kopalnie (latka wpieta, kolejnosc BK -> NoTownMines -> WorkshopInputs), NE-5 kuznia (ekran wpiety,
    samosprawdzenie naprawy 0 ladunkow), NE-6 linia doby w kazdej dobie i potkniecia 0, NE-7 futra (wywolania > 0 przy kluczu), NE-8 sol x3.5 w linii GL5
    (Salt Rate Raised i Goods Rates By Pattern), NE-9 wegiel w dobach = waga startu, NE-10 kopalnie zamienione (INFO), NE-11 kuznia w dobach (INFO),
    NE-12 ERROR 0. Log bez paczki: INFO, bez wyjatku. Poprawki po recenzji: NE-1 z perkiem CharcoalMaker 6 wegli, NE-1b wegiel broni i przetopu z ekranu kuzni
    z otwartej bryly (Smith Coal Kg: zapas 1 kg -> 0 bryl, 0 kg -> 1), NE-10 typ bez wsadu w okregu odlozony (INFO), NE-11 wegiel z otwartej bryly (INFO)."""
    rep = Report()
    if not logp or not os.path.isfile(logp):
        rep.add("NE-0: log Armoury", f"brak pliku {logp}", "podaj <Armoury-*.log>", None)
        rep.show()
        return 0
    last = {k: None for k in (NE_START, NE_COAL, NE_HELM, NE_BULK, NE_MINES, NE_FORGE)}
    days, bad, salt, errs = {}, [], {}, []
    coin, coinBad, pumps, cars, errs2 = {}, [], {}, {}, []   # cz. 2
    with open(logp, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\n"))
            s = m.group(2) if m else ln.rstrip("\n")
            if s.startswith(NE_COIN):
                dd = num(r"dzien (\d+)", s)
                a4, a6, a7, a8, ast = NE_C4.search(s), NE_C6.search(s), NE_C7.search(s), NE_C8.search(s), NE_CST.search(s)
                if dd is not None and a4 and a6 and a7 and a8 and ast:
                    a4b = NE_C4B.search(s)
                    coin[dd] = (a4.groups(), a6.groups(), a7.groups(), a8.groups(), int(ast.group(1)), a4b.groups() if a4b else None)
                else:
                    coinBad.append(s[:160])
                continue
            if s.startswith(NE_PUMP):
                dd = num(r"dzien (\d+)", s)
                if dd is not None:
                    pumps[dd] = s
                continue
            if s.startswith(NE_CAR):
                dd = num(r"dzien (\d+)", s)
                if dd is not None:
                    cars[dd] = s
                continue
            if s.startswith(NE_ERR2):
                errs2.append(s[:160])
            if s.startswith("Noc-ekonomia (NE): "):
                hit = False
                for k in last:
                    if s.startswith(k):
                        last[k] = s
                        hit = True
                        break
                if hit:
                    continue
                if s.startswith(NE_HEAD):
                    a = NE_DAY.search(s)
                    if a:
                        days[int(a.group("d"))] = a.groupdict()
                    else:
                        bad.append(s[:140])
            elif s.startswith("Stawki towarow (GL5): dzien "):
                d = num(r"dzien (\d+)", s)
                if d is not None:
                    salt[d] = s
            elif s.startswith(NE_ERR):
                errs.append(s[:160])
    st0 = last[NE_START]
    print(f"plik: {logp} | linii startu {'tak' if st0 else 'nie'}, linii doby {len(days)} (nierozpoznanych {len(bad)}), linii GL5 doby {len(salt)}")
    if not st0 and not days:
        rep.add("NE-0: linia startu noc-ekonomia", "brak linii", "INFO (wersja sprzed noc-ekonomia)", None)
        rep.show()
        return 0
    keys = {k: (st0 is not None and f"{k} TAK" in st0) for k in NE_KEYS}
    coal0 = st0 is not None and "Charcoal Weight Kg 0 (waga gry)" in st0
    rep.add("NE-0: linia startu (klucze TAK, Charcoal Weight Kg 0 = waga gry)", (st0[len(NE_START):].lstrip(" |")[:300] if st0 else "brak linii startu (sa linie doby)"),
            "linia jest, klucze TAK, wegiel z waga gry", bool(st0) and all(keys.values()) and coal0)
    c = last[NE_COAL]
    if c:
        bw = num(r"bryla ([\d.]+) kg", c, float)
        gw = num(r"waga gry ([\d.]+) kg\)", c, float)
        lw = num(r"ladunek drewna ([\d.]+) kg", c, float)
        got = num(r"-> wegli (-?\d+)", c)
        exp = num(r"oczekiwane (-?\d+)\)", c)
        cst = num(r"potkniecia (\d+)\.", c)
        perk = "perk CharcoalMaker TAK" in c
        four = not (bw == 5.0 and lw == 100.0) or got == (6 if perk else 4)
        rep.add("NE-1: wegiel (bryla = waga gry, wegli z ladunku drewna z modelu kuzni = z wag)", c[len(NE_COAL):].lstrip(" |")[:320],
                "bryla = waga gry (przy kluczu 0), wegli = oczekiwane > 0 (5 kg i ladunek 100 kg: 4, z perkiem CharcoalMaker 6), potkniecia 0",
                (bw is not None and gw is not None and (abs(bw - gw) < 0.01 or not coal0)) and got is not None and got > 0 and got == exp and four and cst == 0)
        # NE-1b (poprawka N2 po recenzji): bron i przetop z ekranu kuzni - 0.5 kg z otwartej bryly (samosprawdzenie: zapas 1 kg -> 0, zapas 0 kg -> -1)
        sc = re.search(r"wykucie przy zapasie 1 kg (-?\d+), przy 0 kg (-?\d+); przetop przy 1 kg (-?\d+), przy 0 kg (-?\d+)", c)
        hk = re.search(r"latki (koszt [^,]+, pobranie [^,]+, przetop [^,]+, pobranie [^,]+, ekran kucia [^,]+), samosprawdzenie", c)
        if "Smith Coal Kg TAK" in c:
            ok1 = bool(sc) and [int(x) for x in sc.groups()] == [0, -1, 0, -1] and bool(hk) and "BRAK" not in hk.group(1) and "wyjatek" not in hk.group(1)
            rep.add("NE-1b: wegiel broni i przetopu z ekranu kuzni w kg (Smith Coal Kg)", (sc.group(0) if sc else "brak samosprawdzenia") + "; latki " + (hk.group(1) if hk else "?"),
                    "wykucie i przetop: zapas 1 kg -> 0 bryl, 0 kg -> 1 bryla; latki bez BRAK", ok1)
        else:
            rep.add("NE-1b: wegiel broni z ekranu kuzni (Smith Coal Kg)", "klucz NIE albo linia sprzed poprawki", "INFO", None)
    else:
        rep.add("NE-1: wegiel", "brak linii", "linia jest", False)
    h = last[NE_HELM]
    if h:
        k = num(r"k ([\d.]+) kg na punkt", h, float)
        ok34 = "po: t3 <= t4 TAK" in h
        hst = num(r"potkniecia (\d+)\.", h)
        rep.add("NE-2: helmy plytowe (po: mediana t3 <= t4; k > 0)", h[len(NE_HELM):].lstrip(" |")[:420], "t3 <= t4 TAK, k > 0, potkniecia 0 (klucz wylaczony - INFO)",
                (ok34 and (k or 0) > 0 and hst == 0) if keys.get("Helm One Rule") else None)
    else:
        rep.add("NE-2: helmy plytowe", "brak linii", "linia jest", False)
    b = last[NE_BULK]
    if b:
        bst = num(r"potkniecia (\d+)\.", b)
        ign = "ignored, campaign uses" in b
        rep.add("NE-3: jednostka ladunku (czynnik kampanii, potkniecia 0)", b[len(NE_BULK):].lstrip(" |")[:260],
                "linia jest, potkniecia 0 (MCM inny niz kampania: linia 'ignored' - INFO w wartosci)", bst == 0)
        rep.add("NE-3b: suwak MCM inny niz czynnik kampanii (INFO)", "tak - " + b[b.find("MCM"):][:120] if ign else "nie", "INFO", None)
    else:
        rep.add("NE-3: jednostka ladunku", "brak linii", "linia jest", False)
    mi = last[NE_MINES]
    if mi:
        wired = "latka wpiete" in mi
        o = mi[mi.find("DecideBestWorkshopType: ") + 24:] if "DecideBestWorkshopType: " in mi else ""
        ib = o.find("WorkshopsCampaignBehaviorPatches.DecideBestWorkshopTypePostfix")   # BK EconomyPatches (klasa zagniezdzona) - postfiks z kopalnia
        iu, iw = o.find("NoTownMines.Postfix"), o.find("WorkshopInputs.DecidePostfix")
        order = iu >= 0 and (ib < 0 or ib < iu) and (iw < 0 or iu < iw)
        rep.add("NE-4: kopalnie - latka wpieta, kolejnosc postfiksow BK -> NoTownMines -> WorkshopInputs", mi[len(NE_MINES):].lstrip(" |")[:420]
                + ("" if ib >= 0 else " [postfiksu BK nie ma na liscie]"),
                "wpiete, NoTownMines po BK (EconomyPatches.WorkshopsCampaignBehaviorPatches) i przed WorkshopInputs", (wired and order) if keys.get("No Town Mines") else None)
    else:
        rep.add("NE-4: kopalnie", "brak linii", "linia jest", False)
    fo = last[NE_FORGE]
    if fo:
        scr = "ekran kucia wpiete" in fo
        # noc 16.10: linia NE pisana PRZED SmithWood.SessionStart (stan "nie wpiete" zawsze) - stan latki z linii "Drewno w kuzni (kg): start sesji"
        if not scr:
            try:
                for _ln in open(logp, encoding="utf-8", errors="replace"):
                    if "Drewno w kuzni (kg): start sesji" in _ln and "ekran kucia wpiete" in _ln: scr = True
            except Exception:
                pass
        pr = num(r"ladunkow (\d+) \(regula kg", fo)
        rep.add("NE-5: kuznia - ekran kucia wpiety, samosprawdzenie naprawy (otwarty 1 kg) 0 ladunkow", fo[len(NE_FORGE):].lstrip(" |")[:320],
                "wpiete; ladunkow 0 przy Self Mend Wood Kg (brak sztuki do proby - INFO)",
                (scr and (pr == 0 if pr is not None else True)) if keys.get("Smith Wood On Screen") and keys.get("Self Mend Wood Kg") else None)
    else:
        rep.add("NE-5: kuznia", "brak linii", "linia jest", False)
    ds = sorted(days)
    if ds:
        miss = [d for d in range(ds[0], ds[-1] + 1) if d not in days]
        stum = sum(int(days[d]["st"]) for d in ds)
        rep.add("NE-6: linia doby w kazdej dobie, potkniecia 0", f"dob {len(ds)} (d{ds[0]}-d{ds[-1]}), brak {len(miss)}" + (f" np. {miss[:4]}" if miss else "")
                + f", nierozpoznanych {len(bad)}" + (f" np. {bad[0]}" if bad else "") + f", potkniecia {stum}", "brak 0, nierozpoznanych 0, potkniecia 0",
                not miss and not bad and stum == 0)
        fur = sum(int(days[d]["fur"]) for d in ds)
        trap = max(int(days[d]["trap"]) for d in ds)
        furOn = all(days[d]["furOn"] == "TAK" for d in ds)
        rep.add("NE-7: futra - wywolania czynnika x3 we wsiach traperskich", f"wsi traperskich {trap}, wywolan {fur} w {len(ds)} dobach ({fur / len(ds):.0f}/d)",
                "> 0 przy Fur Rate Raised TAK", (fur > 0 and trap > 0) if furOn else None)
        coal = {days[d]["coal"] for d in ds}
        bw = num(r"bryla ([\d.]+) kg", c, float) if c else None
        rep.add("NE-9: wegiel w dobach = waga startu", f"wagi w dobach {sorted(coal)}; start {bw}", "jedna waga = start",
                len(coal) == 1 and bw is not None and abs(float(next(iter(coal))) - bw) < 0.01 if "-" not in coal else False)
        sw = sum(int(days[d]["swaps"]) for d in ds)
        pk = sum(int(days[d]["picks"]) for d in ds)
        kp = sum(int(days[d]["kept"]) for d in ds)
        ex = [days[d]["ex"] for d in ds if days[d]["ex"]]
        gt = sum(int(days[d]["gated"] or 0) for d in ds)
        rep.add("NE-10: kopalnie w miastach - zamienione na inny typ (INFO)", f"wyborow typu w miastach {pk}, kopalnia -> inny typ {sw}, kopalnia zostala {kp}, typ bez wsadu w okregu odlozony {gt}"
                + (f"; np. {ex[0][:160]}" if ex else ""), "INFO (zamiany tylko przy bankructwie / zmianie wlasciciela)", None)
        hn = sum(int(days[d]["hints"]) for d in ds)
        mu = sum(int(days[d]["mend"]) for d in ds)
        mk = sum(float(days[d]["mendKg"]) for d in ds)
        ml = sum(int(days[d]["mendL"]) for d in ds)
        cn = sum(int(days[d]["coalN"] or 0) for d in ds)
        ckg = sum(float(days[d]["coalKg"] or 0) for d in ds)
        cl = sum(int(days[d]["coalL"] or 0) for d in ds)
        rep.add("NE-11: kuznia w dobach - podpowiedzi drewna, czesci z drewnem w kg, wegiel z otwartej bryly (INFO)", f"podpowiedzi {hn}, czesci {mu} (kg {mk:.1f}, ladunkow {ml});"
                f" wegiel broni i przetopu {cn} (kg {ckg:.1f}, bryl {cl})", "INFO", None)
    else:
        rep.add("NE-6: linia doby", f"brak linii doby (nierozpoznanych {len(bad)})" + (f" np. {bad[0]}" if bad else ""), "linie doby sa", False)
    sd = sorted(salt)
    if sd and keys.get("Salt Rate Raised"):
        on = [d for d in sd if "Goods Rates By Pattern tak" in salt[d]]
        x35 = [d for d in on if "sol x3.5" in salt[d]]
        rep.add("NE-8: sol x3.5 w linii GL5 (Salt Rate Raised, Goods Rates By Pattern)", f"dob GL5 z kluczem {len(on)}, z x3.5 {len(x35)}", "wszystkie doby z kluczem: x3.5",
                (len(on) == len(x35)) if on else None)
    else:
        rep.add("NE-8: sol x3.5", f"linii GL5 {len(sd)}; Salt Rate Raised {'TAK' if keys.get('Salt Rate Raised') else 'NIE'}", "INFO", None)
    rep.add("NE-12: ERROR noc-ekonomia (NightEcon, NoTownMines, BulkUnit, arm_bulk_unit, ekran kucia, drewno naprawy, GoodsRates.ProdStep, FixCharcoalWeight)",
            f"{len(errs)}" + (f" np. {errs[0]}" if errs else ""), "0", not errs)
    nekon2_rows(rep, st0, coin, coinBad, pumps, cars, errs2)
    rep.show()
    return 0


def nekon2_rows(rep, st0, coin, coinBad, pumps, cars, errs2):
    """nekon cz. 2 (noc 16.10, obieg zlota; Armoury/src/MoneyLedger.Pumps.cs, NightEcon.cs, TownFolk.CraftSale.cs, Sutlers.cs, TownFolk.Guard.cs, TownFolk.Loans.cs):
    NE-13 klucze cz. 2 TAK w linii startu, NE-14 "Pompy - sztuczne przelewy" w kazdej dobie i potkniecia 0 (razem, % zoldu, pierwsza / ostatnia doba - INFO),
    NE-15 "Karawany - zapas wedlug towaru" (dni w jukach i na polkach, ostatnia doba - INFO), NE-16 linia obieg zlota w kazdej dobie, rozpoznana, potkniecia 0,
    NE-17 N4 doplata zaplacona <= stara regula + 5% (suma dob, klucz TAK), NE-17b N4 kontrola polki (do puli w wyrobie do miasta <= przyrost polki, poprawka po
    recenzji: dubli zdarzen gry nie liczymy), NE-18 N6 bez skoku przy rozruchu (pierwsza doba z kluczem: nowa <= stara x 1.2 + 1000),
    NE-19 N7 mnoznik bez pamieci = clamp(1 + 8 x (lud/poziom - 1.5), 0.25, 10) +- 0.01 w kazdej dobie, gdy liczyl, NE-20 N8 (INFO), NE-21 ERROR cz. 2 = 0."""
    if not coin and not pumps and not cars and not (st0 and "Folk Craft Wage On Sale" in st0):
        rep.add("NE-13: noc-ekonomia cz. 2 (obieg zlota)", "brak linii cz. 2", "INFO (wersja sprzed cz. 2)", None)
        return
    keys2 = {k: (st0 is not None and f"{k} TAK" in st0) for k in NE_KEYS2}
    rep.add("NE-13: klucze cz. 2 w linii startu (Folk Craft Wage On Sale, Sutlers By Purse, Folk Guard No Memory, Folk Loan Before Guard)",
            ", ".join(f"{k} {'TAK' if v else 'NIE'}" for k, v in keys2.items()) if st0 else "brak linii startu", "wszystkie TAK poza Folk Guard No Memory (DECYZJA CLAUDE noc 16.10: N7 domyslnie NIE)", bool(st0) and all(v for k, v in keys2.items() if k != "Folk Guard No Memory"))
    # NE-14 pompy
    pd = sorted(pumps)
    if pd:
        miss = [x for x in range(pd[0], pd[-1] + 1) if x not in pumps]
        stp = sum(num(r"\| potkniecia (\d+)\.$", pumps[x], int, 0) for x in pd)
        rep.add("NE-14: linia 'Pompy - sztuczne przelewy (nekon)' w kazdej dobie, potkniecia 0", f"dob {len(pd)} (d{pd[0]}-d{pd[-1]}), brak {len(miss)}, potkniecia {stp}",
                "brak 0, potkniecia 0", not miss and stp == 0)
        vals = [(x, NE_P.search(pumps[x])) for x in pd]
        vals = [(x, int(a.group(1)), a.group(2)) for x, a in vals if a]
        if vals:
            f0, f1 = vals[0], vals[-1]
            avg = sum(v[1] for v in vals) / len(vals)
            sl = pumps[pd[-1]]
            us = sl[sl.find("uspione (0 dzis): ") + 18:].split(" | ")[0] if "uspione (0 dzis): " in sl else "-"
            rep.add("NE-14b: przymus na dobe - razem i % zoldu (INFO)", f"srednio {avg:.0f} zl/d; d{f0[0]} {f0[1]} ({f0[2]}% zoldu) -> d{f1[0]} {f1[1]} ({f1[2]}% zoldu); uspione: {us[:160]}",
                    "INFO (cel: maleje, gdy ujscia naturalne dzialaja)", None)
    else:
        rep.add("NE-14: linia 'Pompy - sztuczne przelewy (nekon)'", "brak linii", "linia jest (od drugiej doby ksiegi pieniadza)", False)
    # NE-15 karawany
    cd = sorted(cars)
    if cd:
        sl = cars[cd[-1]]
        parts = [f"{a.group(1)}: karawany {a.group(2)} ({a.group(3)} dni) / miasta {a.group(4)} ({a.group(5)} dni)" for a in NE_CARI.finditer(sl)]
        rep.add("NE-15: karawany - zapas wedlug towaru, ostatnia doba (INFO)", (f"d{cd[-1]}: " + "; ".join(parts)) if parts else sl[:200],
                "INFO (linia w kazdej dobie ksiegi towarow)", None)
    else:
        rep.add("NE-15: linia 'Karawany - zapas wedlug towaru (nekon)'", "brak linii", "linia jest", False)
    # NE-16 linia obieg zlota
    od = sorted(coin)
    if not od:
        rep.add("NE-16: linia obieg zlota (N4 N6 N7 N8)", f"brak rozpoznanych linii (nierozpoznanych {len(coinBad)})" + (f" np. {coinBad[0]}" if coinBad else ""), "linie sa", False)
    else:
        miss = [x for x in range(od[0], od[-1] + 1) if x not in coin]
        stc = sum(coin[x][4] for x in od)
        rep.add("NE-16: linia obieg zlota w kazdej dobie, rozpoznana, potkniecia 0", f"dob {len(od)} (d{od[0]}-d{od[-1]}), brak {len(miss)}, nierozpoznanych {len(coinBad)}, potkniecia {stc}",
                "brak 0, nierozpoznanych 0, potkniecia 0", not miss and not coinBad and stc == 0)
        # NE-17 N4
        on4 = [x for x in od if coin[x][0][0] == "TAK"]
        if on4:
            paid = sum(int(coin[x][0][8]) for x in on4)
            old = sum(int(coin[x][0][9]) for x in on4)
            made = sum(int(coin[x][0][1]) for x in on4)
            sold = sum(int(coin[x][0][2]) for x in on4)
            pool = coin[on4[-1]][0][6]
            rep.add("NE-17: N4 doplata do 35% od sprzedanego <= stara regula + 5% (suma dob)", f"zaplacono {paid} ({paid / len(on4):.0f}/d), stara regula {old} ({old / len(on4):.0f}/d);"
                    f" wyroby wykonane {made}, zeszle z polki {sold}, pula ostatniej doby {pool}", "zaplacono <= stara x 1.05 + 100", paid <= old * 1.05 + 100)
        else:
            rep.add("NE-17: N4 doplata do 35% od sprzedanego", "klucz NIE w liniach doby", "INFO", None)
        # NE-17b (poprawka po recenzji): do puli tylko sztuki, ktore trafily na polke - w kazdym wywolaniu ProduceAnOutputToTown dopisane do puli <= przyrost polki
        on4b = [x for x in od if coin[x][0][0] == "TAK" and coin[x][5] is not None]
        if on4b:
            g = [coin[x][5] for x in on4b]
            wired = all(v[3] == "TAK" for v in g)
            dup, game, drop = sum(int(v[0]) for v in g), sum(int(v[1]) for v in g), sum(int(v[2]) for v in g)
            cin, csh, over, stale = sum(int(v[4]) for v in g), sum(int(v[5]) for v in g), sum(int(v[6]) for v in g), sum(int(v[7]) for v in g)
            rep.add("NE-17b: N4 do puli tylko sztuki na polce (kontrola polki: ponad przyrost 0, latki TAK)", f"dob {len(on4b)}, latki {'TAK' if wired else 'NIE'}; dubli gry pominietych {dup},"
                    f" sztuk gry bez BK {game}, zdjetych przez rzemieslnikow BK {drop}; do puli w wyrobie do miasta {cin} wobec przyrostu polek {csh}, ponad przyrost {over},"
                    f" oczekiwan bez zdarzenia {stale}", "latki TAK, ponad przyrost 0, oczekiwan bez zdarzenia 0", wired and over == 0 and stale == 0)
        else:
            rep.add("NE-17b: N4 kontrola polki", "klucz NIE albo linia sprzed poprawki", "INFO", None)
        # NE-18 N6
        on6 = [x for x in od if coin[x][1][0] == "TAK" and not coin[x][1][1]]
        if on6:
            f6 = coin[on6[0]][1]
            o0, n0 = int(f6[4]), int(f6[5])
            po = sum(int(coin[x][1][4]) for x in on6)
            pn = sum(int(coin[x][1][5]) for x in on6)
            idle = coin[on6[-1]][1][12]
            rel = sum(int(coin[x][1][13]) for x in on6)
            rep.add("NE-18: N6 markietani wedlug sakiewki - bez skoku pierwszej doby (rozruch)", f"pierwsza doba d{on6[0]} ({f6[3]}, udzial {f6[2]}): stara {o0}, nowa {n0};"
                    f" razem stara {po} / nowa {pn} ({(pn - po) / len(on6):+.0f}/d), nizszy limit K1 ostatniej doby {idle} partii, uwolnione {rel}",
                    "pierwsza doba: nowa <= stara x 1.2 + 1000", n0 <= o0 * 1.2 + 1000)
        else:
            rep.add("NE-18: N6 markietani wedlug sakiewki", "klucz NIE albo markietani nie biegli", "INFO", None)
        # NE-19 N7
        on7 = [x for x in od if coin[x][2][0] == "TAK" and not coin[x][2][1] and coin[x][2][2] != "-" and coin[x][2][3] != "-"]
        if on7:
            bad = []
            for x in on7:
                q, m, glo, ghi = float(coin[x][2][2]), float(coin[x][2][3]), float(coin[x][2][4]), float(coin[x][2][5])
                exp = max(glo, min(ghi, 1 + 8 * (q - 1.5)))
                if abs(exp - m) > 0.011:   # lud/poziom i mnoznik w linii z 3 miejscami po przecinku
                    bad.append((x, q, m, round(exp, 3)))
            plan = sum(int(coin[x][2][9]) for x in on7)
            pold = sum(int(coin[x][2][10]) for x in on7)
            l7 = coin[on7[-1]][2]
            rep.add("NE-19: N7 mnoznik bez pamieci = clamp(1 + 8 x (lud/poziom - 1.5), 0.25, max)", f"dob {len(on7)}, niezgodnych {len(bad)}" + (f" np. {bad[:3]}" if bad else "")
                    + f"; ostatnia: lud/poziom {l7[2]}, mnoznik {l7[3]} (stary {l7[6]}), stawka {l7[7]}%/d (stara {l7[8]}%/d); podatek {plan} wobec starej stawki {pold}",
                    "niezgodnych 0", not bad)
        else:
            rep.add("NE-19: N7 straznik bez pamieci", "klucz NIE albo regula nie liczyla (potrzeba ludu nieznana)", "INFO", None)
        # NE-20 N8
        on8 = [x for x in od if coin[x][3][0] == "TAK"]
        if on8:
            unl = sum(int(coin[x][3][2]) for x in on8)
            lent = sum(int(coin[x][3][5]) for x in on8)
            extra = sum(int(coin[x][3][6]) for x in on8)
            cred = sum(int(coin[x][3][8]) for x in on8)
            less = sum(int(coin[x][3][10]) for x in on8)
            rep.add("NE-20: N8 pozyczka przed darem (INFO)", f"dob {len(on8)}: kandydaci odblokowani migawka {unl}, pozyczone {lent} (ponad stara regule {extra}),"
                    f" zaliczone na podatek {cred}, podatek mniejszy o {less}", "INFO (pozyczki tylko w wojnie przy kiesie rodu ponizej rezerwy)", None)
        else:
            rep.add("NE-20: N8 pozyczka przed darem", "klucz NIE", "INFO", None)
    rep.add("NE-21: ERROR cz. 2 (CraftSale, arm_craft_sale, PumpsLine, Sutlers N6, HoardNote, LnSnapBegin, FolkLoanLend(N8), WatchCapture, CoinLine, CaravanLine)",
            f"{len(errs2)}" + (f" np. {errs2[0]}" if errs2 else ""), "0", not errs2)


# ============================================================ nekon2 (noc 16.10, galaz w-toku/noc-ekonomia2; raport audytu ekonomii 15.10 rozdz. 1.8 tabela
# "nie do wydania", 3.2 P1 jaja, P2 wariant prosty, P7 opal, P8 (b) budzet bez producenta; Armoury/src/VillageFruit.cs (jaja), MineralOnce.cs (lista BK),
# NoMakerBudget.cs, FibreToMarket.cs + MarketCarts.cs (Choose, SellPrefix/SellPostfix), TownFolk.Firewood.cs)
N2E_E1S = "Jaja wsi (N2-E1): start sesji"
N2E_E2S = "Budzet bez producenta (N2-E2): start sesji"
N2E_E3S = "Wlokno do miasta targowego (N2-E3): start sesji"
N2E_E4S = "Opal mieszczan (N2-E4): start sesji"
N2E_E1H = "Jaja wsi (N2-E1): dzien "
N2E_E2H = "Budzet bez producenta (N2-E2): dzien "
N2E_E3H = "Wlokno do miasta targowego (N2-E3): dzien "
N2E_E4H = "Opal mieszczan (N2-E4): dzien "
N2E_E1D = re.compile(r"^Jaja wsi \(N2-E1\): dzien (\d+) \| listy BK z jajami (\d+) \(wsi (\d+)\) \| baza dopisana w (\d+) pytaniach modelu \(tick BK, okna wsi\): "
                     r"jaja (\d+) .*\| potkniecia sesji (\d+)\.$")
N2E_E2D = re.compile(r"^Budzet bez producenta \(N2-E2\): dzien (\d+) \| (CZYNNE|WYLACZONE \(MCM\)) \| osad przeliczonych (\d+) \(zamkow (\d+)\) \| "
                     r"wierszy zrodel z niezaspokojonym budzetem (\d+) \| niezaspokojone \(budzet dnia\) (\d+), przeniesiono (\d+) \(zrodla: ([^)]*)\), "
                     r"zostalo w kategorii zrodla (\d+) \(bez miejsca na polce celu (\d+) wierszy\) .*?budzet BK celow \+(-?\d+) zl \| "
                     r"kontrola limitu celow: z dopisem (\d+), przekroczen (\d+)(?: \(najwiecej [\d.]+% nadwyzki\), przyciete \(indeks ceny rosnie z popytem\) \d+)? \| "
                     r"potkniecia (\d+) \(sesja (\d+)\)\.$")
N2E_E2MAX = re.compile(r"kontrola limitu celow: z dopisem \d+, przekroczen \d+ \(najwiecej ([\d.]+)% nadwyzki\), przyciete \(indeks ceny rosnie z popytem\) (\d+) \|")
N2E_E3D = re.compile(r"^Wlokno do miasta targowego \(N2-E3\): dzien (\d+) \| wozow z wloknem \(najlepsze miasto inne niz targowe\) sprawdzonych (\d+), "
                     r"zapas ponad \d+ dob (\d+) \(najwiekszy ([\d.]+) dob\) \| skierowane do miasta targowego (\d+) \(wsi zamkowych (\d+)\), wlokna w jukach (\d+) szt\., "
                     r"wycena ladunku w miescie targowym (\d+) d wobec najlepszego miasta (\d+) d \(wies traci (\d+) d\) \| bez miasta targowego w zasiegu (\d+), "
                     r"miasto targowe nic nie zaplaci (\d+)(?:, ten sam kurs wybrany drugi raz \(po zamku, bez licznika\) \d+)? \| sprzedaz w miescie celu: wozow (\d+), wlokna sprzedanego (\d+) szt\.(?: \([^)]*\))?, utarg tych wozow "
                     r"\(kasa miasta -> sakwa wozu, po zwrocie nadplaty 119\) (-?\d+) d \| w drodze (\d+), wygasle przy porzadkach (\d+) \| potkniecia (\d+) \(sesja (\d+)\)\.$")
N2E_E4D = re.compile(r"^Opal mieszczan \(N2-E4\): dzien (\d+) \| CZYNNE \| miasta (\d+): glowy kiesy ludu (\S+) \| pora: (ZIMA|lato|wiosna albo jesien|zima bez skutkow)[^|]*\| "
                     r"potrzeba (\S+) ladunkow \(po zaokragleniu (\d+)\) \| kupione i spalone (\d+) ladunkow za (\d+) zl \((?:z kies ludu \d+, )?akcyza do gmin (\d+), do kas miast (-?\d+)\) \| "
                     r"bez opalu dzis (\d+) ladunkow: polka nie wyzej niz zapas rzemiosla (\d+) miast, czesciowo (\d+), za mala kiesa ponad jutrzejszy koszyk (\d+) miast \| "
                     r"drewno zostawione rzemioslu na polkach (\d+) \| poza regula: miasta nieskalibrowane (\d+) \| czas \S+ ms \| potkniecia (\d+)\.$")
N2E_EGG = re.compile(r"^Towary: dzien (\d+) - Egg \(")
N2E_PURSE = r"zl \(z kies ludu (\d+), akcyza do gmin"
N2E_CAPW = re.compile(r"\| magazyn wsi powiekszony o jaja i owoce: wsi (\d+), razem \+(\d+) szt\.")
N2E_CLOG = re.compile(r"^Zatkane wsie \(diagnoza\): dzien (\d+) - .*?rodziny \(zatkane/wszystkie\):.*?rolnicze (\d+)/(\d+)")
N2E_FOLK = "Roboty ludu (P2): dzien "
N2E_FOLK_MAT = re.compile(r"\| material \d+ zl za ([\d/]+) szt\. \(([a-z/]+)\)")
N2E_FOLK_HELD = re.compile(r"budowy zostawily drewno rzemioslu - pan na \d+ targach \((\d+) szt\.\), lud na \d+ targach \((\d+) szt\.\)")
N2E_WOOD = re.compile(r"^Towary: dzien (\d+) - hardwood \(")
N2E_PRICE = "Ceny surowcow: dzien "
N2E_NOMAKER = ("garum", "Ink", "Dyes", "gems", "gold")
N2E_ERR = ("ERROR in VillageFruit", "ERROR in MineralOnce.Eggs", "ERROR in NoMakerBudget", "ERROR in FibreToMarket", "ERROR in TownFolk.Firewood",
           "ERROR in MarketCarts.SellPostfix", "ERROR in MarketCarts.SellPrefix", "ERROR in MarketCarts.Choose",
           "ERROR in TownFolk.FwCart", "ERROR in TownFolk.FwField", "ERROR in TownFolk.Opal")   # f4-opal: pomiar dowozu w latce sprzedazy wozu i regula opalu pod KS


def _n2e_gaps(days):
    """Liczba brakujacych dob miedzy pierwsza a ostatnia doba linii."""
    if not days:
        return 0
    return (max(days) - min(days) + 1) - len(set(days))


def nekon2_main(logp):
    """nekon2 (noc 16.10, galaz noc-ekonomia2: E1 jaja wsi rolniczych wedlug wag drobiu BK, E2 budzet kategorii bez producenta na zbytki z towarem, E3 len,
    welna i skory do miasta targowego przy zapasie wsi ponad 6 dob, E4 opal mieszczan). Wejscie: log Armoury (strumieniowo). N2-0 linie startu czterech
    punktow (klucze TAK), N2-1 jaja - start (wsi rolniczych > 0, oczekiwany plon > 0, Egg jest, lista BK wpieta), N2-2 jaja - linia doby w kazdej dobie,
    listy z jajami > 0 od drugiej doby, potkniecia 0, N2-3 jaja ze wsi poza typem (ksiega towarow "BK poza typem wsi") srednio > 0, N2-3b wobec oczekiwanego
    (INFO), N2-1c magazyn wsi z jajami i owocami i zatkane wsie rolnicze (INFO), N2-4 budzet bez producenta - start (latka wpieta - kod pisze "wpiety",
    5 zrodel w mapie), N2-5 linia doby w kazdej dobie, potkniecia 0, przekroczen limitu 0, najwiecej <= 50.5% nadwyzki, niezaspokojone = przeniesiono + zostalo, N2-5b przeniesiono > 0 (suma dob), N2-5c grupy celu (INFO), N2-6 wlokno - start i linia doby, potkniecia 0,
    N2-6b skierowania i sprzedaz (INFO), N2-7 opal - linia doby w kazdej dobie, potkniecia 0, kupione <= potrzeba po zaokragleniu, N2-7b z kies ludu = zaplacone
    i gminy + kasy = zaplacone, N2-7c opal razem (INFO), N2-7d drewno mieszczan w ksiedze towarow (INFO), N2-7e opal a drewno budow (INFO), N2-8 ERROR 0, N2-9 indeks jaj i budzet bez towaru (INFO).
    Log bez paczki: INFO, bez wyjatku."""
    rep = Report()
    if not logp or not os.path.isfile(logp):
        rep.add("N2-0: log Armoury", f"brak pliku {logp}", "podaj <Armoury-*.log>", None)
        rep.show()
        return 0
    start = {N2E_E1S: None, N2E_E2S: None, N2E_E3S: None, N2E_E4S: None}
    e1, e2, e3, e4, bad = {}, {}, {}, {}, []
    e4off = []
    egg, wood, prices, errs = {}, {}, {}, []
    e2x, e4p, capw, clog, folk = {}, {}, {}, {}, {}
    with open(logp, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\n"))
            s = m.group(2) if m else ln.rstrip("\n")
            if s.startswith("ERROR in "):
                if s.startswith(N2E_ERR):
                    errs.append(s[:160])
                continue
            hit = False
            for k in start:
                if s.startswith(k):
                    start[k] = s
                    hit = True
                    break
            if hit:
                continue
            if s.startswith(N2E_E1H):
                a = N2E_E1D.match(s)
                if a:
                    e1[int(a.group(1))] = tuple(int(x) for x in a.groups())
                    c = N2E_CAPW.search(s)
                    if c:
                        capw[int(a.group(1))] = (int(c.group(1)), int(c.group(2)))
                else:
                    bad.append(s[:140])
                continue
            if s.startswith(N2E_E2H):
                a = N2E_E2D.match(s)
                if a:
                    e2[int(a.group(1))] = a.groups()
                    x = N2E_E2MAX.search(s)
                    if x:
                        e2x[int(a.group(1))] = (float(x.group(1)), int(x.group(2)))
                else:
                    bad.append(s[:140])
                continue
            if s.startswith(N2E_E3H):
                a = N2E_E3D.match(s)
                if a:
                    e3[int(a.group(1))] = a.groups()
                else:
                    bad.append(s[:140])
                continue
            if s.startswith(N2E_E4H):
                a = N2E_E4D.match(s)
                if a:
                    e4[int(a.group(1))] = a.groups()
                    e4p[int(a.group(1))] = num(N2E_PURSE, s, int, None)
                elif " | CZYNNE | " in s:
                    bad.append(s[:140])
                else:
                    e4off.append(s[:160])
                continue
            if s.startswith("Towary: dzien "):
                a = N2E_EGG.match(s)
                if a:
                    egg[int(a.group(1))] = (num(r"\| produkcja (-?\d+)", s, int, 0), num(r"BK poza typem wsi (\d+)", s, int, 0),
                                            num(r"\| produkcja -?\d+ \[(?:[^\]]*?; )?wsie (\d+)", s, int, 0))
                    continue
                a = N2E_WOOD.match(s)
                if a:
                    wood[int(a.group(1))] = num(r"\| zuzycie -?\d+ \[(?:[^\]]*?; )?mieszczanie (\d+)", s, int, 0)
                continue
            if s.startswith(N2E_PRICE):
                d = num(r"dzien (\d+)", s)
                if d is not None:
                    prices[d] = s
                continue
            if s.startswith("Zatkane wsie (diagnoza): dzien "):
                a = N2E_CLOG.match(s)
                if a:
                    clog[int(a.group(1))] = (int(a.group(2)), int(a.group(3)))
                continue
            if s.startswith(N2E_FOLK):
                d = num(r"dzien (\d+)", s)
                if d is None:
                    continue
                hw = None
                a = N2E_FOLK_MAT.search(s)
                if a:
                    names, vals = a.group(2).split("/"), a.group(1).split("/")
                    if "hardwood" in names and len(vals) == len(names):
                        hw = int(vals[names.index("hardwood")])
                h = N2E_FOLK_HELD.search(s)
                folk[d] = (num(r", bez materialu (\d+),", s, int, None), hw, (int(h.group(1)) + int(h.group(2))) if h else None)
    print(f"plik: {logp} | linii startu {sum(1 for v in start.values() if v)}/4, linii doby: jaja {len(e1)}, budzet {len(e2)}, wlokno {len(e3)}, opal {len(e4)}"
          f" (opal nieczynny {len(e4off)}, nierozpoznanych {len(bad)}), Towary Egg {len(egg)}, hardwood {len(wood)}, Ceny surowcow {len(prices)}")
    if not any(start.values()) and not (e1 or e2 or e3 or e4):
        rep.add("N2-0: linie startu noc-ekonomia2", "brak linii", "INFO (wersja sprzed noc-ekonomia2)", None)
        rep.show()
        return 0
    s1, s2, s3, s4 = start[N2E_E1S], start[N2E_E2S], start[N2E_E3S], start[N2E_E4S]
    k1 = bool(s1) and "klucz VillageEggsFromBk TAK" in s1
    k2 = bool(s2) and "klucz NoMakerBudgetToLuxury TAK" in s2
    k3 = bool(s3) and "klucz VillageFibreToMarket TAK | CZYNNE" in s3
    k4 = bool(s4) and "klucz TownFolkFirewood TAK" in s4 and "kiesa ludu czynna" in s4
    rep.add("N2-0: linie startu E1-E4 (klucze TAK; E3 czynne; E4 przy czynnej kiesie ludu)",
            f"jaja {'TAK' if k1 else ('jest' if s1 else 'brak')}, budzet {'TAK' if k2 else ('jest' if s2 else 'brak')}, wlokno {'TAK' if k3 else ('jest' if s3 else 'brak')},"
            f" opal {'TAK' if k4 else ('jest' if s4 else 'brak')}", "4 x TAK", k1 and k2 and k3 and k4)
    if bad:
        rep.add("N2-0b: linie doby nierozpoznane", f"{len(bad)} np. {bad[0]}", "0", False)
    # ---- E1 jaja
    if s1 and k1:
        farms = num(r"wsi rolniczych BK \(klasa uprawy i wlokna typu wsi\) (\d+)", s1)
        exp = num(r"waga x \(poziom ognisk \+ 1\) x 0\.5\): jaja (\d+)", s1)
        ok1 = bool(farms) and bool(exp) and "Egg w grze jest" in s1 and "lista produkcji BK jest" in s1
        rep.add("N2-1: jaja - linia startu (wsi rolniczych, oczekiwany plon, Egg, lista BK)", f"wsi {farms}, oczekiwany plon {exp} jaj/d przed mnoznikami; " + s1[len(N2E_E1S):].split(" | ")[-2][:80],
                "wsi > 0, plon > 0, Egg jest, lista BK wpieta", ok1)
    else:
        farms, exp = None, None
        rep.add("N2-1: jaja - linia startu", (s1[len(N2E_E1S):][:120] if s1 else "brak"), "INFO (klucz NIE albo log bez paczki)", None)
    if e1:
        ds = sorted(e1)
        gaps = _n2e_gaps(ds)
        st = max(v[5] for v in e1.values())
        later = ds[1:] if len(ds) > 1 else ds
        zero = [d for d in later if e1[d][1] <= 0]
        rep.add("N2-2: jaja - linia doby w kazdej dobie, listy z jajami > 0 (od drugiej doby), potkniecia 0",
                f"dob {len(ds)} (d{ds[0]}-d{ds[-1]}, brak {gaps}), dob bez list z jajami {len(zero)}, srednio list {sum(e1[d][1] for d in later) / max(1, len(later)):.0f}"
                f" (wsi {sum(e1[d][2] for d in later) / max(1, len(later)):.0f}), baza {sum(e1[d][4] for d in later) / max(1, len(later)):.0f} jaj/d, potkniecia {st}",
                "brak 0, bez list 0, potkniecia 0", gaps == 0 and not zero and st == 0)
    else:
        rep.add("N2-2: jaja - linia doby", "brak linii doby", "linie sa (klucz TAK)" if k1 else "INFO", False if k1 else None)
    if egg:
        dd = sorted(egg)
        later = dd[1:] if len(dd) > 1 else dd
        out = [egg[d][1] for d in later]
        avg = sum(out) / max(1, len(out))
        rep.add("N2-3: jaja ze wsi poza typem wsi (ksiega towarow 'BK poza typem wsi', srednio od drugiej doby)", f"{avg:.0f} szt./d ({len(out)} dob)",
                "> 0" if k1 else "INFO (klucz NIE)", (avg > 0) if k1 else None)
        if exp:
            rep.add("N2-3b: jaja ze wsi poza typem wobec oczekiwanego plonu przed mnoznikami (INFO)",
                    f"{avg:.0f} / {exp} = {avg / max(1, exp):.2f}; produkcja Egg calosc d{dd[0]} {egg[dd[0]][0]} -> d{dd[-1]} {egg[dd[-1]][0]}, wsie {egg[dd[0]][2]} -> {egg[dd[-1]][2]}",
                    "INFO (mnozniki P1, rece, zima - zwykle 0.5-1.5)", None)
    else:
        rep.add("N2-3: jaja ze wsi (ksiega towarow)", "brak linii 'Towary: ... Egg'", "INFO (ksiega towarow wylaczona albo bez BK)", None)
    if capw or clog:
        cd = sorted(capw)
        kd = sorted(clog)
        cap_t = (f"wsi z wiekszym magazynem srednio {sum(capw[d][0] for d in cd) / len(cd):.0f}, +{sum(capw[d][1] for d in cd) / max(1, sum(capw[d][0] for d in cd)):.1f} szt. na wies"
                 if cd else "brak liczb magazynu w linii jaj")
        clog_t = (f"zatkane wsie rolnicze d{kd[0]} {clog[kd[0]][0]}/{clog[kd[0]][1]} -> d{kd[-1]} {clog[kd[-1]][0]}/{clog[kd[-1]][1]}" if kd else "brak linii 'Zatkane wsie (diagnoza)'")
        rep.add("N2-1c: magazyn wsi + 5 dob jaj i owocow (GetWarehouseCapacity) i zatkane wsie rolnicze (INFO)", cap_t + "; " + clog_t,
                "INFO (magazyn rosnie o dodatki listy BK - wsie rolnicze nie powinny zatykac sie czesciej niz przed paczka)", None)
    # ---- E2 budzet bez producenta
    if s2:
        srcs = [x for x in ("garum ->", "Dyes ->", "gems ->", "gold ->", "Ink ->") if x in s2]
        wired = re.search(r"latka wpiet[ay]", s2) is not None      # kod: "latka wpiety (UpdateDemandShift, ...)" - jak NC-23 dla B2
        rep.add("N2-4: budzet bez producenta - linia startu (latka wpieta, 5 zrodel w mapie)", f"latka {'wpieta' if wired else 'NIE'}, zrodel {len(srcs)}/5",
                "wpieta, 5/5" if k2 else "INFO (klucz NIE)", (wired and len(srcs) == 5) if k2 else None)
    else:
        rep.add("N2-4: budzet bez producenta - linia startu", "brak", "INFO (log bez paczki)", None)
    if e2:
        ds = sorted(e2)
        on = [d for d in ds if e2[d][1] == "CZYNNE"]
        gaps = _n2e_gaps(ds)
        st = sum(int(e2[d][13]) for d in ds)
        over = sum(int(e2[d][12]) for d in ds)
        sumbad = [d for d in on if abs(int(e2[d][5]) - int(e2[d][6]) - int(e2[d][8])) > 3 + 0.01 * int(e2[d][5])]
        mx = max((e2x[d][0] for d in ds if d in e2x), default=None)
        trim = sum(e2x[d][1] for d in ds if d in e2x)
        rep.add("N2-5: budzet - linia doby w kazdej dobie, potkniecia 0, przekroczen limitu celu 0 (najwiecej <= 50.5% nadwyzki), niezaspokojone = przeniesiono + zostalo",
                f"dob {len(ds)} (czynnych {len(on)}, brak {gaps}), potkniecia {st}, przekroczen {over}"
                + (f" (najwiecej {mx:.1f}% nadwyzki, przycietych przy nowym popycie targu {trim})" if mx is not None else " (linia bez najwiekszego udzialu - wersja sprzed poprawki)")
                + f", dob z niezgodna suma {len(sumbad)}"
                + (f" (np. d{sumbad[0]}: {e2[sumbad[0]][5]} vs {e2[sumbad[0]][6]} + {e2[sumbad[0]][8]})" if sumbad else ""),
                "brak 0, potkniecia 0, przekroczen 0, najwiecej <= 50.5%, niezgodnych 0",
                gaps == 0 and st == 0 and over == 0 and not sumbad and (mx is None or mx <= 50.5))
        mv = sum(int(e2[d][6]) for d in on)
        nd = sum(int(e2[d][5]) for d in on)
        gold = sum(int(e2[d][10]) for d in on)
        rep.add("N2-5b: budzet - przeniesiono na zbytki z towarem (suma dob czynnych)",
                f"niezaspokojone {nd}, przeniesiono {mv} ({100.0 * mv / max(1, nd):.0f}%), budzet BK celow +{gold} zl, srednio {gold / max(1, len(on)):.0f} zl/d",
                "> 0" if on else "INFO (klucz NIE)", (mv > 0) if on else None)
        if on:
            last = e2[on[-1]]
            rep.add("N2-5c: budzet - zrodla i cele (ostatnia doba, INFO)", f"d{on[-1]}: zrodla {last[7]}; osad {last[2]} (zamkow {last[3]}), bez miejsca {last[9]} wierszy",
                    "INFO", None)
    else:
        rep.add("N2-5: budzet - linia doby", "brak linii doby", "linie sa (klucz TAK)" if k2 else "INFO", False if k2 else None)
    # ---- E3 wlokno
    if e3:
        ds = sorted(e3)
        gaps = _n2e_gaps(ds)
        st = sum(int(e3[d][17]) for d in ds)
        rep.add("N2-6: wlokno - linia startu i doby w kazdej dobie, potkniecia 0", f"start {'TAK' if k3 else ('jest' if s3 else 'brak')}, dob {len(ds)} (brak {gaps}), potkniecia {st}",
                "start TAK, brak 0, potkniecia 0", k3 and gaps == 0 and st == 0)
        chk = sum(int(e3[d][1]) for d in ds); ovr = sum(int(e3[d][2]) for d in ds); mx = max(float(e3[d][3]) for d in ds)
        sent = sum(int(e3[d][4]) for d in ds); units = sum(int(e3[d][6]) for d in ds)
        vo = sum(int(e3[d][7]) for d in ds); vb = sum(int(e3[d][8]) for d in ds)
        sold = sum(int(e3[d][12]) for d in ds); sunits = sum(int(e3[d][13]) for d in ds); sg = sum(int(e3[d][14]) for d in ds)
        noown = sum(int(e3[d][10]) for d in ds)
        rep.add("N2-6b: wlokno - skierowania i sprzedaz w miescie targowym (INFO)",
                f"sprawdzonych {chk}, zapas ponad prog {ovr} (najwiekszy {mx:.1f} dob), skierowanych {sent} (wlokna {units} szt.), wycena {vo} d wobec {vb} d"
                f" (wies traci {max(0, vb - vo)} d), bez miasta targowego {noown}; sprzedaz: wozow {sold}, wlokna {sunits} szt., utarg {sg} d",
                "INFO (skierowania tylko przy zapasie ponad 6 dob; sprzedane <= skierowane + w drodze)", None)
        if sold > 0 or sent > 0:
            rep.add("N2-6c: wlokno - sprzedaz nie wieksza niz skierowania (wozy)", f"sprzedaz {sold}, skierowania {sent} (w drodze na koncu {e3[ds[-1]][15]})",
                    "sprzedaz <= skierowania", sold <= sent)
    else:
        rep.add("N2-6: wlokno - linia doby", "brak linii doby", "linie sa (klucz TAK)" if k3 else "INFO", False if k3 else None)
    # ---- E4 opal
    if e4:
        ds = sorted(e4)
        gaps = _n2e_gaps(ds)
        st = max(int(e4[d][16]) for d in ds)
        over = [d for d in ds if int(e4[d][6]) > int(e4[d][5])]
        rep.add("N2-7: opal - linia doby w kazdej dobie, potkniecia 0, kupione <= potrzeba po zaokragleniu",
                f"dob {len(ds)} (d{ds[0]}-d{ds[-1]}, brak {gaps}), potkniecia {st}, dob z kupionymi ponad potrzebe {len(over)}",
                "brak 0, potkniecia 0, ponad potrzebe 0", gaps == 0 and st == 0 and not over)
        withp = [d for d in ds if e4p.get(d) is not None]
        if withp:
            # obieg liczony osobno w kodzie: z kies klas (W/R/P) = zaplacone, wplaty do kas miast + akcyza gmin = zaplacone; kupione > 0 => zaplacone > 0
            badg = [d for d in withp if e4p[d] != int(e4[d][7]) or int(e4[d][8]) + int(e4[d][9]) != int(e4[d][7]) or (int(e4[d][6]) > 0 and int(e4[d][7]) <= 0)]
            rep.add("N2-7b: opal - zloto: z kies ludu = zaplacone, gminy + kasy miast = zaplacone, kupione > 0 => zaplacone > 0",
                    f"dob {len(withp)}, niezgodnych {len(badg)}" + (f" (np. d{badg[0]}: z kies {e4p[badg[0]]}, zaplacone {e4[badg[0]][7]}, gminy {e4[badg[0]][8]}, kasy {e4[badg[0]][9]})" if badg else ""),
                    "0", not badg)
        else:
            rep.add("N2-7b: opal - zloto (z kies ludu = zaplacone)", "linie bez 'z kies ludu' (wersja sprzed poprawki 16.10)", "INFO", None)
        need = sum(float(e4[d][4]) for d in ds if e4[d][4] != "-")
        bought = sum(int(e4[d][6]) for d in ds); gold = sum(int(e4[d][7]) for d in ds); win = sum(1 for d in ds if e4[d][3] == "ZIMA")
        short = sum(int(e4[d][10]) for d in ds)
        rep.add("N2-7c: opal razem (INFO)", f"potrzeba {need:.0f} ladunkow, kupione {bought} ({100.0 * bought / max(1.0, need):.0f}%) za {gold} zl"
                f" ({gold / max(1, bought):.1f} zl/ladunek), bez opalu {short}; dob zimy {win} z {len(ds)}; glowy (ostatnia) {e4[ds[-1]][2]}",
                "INFO (latem x0.5 i tylko drewno ponad zapas rzemiosla - malo; wiosna i jesien ok. 150/d, zima do ok. 300/d)", None)
    elif e4off:
        rep.add("N2-7: opal - linia doby", e4off[-1][:140], "INFO (klucz NIE albo kiesa ludu nieczynna)" if not k4 else "linie CZYNNE", None if not k4 else False)
    else:
        rep.add("N2-7: opal - linia doby", "brak linii doby", "linie sa (klucz TAK)" if k4 else "INFO", False if k4 else None)
    if wood:
        wd = sorted(wood)
        rep.add("N2-7d: drewno mieszczan w ksiedze towarow ('mieszczanie' w zuzyciu hardwood, INFO)",
                f"d{wd[0]} {wood[wd[0]]} -> d{wd[-1]} {wood[wd[-1]]}, srednio {sum(wood.values()) / len(wd):.0f}/d ({len(wd)} dob)", "INFO (koszyk BK + opal E4)", None)
    if e4 and folk:
        # opal biegnie w dobie PRZED budowami (ArmouryBehavior: FirewoodDaily przed BuildFunding.Daily) i bierze z tej samej puli ponad zapas rzemiosla;
        # linia opalu ma dzien = doba - 1, linia "Roboty ludu (P2)" - doba (ta sama doba gry: opal d, roboty d + 1)
        pairs = [(d, folk[d + 1]) for d in sorted(e4) if (d + 1) in folk]
        if pairs:
            ob = sum(int(e4[d][6]) for d, _ in pairs)
            hw = sum(f[1] for _, f in pairs if f[1] is not None)
            held = [f[2] for _, f in pairs if f[2] is not None]
            nm = [f[0] for _, f in pairs if f[0] is not None]
            on_d = [f[0] for d, f in pairs if f[0] is not None and int(e4[d][6]) > 0]
            off_d = [f[0] for d, f in pairs if f[0] is not None and int(e4[d][6]) <= 0]
            rep.add("N2-7e: opal a drewno budow w tych samych dobach (INFO - czy opal przed budowami nie zabiera im drewna)",
                    f"dob {len(pairs)}: opal kupiony {ob} ladunkow, drewno robot ludu {hw} szt., budowy zostawily rzemioslu (pan + lud) srednio {sum(held) / max(1, len(held)):.0f} szt./d"
                    f"; roboty ludu bez materialu srednio {sum(nm) / max(1, len(nm)):.0f} osad/d (doby z opalem {sum(on_d) / max(1, len(on_d)):.0f}"
                    f" [{len(on_d)}], bez opalu {sum(off_d) / max(1, len(off_d)):.0f} [{len(off_d)}])",
                    "INFO (gdy w dobach z opalem roboty wyraznie czesciej bez materialu - przeniesc E4 za BuildFunding)", None)
    # ---- bledy i ceny
    rep.add("N2-8: ERROR noc-ekonomia2 (VillageFruit, MineralOnce.Eggs, NoMakerBudget, FibreToMarket, TownFolk.Firewood, MarketCarts sprzedaz/wybor)",
            f"{len(errs)}" + (f" np. {errs[0]}" if errs else ""), "0", not errs)
    if prices:
        pd = sorted(prices)

        def idx_of(s, cat):
            m = re.search(r"(?:^|[;:] )" + re.escape(cat) + r"(?: \([^)]*\))? /[\d.]+ [\d.]+/([\d.]+)/[\d.]+, na polkach (\d+) szt\., pusto w (\d+) miastach, budzet mieszczan (\d+) d"
                          r" \(przy dzisiejszych polkach do (\d+) d\)", s)
            return m.groups() if m else None

        a, b = prices[pd[0]], prices[pd[-1]]
        e_a, e_b = idx_of(a, "Eggs"), idx_of(b, "Eggs")
        nm_a = sum(int(x[3]) - int(x[4]) for x in (idx_of(a, c) for c in N2E_NOMAKER) if x)
        nm_b = sum(int(x[3]) - int(x[4]) for x in (idx_of(b, c) for c in N2E_NOMAKER) if x)
        rep.add("N2-9: jaja - indeks (mediana miast) i budzet bez towaru garum/Ink/Dyes/gems/gold (pierwsza i ostatnia linia 'Ceny surowcow', INFO)",
                f"Eggs d{pd[0]} {e_a[0] + ' (pusto ' + e_a[2] + ')' if e_a else '-'} -> d{pd[-1]} {e_b[0] + ' (pusto ' + e_b[2] + ')' if e_b else '-'}; "
                f"niewydany budzet 5 kategorii {nm_a} -> {nm_b} d/dobe", "INFO (budzet w 'Ceny surowcow' to prognoza BK bez przesuniecia E2)", None)
    rep.show()
    return 0


