def _npf_prof_scan(logp):
    """Profil doby i doba zegara z logu -> (slownik nazwa -> lista wartosci, lista taktu, godzin, nasze, doba). Pozycja spoza top 15 - najmniejsza wartosc top (gorna granica)."""
    vals = {k: [] for k in NPF_PROF}
    takt, hour, our, doba = [], [], [], []
    if not logp or not os.path.isfile(logp):
        return vals, takt, hour, our, doba
    with open(logp, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\r\n"))
            s = m.group(2) if m else ln.rstrip("\r\n")
            if s.startswith("Profil doby (E8/0): dzien"):
                mt = NPF_TAKT.search(s)
                low = None
                if mt:
                    takt.append(float(mt.group(1)))
                    nums = [float(x) for x in re.findall(r" ([\d.]+)(?=, |$)", mt.group(2))]
                    low = min(nums) if nums else None
                for k, rx in NPF_PROF.items():
                    mm = rx.search(s)
                    if mm:
                        vals[k].append(float(mm.group(1)))
                    elif low is not None and k != "LegendaryLaw (czystki, ValyrianBlades)":
                        vals[k].append(low)   # poza top 15 taktu - najwyzej tyle, co najmniejsza pozycja top
                mh = NPF_HOUR.search(s)
                if mh:
                    hour.append(float(mh.group(1)))
                mo = NPF_OUR.search(s)
                if mo:
                    our.append(float(mo.group(1)))
            elif s.startswith("Koszt 171-174 (doba): dzien"):
                md = NPF_DOBA.match(s)
                if md:
                    doba.append(float(md.group(2)))
    return vals, takt, hour, our, doba


def _npf_f4b(rep, days):
    """f4b-perf (noc 17/18.10): NPERF-4b zold markietanow tylko pewny (PerfSutlerWageExact), NPERF-11b probki hakow osobno na miejsce (PerfProbeEachPlace),
    NPERF-12 rozjazdy kazdej pamieci i skrotu perf-d2d3 osobno. Brak segmentu f4b-perf w liniach doby - INFO (bez wyjatku)."""
    ex = [g["exact"] for g in days if g.get("exact")]
    if ex:
        first = sum(int(x["first"]) for x in ex); sure = sum(int(x["sure"]) for x in ex); hero = sum(int(x["hero"]) for x in ex)
        drew = sum(int(x["drew"]) for x in ex); raw = sum(int(x["raw"]) for x in ex); pdrew = sum(int(x["pdrew"]) for x in ex)
        nog = sum(int(x["noguard"]) for x in ex)
        guard = ex[-1]["guard"]; key = ex[-1]["key"]
        parts_bad = sum(1 for x in ex if int(x["first"]) != int(x["sure"]) + int(x["hero"]) + int(x["drew"]))   # tozsamosc: pierwsze = z pamiecia + bohater + losowanie
        share = f" ({100.0 * (hero + drew) / first:.1f}% partii)" if first else ""
        # werdykt (recenzja f4b-perf): losowanie w probce albo czesci != calosc - NIE; straznik BRAK/nieuzyty przy pierwszych liczeniach - INFO (bezpieczny
        # odwrot: pamiec tylko z warunkiem bohaterow, wynik pamieci sprawdza NPERF-4), zgodnie z progiem i opisem grupy; klucz [wyl] - INFO (liczniki puste)
        if key == "[WL]":
            v4b = False if (pdrew or parts_bad) else (True if (guard == "CZYNNY" or first == 0) else None)
        else:
            v4b = False if parts_bad else None
        rep.add("NPERF-4b: zold markietanow tylko pewny (PerfSutlerWageExact) - losowanie w probce i straznik",
                f"klucz {key}; pierwszych liczen {first}, z pamiecia {sure}, bez pamieci {hero + drew}{share}: bohater poza wodzem (zold BK losowany) {hero}, "
                f"losowanie przy liczeniu {drew}; odczytow liczonych jak dotad {raw}; losowanie w probce {pdrew}; bez straznika {nog}; straznik losowania {guard}; "
                f"pierwsze != z pamiecia + bohater + losowanie w {parts_bad} dobach"
                + ("; straznik niedostepny - pamiec tylko z warunkiem bohaterow (wynik pamieci sprawdza NPERF-4)" if (key == "[WL]" and v4b is None) else ""),
                "losowanie w probce 0; czesci = calosc; straznik CZYNNY (BRAK/nieuzyty - INFO: decyduje sam warunek bohaterow); bez pamieci - INFO",
                v4b)
    else:
        rep.add("NPERF-4b: zold markietanow tylko pewny (PerfSutlerWageExact)", "brak segmentu 'kontrola dokladnosci (f4b-perf)' w liniach doby",
                "INFO (log sprzed f4b-perf - pamiec zoldu dla kazdej partii, takze z losowanym zoldem BK)", None)
    # probki i rozjazdy kazdego miejsca hakow (segment 5) + wywolania (segment f4b-perf)
    per = {}
    for g in days:
        fx = g.get("fast")
        if not fx:
            continue
        for mm in NPF_FAST_SITE.finditer(fx["sites"]):
            k = mm.group("name").strip()
            a = per.setdefault(k, [0, 0])
            a[0] += int(mm.group("p")); a[1] += int(mm.group("d"))
    # recenzja f4b-perf: wywolania i probki liczone osobno dla dob z kluczem PerfProbeEachPlace [WL] (licznik na miejsce) - przy [wyl] wspolny licznik 1/64
    # jak w perf-d2d3 trafia zawsze w rade TownBase, wiec miejsca bez probek sa oczekiwane (INFO, nie NIE); PerfD2 liczy wywolania przy kazdym kluczu
    calls, each_days, each_key = {}, 0, None
    calls_on, per_on, on_days, off_days = {}, {}, 0, 0
    for g in days:
        e = g.get("each")
        if not e:
            continue
        each_days += 1; each_key = e["key"]
        on = e["key"] == "[WL]"
        if on:
            on_days += 1
        else:
            off_days += 1
        for k, v in e["calls"].items():
            calls[k] = calls.get(k, 0) + v
            if on:
                calls_on[k] = calls_on.get(k, 0) + v
        fx = g.get("fast")
        if on and fx:
            for mm in NPF_FAST_SITE.finditer(fx["sites"]):
                a = per_on.setdefault(mm.group("name").strip(), [0, 0])
                a[0] += int(mm.group("p")); a[1] += int(mm.group("d"))
    low = [k for k in NPF_SITES if calls_on.get(k, 0) >= NPF_EACH_MIN and per_on.get(k, [0, 0])[0] == 0]   # niesprawdzane przy kluczu [WL]
    if on_days:
        keytxt = each_key if not off_days else f"mieszany ([WL] {on_days} dob, [wyl] {off_days} dob - liczone doby [WL])"
        rep.add("NPERF-11b: probki hakow podatku miast osobno na miejsce (PerfProbeEachPlace) - kazde wolane miejsce sprawdzone",
                f"klucz {keytxt}; " + ", ".join(f"{k}: wywolan {calls_on.get(k, 0)}, probek {per_on.get(k, [0, 0])[0]}" for k in NPF_SITES)
                + (f"; bez probek przy >= {NPF_EACH_MIN} wywolaniach: {', '.join(low)}" if low else ""),
                f"miejsce z >= {NPF_EACH_MIN} wywolaniami (doby z kluczem [WL]) ma >= 1 probke", not low)
    elif each_days:
        zero = [k for k in NPF_SITES if calls.get(k, 0) >= NPF_EACH_MIN and per.get(k, [0, 0])[0] == 0]
        rep.add("NPERF-11b: probki hakow podatku miast osobno na miejsce (PerfProbeEachPlace)",
                f"klucz [wyl] we wszystkich {off_days} dobach - wspolny licznik 1/64 jak w perf-d2d3; "
                + ", ".join(f"{k}: wywolan {calls.get(k, 0)}, probek {per.get(k, [0, 0])[0]}" for k in NPF_SITES)
                + (f"; bez probek (oczekiwane przy wspolnym liczniku): {', '.join(zero)}" if zero else ""),
                "INFO (klucz wylaczony - stara droga probek perf-d2d3, miejsca bez probek oczekiwane)", None)
    elif per:
        zero = [k for k in NPF_SITES if k in per and per[k][0] == 0]
        rep.add("NPERF-11b: probki hakow podatku miast osobno na miejsce", "brak liczby wywolan miejsc w liniach doby"
                + (f"; probek 0 przez caly bieg: {', '.join(zero)} (wspolny licznik 1/64 przy 4 hakach na liczenie trafia zawsze w to samo miejsce)" if zero else ""),
                "INFO (log sprzed f4b-perf - nie wiadomo, czy miejsca bez probek byly wolane)", None)
    # NPERF-12: rozjazdy kazdej pamieci / skrotu perf-d2d3 osobno
    items, bad, unk = [], [], []
    vs = [g["vs"] for g in days]
    for nm, pk, dk in (("spis VS - bohaterowie bez klingi", "hp", "hd"), ("spis VS - rostery bez klingi", "rp", "rd")):
        p_ = sum(int(v[pk]) for v in vs); d_ = sum(int(v[dk]) for v in vs)
        items.append(f"{nm} {p_}/{d_}")
        if d_:
            bad.append(nm)
    wg = [g["wage"] for g in days]
    wp = sum(int(w["p"]) for w in wg); wd = sum(int(w["d"]) for w in wg)
    pdrew = sum(int(x["pdrew"]) for x in ex) if ex else None
    items.append(f"zold markietanow (pamiec na partie) {wp}/{wd}" + (f" + losowanie w probce {pdrew}" if pdrew is not None else ""))
    if wd or pdrew:
        bad.append("zold markietanow")
    for k in NPF_SITES:
        if k not in per:
            continue
        p_, d_ = per[k]
        c_ = calls.get(k) if each_days else None
        items.append(f"hak {k} {p_}/{d_}" + (f" (wywolan {c_})" if c_ is not None else ""))
        if d_:
            bad.append(k)
        elif k in low:
            bad.append(k + " - niesprawdzane")   # klucz [WL], >= 128 wywolan, probek 0
        elif p_ == 0:
            if c_ is None:
                unk.append(k)
            elif c_ >= NPF_EACH_MIN:
                unk.append(k + " (PerfProbeEachPlace [wyl] - wspolny licznik)")
    tx = [g["tax"] for g in days]
    su = sum(int(t["su"]) for t in tx); pu = sum(int(t["pu"]) for t in tx); sk = sum(int(t["skip"]) for t in tx); pr = sum(int(t["probe"]) for t in tx)
    items.append(f"podatek miast - cialo BK pominiete: rada niepokryta przy pominieciu {su} / w probkach {pu} (pominiec {sk}, probek {pr})")
    if su or pu:
        bad.append("podatek miast (rada niepokryta)")
    verdict = False if bad else (None if unk else True)
    rep.add("NPERF-12: rozjazdy kazdej pamieci i skrotu perf-d2d3 osobno (probek/rozjazdow)",
            "; ".join(items) + (f" | ROZJAZD/NIESPRAWDZANE: {', '.join(bad)}" if bad else "") + (f" | probek 0 bez dowodu wywolan (log bez liczby wywolan albo PerfProbeEachPlace [wyl]): {', '.join(unk)}" if unk else ""),
            "rozjazdow 0 w kazdej; miejsce z >= 128 wywolaniami przy PerfProbeEachPlace [WL] ma probki (log bez liczby wywolan albo klucz [wyl], probek 0 - INFO)", verdict)


def nperf_main(logp, csp=None, bdp=None):
    """nperf (noc 17/18.10, paczka perf-d2d3 - CO-ZOSTALO D2/D3; Armoury/src/PerfD2.cs). Log Armoury (strumieniowo); --crashscribe <session-*.log> (bez niego - log sesji
    z tego samego startu); --baza-doby <log Armoury biegu bazowego> (bez niego - mediany fin81 w kodzie: NPF_BASE). NPERF-0 linia startu sesji (klucze, straznik
    podatku miast; STOI - INFO z powodem), NPERF-1 linie doby rozpoznane (nierozpoznane 0), NPERF-2 spis stali valyrianskiej: rozjazdow 0 (bohaterowie i rostery),
    probek >= 1 przy pominieciach, mediana czasu spisu <= 10 ms, NPERF-3 podatek miast: rada niepokryta 0 (przy pominieciu i w probkach), wyjatkow przy pominieciu 0,
    probek >= 1 przy pominieciach; czasy z cialem BK / bez i oszczednosc (INFO), NPERF-3c linia "Rada (3.5)": segment przeliczen przy pominietym ciele BK wtedy i tylko
    wtedy, gdy pominiecia > 0, czesci = calosc, nierozpoznane 0 (brak linii doby perf-d2d3 - INFO), NPERF-4 zold markietanow: rozjazdow 0, probek >= 1 przy odczytach z pamieci,
    oszczednosc (INFO), NPERF-5 Profil doby - mediany wobec bazy: LegendaryLaw <= 0.55 x baza, Sutlers <= 0.92 x baza, ClanIncomeBook, KingdomTreasury,
    BuildFunding, takt doby, godzina - <= 1.05 x baza (nie gorzej), NPERF-6 nasze razem (dolna granica) i doba zegara wobec bazy (INFO - zalezy od obciazenia
    komputera), NPERF-7 dochod modelu w ksiedze rodow wedlug rodu (INFO - gdzie siedzi koszt CalculateClanIncome), NPERF-8 (CS) swaty ROT - mediana czasu
    <= 400 ms, EconomyAudit (INFO), NPERF-9 ERROR in PerfD2 / ValyrianBlades / Sutlers / MenPurse / PopulationLaw / CouncilWages35 = 0, NPERF-10 koszt
    linii <= 1 ms, NPERF-11 haki podatku miast bez refleksji (PerfTownTaxFastHooks: KeptTownLines, linie notabli i wlascicieli, rada TownBase, zachowanie BK
    z pamieci) - rozjazdow 0 w probce 1/64 (brak segmentu - INFO). Log bez paczki: INFO, bez wyjatku.
    f4b-perf (noc 17/18.10, _npf_f4b): NPERF-4b zold markietanow tylko pewny (losowanie w probce 0, straznik losowania CZYNNY), NPERF-11b probki hakow
    osobno na miejsce (miejsce z >= 128 wywolaniami ma probke), NPERF-12 rozjazdy kazdej pamieci i skrotu perf-d2d3 osobno (0 w kazdej)."""
    rep = Report()
    if not logp or not os.path.isfile(logp):
        rep.add("NPERF-0: log Armoury", f"brak pliku {logp}", "podaj <Armoury-*.log>", None)
        rep.show()
        return 0
    starts, days, bad, n_err, err_first = [], [], [], 0, None
    rada, rada_bad = [], 0   # recenzja: linie "Rada (3.5)" (NPERF-3c)
    start_raw = None         # f4b-perf: ostatnia linia startu sesji (klucze PerfSutlerWageExact, PerfProbeEachPlace - NPERF-0c)
    with open(logp, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\r\n"))
            s = m.group(2) if m else ln.rstrip("\r\n")
            if s.startswith("Rada (3.5): dzien "):
                mm = NPF_RADA.match(s)
                if mm:
                    rada.append(mm.groupdict())
                else:
                    rada_bad += 1
                continue
            if s.startswith(NPF_HEAD):
                if s.startswith(NPF_HEAD + "start sesji"):
                    start_raw = s
                    mm = NPF_START.match(s)
                    starts.append(mm.groups() if mm else (None, None, None, s[:200], None))
                elif s.startswith(NPF_HEAD + "dzien "):
                    g = {"day": num(r"dzien (-?\d+)", s)}
                    ok = True
                    for nm, rx in (("vs", NPF_VS), ("tax", NPF_TAX), ("wage", NPF_WAGE), ("model", NPF_MODEL)):
                        mm = rx.search(s)
                        if mm:
                            g[nm] = mm.groupdict()
                        else:
                            ok = False
                    mc = NPF_COST.search(s)
                    g["cost"] = float(mc.group(1)) if mc else None
                    mf = NPF_FAST.search(s)
                    g["fast"] = mf.groupdict() if mf else None   # segment 5 (PerfTownTaxFastHooks) - brak w liniach starszej wersji paczki: INFO
                    mx = NPF_EXACT.search(s)
                    g["exact"] = mx.groupdict() if mx else None  # f4b-perf: zold markietanow tylko pewny - brak w liniach sprzed f4b-perf: INFO
                    me = NPF_EACH.search(s)
                    g["each"] = None
                    if me:                                       # f4b-perf: wywolania kazdego miejsca hakow (PerfProbeEachPlace)
                        cc = {}
                        for part in me.group("calls").split(", "):
                            nm_, _, v_ = part.strip().rpartition(" ")
                            if nm_ and v_.isdigit():
                                cc[nm_] = int(v_)
                        g["each"] = {"key": me.group("key"), "calls": cc}
                    mw = NPF_TAXWHY.search(s)
                    g["why"] = mw.group(1) if mw else None
                    (days.append(g) if ok else bad.append(s))
            elif s.startswith(NPF_ERR):
                n_err += 1
                err_first = err_first or s[:160]
    vals, takt, hour, our, doba = _npf_prof_scan(logp)
    print(f"plik: {logp} | linii startu {len(starts)}, doby {len(days)} (nierozpoznanych {len(bad)}), Profil doby {len(takt)} dob, Koszt 171-174 {len(doba)} dob")
    # baza
    base, base_src = dict(NPF_BASE), "mediany fin81 (Armoury-2026-10-17_17-55-14.log)"
    if bdp and os.path.isfile(bdp):
        bv, bt, bh, bo, bd = _npf_prof_scan(bdp)
        for k, v in bv.items():
            if v:
                base[k] = st.median(v)
        if bt:
            base["takt"] = st.median(bt)
        if bh:
            base["godzina"] = st.median(bh)
        if bo:
            base["nasze"] = st.median(bo)
        if bd:
            base["doba"] = st.median(bd)
        base_src = f"--baza-doby {os.path.basename(bdp)} ({len(bt)} dob)"
    # NPERF-0
    if starts:
        st0 = starts[-1]
        if st0[0] is None:
            rep.add("NPERF-0: linia startu sesji", st0[3], "format linii PerfD2.EnsureHooks", False)
        else:
            rep.add("NPERF-0: linia startu sesji - klucze", f"spis VS {st0[0]}, podatek miast {st0[1]}, zold markietanow {st0[4]}", "klucze [WL] (wylaczone - INFO)",
                    None if "[wyl]" in (st0[0], st0[1], st0[4]) else True)
            rep.add("NPERF-0b: straznik podatku miast (pominiecie ciala BK)", f"{st0[2]} ({st0[3][:220]})",
                    "CZYNNY (STOI - INFO z powodem: obca latka, inny model, inna wersja BK - paczka bez zysku tej czesci, gra jak dotad)", True if st0[2] == "CZYNNY" else None)
    else:
        rep.add("NPERF-0: linia startu sesji 'Szybkosc doby (perf-d2d3)'", "brak", "INFO (log sprzed paczki perf-d2d3)", None)
    if start_raw:   # f4b-perf: klucze kontroli dokladnosci w linii startu
        k1 = re.search(r"zold markietanow tylko pewny \(PerfSutlerWageExact\) (\[WL\]|\[wyl\])", start_raw)
        k2 = re.search(r"probki hakow osobno na miejsce \(PerfProbeEachPlace\) (\[WL\]|\[wyl\])", start_raw)
        if k1 or k2:
            v1 = k1.group(1) if k1 else "-"; v2 = k2.group(1) if k2 else "-"
            rep.add("NPERF-0c: linia startu sesji - klucze f4b-perf", f"zold markietanow tylko pewny {v1}, probki hakow osobno na miejsce {v2}",
                    "klucze [WL] (wylaczone - INFO: pamiec zoldu i probki jak w perf-d2d3)", True if (v1 == "[WL]" and v2 == "[WL]") else None)
        else:
            rep.add("NPERF-0c: linia startu sesji - klucze f4b-perf", "brak w linii startu", "INFO (log sprzed f4b-perf)", None)
    # NPERF-1
    if days or bad:
        rep.add("NPERF-1: linie doby rozpoznane", f"{len(days)} (nierozpoznane {len(bad)})" + (f" np. {bad[0][:180]}" if bad else ""), "nierozpoznane 0", not bad)
    else:
        rep.add("NPERF-1: linie doby 'Szybkosc doby (perf-d2d3)'", "brak", "INFO (log sprzed paczki albo bieg krotszy niz 2 doby)", None)
    if days:
        vs = [g["vs"] for g in days]
        hd = sum(int(v["hd"]) for v in vs); rd = sum(int(v["rd"]) for v in vs)
        hs = sum(int(v["hs"]) for v in vs); rs = sum(int(v["rs"]) for v in vs)
        hp = sum(int(v["hp"]) for v in vs); rp = sum(int(v["rp"]) for v in vs)
        vms = [float(v["ms"]) for v in vs if int(v["g"]) > 0]
        rep.add("NPERF-2: spis stali valyrianskiej - rozjazdy (stara droga w probce 1/64)", f"bohaterowie: pominieci {hs}, probek {hp}, rozjazdow {hd}; rostery: pominiete {rs}, probek {rp}, rozjazdow {rd}",
                "rozjazdow 0; probek >= 1 przy pominieciach", hd == 0 and rd == 0 and (hs + rs == 0 or hp + rp >= 1))
        rep.add("NPERF-2b: spis stali valyrianskiej - mediana czasu (Gather)", f"{st.median(vms):.1f} ms ({len(vms)} dob; maks. {max(vms):.1f})" if vms else "brak spisow",
                f"<= {NPF_VS_MS:.0f} ms", (st.median(vms) <= NPF_VS_MS) if vms else None)
        tx = [g["tax"] for g in days]
        su = sum(int(t["su"]) for t in tx); pu = sum(int(t["pu"]) for t in tx); es = sum(int(t["es"]) for t in tx); ep = sum(int(t["ep"]) for t in tx)
        sk = sum(int(t["skip"]) for t in tx); pr = sum(int(t["probe"]) for t in tx); calls = sum(int(t["calls"]) for t in tx); off = sum(int(t["off"]) for t in tx)
        live = sum(1 for t in tx if t["live"] == "CZYNNY")
        if sk + pr > 0:
            rep.add("NPERF-3: podatek miast - rada pokryta i bez wyjatkow (cialo BK pominiete)",
                    f"wywolan {calls}, pominietych {sk}, probek {pr}, poza warunkiem {off}; rada niepokryta: przy pominieciu {su}, w probkach {pu}; wyjatkow przy pominieciu {es} (w probkach {ep})",
                    "rada niepokryta 0 i 0; wyjatkow przy pominieciu 0; probek >= 1", su == 0 and pu == 0 and es == 0 and pr >= 1)
            ub = [float(t["ub"]) for t in tx if int(t["nb"]) > 0]; us_ = [float(t["us"]) for t in tx if int(t["ns"]) > 0]
            sv = [float(t["save"]) for t in tx]
            rep.add("NPERF-3b: podatek miast - czas wywolania i oszczednosc", f"z cialem BK mediana {st.median(ub) if ub else 0:.1f} us, bez {st.median(us_) if us_ else 0:.1f} us; "
                    f"oszczednosc mediana {st.median(sv):.1f} ms/dobe (wywolan srednio {calls / len(tx):.0f}/dobe)", "INFO", None)
        else:
            why = next((g["why"] for g in reversed(days) if g.get("why")), "-")
            rep.add("NPERF-3: podatek miast - pominiecia ciala BK", f"pominietych 0 (straznik czynny {live} z {len(tx)} dob; powod: {why[:200]})",
                    "INFO (straznik STOI albo klucz wylaczony - gra jak dotad)", None)
        wg = [g["wage"] for g in days]
        wh = sum(int(w["hits"]) for w in wg); wp = sum(int(w["p"]) for w in wg); wd = sum(int(w["d"]) for w in wg)
        wsv = [float(w["save"]) for w in wg]
        rep.add("NPERF-4: zold markietanow raz na partie - rozjazdy (probka 1/64)", f"odczytow z pamieci {wh}, probek {wp}, rozjazdow {wd}; oszczednosc mediana {st.median(wsv):.1f} ms/dobe",
                "rozjazdow 0; probek >= 1 przy odczytach z pamieci", wd == 0 and (wh == 0 or wp >= 1) if wh > 0 else None)
        md = [g["model"] for g in days]
        rep.add("NPERF-7: dochod modelu w ksiedze rodow wedlug rodu (mediana ms/dobe)",
                f"krolow {st.median([float(x['rms']) for x in md]):.1f} ms ({md[-1]['rn']} rodow), z lennami {st.median([float(x['fms']) for x in md]):.1f} ms ({md[-1]['fn']} rodow, "
                f"lenn {md[-1]['fiefs']}), bez lenn {st.median([float(x['nms']) for x in md]):.1f} ms ({md[-1]['nn']} rodow)", "INFO (gdzie siedzi koszt CalculateClanIncome)", None)
        fs = [g["fast"] for g in days if g.get("fast")]
        if fs:
            fdiff = sum(int(x["d"]) for x in fs)
            per = {}
            for x in fs:
                for mm in NPF_FAST_SITE.finditer(x["sites"]):
                    k = mm.group("name").strip()
                    a = per.setdefault(k, [0, 0])
                    a[0] += int(mm.group("p")); a[1] += int(mm.group("d"))
            tot_p = sum(v[0] for v in per.values())
            rep.add("NPERF-11: haki podatku miast bez refleksji - rozjazdy (stara droga w probce 1/64)",
                    f"rozjazdow razem {fdiff}; " + ", ".join(f"{k} {v[0]}/{v[1]}" for k, v in per.items()) + " (probek/rozjazdow)",
                    "rozjazdow 0; probek >= 1 (gdy klucz [WL] i byl podatek miast)", fdiff == 0 and (tot_p >= 1 or fs[-1]["key"] == "[wyl]"))
        else:
            rep.add("NPERF-11: haki podatku miast bez refleksji", "brak segmentu w liniach doby", "INFO (wersja paczki bez PerfTownTaxFastHooks)", None)
        cs_ = [g["cost"] for g in days if g["cost"] is not None]
        rep.add("NPERF-10: koszt linii i straznika", f"mediana {st.median(cs_):.2f} ms, maks. {max(cs_):.2f}" if cs_ else "brak", "<= 1 ms (mediana)",
                (st.median(cs_) <= 1.0) if cs_ else None)
        _npf_f4b(rep, days)   # f4b-perf: NPERF-4b, NPERF-11b, NPERF-12
    # NPERF-3c (recenzja): linia "Rada (3.5)" - przeliczenia przy pominietym ciele BK oznaczone osobno (stara pensja BK z nich nieznana), czesci sumuja sie do calosci
    if rada:
        segs = [r for r in rada if r.get("k") is not None]
        kk = sum(int(r["k"]) for r in segs)
        mm_ = sum(int(r["m"]) for r in segs if r.get("m") is not None)
        a_b = sum(int(r["a"]) for r in segs)
        n1 = sum(int(r["n1"]) for r in segs if r.get("n1") is not None)
        bad_sum = sum(1 for r in segs if r.get("m") is None or r.get("n1") is None
                      or int(r["m"]) + int(r["k"]) != int(r["c"]) or int(r["n1"]) + int(r["kn"]) != int(r["b"]))
        sk_tot = sum(int(g["tax"]["skip"]) for g in days) if days else 0
        val = (f"dob z segmentem pominiec {len(segs)} z {len(rada)} (nierozpoznanych {rada_bad}); przeliczen pominietych {kk}, z cialem BK {mm_}; "
               f"stara pensja BK z przeliczen z cialem BK {a_b} wobec wedlug renty w nich {n1}" + (f" (x{a_b / n1:.2f})" if n1 else "")
               + f"; czesci != calosc w {bad_sum} dobach; pominiec ciala BK w liniach perf-d2d3 {sk_tot}")
        if days:
            rep.add("NPERF-3c: Rada (3.5) - przeliczenia przy pominietym ciele BK osobno (suma 'wedlug zastapionego podatku BK' bez nich)", val,
                    "segment wtedy i tylko wtedy, gdy pominiecia ciala BK > 0; czesci = calosc (przeliczenia i suma wedlug renty); nierozpoznane 0",
                    ((kk > 0) == (sk_tot > 0)) and bad_sum == 0 and rada_bad == 0)
        else:
            rep.add("NPERF-3c: Rada (3.5) - przeliczenia przy pominietym ciele BK", val, "INFO (brak linii doby perf-d2d3)", None)
    else:
        rep.add("NPERF-3c: Rada (3.5)", "brak linii", "INFO (CouncilWagesRealBase wylaczone albo log bez rady)", None)
    # NPERF-5: Profil doby wobec bazy (log bez paczki - tylko pomiar wyjsciowy, INFO)
    pkg = bool(starts or days)
    if takt:
        def row(name, key, vals_, mult, rule):
            if not vals_:
                rep.add(name, "brak w Profilu doby", "INFO", None)
                return
            med = st.median(vals_)
            b = base.get(key)
            rep.add(name, f"mediana {med:.1f} ms ({len(vals_)} dob) wobec bazy {b:.1f} ms = x{med / b:.2f}" if b else f"mediana {med:.1f} ms",
                    rule if pkg else "INFO (log bez paczki perf-d2d3 - pomiar wyjsciowy)", (med <= b * mult) if b and pkg else None)
        row("NPERF-5a: LegendaryLaw (czystki, ValyrianBlades)", "LegendaryLaw (czystki, ValyrianBlades)", vals["LegendaryLaw (czystki, ValyrianBlades)"], NPF_LL_MAX, f"<= {NPF_LL_MAX} x baza ({base_src})")
        row("NPERF-5b: Sutlers.Daily (markietani)", "Sutlers.Daily", vals["Sutlers.Daily"], NPF_SUT_MAX, f"<= {NPF_SUT_MAX} x baza")
        row("NPERF-5c: ClanIncomeBook.Daily", "ClanIncomeBook.Daily", vals["ClanIncomeBook.Daily"], NPF_REG, f"<= {NPF_REG} x baza (nie gorzej)")
        row("NPERF-5d: KingdomTreasury.Daily", "KingdomTreasury.Daily", vals["KingdomTreasury.Daily"], NPF_REG, f"<= {NPF_REG} x baza (nie gorzej)")
        row("NPERF-5e: BuildFunding.Daily", "BuildFunding.Daily", vals["BuildFunding.Daily"], NPF_REG, f"<= {NPF_REG} x baza (nie gorzej)")
        row("NPERF-5f: takt doby (caly OnDailyTick)", "takt", takt, NPF_REG, f"<= {NPF_REG} x baza (nie gorzej)")
        row("NPERF-5g: godzina (suma sluchaczy godzinowych)", "godzina", hour, NPF_REG, f"<= {NPF_REG} x baza (nie gorzej)")
        mo = st.median(our) if our else None
        mdb = st.median(doba) if doba else None
        rep.add("NPERF-6: nasze razem (dolna granica) i doba zegara (mediany)",
                (f"nasze {mo:.0f} ms (baza {base['nasze']:.0f}, x{mo / base['nasze']:.2f})" if mo else "nasze -") + "; "
                + (f"doba {mdb / 1000:.1f} s (baza {base['doba'] / 1000:.1f} s, x{mdb / base['doba']:.2f})" if mdb else "doba -"),
                "INFO (zalezy od obciazenia komputera - inne biegi rownolegle)", None)
    else:
        rep.add("NPERF-5: Profil doby (E8/0)", "brak linii", "INFO (Stage8ProfileLog wylaczony)", None)
    # NPERF-8: CrashScribe - swaty ROT i audyt CS
    cpath, how = crashscribe_session_of(logp, csp)
    if cpath:
        z3, ea = [], []
        with open(cpath, encoding="utf-8", errors="replace") as fh:
            for ln in fh:
                m = TS.match(ln.rstrip("\r\n"))
                s = m.group(2) if m else ln.rstrip("\r\n")
                if s.startswith("Swaty ROT (Z.3): dzien"):
                    v = num(r"czas ([\d.]+) ms", s, float)
                    if v is not None:
                        z3.append(v)
                elif s.startswith("Profil CS (E8/0): dzien"):
                    v = num(r"EconomyAudit: przebiegow \d+ \(po wczytaniu \d+\), ([\d.]+) ms", s, float)
                    if v is not None:
                        ea.append(v)
        rep.add("NPERF-8: (CS) swaty ROT - mediana czasu doby", f"{st.median(z3[1:] or z3):.0f} ms ({len(z3)} dob; {os.path.basename(cpath)}, {how})" if z3 else f"brak linii Z.3 ({how})",
                f"<= {NPF_Z3_MS:.0f} ms", (st.median(z3[1:] or z3) <= NPF_Z3_MS) if z3 else None)
        rep.add("NPERF-8b: (CS) EconomyAudit - suma i mediana", f"suma {sum(ea):.0f} ms, mediana dob z przebiegiem {st.median([x for x in ea if x > 0] or [0]):.0f} ms" if ea else "brak",
                "INFO (w grze Jeffa co 7 dob - EconomyAuditWeekly)", None)
    else:
        rep.add("NPERF-8: (CS) swaty ROT", f"brak logu sesji CrashScribe ({how})", "INFO", None)
    rep.add("NPERF-9: ERROR w miejscach paczki", f"{n_err}" + (f" (np. {err_first})" if err_first else ""), "0", n_err == 0)
    rep.show()
    return 0


# ============================================================ NW (noc 16.10, w-toku/noc-wydajnosc): wydajnosc - grupa nwyd
# Armoury: LogGate.cs (ciche logi), ScorchedEarth.Next (O3), NightRest siatka zagrozen (O5), DayProfile pola NW (O4, O6), LegendaryLaw (O6c, O7);
# CrashScribe (--crashscribe): MarriageFast.PickViableLazy (O1), EconomyAudit.Due (O2), Scribe pisarz (O9).
NW_START = re.compile(r"^Ciche logi \(NW\): (\[WL\] co (\d+) dob|\[wyl\][^|]*).*? \| tryb: (.*?) \| dzialaja: (tak|nie)")
NW_O6 = re.compile(r"^Log \(E8/O6\): dzien (\d+) .*?\| ciche logi \(NW\) (\[WL\]|\[wyl\]) tryb (\S+(?: rozpoznany)?), linie pomiarow tej doby (tak|nie)")
NW_FAM = ("Ceny surowcow: dzien", "Dowoz: dzien", "Dowoz (skutki): dzien", "Kary terenu (E7/T): dzien", "Budzet rodow (na sucho): dzien",
          "Towary (inne ticki dobowe): dzien")
NW_PROF_Q = re.compile(r"\| ciche \(tylko log, NW\) ([0-9.]+) ms / (\d+) odcinkow")
NW_PROF_G = re.compile(r"\| AiGear doba partii wg czesci \(NW, probka 1/16\):.*?; razem ([0-9.]+) ms")
NW_PROF_GK = re.compile(r"(zalogi|lordowie|inne) (\d+) \(probek (\d+)\) \[zaloga ([0-9.]+), rynek ([0-9.]+), naprawy ([0-9.]+), zakupy ([0-9.]+)\]")
NW_PROF_F = re.compile(r"\| AiFitted \(NW, probka 1/16\): wywolan (\d+) \(probek (\d+), bez sztuk (\d+)\), AiPieces ([0-9.]+) ms, MenOf ([0-9.]+) ms, FitBest ([0-9.]+) ms")
NW_SE = re.compile(r"^Spalona ziemia \(NW\): dzien (\d+) \| szybki przeglad \(ScorchedEarthFastScan\) (\[WL\]|\[wyl\]) \| partii (\d+), probek starej drogi (\d+), "
                   r"rozjazdow (\d+) \(od wczytania (\d+)\) \| czas ([0-9.]+) ms")
NW_DAWN = re.compile(r"^NocnyMarsz: swit dnia (\d+)")
NW_DAWN_C = re.compile(r"oboz swiata \(petla AiNightCamp\): sr\. ([0-9.]+) ms, maks\. ([0-9.]+) ms")
NW_DAWN_T = re.compile(r"\| zagrozenia karawan \(NW\): siatka \(AiCampFastScan\) (\[WL\]|\[wyl\]), zapytan (\d+), probek starej drogi (\d+), rozjazdow (\d+), czas zagrozen ([0-9.]+) ms")
NW_LL = re.compile(r"^LegendaryLaw \(doba, NW\): dzien (\d+) \| zbrojownie AI ([0-9.]+) ms \(wlascicieli sprawdzonych (\d+) z (\d+), szukanie leniwe \(LegendarySweepLazy\) "
                   r"(\[WL\]|\[wyl\]), probek starej drogi (\d+), rozjazdow (\d+) \(od wczytania (\d+)\)\), targi ([0-9.]+) ms, stal valyrianska ([0-9.]+) ms")
NW_ERR_WHERE = ("LogGate", "RawPrice.QuietDay", "MarketRoad.Daily", "ScorchedEarth", "AiNightCamp", "DayProfile.Line", "NocnyMarsz.LogDawn", "LegendaryLaw")
NW_Z3 = re.compile(r"^Swaty ROT \(Z\.3\): dzien (\d+) - klanow (\d+), slubow (\d+), czas ([0-9.]+) ms; lordow szukajacych (\d+) .*?ocen pary (\d+)")
NW_Z3V = re.compile(r"proby wolnych lordow (\d+), w tym stara regula trafilaby w kandydata bez szans (\d+)(?: \(\d+%\))?, bez zadnego kandydata z szansa (\d+), pytan o szanse (\d+)")
NW_Z3L = re.compile(r"; losowanie leniwe \(MarriageLazyDraw\) (\[WL\]|\[wyl\][^:]*|NIE DZIALA[^:]*): losowan (\d+), probek starej drogi (\d+) \(ocen pary w probkach (\d+)\), "
                    r"rozjazdow (\d+) \(od wczytania (\d+)\)")
NW_CS = re.compile(r"^Profil CS \(E8/0\): dzien (\d+) .*?\| EconomyAudit: przebiegow (\d+) \(po wczytaniu (\d+)\), ([0-9.]+) ms; (.*?)(?: \| log sesji: (.*))?$")
NW_CS_W = re.compile(r"(otwarty plik \(ScribeKeepOpen \[WL\]\)|plik na zapis \(ScribeKeepOpen \[wyl\]\)), otwarc (\d+), potkniec pisarza (\d+), zapisow stara droga (\d+)")


def nwyd_main(logp, csp=None):
    """nwyd (noc 16.10, w-toku/noc-wydajnosc; rozpoznanie wydajnosci WGRANIA 61, kroki O1-O7, O9). Log Armoury (strumieniowo) i --crashscribe <session-*.log>
    (bez niego - log sesji z tego samego startu, jak inne grupy). NW-0 linia 'Ciche logi (NW)': w autotescie (bez -Profile) 'tryb: autotest - pelne' - inaczej
    NIE (wykrycie autotestu zawiodlo: progi dzienne innych grup padna); bieg -Profile - INFO (ciche jak u gracza). NW-1 linia 'Log (E8/O6)': 'linie pomiarow
    tej doby' tak w kazdej dobie (tryb pelny) albo tylko w dobach podzielnych przez N (tryb gry / profilu), a linie zestawu 1 (Ceny surowcow, Dowoz, Dowoz
    (skutki), Kary terenu, Budzet rodow (na sucho), Towary (inne ticki dobowe)) dokladnie w dobach 'tak' (bez dwoch pierwszych dob sesji). NW-2 'ciche (tylko
    log, NW)' w Profilu doby: doby 'nie' srednio <= 1 ms (INFO, gdy wszystkie 'tak'). NW-3 (CS) swaty Z.3 - losowanie leniwe [WL]: rozjazdow 0, probek >= 1,
    srednio ocen pary <= 300000 i czas <= 300 ms (doby 2..), sluby w biegu >= 100 dob 8-26 na 120 dob; proporcje prob (pytan / proby, trafienia bez szans,
    bez kandydata) INFO. NW-4 (CS) 'Profil CS': EconomyAudit codziennie (tryb pelny) albo dokladnie w dobach podzielnych przez 7 (gra / profil). NW-5
    'Spalona ziemia (NW)': rozjazdow 0, probek >= 1, mediana czasu <= 15 ms; ScorchedEarth.OnDaily z Profilu doby INFO. NW-6 linia switu - zagrozenia karawan:
    rozjazdow 0, probek >= 1 (gdy byly zapytania), 'oboz swiata (petla AiNightCamp)' srednio <= 3.0 ms. NW-7 AiGear wedlug czesci: suma = AiGear.OnDailyTickParty
    z Profilu doby +-25% (suma okna); AiFitted INFO. NW-8 'LegendaryLaw (doba, NW)': rozjazdow 0, przy [WL] wlascicieli sprawdzonych <= 20% magazynow,
    suma czesci = 'LegendaryLaw (czystki, ValyrianBlades)' z Profilu doby +-10% (suma okna). NW-9 bledy: Armoury 'ERROR in' w miejscach paczki 0, CrashScribe
    raporty WHERE MarriageFast / EconomyAudit 0 i POTKNIECIA w Z.3 0. NW-10 (CS) pisarz logu sesji: otwarty plik, potkniec 0 (ostatnia linia Profil CS);
    koniec sesji (SUMMARY / Session ended) INFO. Log bez paczki: INFO, bez wyjatku."""
    rep = Report()
    starts, o6, fam, prof, se, dawn, ll, errs = [], {}, {f: set() for f in NW_FAM}, {}, [], [], [], []
    if logp and os.path.isfile(logp):
        with open(logp, encoding="utf-8", errors="replace") as fh:
            for ln in fh:
                m = TS.match(ln.rstrip("\r\n"))
                s = m.group(2) if m else ln.rstrip("\r\n")
                if s.startswith("Ciche logi (NW)"):
                    mm = NW_START.search(s)
                    starts.append(mm.groups() if mm else (s[:160], None, "?", "?"))
                    continue
                if s.startswith("Log (E8/O6): dzien"):
                    mm = NW_O6.search(s)
                    if mm:
                        o6[int(mm.group(1))] = (mm.group(2), mm.group(3), mm.group(4))
                    continue
                if s.startswith("Profil doby (E8/0): dzien"):
                    d = num(r"dzien (\d+)", s)
                    if d is not None:
                        prof[d] = s
                    continue
                if s.startswith("Spalona ziemia (NW)"):
                    mm = NW_SE.search(s)
                    if mm:
                        se.append(mm.groups())
                    continue
                if s.startswith("NocnyMarsz: swit dnia"):
                    mc, mt = NW_DAWN_C.search(s), NW_DAWN_T.search(s)
                    dawn.append((int(NW_DAWN.match(s).group(1)), mc.groups() if mc else None, mt.groups() if mt else None))
                    continue
                if s.startswith("LegendaryLaw (doba, NW)"):
                    mm = NW_LL.search(s)
                    if mm:
                        ll.append(mm.groups())
                    continue
                if s.startswith("ERROR in "):
                    w = s[9:].split(":", 1)[0]
                    if any(w.startswith(x) for x in NW_ERR_WHERE):
                        errs.append(w)
                    continue
                for f in NW_FAM:
                    if s.startswith(f):
                        d = num(r"dzien (\d+)", s)
                        if d is not None:
                            fam[f].add(d)
                        break
        print(f"plik: {logp} | NW: linii startu {len(starts)}, Log (E8/O6) z polem NW {len(o6)}, Profil doby {len(prof)}, Spalona ziemia {len(se)}, switow {len(dawn)}, LegendaryLaw NW {len(ll)}")
    else:
        rep.add("NW-0..9: log Armoury", f"brak ({logp})", "INFO (podaj <Armoury-*.log>)", None)
    full, every, mode = True, 7, "?"
    # NW-0
    if not starts:
        rep.add("NW-0: linia startu 'Ciche logi (NW)'", "brak linii", "INFO (log bez paczki noc-wydajnosc)", None)
    else:
        st = starts[-1]
        mode = st[2]
        every = int(st[1]) if st[1] else 1
        full = mode.startswith("autotest - pelne") or mode.startswith("nie rozpoznany") or not st[0].startswith("[WL]")
        if mode.startswith("profil autotestu"):
            rep.add("NW-0: tryb cichych logow", f"{st[0]}, tryb: {mode}, dzialaja: {st[3]} (linii {len(starts)})", "INFO (bieg -Profile mierzy gre jak u gracza)", None)
        else:
            rep.add("NW-0: tryb cichych logow w autotescie - 'autotest - pelne'", f"{st[0]}, tryb: {mode}, dzialaja: {st[3]} (linii {len(starts)})",
                    "'tryb: autotest - pelne (codziennie)', dzialaja: nie (inny tryb = wykrycie autotestu zawiodlo)", mode.startswith("autotest - pelne") and st[3] == "nie")
    # NW-1
    if o6:
        days = sorted(o6)
        bad = [d for d in days if (o6[d][2] == "tak") != (True if full else (every <= 1 or d % every == 0))]
        rep.add("NW-1a: 'linie pomiarow tej doby' w linii Log (E8/O6) zgodnie z trybem",
                f"dob {len(days)} ({days[0]}-{days[-1]}), 'tak' {sum(1 for d in days if o6[d][2] == 'tak')}, niezgodnych {len(bad)}" + (f" (np. d{bad[0]})" if bad else ""),
                ("tak w kazdej dobie (tryb pelny)" if full else f"tak tylko w dobach podzielnych przez {every}"), not bad)
        inner = days[2:]
        miss, extra, seen = [], [], []
        for f in NW_FAM:
            if not fam[f]:
                continue
            seen.append(f.split(":")[0])
            for d in inner:
                on = o6[d][2] == "tak"
                if on and d not in fam[f]:
                    miss.append(f"{f.split(':')[0]} d{d}")
                elif not on and d in fam[f]:
                    extra.append(f"{f.split(':')[0]} d{d}")
        rep.add("NW-1b: linie zestawu 1 dokladnie w dobach 'tak' (bez 2 pierwszych dob sesji)",
                f"rodzin linii {len(seen)} ({', '.join(seen)}), brak w dobie 'tak' {len(miss)}" + (f" ({'; '.join(miss[:4])})" if miss else "")
                + f", w dobie 'nie' {len(extra)}" + (f" ({'; '.join(extra[:4])})" if extra else ""), "0 i 0", (not miss and not extra) if seen and inner else None)
    else:
        rep.add("NW-1: linia Log (E8/O6) z polem 'ciche logi (NW)'", "brak", "INFO (log bez paczki albo LogEnabled wylaczony)", None)
    # NW-2
    qy, qn = [], []
    for d, s in prof.items():
        m = NW_PROF_Q.search(s)
        if not m:
            continue
        flag = o6.get(d, (None, None, None))[2]
        (qn if flag == "nie" else qy).append(float(m.group(1)))
    if qy or qn:
        rep.add("NW-2: Profil doby - odcinki tylko-log (ciche) w dobach bez pomiaru",
                f"doby z pomiarem srednio {sum(qy) / len(qy) if qy else 0:.1f} ms ({len(qy)}), bez pomiaru {sum(qn) / len(qn) if qn else 0:.2f} ms ({len(qn)})",
                "<= 1 ms w dobach bez pomiaru (wszystkie z pomiarem - INFO)", (sum(qn) / len(qn) <= 1.0) if qn else None)
    else:
        rep.add("NW-2: Profil doby - pole 'ciche (tylko log, NW)'", "brak", "INFO (Stage8ProfileLog wylaczony albo log bez paczki)", None)
    # NW-5
    if se:
        rd = sum(int(g[4]) for g in se); smp = sum(int(g[3]) for g in se); ms = sorted(float(g[6]) for g in se)
        med = ms[len(ms) // 2]
        on = se[-1][1] == "[WL]"
        rep.add("NW-5: spalona ziemia - odleglosc przed wojna: rozjazdow 0, probek >= 1, mediana czasu <= 15 ms",
                f"dob {len(se)}, klucz {se[-1][1]}, partii srednio {sum(int(g[2]) for g in se) / len(se):.0f}, probek {smp}, rozjazdow {rd}, czas mediana {med:.1f} ms (maks. {ms[-1]:.1f})",
                "rozjazdow 0, probek >= 1, mediana <= 15 ms (bylo 41.6-42.2 ms w klatce polnocy)", (rd == 0 and smp >= 1 and med <= 15.0) if on else None)
        sod = [fnum(r"ScorchedEarth\.OnDaily ([0-9.]+)", s) for s in prof.values()]
        sod = [x for x in sod if x is not None]
        rep.add("NW-5b: ScorchedEarth.OnDaily w Profilu doby (top 15 taktu)", f"srednio {sum(sod) / len(sod):.1f} ms ({len(sod)} dob w top 15)" if sod else "poza top 15 w kazdej dobie",
                "INFO (bylo 41.6-42.2 ms)", None)
    else:
        rep.add("NW-5: linia 'Spalona ziemia (NW)'", "brak", "INFO (ScorchedEarthEnabled wylaczony albo log bez paczki)", None)
    # NW-6
    dt = [g for g in dawn if g[2]]
    if dt:
        rd = sum(int(g[2][3]) for g in dt); smp = sum(int(g[2][2]) for g in dt); q = sum(int(g[2][1]) for g in dt)
        camp = [float(g[1][0]) for g in dt if g[1]]
        avg = sum(camp) / len(camp) if camp else None
        on = dt[-1][2][0] == "[WL]"
        rep.add("NW-6: oboz nocy - siatka zagrozen karawan: rozjazdow 0, probek >= 1, petla AiNightCamp srednio <= 3.0 ms",
                f"switow {len(dt)}, klucz {dt[-1][2][0]}, zapytan {q}, probek {smp}, rozjazdow {rd}, czas zagrozen srednio {sum(float(g[2][4]) for g in dt) / len(dt):.1f} ms/noc"
                + (f", petla AiNightCamp sr. {avg:.2f} ms (maks. nocy {max(float(g[1][1]) for g in dt if g[1]):.1f} ms)" if camp else ""),
                "rozjazdow 0, probek >= 1 przy zapytaniach, sr. <= 3.0 ms (bylo 6.24)", (rd == 0 and (smp >= 1 or q == 0) and (avg is None or avg <= 3.0)) if on else None)
    else:
        rep.add("NW-6: linia switu z polem 'zagrozenia karawan (NW)'", "brak", "INFO (AiCampsAtNight wylaczony albo log bez paczki)", None)
    # NW-7
    gs, ev, fit = 0.0, 0.0, []
    nd = 0
    for d, s in prof.items():
        mg = NW_PROF_G.search(s); me = fnum(r"AiGear\.OnDailyTickParty ([0-9.]+)", s)
        if mg and me is not None:
            gs += float(mg.group(1)); ev += me; nd += 1
        mf = NW_PROF_F.search(s)
        if mf:
            fit.append(mf.groups())
    if nd:
        rel = abs(gs - ev) / ev if ev > 0 else 0.0
        rep.add("NW-7: AiGear doba partii wedlug czesci = AiGear.OnDailyTickParty z Profilu doby +-25% (suma okna)",
                f"dob {nd}: czesci {gs:.0f} ms, zdarzenie {ev:.0f} ms (roznica {100 * rel:.0f}%)", "+-25%", rel <= 0.25 if ev > 0 else None)
    else:
        rep.add("NW-7: AiGear wedlug czesci", "brak pola albo AiGear.OnDailyTickParty poza top 4 zdarzen", "INFO", None)
    if fit:
        n = len(fit)
        rep.add("NW-7b: AiFitted wedlug czesci (INFO pod runde 2)",
                f"dob {n}: wywolan srednio {sum(int(g[0]) for g in fit) / n:.0f}, AiPieces {sum(float(g[3]) for g in fit) / n:.1f} ms, MenOf {sum(float(g[4]) for g in fit) / n:.1f} ms,"
                f" FitBest {sum(float(g[5]) for g in fit) / n:.1f} ms na dobe", "INFO", None)
    # NW-8
    if ll:
        rd = sum(int(g[6]) for g in ll); own = sum(int(g[2]) for g in ll); arm = sum(int(g[3]) for g in ll)
        parts = sum(float(g[1]) + float(g[8]) + float(g[9]) for g in ll[1:-1])
        dx = [fnum(r"LegendaryLaw \(czystki, ValyrianBlades\) ([0-9.]+)", prof[d]) for d in sorted(prof)[1:-1]]
        dx = [x for x in dx if x is not None]
        lazy = ll[-1][4] == "[WL]"
        rep.add("NW-8: LegendaryLaw - wlasciciel zbrojowni leniwie: rozjazdow 0, wlascicieli <= 20% magazynow",
                f"dob {len(ll)}, klucz {ll[-1][4]}, wlascicieli {own} z {arm} ({100.0 * own / arm if arm else 0:.0f}%), probek {sum(int(g[5]) for g in ll)}, rozjazdow {rd};"
                f" srednio zbrojownie {sum(float(g[1]) for g in ll) / len(ll):.1f} ms, targi {sum(float(g[8]) for g in ll) / len(ll):.1f} ms, stal {sum(float(g[9]) for g in ll) / len(ll):.1f} ms",
                "rozjazdow 0; przy [WL] <= 20%", (rd == 0 and (not lazy or arm == 0 or own <= 0.2 * arm)))
        if dx and len(ll) > 2:
            sx = sum(dx)
            rel = abs(parts - sx) / sx if sx > 0 else 0.0
            rep.add("NW-8b: LegendaryLaw czesci = 'LegendaryLaw (czystki, ValyrianBlades)' z Profilu doby +-10% (suma okna bez pierwszej i ostatniej)",
                    f"czesci {parts:.0f} ms ({len(ll) - 2} dob), Profil doby {sx:.0f} ms ({len(dx)} dob), roznica {100 * rel:.0f}%", "+-10% (INFO, gdy liczba dob okien rozna)", (rel <= 0.10 if sx > 0 else None) if len(dx) == len(ll) - 2 else None)
    else:
        rep.add("NW-8: linia 'LegendaryLaw (doba, NW)'", "brak", "INFO (Stage8ProfileLog wylaczony, brak DTE albo log bez paczki)", None)
    # CrashScribe
    cs_path, how = (None, "bez logu Armoury")
    if csp or logp:
        cs_path, how = crashscribe_session_of(logp, csp) if logp else ((csp, "--crashscribe") if csp and os.path.isfile(csp) else (None, "brak pliku"))
    z3, csl, lazy_lines, cs_err, z3_stumble, ended, start_z3 = [], [], [], 0, 0, False, None
    if cs_path:
        with open(cs_path, encoding="utf-8", errors="replace") as fh:
            for ln in fh:
                s = ln.rstrip("\r\n")
                m = TS.match(s)
                s2 = m.group(2) if m else s
                if s2.startswith("Swaty ROT (Z.3): dzien"):
                    mz = NW_Z3.search(s2)
                    if mz:
                        mv, ml = NW_Z3V.search(s2), NW_Z3L.search(s2)
                        z3.append((mz.groups(), mv.groups() if mv else None, ml.groups() if ml else None))
                    if "POTKNIECIA" in s2:
                        z3_stumble += 1
                    continue
                if s2.startswith("Swaty ROT (Z.3): losowanie leniwe - ROZJAZD"):
                    lazy_lines.append(s2)
                    continue
                if s2.startswith("Mends: swaty ROT (Z.3)"):
                    start_z3 = s2
                    continue
                if s2.startswith("Profil CS (E8/0): dzien"):
                    mc = NW_CS.search(s2)
                    if mc:
                        csl.append(mc.groups())
                    continue
                if s2.startswith("WHERE   : ") and ("MarriageFast" in s2 or "EconomyAudit" in s2):
                    cs_err += 1
                    continue
                if "SUMMARY" in s2 or s2.startswith("Session ended"):
                    ended = True
        print(f"plik: {cs_path} ({how}) | NW: linii Z.3 {len(z3)}, Profil CS z EconomyAudit {len(csl)}")
    # NW-3
    zl = [g for g in z3 if g[2]]
    if zl:
        body = zl[1:] if len(zl) > 1 else zl
        rd = sum(int(g[2][4]) for g in zl); smp = sum(int(g[2][2]) for g in zl)
        ev = sum(int(g[0][5]) for g in body) / len(body); tm = sum(float(g[0][3]) for g in body) / len(body)
        on = zl[-1][2][0] == "[WL]"
        rep.add("NW-3: swaty Z.3 - losowanie leniwe: rozjazdow 0, probek >= 1, srednio ocen pary <= 300000 i czas <= 300 ms (doby 2..)",
                f"dob {len(zl)}, stan {zl[-1][2][0]}, losowan srednio {sum(int(g[2][1]) for g in zl) / len(zl):.0f}, probek {smp}, rozjazdow {rd} (linii ROZJAZD {len(lazy_lines)});"
                f" ocen pary srednio {ev:.0f}, czas {tm:.1f} ms", "rozjazdow 0, probek >= 1, <= 300000, <= 300 ms (bylo 1.03-1.13 mln, 944-1013 ms)",
                (rd == 0 and smp >= 1 and ev <= 300000 and tm <= 300.0) if on else None)
        vv = [g[1] for g in body if g[1] and int(g[1][0]) > 0]
        if vv:
            fr = sum(int(v[0]) for v in vv); dead = sum(int(v[1]) for v in vv); nov = sum(int(v[2]) for v in vv); ce = sum(int(v[3]) for v in vv)
            rep.add("NW-3b: swaty - proporcje prob (ten sam rozklad co pelna lista; porownac z biegiem MarriageLazyDraw=false na tym samym zapisie)",
                    f"proby wolnych lordow {fr}: pytan o szanse na probe {ce / fr:.2f}, stara regula w kandydata bez szans {100.0 * dead / fr:.0f}%, bez kandydata z szansa {100.0 * nov / fr:.0f}%",
                    "INFO (Jeff 15.10, pozna kampania: ok. 5.3, 66-69%, ok. 10%)", None)
        wed = sum(int(g[0][2]) for g in zl)
        if len(zl) >= 100:
            per120 = wed * 120.0 / len(zl)
            rep.add("NW-3c: swaty - sluby w biegu (regulator 48 na rok)", f"{wed} w {len(zl)} dobach ({per120:.1f} na 120 dob)", "8-26 na 120 dob", 8 <= per120 <= 26)
        else:
            rep.add("NW-3c: swaty - sluby w biegu", f"{wed} w {len(zl)} dobach", "INFO (prog 8-26 dla biegu >= 100 dob)", None)
    elif z3:
        rep.add("NW-3: swaty Z.3 - pole losowania leniwego", "brak pola w liniach Z.3", "INFO (CrashScribe bez paczki)", None)
    else:
        rep.add("NW-3: swaty Z.3 (CrashScribe)", f"brak linii ({how})", "INFO (--crashscribe <session-*.log>)", None)
    if start_z3 is not None:
        rep.add("NW-3d: linia startu swatow - stan losowania leniwego", start_z3[start_z3.find("losowanie leniwe"):][:120] if "losowanie leniwe" in start_z3 else start_z3[:160],
                "INFO", None)
    # NW-4
    if csl:
        body = csl[1:]
        tryb = csl[-1][4]
        cfull = "codziennie" in tryb
        # kolejnosc sluchaczy doby (MbEvent: od ostatnio dopisanego) - linia "dzien D" niesie przebieg z taktu D; druga hipoteza (takt D+1) dla pewnosci
        bads = []
        for sh in (0, 1):
            bad = []
            for g in body:
                d, runs, st0 = int(g[0]), int(g[1]), int(g[2])
                want = 1 if (cfull or (d + sh) % 7 == 0) else 0
                if (runs - st0 >= 1) != (want == 1):
                    bad.append(f"d{d} {runs - st0}")
            bads.append(bad)
        bad = bads[0] if len(bads[0]) <= len(bads[1]) else bads[1]
        ran = [float(g[3]) / max(1, int(g[1])) for g in csl if int(g[1]) > 0]
        rep.add("NW-4: audyt ekonomii CS - przebiegi zgodnie z trybem",
                f"linii {len(csl)}, tryb '{tryb}', niezgodnych {len(bad)}" + (f" ({', '.join(bad[:4])})" if bad else "")
                + (f"; przebieg srednio {sum(ran) / len(ran):.0f} ms" if ran else ""),
                "codziennie (autotest) albo tylko w dobach podzielnych przez 7 (gra, -Profile)", not bad if body else None)
        mw = NW_CS_W.search(csl[-1][5] or "")
        if mw:
            rep.add("NW-10: pisarz logu sesji CrashScribe - otwarty plik, potkniec 0", f"{mw.group(1)}, otwarc {mw.group(2)}, potkniec {mw.group(3)}, zapisow stara droga {mw.group(4)}",
                    "[WL], potkniec 0", "[WL]" in mw.group(1) and int(mw.group(3)) == 0)
        else:
            rep.add("NW-10: pisarz logu sesji CrashScribe", "brak pola 'log sesji' w linii Profil CS", "INFO", None)
    else:
        rep.add("NW-4: audyt ekonomii CS (linia Profil CS z polem EconomyAudit)", f"brak ({how})", "INFO (Stage8ProfileLog CrashScribe albo log bez paczki)", None)
    if cs_path:
        rep.add("NW-10b: koniec sesji CrashScribe (SUMMARY / Session ended - pisarz zamkniety przy wyjsciu)", "jest" if ended else "brak", "INFO (brak = gra nie wyszla zwyczajnie)", None)
    # NW-9
    rep.add("NW-9: bledy w miejscach paczki - Armoury 'ERROR in', CrashScribe WHERE MarriageFast / EconomyAudit, POTKNIECIA w Z.3",
            f"Armoury {len(errs)}" + (f" ({', '.join(sorted(set(errs))[:4])})" if errs else "") + (f", CrashScribe raportow {cs_err}, potkniec Z.3 {z3_stumble}" if cs_path else ", bez logu CrashScribe"),
            "0, 0, 0", len(errs) == 0 and cs_err == 0 and z3_stumble == 0)
    rep.show()
    return 0


# ------------------------------------------------------------ nzlec (16.10, Jeff "jak ktos nie ma kasy to jak moze ofertowac kucie mieczy??"; Armoury/src/CraftOrdersPurse.cs)
NZE_HEAD = "Zlecenia kowalskie (NZ): "
NZE_REST = (r", wiszacych (\d+) \(bez pokrycia (\d+)\), kiesa zleceniodawcow min/mediana (-?\d+|-)/(-?\d+|-) "
            r"\| suma zlecen jednego zleceniodawcy \(zapas na premie \+(\d+)%\): kiesa na jedno, nie na sume (\d+), "
            r"zleceniodawcow z kilkoma zleceniami (\d+) \(najwiecej (\d+) u jednego\) "
            r"\| zostawione mimo braku: ekran kuzni otwarty (\d+), niezgodny slot albo brak drogi gry (\d+) "
            r"\| w cieniu \(klucz wylaczony\): bez kiesy (\d+), bez zywego zleceniodawcy (\d+) "
            r"\| zlecen zadan \(pominiete\) (\d+), bez pokrycia (\d+) "
            # r4-zlecenia (20.10, Craft Order Clan Purse): segment kiesy rodu - opcjonalny (logi sprzed galezi bez niego; grupy None)
            r"(?:\| kiesa rodu \(Craft Order Clan Purse (CZYNNE|WYLACZONE)\): zlecen lordow, ktorzy nie sa glowa rodu (\d+), pokryte dopiero doplata glowy (\d+) "
            r"\(doplata glowy na nie razem (\d+), glow (\d+)\), bez pokrycia mimo glowy (\d+), w cieniu \(klucz wylaczony\) pokrylaby glowa (\d+) )?"
            r"\| klucz Craft Orders Giver Can Pay (CZYNNE|WYLACZONE), placi zleceniodawca \(Craft Orders Historical\) (CZYNNE|WYLACZONE), dziala (TAK|NIE)")
NZE_DAY = re.compile(r"Zlecenia kowalskie \(NZ\): dzien (-?\d+) \| utworzone (\d+), odrzucone przy tworzeniu (\d+) \(brak kiesy\), "
                     r"usuniete w dobie (\d+) \(kiesa (\d+), smierc (\d+)\)" + NZE_REST
                     + r" \| przy tworzeniu bez sprawdzenia: klucz albo platnik wylaczony (\d+), przed przeliczeniem cen (\d+), ekran kuzni otwarty (\d+), "
                     r"zostawione \(niezgodny slot albo brak drogi gry\) (\d+) \| odrzucone przy tworzeniu przez sume zlecen zleceniodawcy (\d+)"
                     r"(?:, zostawione przy tworzeniu dzieki doplacie glowy rodu (\d+))? \| nagrody: odrzuconych razem (\d+), usunietych w dobie razem (\d+) "
                     r"\| koszt ([0-9.]+) ms/dobe \| potkniecia (\d+) \(od wczytania (\d+)\)\.$")
NZE_SES = re.compile(r"Zlecenia kowalskie \(NZ\): start sesji \| zlecen miejskich z zapisu (\d+), usuniete z zapisu (\d+) \(kiesa (\d+), smierc (\d+); "
                     r"nagrod usunietych razem (\d+)\)" + NZE_REST
                     + r" \| przed startem sesji \(start nowej kampanii\): utworzone (\d+), odrzucone przy tworzeniu (\d+) \(w tym przez sume zlecen (\d+)\), przed przeliczeniem cen \(sprawdzone tutaj\) (\d+) "
                     r"\| latka tworzenia \(CreateTownOrder\) (TAK|NIE), droga gry RemoveTownOrder (TAK|NIE) \| koszt ([0-9.]+) ms \| potkniecia (\d+)\.$")
NZE_WIRE = NZE_HEAD + "latki przy starcie gry"
NZE_E8K = re.compile(r"Kuznia \(E8/K\): dzien (-?\d+) \|.*?oddanych (\d+) \(w tym zlecen zadan (\d+)\), obiecane (\d+), zaplacone przez zleceniodawce (\d+), "
                     r"(?:doplata glowy rodu \(Craft Order Clan Purse (CZYNNE|WYLACZONE)\) (\d+) w (\d+) zleceniach \(do pelna (\d+), potkniecia (\d+)\), )?"   # r4-zlecenia
                     r"niedoplata przy pustej kiesie (-?\d+) w (\d+) zleceniach")
NZE_CERR = "ERROR in CraftOrderClanPurse."   # r4-zlecenia
NZE_ERR = "ERROR in CraftOrdersPurse."
NZE_REST_KEYS = ("hang", "unc", "pmin", "pmed", "resv", "psum", "multi", "maxn", "open", "mism", "shp", "shd", "quest", "qunc",
                 "ckey", "clords", "ccov", "chelp", "cheads", "cshort", "cshadow",   # r4-zlecenia: kiesa rodu (None - log sprzed galezi)
                 "key", "pay", "on")


def nze_rest(g, i):
    """Wspolny srodek linii doby i startu sesji (Rest w CraftOrdersPurse.cs) od grupy i."""
    v = g[i:i + len(NZE_REST_KEYS)]
    d = {}
    for k, x in zip(NZE_REST_KEYS, v):
        if x is None:
            d[k] = None                                   # r4-zlecenia: segment kiesy rodu nieobecny (log sprzed galezi)
        elif k in ("key", "pay", "ckey"):
            d[k] = x == "CZYNNE"
        elif k == "on":
            d[k] = x == "TAK"
        elif k in ("pmin", "pmed"):
            d[k] = None if x == "-" else int(x)
        else:
            d[k] = int(x)
    return d


def nzlec_main(logp):
    """nzlec (16.10; Armoury/src/CraftOrdersPurse.cs, klucz CraftOrdersGiverCanPay): zlecenie kowalskie (miejskie: notable i lordowie) tylko od zleceniodawcy
    z kiesa na sume swoich zlecen (miejskie we wszystkich miastach + zadan, zapas +20% na premie) - odrzucenie przy tworzeniu (postfiks CreateTownOrder),
    przeglad przy starcie sesji i co dobe (zmarly albo kiesa ponizej narastajacej sumy - zdjete droga gry RemoveTownOrder; ekran kuzni otwarty - zostaje;
    zlecenia zadan pominiete, tylko licznik bez pokrycia). Wejscie: log Armoury (strumieniowo).
    NZE-0 linia startu gry (wpiete 2/2, BRAK: -), NZE-1 linia startu sesji (klucz i platnik czynne, dziala TAK; klucz wylaczony - INFO), NZE-2 start sesji:
    bez pokrycia = ekran kuzni + niezgodny slot + cien, przy dziala TAK bez pokrycia 0, NZE-3 linia doby w kazdej dobie z linia "Kuznia (E8/K): dzien"
    od pierwszej linii NZ i wszystkie rozpoznane, NZE-4 spojnosc linii doby (usuniete = kiesa + smierc, odrzucone <= utworzone, bez pokrycia = ekran kuzni +
    niezgodny + cien; dziala TAK - cien 0; dziala NIE - odrzucone i usuniete 0; kiesa na jedno, nie na sume <= kiesa + cien bez kiesy, przy tworzeniu <=
    odrzucone; kilka zlecen u jednego - najwiecej >= 2; zadan bez pokrycia <= zadan), NZE-5 po przegladzie doby (dziala TAK) wiszace bez pokrycia tylko spod
    otwartej kuzni, niezgodny slot / brak drogi gry 0 (przegladu i tworzenia), NZE-6 odrzucone i usuniete (INFO), NZE-7 wiszace i kiesy zleceniodawcow
    (INFO), NZE-8 niedoplata przy oddaniu (linie E8/K w dobach z NZ dziala TAK): najwyzej 1 na 10 oddanych (oddanych < 5 - INFO), NZE-9 potkniecia (doby
    i startu sesji) i ERROR in CraftOrdersPurse.* 0, NZE-10 koszt (INFO). Log bez paczki: INFO, bez wyjatku.
    r4-zlecenia (20.10, klucz CraftOrderClanPurse): segment "kiesa rodu (Craft Order Clan Purse ...)" w linii NZ, pole "zostawione przy tworzeniu dzieki doplacie
    glowy rodu" w linii doby i "doplata glowy rodu (...)" w linii E8/K - opcjonalne (logi sprzed galezi bez nich); NZE-11 spojnosc kiesy rodu (pokryte + bez pokrycia
    + cien <= zlecen lordow-czlonkow, pokryte > 0 <=> doplata > 0, cien tylko przy kluczu wylaczonym, E8/K do pelna <= z doplata, potkniecia 0), NZE-9 liczy
    takze ERROR in CraftOrderClanPurse.*."""
    rep = Report()
    if not logp or not os.path.isfile(logp):
        rep.add("NZE-0: log Armoury", f"brak pliku {logp}", "podaj <Armoury-*.log>", None)
        rep.show()
        return 0
    wires, sess, days, bad, e8k = [], [], {}, [], {}
    n_err = 0
    with open(logp, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\n"))
            s = m.group(2) if m else ln.rstrip("\n")
            if s.startswith(NZE_HEAD):
                if s.startswith(NZE_WIRE):
                    wires.append(s)
                elif s.startswith(NZE_HEAD + "start sesji"):
                    mm = NZE_SES.match(s)
                    if mm:
                        g = mm.groups()
                        r = dict(seen=int(g[0]), rem=int(g[1]), poor=int(g[2]), dead=int(g[3]), due=int(g[4]))
                        r.update(nze_rest(g, 5))
                        k = 5 + len(NZE_REST_KEYS)
                        r.update(made=int(g[k]), rej=int(g[k + 1]), rejsum=int(g[k + 2]), early=int(g[k + 3]), wired=g[k + 4] == "TAK", way=g[k + 5] == "TAK",
                                 ms=float(g[k + 6]), stum=int(g[k + 7]))
                        sess.append(r)
                    else:
                        bad.append(s)
                elif s.startswith(NZE_HEAD + "dzien "):
                    mm = NZE_DAY.match(s)
                    if mm:
                        g = mm.groups()
                        r = dict(day=int(g[0]), made=int(g[1]), rej=int(g[2]), rem=int(g[3]), poor=int(g[4]), dead=int(g[5]))
                        r.update(nze_rest(g, 6))
                        k = 6 + len(NZE_REST_KEYS)
                        r.update(c_off=int(g[k]), c_early=int(g[k + 1]), c_open=int(g[k + 2]), c_kept=int(g[k + 3]), rejsum=int(g[k + 4]),
                                 mclan=int(g[k + 5]) if g[k + 5] is not None else None, rej_due=int(g[k + 6]),
                                 rem_due=int(g[k + 7]), ms=float(g[k + 8]), stum=int(g[k + 9]), stum_s=int(g[k + 10]))
                        days[r["day"]] = r
                    else:
                        bad.append(s)
                else:
                    bad.append(s)
            elif s.startswith("Kuznia (E8/K): dzien "):
                mm = NZE_E8K.match(s)
                if mm:
                    g = mm.groups()
                    e8k[int(g[0])] = dict(done=int(g[1]), quest=int(g[2]), due=int(g[3]), paid=int(g[4]), short=int(g[11]),
                                          ckey=None if g[5] is None else g[5] == "CZYNNE", head=int(g[6] or 0), headn=int(g[7] or 0), headfull=int(g[8] or 0),
                                          cstum=int(g[9] or 0))
                else:
                    e8k.setdefault(num(r"dzien (-?\d+)", s, int, -10 ** 9), None)
            elif s.startswith(NZE_ERR) or s.startswith(NZE_CERR):
                n_err += 1
    print(f"plik: {logp} | linii startu gry {len(wires)}, startu sesji {len(sess)}, doby {len(days)}, nierozpoznanych NZ {len(bad)}, linii E8/K doby {len(e8k)}")
    if not wires and not sess and not days and not bad:
        rep.add("NZE-0: linie 'Zlecenia kowalskie (NZ)'", "brak w logu", "INFO (log sprzed paczki NZ)", None)
        rep.show()
        return 0
    # NZE-0 start gry
    if wires:
        w0 = wires[-1]
        ok = "wpiete 2/2" in w0 and "; BRAK: - |" in w0
        rep.add("NZE-0: linia startu gry (postfiks CreateTownOrder, droga gry RemoveTownOrder)", w0[len(NZE_HEAD):][:220], "wpiete 2/2, BRAK: -", ok)
    else:
        rep.add("NZE-0: linia startu gry", "brak linii (sa inne linie NZ)", "linia przy kazdym starcie gry", False)
    # NZE-1 start sesji
    if sess:
        allon = all(r["key"] and r["pay"] and r["on"] for r in sess)
        anyoff = [i for i, r in enumerate(sess) if not r["key"]]
        wired = all(r["wired"] and r["way"] for r in sess)
        last = sess[-1]
        val = (f"sesji {len(sess)}; ostatnia: zlecen {last['seen']}, usuniete z zapisu {last['rem']} (kiesa {last['poor']}, smierc {last['dead']}), "
               f"wiszacych {last['hang']}, klucz {'tak' if last['key'] else 'NIE'}, platnik {'tak' if last['pay'] else 'NIE'}, dziala {'TAK' if last['on'] else 'NIE'}; "
               f"latka {'tak' if last['wired'] else 'NIE'}, droga gry {'tak' if last['way'] else 'NIE'}")
        if anyoff and not any(r["key"] for r in sess):
            rep.add("NZE-1: linia startu sesji (klucz CraftOrdersGiverCanPay wylaczony)", val, "INFO (klucz wylaczony - liczniki w cieniu)", None)
        else:
            rep.add("NZE-1: linia startu sesji - klucz i platnik czynne, latka i droga gry", val, "kazda sesja: klucz CZYNNE, platnik CZYNNE, dziala TAK, latka TAK, droga TAK",
                    allon and wired)
    else:
        rep.add("NZE-1: linia startu sesji", "brak linii (sa inne linie NZ)", "linia przy kazdym starcie sesji", False)
    # NZE-2 start sesji - po przegladzie
    if sess:
        bad_s = [i + 1 for i, r in enumerate(sess)
                 if r["unc"] != r["open"] + r["mism"] + r["shp"] + r["shd"] or (r["on"] and (r["unc"] != r["open"] or r["mism"] != 0))
                 or r["rem"] != r["poor"] + r["dead"] or r["psum"] > r["poor"] + r["shp"] or r["rejsum"] > r["rej"]
                 or (r["on"] and r["psum"] > r["poor"]) or (r["multi"] > 0) != (r["maxn"] >= 2) or r["qunc"] > r["quest"]]
        rem = sum(r["rem"] for r in sess)
        rep.add("NZE-2: start sesji - zlecenia z zapisu bez pokrycia zdjete",
                f"usuniete z zapisu razem {rem} (kiesa {sum(r['poor'] for r in sess)}, smierc {sum(r['dead'] for r in sess)}, nagrod {sum(r['due'] for r in sess)}); "
                f"bez pokrycia po przegladzie {sum(r['unc'] for r in sess)} (ekran kuzni {sum(r['open'] for r in sess)}, niezgodny slot {sum(r['mism'] for r in sess)}, "
                f"cien {sum(r['shp'] + r['shd'] for r in sess)}); kiesa na jedno, nie na sume (z zapasem +{sess[-1]['resv']}%) {sum(r['psum'] for r in sess)}, "
                f"zleceniodawcow z kilkoma zleceniami po przegladzie (ostatnia sesja) {sess[-1]['multi']} (najwiecej {sess[-1]['maxn']}); "
                f"przed startem sesji utworzone {sum(r['made'] for r in sess)}, odrzucone {sum(r['rej'] for r in sess)} (przez sume {sum(r['rejsum'] for r in sess)}), "
                f"przed przeliczeniem cen {sum(r['early'] for r in sess)}"
                + (f"; NIESPOJNE sesje {bad_s[:5]}" if bad_s else ""),
                "usuniete = kiesa + smierc; bez pokrycia = ekran kuzni + niezgodny + cien; dziala TAK - bez pokrycia tylko spod otwartej kuzni, niezgodny 0; "
                "kiesa na jedno, nie na sume <= kiesa (+ cien); kilka zlecen - najwiecej >= 2", not bad_s)
    # NZE-3 linie doby
    first = min(days) if days else None
    want = sorted(d for d in e8k if first is not None and d >= first)
    miss = [d for d in want if d not in days]
    if days:
        rep.add("NZE-3: linia doby 'Zlecenia kowalskie (NZ)' w kazdej dobie z linia E8/K (od pierwszej linii NZ), wszystkie rozpoznane",
                f"linii doby {len(days)}, dob E8/K od d{first}: {len(want)}, brak w {len(miss)}" + (f" ({miss[:5]})" if miss else "")
                + f"; nierozpoznanych linii NZ {len(bad)}" + (f" - np.: {bad[0][:160]}" if bad else ""),
                "brak 0, nierozpoznanych 0", not miss and not bad)
    else:
        rep.add("NZE-3: linia doby 'Zlecenia kowalskie (NZ)'", "brak linii doby" + (f"; nierozpoznanych linii NZ {len(bad)} - np.: {bad[0][:160]}" if bad else ""),
                "INFO (bieg bez doby po starcie sesji)" if not bad else "linie rozpoznane", None if not bad else False)
        rep.show()
        return 0
    rows = [days[d] for d in sorted(days)]
    # NZE-4 spojnosc linii doby
    inc = []
    for r in rows:
        why = []
        if r["rem"] != r["poor"] + r["dead"]:
            why.append("usuniete != kiesa + smierc")
        if r["rej"] > r["made"]:
            why.append("odrzucone > utworzone")
        if r["unc"] != r["open"] + r["mism"] + r["shp"] + r["shd"]:
            why.append("bez pokrycia != ekran + niezgodny + cien")
        if r["on"] and (r["shp"] or r["shd"]):
            why.append("cien przy dziala TAK")
        if not r["on"] and (r["rej"] or r["rem"]):
            why.append("odrzucone/usuniete przy dziala NIE")
        if r["on"] != (r["key"] and r["pay"]):
            why.append("dziala != klucz i platnik")
        if r["psum"] > r["poor"] + r["shp"] or (r["on"] and r["psum"] > r["poor"]):
            why.append("kiesa na jedno, nie na sume > usuniete przez kiese (+ cien)")
        if r["rejsum"] > r["rej"]:
            why.append("odrzucone przez sume > odrzucone")
        if (r["multi"] > 0) != (r["maxn"] >= 2):
            why.append("kilka zlecen u jednego != najwiecej >= 2")
        if r["qunc"] > r["quest"]:
            why.append("zadan bez pokrycia > zadan")
        if why:
            inc.append((r["day"], why))
    rep.add("NZE-4: spojnosc linii doby (usuniete = kiesa + smierc, odrzucone <= utworzone, bez pokrycia = ekran + niezgodny + cien, cien tylko przy kluczu wylaczonym, "
            "suma zlecen jednego zleceniodawcy)",
            f"dob {len(rows)}, niespojnych {len(inc)}" + (f" (np. d{inc[0][0]}: {', '.join(inc[0][1])})" if inc else ""), "0", not inc)
    on_rows = [r for r in rows if r["on"]]
    off_rows = [r for r in rows if not r["on"]]
    # NZE-5 po przegladzie doby
    if on_rows:
        unc = sum(r["unc"] - r["open"] for r in on_rows)
        mism = sum(r["mism"] for r in on_rows)
        kept = sum(r["c_kept"] for r in on_rows)
        opn = sum(r["open"] + r["c_open"] for r in on_rows)
        rep.add("NZE-5: po przegladzie doby (dziala TAK) - wiszace bez pokrycia poza otwarta kuznia, niezgodny slot / brak drogi gry (przeglad i tworzenie)",
                f"bez pokrycia poza kuznia {unc}, niezgodny przeglad {mism}, tworzenie {kept}; zostawione spod otwartej kuzni {opn} (dob dziala TAK {len(on_rows)})",
                "0 / 0 / 0", unc == 0 and mism == 0 and kept == 0)
    else:
        rep.add("NZE-5: po przegladzie doby", "brak dob z dziala TAK" + (f"; w cieniu (dob {len(off_rows)}): bez kiesy razem {sum(r['shp'] for r in off_rows)}, "
                f"bez zywego zleceniodawcy {sum(r['shd'] for r in off_rows)}" if off_rows else ""), "INFO (klucz albo platnik wylaczony)", None)
    # NZE-6 odrzucone i usuniete
    made, rej = sum(r["made"] for r in rows), sum(r["rej"] for r in rows)
    remp, remd = sum(r["poor"] for r in rows), sum(r["dead"] for r in rows)
    rep.add("NZE-6: zlecenia utworzone, odrzucone przy tworzeniu (brak kiesy) i usuniete w dobie (suma dob)",
            f"utworzone {made} ({made / len(rows):.1f}/d), odrzucone {rej}" + (f" ({100.0 * rej / made:.0f}%)" if made else "")
            + f" (przez sume zlecen {sum(r['rejsum'] for r in rows)}), nagrod odrzuconych {sum(r['rej_due'] for r in rows)}; usuniete w dobie {remp + remd} "
            f"(kiesa {remp}, w tym przez sume {sum(r['psum'] for r in rows if r['on'])}, smierc {remd}, nagrod {sum(r['rem_due'] for r in rows)}); "
            f"bez sprawdzenia: klucz albo platnik wylaczony {sum(r['c_off'] for r in rows)}, przed przeliczeniem cen {sum(r['c_early'] for r in rows)}",
            "INFO (odrzucone 100% przez >= 28 dob - sprawdzic kiesy notabli)", None)
    # NZE-7 wiszace i kiesy
    step = max(1, len(rows) // 8)
    path = "; ".join(f"d{r['day']}: {r['hang']} (kiesa min/med {r['pmin'] if r['pmin'] is not None else '-'}/{r['pmed'] if r['pmed'] is not None else '-'})" for r in rows[::step])
    rep.add("NZE-7: wiszace zlecenia miejskie i kiesy zleceniodawcow (przebieg), zleceniodawcy z kilkoma zleceniami, zlecenia zadan (pominiete) bez pokrycia",
            path[:600] + f" | ostatnia doba: zleceniodawcow z kilkoma zleceniami {rows[-1]['multi']} (najwiecej {rows[-1]['maxn']}), zapas +{rows[-1]['resv']}%; "
            f"zadan {rows[-1]['quest']}, bez pokrycia {rows[-1]['qunc']} (najwiecej w dobie {max(r['qunc'] for r in rows)})",
            "INFO (zadanie szefa gangu bez pokrycia - przy oddaniu 'could pay only'; zadania nie zdejmujemy)", None)
    # NZE-8 niedoplata przy oddaniu
    ed = [e8k[r["day"]] for r in on_rows if e8k.get(r["day"])]
    done = sum(x["done"] for x in ed)
    short = sum(x["short"] for x in ed)
    if done >= 5:
        rep.add("NZE-8: niedoplata przy oddaniu zlecenia (linie E8/K w dobach z dziala TAK)",
                f"oddanych {done} (zadan {sum(x['quest'] for x in ed)}), z niedoplata {short}; obiecane {sum(x['due'] for x in ed)}, zaplacone {sum(x['paid'] for x in ed)}"
                f", doplata glowy rodu {sum(x['head'] for x in ed)} w {sum(x['headn'] for x in ed)} (do pelna {sum(x['headfull'] for x in ed)})",
                "najwyzej 1 na 10 oddanych (kiesa spadla po przegladzie albo premia za lepsza bron)", short * 10 <= done)
    else:
        rep.add("NZE-8: niedoplata przy oddaniu zlecenia", f"oddanych {done}, z niedoplata {short} (dob z linia E8/K i dziala TAK {len(ed)})",
                "INFO (oddanych < 5 - autotest nie kuje zlecen; sprawdzenie w grze: brak komunikatu 'could pay only 0 of the agreed')", None)
    # NZE-11 (r4-zlecenia, Craft Order Clan Purse): kiesa rodu - spojnosc segmentu w liniach NZ i pola doplaty glowy w liniach E8/K
    crow = [r for r in rows if r.get("ckey") is not None]
    if crow:
        cinc = []
        for r in crow:
            why = []
            if r["ccov"] + r["cshort"] + r["cshadow"] > r["clords"]:
                why.append("pokryte + bez pokrycia + cien > zlecen lordow")
            if (r["ccov"] > 0) != (r["chelp"] > 0) or r["cheads"] > r["ccov"] or (r["cheads"] > 0) != (r["ccov"] > 0):
                why.append("pokryte / doplata / glow niespojne")
            if r["ckey"] and r["pay"] and r["cshadow"]:          # cien tylko, gdy klucz kiesy rodu albo platnik (Craft Orders Historical) wylaczony
                why.append("cien przy kluczu i platniku czynnych")
            if not (r["ckey"] and r["pay"]) and (r["ccov"] or r["chelp"]):
                why.append("doplata glowy przy kluczu albo platniku wylaczonym")
            if not r["on"] and (r.get("mclan") or 0):            # tworzenie sprawdzane tylko przy dziala TAK
                why.append("zostawione przy tworzeniu dzieki glowie przy dziala NIE")
            if why:
                cinc.append((r["day"], why))
        eh = [x for x in e8k.values() if x and x.get("ckey") is not None]
        e_bad = [x for x in eh if x["headfull"] > x["headn"] or (x["head"] > 0) != (x["headn"] > 0)]
        cstum = max([x["cstum"] for x in eh] or [0])
        last = crow[-1]
        rep.add("NZE-11: kiesa rodu (Craft Order Clan Purse) - segment w liniach NZ spojny, doplata glowy w E8/K spojna, potkniecia 0",
                f"dob z segmentem {len(crow)} (klucz {'CZYNNE' if last['ckey'] else 'WYLACZONE'}), niespojnych {len(cinc)}" + (f" (np. d{cinc[0][0]}: {', '.join(cinc[0][1])})" if cinc else "")
                + f"; suma dob: zlecen lordow-czlonkow (wiszacych) srednio {sum(r['clords'] for r in crow) / len(crow):.0f}, pokryte dopiero doplata glowy srednio "
                f"{sum(r['ccov'] for r in crow) / len(crow):.1f} (doplata srednio {sum(r['chelp'] for r in crow) / len(crow):.0f}), bez pokrycia mimo glowy {sum(r['cshort'] for r in crow)}, "
                f"zostawione przy tworzeniu dzieki glowie {sum(r.get('mclan') or 0 for r in crow)}; E8/K: linii z polem {len(eh)}, niespojnych {len(e_bad)}, "
                f"doplata glowy {sum(x['head'] for x in eh)} w {sum(x['headn'] for x in eh)} zleceniach, potkniecia {cstum}",
                "niespojnych 0 / 0, potkniecia 0 (pokryte dopiero doplata glowy > 0 - INFO: lordowie-czlonkowie rodu skladaja zlecenia)",
                not cinc and not e_bad and cstum == 0)
    else:
        rep.add("NZE-11: kiesa rodu (Craft Order Clan Purse)", "brak segmentu 'kiesa rodu' w liniach doby NZ", "INFO (log sprzed galezi r4-zlecenia)", None)
    # NZE-9 potkniecia i bledy
    stu = sum(r["stum"] for r in rows)
    stu_s = max([r["stum"] for r in sess] or [0])
    rep.add("NZE-9: potkniecia (doby / start sesji) i linie ERROR in CraftOrdersPurse.* / CraftOrderClanPurse.*", f"{stu} / {stu_s} / {n_err}", "0 / 0 / 0", stu == 0 and stu_s == 0 and n_err == 0)
    # NZE-10 koszt
    cs = [r["ms"] for r in rows]
    rep.add("NZE-10: koszt (tworzenie i przeglad)", f"srednio {sum(cs) / len(cs):.2f} ms/dobe, najwiecej {max(cs):.2f} ms" + (f"; start sesji najwiecej {max(r['ms'] for r in sess):.2f} ms" if sess else ""),
            "INFO", None)
    rep.show()
    return 0



