N3E_OB_TOPUP = re.compile(r"doplaty notabli do 5000 ([+-]?\d+)")
N3E_1_PORT = re.compile(r"wstrzymane \(porcja\) (\d+) \(")
N3E_1_KIND = re.compile(r"spadek indeksu wedlug rodzaju sprzedazy \(najwiekszy w jednym miescie dzis\): z zyskiem (-?[\d.]+)%, na stracie porcjami (-?[\d.]+)% "
                        r"\(granica [\d.]+%\), bez wyjscia \(rozwiazanie, brak na zold\) (-?[\d.]+)%")


def _n3e_read(logp, full=True):
    """Strumieniowo: linie dob nekon3 (full=False - tylko 'Pieniadz swiata', 'Pompy', 'Kredyt korony', 'Korona 165' i 'Ceny surowcow' - log bazy)."""
    d = {k: {} for k in ("world", "guard", "folk", "pumps", "crown", "loan", "sutl", "toll", "t1", "stock", "price", "flow", "t2", "obnc")}
    st = {"guard": None, "toll": None, "t1": None, "hook": None}
    errs, newerr = [], []
    heads = [(N3E_WORLD, "world"), (N3E_PUMPS, "pumps"), (N3E_LOAN, "loan"), (N3E_PRICE, "price"), (N3E_CROWN, "crown"), (N3E_FLOW, "flow"), (N3E_OBNC, "obnc")]
    if full:
        heads += [(N3E_GUARD, "guard"), (N3E_FOLK, "folk"), (N3E_SUTL, "sutl"), (N3E_TOLL, "toll"), (N3E_T1, "t1"), (N3E_STOCK, "stock"), (N3E_T2, "t2")]
    with open(logp, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\n"))
            s = m.group(2) if m else ln.rstrip("\n")
            if s.startswith("ERROR in "):
                errs.append(s[:160])
                if s.startswith(N3E_NEWERR):
                    newerr.append(s[:160])
                continue
            if full:
                if s.startswith(N3E_S_GUARD):
                    st["guard"] = s; continue
                if s.startswith(N3E_S_TOLL):
                    st["toll"] = s; continue
                if s.startswith(N3E_S_T1):
                    st["t1"] = s; continue
                if s.startswith(N3E_S_HOOK):
                    st["hook"] = s; continue
            for h, k in heads:
                if s.startswith(h):
                    a = N3E_DAY.search(s)
                    if a:
                        d[k][int(a.group(1))] = s
                    break
    return d, st, errs, newerr


def _n3e_world(s):
    """'Pieniadz swiata': razem, zmiana, posiadacze, udzialy lud / lordowie / korony."""
    a = N3E_W_TOT.search(s)
    if not a:
        return None
    w = {"razem": int(a.group(1)), "zmiana": int(a.group(2))}
    for k, p in N3E_W_HOLD.items():
        w[k] = num(p, s, int, 0)
    tot = max(1, w["razem"])
    w["lud"] = (w["kiesy_wsi"] + w["lud_miasta"] + w["lud_podzamcza"] + w["lud_gminy"]) / tot * 100
    w["lordowie_pct"] = (w["glowy"] + w["lordowie"] + w["gracz"]) / tot * 100
    w["korony_pct"] = w["korony"] / tot * 100
    for k in ("sakiewki", "karawany", "kasy_miast", "notable", "bank"):
        w[k + "_pct"] = w[k] / tot * 100
    return w


def _n3e_mean(vals):
    return sum(vals) / len(vals) if vals else None


def _n3e_slope(pts):
    """Nachylenie (na dobe) prostej najmniejszych kwadratow przez (doba, wartosc)."""
    if len(pts) < 2:
        return None
    n = len(pts)
    mx = sum(p[0] for p in pts) / n
    my = sum(p[1] for p in pts) / n
    sxx = sum((p[0] - mx) ** 2 for p in pts)
    if sxx <= 0:
        return None
    return sum((p[0] - mx) * (p[1] - my) for p in pts) / sxx


def _n3e_nd(s):
    """'Ceny surowcow': suma 'nie do wydania' = budzet mieszczan - przy dzisiejszych polkach (wzor plan3/nd2.py)."""
    return sum(int(m.group(1)) - int(m.group(2)) for m in N3E_PRICE_ND.finditer(s))


