def nbw_first(rows, key):
    """Pierwsza probka (napis inny niz '-') z linii misji NB2 - czesc 2."""
    for r in rows:
        v = r.get(key)
        if isinstance(v, str) and v != "-":
            return v
    return "-"


def nbw_part2(rep, rows, tot):
    """nbitwa czesc 2 (16.10): NBW-9 taktyka wedlug dowodcy, NBW-10 weterani wedlug tieru, NBW-11 krew przez pancerz, NBW-12 okrzyki i jeki -
    INFO (autotest nie gra bitew). Linie czesci 1 (bez tych pol) - INFO 'brak pol czesci 2'."""
    p2 = [r for r in rows if r.get("takt") is not None]
    if not p2:
        rep.add("NBW-9..12: taktyka, weterani, krew, glosy", "brak pol czesci 2 w liniach misji", "INFO (wersja sprzed czesci 2)", None)
        return
    rep.add("NBW-9: taktyka wedlug dowodcy (Commander Tactics)", f"druzyn {tot('t_druzyn')} (tlum {tot('t_tlum')}, konnica i obrona {tot('t_konnica')},"
            f" okrazenie {tot('t_okrazenie')}, bez zmian {tot('t_bez_zmian')}, gracza pominieto {tot('t_gracza')}, nie pole {tot('t_nie_pole')},"
            f" bez danych {tot('t_bez_danych')}); dodanych {tot('t_dodane')} (duble {tot('t_duble')}, brak typu RBM {tot('t_brak_typu')});"
            f" probka atak {nbw_first(p2, 't_probka_a')}, obrona {nbw_first(p2, 't_probka_d')}",
            "INFO (bitwa polowa: druzyny AI z taktyka wedlug Tactics; bez danych i brak typu RBM 0)", None)
    wt = [tot(f"w{i}") for i in range(1, 8)]
    orders = sorted(set(str(r.get("w_po_rbm")) for r in p2))
    rep.add("NBW-10: weterani wedlug tieru (Veterans By Tier)", f"ludzi {tot('w_ludzi')} (" + ", ".join(f"T{i + 1} {n}" for i, n in enumerate(wt))
            + f"), wywolan {tot('w_wywolan')}, ponad limit RBM {tot('w_ponad')}, z tarcza {tot('w_tarcza')}, kapitan Tactics 150+ {tot('w_kapitan')};"
            f" po RBM: {', '.join(orders)}; probka T6 parowanie {nbw_first(p2, 'w_probka')}",
            "INFO (po RBM TAK; ponad limit tylko T5+ bez tarczy; probka T6 0.60->0.80 przy Realistic)", None)
    rep.add("NBW-11: krew przez pancerz (Blood Through Armour)", f"bryzgi {tot('g_bryzgi')} (przez pancerz {tot('g_pancerz')}, smiertelne"
            f" {tot('g_smiertelne')}), odrzucone limitem {tot('g_limit')}, zla kosc {tot('g_kosc')}; misji z RBMCombat"
            f" {sum(1 for r in p2 if r.get('g_rbm') == 'TAK')} z {len(p2)}", "INFO (zla kosc 0; limit 1 na czlowieka na 0.5 s, 20 na s)", None)
    vl = tot("v_ludzi")
    rep.add("NBW-12: okrzyki przy szarzy i jeki rannych (Battle Cries And Moans)", f"szarze {tot('v_szarze')} (okrzykow {tot('v_okrzyki')}, roznych"
            f" ludzi {vl}, na glowe {tot('v_okrzyki') / max(1, vl):.1f}), jeki {tot('v_jeki')} (rannych {tot('v_rannych')}, na rannego"
            f" {tot('v_jeki') / max(1, tot('v_rannych')):.1f}), odrzucone limitem {tot('v_limit')}",
            "INFO (okrzyk najwyzej raz na 20 s na czlowieka, szyk raz na 40 s; jekow na rannego <= 3; najwyzej 6 glosow na s)", None)


def nbw_part3(rep, rows, tot):
    """nbitwa czesc 3 (16.10, BloodPools.cs): NBW-13 kaluze krwi na ziemi - INFO (liczby); NBW-13b (poprawka po recenzji 16.10) - TAK / NIE:
    w misjach z kluczem TAK, rendererem TAK i bez MoreBlood materialy 12/12, bez materialu 0, a przy zgonach, ktore mogly krwawic (zgony bez
    nieumarlych, w wodzie i po zamknieciu misji) > 0 - decali > 0. Bez takiej misji - INFO. Linie bez segmentu kaluz - INFO 'brak pol czesci 3'."""
    p3 = [r for r in rows if r.get("kal") is not None]
    if not p3:
        rep.add("NBW-13: kaluze krwi (Ground Blood Pools)", "brak pol czesci 3 w liniach misji", "INFO (wersja sprzed kaluz)", None)
        return
    on = [r for r in p3 if r.get("kal") == "TAK"]
    mats = sorted(set(f"{r.get('p_mat')}/{r.get('p_mat_all')}" for r in on)) or ["-"]
    over = sum(1 for r in p3 if isinstance(r.get("p_decali"), int) and isinstance(r.get("p_max"), int) and r["p_decali"] > r["p_max"])
    rep.add("NBW-13: kaluze krwi (Ground Blood Pools)", f"decali {tot('p_decali')} (kaluze {tot('p_kaluze')}, plamy {tot('p_plamy')}, bez materialu"
            f" {tot('p_bez_mat')}); zgonow {tot('p_zgonow')} (z krwia {tot('p_z_krwia')}: ludzi {tot('p_ludzi')}, nieprzytomnych {tot('p_nieprz')},"
            f" koni {tot('p_koni')}; nieumarli {tot('p_nieumarli')}, w wodzie {tot('p_woda_zg')}, po zamknieciu misji {tot('p_koniec_zg')});"
            f" pominiete decale: limit misji {tot('p_limit')}, kolejka {tot('p_kolejka')}, zageszczenie {tot('p_gesto')}, bez ziemi {tot('p_bez_ziemi')},"
            f" w wodzie {tot('p_woda')}, poza polem {tot('p_poza')}, zle wspolrzedne {tot('p_zle')}, bez renderera {tot('p_bez_rend')}, przy zamknieciu"
            f" misji {tot('p_koniec')}; misji z kluczem {len(on)} z {len(p3)}, materialy {', '.join(mats)}, renderer TAK w"
            f" {sum(1 for r in on if r.get('p_renderer') == 'TAK')}, MoreBlood w {sum(1 for r in p3 if r.get('p_moreblood') == 'TAK')};"
            f" ponad pulap {over}; potkniecia 'kaluze' {tot('st_kaluze')}",
            "INFO (materialy 12/12, renderer TAK, bez materialu 0, decali <= 600 na misje, potkniecia 0; zle wspolrzedne i poza polem 0;"
            " bez ziemi to drabiny / mury / wieze; kolejka, limit i zageszczenie w duzych bitwach)", None)

    def ival(r, k):
        v = r.get(k)
        return v if isinstance(v, int) else 0

    # NBW-13b: czy kaluze w ogole dzialaja (cichy wynik 'materialy 0/12' / 'decali 0' przeszedlby na zielono w samym INFO)
    act = [r for r in on if r.get("p_renderer") == "TAK" and r.get("p_moreblood") != "TAK"]
    if not act:
        rep.add("NBW-13b: kaluze krwi dzialaja (decale z materialem przy zgonach)", f"brak misji z kluczem TAK, rendererem TAK i bez MoreBlood"
                f" (misji z kluczem {len(on)}, renderer NIE w {sum(1 for r in on if r.get('p_renderer') != 'TAK')})",
                "INFO (bez bitwy z rendererem decali nie ma czego sprawdzic)", None)
        return
    bad = []
    for r in act:
        bleed = ival(r, "p_zgonow") - ival(r, "p_nieumarli") - ival(r, "p_woda_zg") - ival(r, "p_koniec_zg")
        why = []
        if ival(r, "p_mat") < ival(r, "p_mat_all") or ival(r, "p_mat_all") == 0:
            why.append(f"materialy {r.get('p_mat')}/{r.get('p_mat_all')}")
        if ival(r, "p_bez_mat") > 0:
            why.append(f"bez materialu {ival(r, 'p_bez_mat')}")
        if bleed > 0 and ival(r, "p_decali") == 0:
            why.append(f"decali 0 przy {bleed} zgonach")
        if why:
            bad.append(f"misja {r.get('bitwa')}: " + ", ".join(why))
    withd = sum(1 for r in act if ival(r, "p_decali") > 0)
    rep.add("NBW-13b: kaluze krwi dzialaja (decale z materialem przy zgonach)", f"misji sprawdzonych {len(act)}, z decalami {withd}"
            + (f"; zle {len(bad)}: " + "; ".join(bad[:3]) if bad else ""),
            "TAK, gdy w kazdej misji z kluczem, rendererem i bez MoreBlood: materialy 12/12, bez materialu 0, decali > 0 przy zgonach > 0"
            " (po autotescie takze recznie: wyjscie z bitwy bez crasha - RemoveDecalInstance setek decali)", not bad)


# f5-bitwa (noc 17/18.10, Armoury/src/AutotestBattleKit.cs): zestaw bitwy autotestu - linie startu, zestawu, zdjecia; linie bitwy gracza sklad7b-p i DTE Underequipped
F5_HEAD = "Bitwa autotestu (f5-bitwa): "
F5_WIRE = re.compile(r"Bitwa autotestu \(f5-bitwa\): latka DTE TryInitializeDistributors \(prefiks\) (.*?) \| klucz AutotestBattleKit (TAK|NIE)")
F5_STOCK = re.compile(r"Bitwa autotestu \(f5-bitwa\): zestaw na bitwe \| plan (\S+) \| ludzi zdrowych (\d+) w (\d+) oddzialach \| potrzeba (\d+) szt\. "
                      r"\(konie (\d+), uprzaz (\d+)\), bylo w zbrojowni (\d+), dodane (\d+), odmowy DTE (\d+)")
F5_BACK = re.compile(r"Bitwa autotestu \(f5-bitwa\): zestaw zdjety po bitwie \(([^)]*)\) \| plan (\S+) \| wynik ([^|]+?) \| dodane (\d+) = zdjete (\d+) "
                     r"\+ ubytek (\d+)")
F5_SKLAD = re.compile(r"Bitwa gracza \(sklad7b-p, start\): Twoich ludzi (\d+) - bez broni (\d+), bez zbroi (\d+), jezdzcy pieszo (\d+)")
F5_UNDER = re.compile(r"Underequipped \(E8/P3\): dzien (-?\d+), koniec misji \| druzyna gracza \(DTE naklada kare na morale\): wystawieni (\d+), kara 0: (\d+), "
                      r"2-10: (\d+), 12-20: (\d+), srednia kara ([\d.]+|-)")


F5_OWN = re.compile(r"strata sztuk gracza tego samego id \(proporcja\) (\d+)")


def nbw_f5_scan(s, ev):
    """f5-bitwa: jedna linia logu (bez znacznika czasu) -> zdarzenie w kolejnosci logu. True = linia rozpoznana."""
    # recenzja 18.10: bledy paczki (Stumble / ApplyAll) i znacznik biegu autotestu (LogGate - ta sama flaga CrashScribe.Autotest.Active)
    if s.startswith("ERROR in AutotestBattleKit"):
        ev.append(("err", s[:200]))
        return True
    if s.startswith("Ciche logi (NW)"):
        if "tryb: autotest" in s:
            ev.append(("at",))
        return False
    if s.startswith(F5_HEAD):
        m = F5_WIRE.match(s)
        if m:
            ev.append(("wire", m.group(1), m.group(2)))
            return True
        m = F5_STOCK.match(s)
        if m:
            g = m.groups()
            ev.append(("stock", dict(plan=g[0], men=int(g[1]), troops=int(g[2]), need=int(g[3]), horses=int(g[4]), harness=int(g[5]),
                                     had=int(g[6]), added=int(g[7]), refused=int(g[8]))))
            return True
        m = F5_BACK.match(s)
        if m:
            g = m.groups()
            mo = F5_OWN.search(s)
            ev.append(("back", dict(why=g[0], plan=g[1], result=g[2].strip(), added=int(g[3]), removed=int(g[4]), lost=int(g[5]),
                                    own=int(mo.group(1)) if mo else 0)))
            return True
        ev.append(("other", s[len(F5_HEAD):][:160]))
        return True
    if s.startswith("Bitwa gracza (sklad7b-p, start): "):
        m = F5_SKLAD.match(s)
        if m:
            ev.append(("sklad", tuple(int(x) for x in m.groups())))
        return True
    if s.startswith("Underequipped (E8/P3): ") and "koniec misji" in s:
        m = F5_UNDER.match(s)
        if m:
            g = m.groups()
            ev.append(("under", int(g[1]), None if g[5] == "-" else float(g[5])))
        return True
    return False


def nbw_f5(rep, ev):
    """f5-bitwa (noc 17/18.10): NBW-14..NBW-19 - zestaw bitwy autotestu (AutotestBattleKit). Zdarzenia w kolejnosci logu z nbw_f5_scan."""
    wires = [e for e in ev if e[0] == "wire"]
    if wires:
        w = wires[-1]
        rep.add("NBW-14: zestaw bitwy autotestu - latka DTE (f5-bitwa)", f"latka {w[1]}, klucz AutotestBattleKit {w[2]}", "latka wpieta",
                w[1].startswith("wpieta"))
    else:
        rep.add("NBW-14: zestaw bitwy autotestu - latka DTE (f5-bitwa)", "brak linii", "INFO (DLL sprzed f5-bitwa)", None)
    # recenzja 18.10: NBW-14b bledy paczki; zestaw oczekiwany = latka wpieta z kluczem TAK; bieg autotestu = znacznik LogGate
    errs = [e[1] for e in ev if e[0] == "err"]
    if wires or errs:
        rep.add("NBW-14b: ERROR in AutotestBattleKit (potkniecia zestawu)", f"{len(errs)}" + (f"; pierwszy: {errs[0][:160]}" if errs else ""), "0", not errs)
    else:
        rep.add("NBW-14b: ERROR in AutotestBattleKit (potkniecia zestawu)", "brak linii wpiecia i bledow", "INFO (DLL sprzed f5-bitwa)", None)
    expect_kit = bool(wires) and wires[-1][1].startswith("wpieta") and wires[-1][2] == "TAK"
    at_run = any(e[0] == "at" for e in ev)
    # bitwy: linia sklad7b-p i Underequipped przypisane do ostatniego zestawu (albo 'plan slaba') przed nimi (zestaw otwiera bitwe, zdjecie ja zamyka)
    battles, cur = [], None
    for e in ev:
        if e[0] == "stock":
            cur = dict(stock=e[1], weak=False, sklad=None, under=None, back=None)
            battles.append(cur)
        elif e[0] == "other" and e[1].startswith("plan slaba"):
            cur = dict(stock=None, weak=True, sklad=None, under=None, back=None)
            battles.append(cur)
        elif e[0] == "sklad":
            if cur is not None and cur["sklad"] is None and cur["back"] is None:
                cur["sklad"] = e[1]
            else:
                battles.append(dict(stock=None, weak=False, sklad=e[1], under=None, back=None))
                cur = battles[-1]
        elif e[0] == "under":
            if cur is not None and cur["under"] is None:
                cur["under"] = (e[1], e[2])
        elif e[0] == "back":
            if cur is not None and cur["stock"] is not None and cur["back"] is None:
                cur["back"] = e[1]
            else:
                battles.append(dict(stock=None, weak=False, sklad=None, under=None, back=e[1]))
            cur = None
    kit = [b for b in battles if b["stock"] is not None]
    old = [b for b in battles if b["stock"] is None and not b["weak"] and b["sklad"] is not None]
    allbare = sum(1 for b in old if b["sklad"][0] > 0 and b["sklad"][1] == b["sklad"][0])
    # recenzja 18.10: bitwa bez zestawu przy wpietej latce z kluczem TAK w biegu autotestu (albo wszyscy bez broni) = zestaw nie zadzialal
    failed = old if expect_kit and (at_run or allbare > 0) else []
    # NBW-15 uzbrojenie
    if kit:
        rows, bad = [], 0
        for b in kit:
            sk = b["sklad"]
            if sk is None:
                rows.append(f"plan {b['stock']['plan']}: brak linii sklad7b-p")
                bad += 1
                continue
            men, nw, nb, nf = sk
            ok = men > 0 and nw <= 0.10 * men
            bad += 0 if ok else 1
            rows.append(f"plan {b['stock']['plan']}: ludzi {men}, bez broni {nw}, bez zbroi {nb}, pieszo {nf}")
        for b in failed:
            sk = b["sklad"]
            rows.append(f"BEZ ZESTAWU: ludzi {sk[0]}, bez broni {sk[1]}")
        bad += len(failed)
        rep.add("NBW-15: ludzie uzbrojeni w bitwie autotestu z zestawem", "; ".join(rows)[:400],
                "bez broni <= 10% ludzi w kazdej bitwie z zestawem; bitwa bez zestawu przy wpietej latce w autotescie - NIE", bad == 0)
    elif old:
        sk = old[-1]["sklad"]
        txt = (f"bez zestawu: bitew {len(old)}, wszyscy bez broni w {allbare}; ostatnia: ludzi {sk[0]}, bez broni {sk[1]}, bez zbroi {sk[2]}, pieszo {sk[3]}"
               + f" | latka wpieta z kluczem TAK: {'tak' if expect_kit else 'nie'}, bieg autotestu: {'tak' if at_run else 'nie'}")
        notes = [e[1] for e in ev if e[0] == "other" and (e[1].startswith("pominiete") or e[1].startswith("brak zbrojowni"))]
        if notes:
            txt += f" | linie paczki: {notes[-1][:120]}"
        if failed:
            rep.add("NBW-15: ludzie uzbrojeni w bitwie autotestu z zestawem", txt,
                    "zestaw w kazdej bitwie (plan mocna / odwrot) przy wpietej latce z kluczem TAK w autotescie - NIE: zestaw nie zadzialal", False)
        elif expect_kit:
            rep.add("NBW-15: ludzie uzbrojeni w bitwie autotestu z zestawem", txt, "INFO (log gry bez autotestu - zestaw nieczynny poza autotestem, poprawnie)", None)
        else:
            rep.add("NBW-15: ludzie uzbrojeni w bitwie autotestu z zestawem", txt,
                    "INFO (stary uklad testu - druzyna testu bez broni, zbroi i koni = przyczyna przegranych z panika; f5-bitwa)", None)
    else:
        rep.add("NBW-15: ludzie uzbrojeni w bitwie autotestu z zestawem", "brak bitew gracza w logu", "INFO (test bez bitwy)", None)
    if not kit:
        for name in ("NBW-16: tozsamosc zestawu (potrzeba = bylo + dodane + odmowy)", "NBW-17: zestaw zdjety po bitwie (dodane = zdjete + ubytek)",
                     "NBW-18: plan mocna - wygrana", "NBW-19: kara morale DTE po zestawie (Underequipped)"):
            rep.add(name, "brak linii zestawu", "INFO", None)
        skips = [e for e in ev if e[0] == "other" and e[1].startswith("plan slaba")]
        if skips:
            rep.add("NBW-15b: plan slaba bez zestawu", f"bitew {len(skips)}", "INFO (test przegranej i niewoli)", None)
        return
    # NBW-16 tozsamosc zestawu
    st = [b["stock"] for b in kit]
    idbad = sum(1 for x in st if x["need"] != x["had"] + x["added"] + x["refused"])
    need, ref = sum(x["need"] for x in st), sum(x["refused"] for x in st)
    rep.add("NBW-16: tozsamosc zestawu (potrzeba = bylo + dodane + odmowy)", f"zestawow {len(st)}, potrzeba {need}, bylo {sum(x['had'] for x in st)}, dodane"
            f" {sum(x['added'] for x in st)}, odmowy DTE {ref} ({100.0 * ref / max(1, need):.1f}%), niezgodnych {idbad}",
            "kazdy zgodny, odmowy <= 10% potrzeby", idbad == 0 and ref <= 0.10 * max(1, need))
    # NBW-17 zdjecie po bitwie
    withadd = [b for b in kit if b["stock"]["added"] > 0]
    miss = [b for b in withadd if b["back"] is None]
    backs = [b["back"] for b in withadd if b["back"] is not None]
    bbad = sum(1 for x in backs if x["added"] != x["removed"] + x["lost"])
    rep.add("NBW-17: zestaw zdjety po bitwie (dodane = zdjete + ubytek)", f"bitew z zestawem {len(withadd)}, zdjec {len(backs)}, brak zdjecia {len(miss)};"
            f" dodane {sum(x['added'] for x in backs)} = zdjete {sum(x['removed'] for x in backs)} + ubytek {sum(x['lost'] for x in backs)}; niezgodnych {bbad}"
            f"; strata sztuk gracza tego samego id (proporcja) {sum(x.get('own', 0) for x in backs)}"
            + (f"; powody: {', '.join(sorted(set(x['why'] for x in backs)))}" if backs else ""),
            "zdjecie po kazdej bitwie z zestawem, tozsamosc w kazdym", not miss and bbad == 0)
    # NBW-18 wynik planu mocna
    strong = [b["back"] for b in kit if b["stock"]["plan"] == "mocna" and b["back"] is not None]
    if strong:
        lost = [x["result"] for x in strong if x["result"] != "wygrana"]
        rep.add("NBW-18: plan mocna - wygrana", f"bitew {len(strong)}, wyniki: {', '.join(x['result'] for x in strong)}", "wygrana w kazdej", not lost)
    else:
        rep.add("NBW-18: plan mocna - wygrana", "brak bitwy planu mocna ze zdjeciem zestawu", "INFO", None)
    # NBW-19 kara morale DTE
    pen = [b["under"][1] for b in kit if b["under"] is not None and b["under"][1] is not None]
    if pen:
        rep.add("NBW-19: kara morale DTE po zestawie (Underequipped)", f"bitew {len(pen)}, srednia kara: {', '.join(f'{x:.1f}' for x in pen)}",
                "<= 5 w kazdej (bez zestawu 20.0)", max(pen) <= 5.0)
    else:
        rep.add("NBW-19: kara morale DTE po zestawie (Underequipped)", "brak linii Underequipped po zestawie", "INFO", None)


def nbitwa_main(logp):
    """nbitwa (16.10, bitwa czesc 1; Armoury/src/RoutHold.cs, BattleWind.PostureInitPostfix): (A) zlamany ranny (BrokenMen + FieldCraft) panikuje
    raz na bitwe, morale przypiete na 0, ponowienia odwrotu bez okrzyku co 4 s, cel ucieczki z 16 sektorow (klucze BrokenMenNeverRally,
    FleeAwayFromEnemies); (B) postura szeregowych RBM wedlug tieru (SoldierPostureByTier, T1 x0.85 ... T6 x1.7). Wejscie: log Armoury
    (strumieniowo). Progi twarde: NBW-0 linia startu sesji (4 x TAK), NBW-0b linia wpiecia latki postury przy starcie gry, NBW-1 ERROR in
    RoutHold / RoutKeeper / BattleWind.PostureInit / BattleWind.ApplyAll = 0 (poprawka 16.10: ApplyAll; NBW-5 z 'cel gry odrzucony'). Reszta INFO (autotest nie gra bitew): NBW-2 linie misji, NBW-3 raz Panic na czlowieka
    (ponowne paniki gry 0), NBW-4 morale i ponowienia, NBW-5 kierunek, NBW-6 postura wedlug tieru (probki: mnoznik T1 / T6), NBW-7 potkniecia,
    NBW-8 linia NM w bitwach (wywolan = roznych ludzi). Log bez paczki: NBW-0 NIE, reszta INFO, bez wyjatku.
    Czesc 4 (f5-bitwa, noc 17/18.10): NBW-14..NBW-19 - zestaw bitwy autotestu (nbw_f5; opis w naglowku pliku)."""
    rep = Report()
    if not logp or not os.path.isfile(logp):
        rep.add("NBW-0: log Armoury", f"brak pliku {logp}", "podaj <Armoury-*.log>", None)
        rep.show()
        return 0
    starts, wires, rows, bad, notes, nm, vets = [], [], [], [], [], [], []
    f5ev = []           # f5-bitwa: zdarzenia zestawu bitwy autotestu w kolejnosci logu
    wind_off = wind_bad = wind_norbm = 0
    wind_err = None     # pierwsza linia 'ERROR in BattleWind.ApplyAll' (do NBW-0b)
    errs = {k: 0 for k in NBW_ERR}
    with open(logp, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\n"))
            s = m.group(2) if m else ln.rstrip("\n")
            if nbw_f5_scan(s, f5ev):
                continue
            if s.startswith(NBW_HEAD):
                if s.startswith(NBW_START):
                    starts.append(s)
                elif s.startswith(NBW_HEAD + "misja "):
                    mm = NBW_LINE.match(s)
                    if mm:
                        r = {}
                        for k, v in zip(NBW_KEYS, mm.groups()):
                            r[k] = int(v) if v is not None and v.isdigit() else v
                        rows.append(r)
                    else:
                        bad.append(s)
                else:
                    notes.append(s)
            elif s.startswith(NBW_WIRE):
                wires.append(s)
            elif s.startswith(NBW_VET_HEAD):
                vets.append(s)
            elif s.startswith("BattleWind: RBM nieobecny"):
                wind_norbm += 1
            elif s.startswith("BattleWind: pola RBMAI.Stance nie pasuja") or s.startswith("BattleWind: metody RBMAI.Stance nie pasuja"):
                wind_bad += 1
            elif s.startswith("BattleWind: wylaczone."):
                wind_off += 1
            elif s.startswith("Druzyny w misji (NM): misja "):
                mm = NM_LINE.match(s)
                if mm:
                    g = mm.groups()
                    nm.append(dict(battle=g[1] == "TAK", pushed=(int(g[12]), int(g[13])), calls=(int(g[14]), int(g[15]))))
            elif s.startswith("ERROR in "):
                for k in NBW_ERR:
                    if s.startswith(k):
                        errs[k] += 1
                        if k == "ERROR in BattleWind.ApplyAll" and wind_err is None:
                            wind_err = s[:200]
                        break
    print(f"plik: {logp} | linii startu {len(starts)}, wpiecia postury {len(wires)}, linii misji {len(rows) + len(bad)} (rozpoznanych {len(rows)}),"
          f" innych linii NB2 {len(notes)}, linii NM {len(nm)}")
    # NBW-0 start sesji
    st = starts[-1] if starts else ""
    if st:
        miss = [k for k in NBW_NEED if k not in st]
        rep.add("NBW-0: linia startu sesji (Bitwa NB2)", st[len(NBW_HEAD):][:260] + (" | brak: " + "; ".join(miss) if miss else ""),
                "linia jest, " + ", ".join(NBW_NEED), not miss)
    else:
        rep.add("NBW-0: linia startu sesji (Bitwa NB2)", "brak linii", "linia jest (brak = wersja sprzed NB2 albo log bez kampanii)", False)
    # NBW-0b latka postury przy starcie gry
    if wires:
        rep.add("NBW-0b: latka postury RBM (start gry)", wires[-1][:200], "linia wpiecia jest", True)
    elif wind_norbm:
        rep.add("NBW-0b: latka postury RBM (start gry)", "RBM nieobecny", "INFO (bez RBM nie ma postury)", None)
    elif wind_off:
        rep.add("NBW-0b: latka postury RBM (start gry)", "BattleWind: wylaczone (oba klucze wylaczone przy starcie)", "INFO", None)
    else:
        rep.add("NBW-0b: latka postury RBM (start gry)", "pola / metody RBM nie pasuja" if wind_bad else (wind_err or "brak linii"),
                "linia wpiecia jest", False)
    # NBW-0c latka weteranow przy starcie gry (czesc 2)
    vw = [v for v in vets if v.startswith(NBW_VET_WIRE)]
    if vw:
        rep.add("NBW-0c: latka weteranow wedlug tieru (start gry)", vw[-1][:200], "linia wpiecia jest", True)
    elif any("RBM nieobecny" in v for v in vets):
        rep.add("NBW-0c: latka weteranow wedlug tieru (start gry)", "RBM nieobecny", "INFO (bez RBM nic do zmiany)", None)
    elif any("wylaczeni przy starcie" in v for v in vets):
        rep.add("NBW-0c: latka weteranow wedlug tieru (start gry)", "VeteransByTier wylaczony przy starcie", "INFO", None)
    else:
        rep.add("NBW-0c: latka weteranow wedlug tieru (start gry)", (vets[-1][:200] if vets else "brak linii"), "linia wpiecia jest", False)
    # NBW-1 bledy
    n_err = sum(errs.values())
    rep.add("NBW-1: ERROR zlamanych, postury, taktyki, weteranow, krwi, glosow i kaluz", ", ".join(f"{k[len('ERROR in '):]} {v}" for k, v in errs.items()),
            "0", n_err == 0)
    nbw_f5(rep, f5ev)   # f5-bitwa (noc 17/18.10): zestaw bitwy autotestu - NBW-14..NBW-19
    # NBW-2 linie misji
    if not rows and not bad:
        rep.add("NBW-2: linie misji 'Bitwa (NB2)'", "brak linii", "INFO (autotest nie gra bitew - sprawdzenie w grze: bitwa polowa z rannymi)", None)
        rep.show()
        return 0
    kinds = {}
    for r in rows:
        kinds[r["bitwa"]] = kinds.get(r["bitwa"], 0) + 1
    rep.add("NBW-2: linie misji rozpoznane", f"{len(rows)} z {len(rows) + len(bad)} (" + ", ".join(f"{k} {v}" for k, v in sorted(kinds.items())) + ")"
            + (f"; nierozpoznana np.: {bad[0][:160]}" if bad else ""), "INFO (wszystkie rozpoznane)", None)

    def tot(k):
        return sum(r[k] for r in rows if isinstance(r.get(k), int))

    br = tot("zlamani")
    # NBW-3 raz Panic
    rep.add("NBW-3: raz Panic na czlowieka na bitwe", f"zlamani {br} (rozbici {tot('rozbici')}, ucieczka {tot('ucieczka')}); Panic {tot('panic')}, juz w panice"
            f" {tot('juz')}, ponowne paniki gry {tot('repanic')}; odmowy: po koncu {tot('po_koncu')}, bez druzyny {tot('bez_druzyny')},"
            f" z rozkazu {tot('rozkaz')}", "INFO (Panic + juz w panice = zlamani; ponowne paniki gry 0; log 16.10 03:50: 257 wywolan na 7 ludzi)", None)
    # NBW-4 morale i ponowienia
    rp = tot("ponowienia_ludzi")
    rep.add("NBW-4: morale przypiete i ponowienia bez okrzyku", f"przypiete {tot('pin')} razy (ludzi {tot('pin_ludzi')}), zgaszone przez innych {tot('zgaszone')};"
            f" ponowienia {tot('ponowienia')} (ludzi {rp}, na glowe {tot('ponowienia') / max(1, rp):.1f}), zmiany kierunku {tot('zwroty')},"
            f" bez handlera {tot('bez_handlera')}, przejeci przez gracza {tot('gracz')}",
            "INFO (ponowien najwyzej czas ucieczki / 4 s na glowe; zgaszone = RBM zdazyl przed przypieciem)", None)
    # NBW-5 kierunek
    rep.add("NBW-5: cel ucieczki", f"gry {tot('k_gry')}, sektor {tot('k_sektor')}, bez drogi {tot('k_bez_drogi')}, limit zapytan {tot('k_limit')},"
            f" poza polem {tot('k_poza')}; zapytan o droge {tot('zapytan')}; cel gry odrzucony {tot('k_odrzucony')} (blisko gracza"
            f" {tot('k_gracz')}); misji z polem bitwy {sum(1 for r in rows if r['pole'] == 'TAK')}",
            "INFO (gry + sektor + bez drogi + poza polem = zlamani z odwrotem; limit rzadko; odrzucony = cel gry w strone wrogow / gracza)", None)
    # NBW-6 postura
    tiers = [tot(f"t{i}") for i in range(1, 8)]

    def ratio(key):
        for r in rows:
            v = r.get(key, "-")
            if isinstance(v, str) and "->" in v:
                a, b = v.split("->", 1)
                try:
                    a, b = float(a), float(b)
                    if a > 0:
                        return f"{v} (x{b / a:.2f})"
                except ValueError:
                    pass
        return "-"

    rep.add("NBW-6: postura szeregowych wedlug tieru", f"szeregowych {sum(tiers)} (" + ", ".join(f"T{i + 1} {n}" for i, n in enumerate(tiers))
            + f"), bohaterow {tot('bohaterow')}, bez broni pominiete {tot('bez_broni')}; probka T1 {ratio('probka1')}, T6 {ratio('probka6')}",
            "INFO (T1 x0.85, T6 x1.70 przy kluczach domyslnych; pula T1 ok. 115, T6 ok. 344)", None)
    # NBW-7 potkniecia
    rep.add("NBW-7: potkniecia w liniach misji", f"panika {tot('st_panika')}, kierunek {tot('st_kierunek')}, postura {tot('st_postura')},"
            f" taktyka {tot('st_taktyka')}, weteran {tot('st_weteran')}, krew {tot('st_krew')}, glosy {tot('st_glosy')}, kaluze {tot('st_kaluze')}"
            + (f"; linii '3. potkniecie' {len(notes)}" if notes else ""), "INFO (oczekiwane 0)", None)
    nbw_part2(rep, rows, tot)
    nbw_part3(rep, rows, tot)   # czesc 3 (16.10): kaluze krwi
    # NBW-8 linia NM w bitwach
    bat = [r for r in nm if r["battle"]]
    if bat:
        push = (sum(r["pushed"][0] for r in bat), sum(r["pushed"][1] for r in bat))
        calls = (sum(r["calls"][0] for r in bat), sum(r["calls"][1] for r in bat))
        rep.add("NBW-8: linia NM w bitwach - wywolan na czlowieka", f"rozbici {calls[0]} wywolan / {push[0]} ludzi, ucieczka {calls[1]} / {push[1]}",
                "INFO (przy Broken Men Never Rally wywolan = roznych ludzi; dotad 342 na 23)", None)
    else:
        rep.add("NBW-8: linia NM w bitwach", "brak linii bitwy", "INFO", None)
    rep.show()
    return 0


# ------------------------------------------------------------ nturniej (16.10, Jeff "miasto nie moglo zaplacic mi 1300 za stake w turnieju"; Armoury/src/TourneyPay.cs)
NTU_HEAD = "Turniej-platnik (TP): "
NTU_DAY = re.compile(r"Turniej-platnik \(TP\): dzien (?P<day>-?\d+) \| klucze: Tourney Payer Chain (?P<k1>tak|WYLACZONE), Tourney Debts (?P<k2>tak|WYLACZONE), "
                     r"Tourney Seagard Catch Up (?P<k3>tak|WYLACZONE) "
                     r"\| wyplaty lancuchem (?P<chn>\d+) \(niepelne (?P<chshort>\d+)\): kasa osady (?P<ctown>\d+), gospodarz (?P<chost>\d+), panujacy (?P<cruler>\d+), "
                     r"w dlug (?P<cdebt>\d+), przepadlo (?P<clost>\d+) \(w tym osada gracza (?P<cown>\d+)\) "
                     r"\| splaty dlugow (?P<rn>\d+): (?P<rsum>\d+) \(kasa osady (?P<rtown>\d+), gospodarz (?P<rhost>\d+), panujacy (?P<rruler>\d+)\), "
                     r"czeka na pokoj (?P<war>\d+), osada nieznana (?P<unk>\d+), drobna splata czeka \(ponizej \d+\) (?P<small>\d+) "
                     r"\| nowe dlugi (?P<nn>\d+): (?P<nsum>\d+) \| dlugi osad wobec gracza (?P<dn>\d+) na sume (?P<dsum>\d+)(?P<dlist>.*?) "
                     r"\| wyrownanie Seagard 16\.10: (?P<catch>.*?) \| rody z rezerwa wedlug zapisu budzetu \(pierwsza doba po wczytaniu\) (?P<old>\d+) "
                     r"\| kontrola \(prog 0\): rod ponizej rezerwy po wyplacie (?P<below>\d+), roznica rachunku dlugow (?P<diff>-?\d+) .*?"
                     r"\| potkniecia dzis (?P<stum>\d+) \(od wczytania (?P<stumall>\d+)\)\.$")
# recenzja TP-4: bledy paczki takze pod innymi przedrostkami (wczytanie dlugow z zapisu, potkniecia PlayerFees8 w lancuchu TP, budzet z zapisu)
NTU_ERR = ("ERROR in TourneyPay.", "ERROR in SyncData.arm_tp_debts", "ERROR in PlayerFees8.TourneyPay", "ERROR in PlayerFees8.TownPays(TP)",
           "ERROR in PlayerFees8.SettlePrize(TP)", "ERROR in ClanBudget.PendingChestOf")
# f8-sakiewka (18.10, decyzja Jeffa "4 tak"; Armoury/src/TourneyFolkPurse.cs, TownFolk.Tourney.cs, klucz TourneyFolkPurse): sakiewka mieszczan miasta-gospodarza
NTS_HEAD = "Sakiewka turniejowa (f8): "
NTS_DAY = re.compile(r"Sakiewka turniejowa \(f8\): dzien (?P<day>-?\d+) \| klucz Tourney Folk Purse tak, dni oferty (?P<days>\d+\.\d+), minimum (?P<min>\d+) "
                     r"\| KS (?P<ks>zastosowany|NIEZASTOSOWANY), kiesa ludu (?P<folk>czynna|NIECZYNNA) "
                     r"\| turnieje (?P<n>\d+): sakiewki (?P<k>\d+) na sume (?P<sum>\d+) \(lud W (?P<w>\d+), R (?P<r>\d+), P (?P<p>\d+)\) -> glowy rodow (?P<heads>\d+) \((?P<headsn>\d+)\), "
                     r"gracz (?P<pl>\d+) \((?P<pln>\d+)\); oferta dnia ludu tych miast (?P<off>\d+); najwieksza (?P<max>\d+) \((?P<maxtown>.*?)\) "
                     r"\| bez sakiewki (?P<none>\d+): bez miasta (?P<notown>\d+), KS niezastosowany (?P<noks>\d+), kiesa nieczynna (?P<nolive>\d+), zwyciezca nie bohater (?P<nohero>\d+), "
                     r"bez odbiorcy (?P<norec>\d+), miasto bez kiesy (?P<nofolk>\d+), bez swiezej doby ludu (?P<stale>\d+), bez nadwyzki (?P<nooffer>\d+), nadwyzka zajeta (?P<noroom>\d+), "
                     r"ponizej minimum (?P<belowmin>\d+) "
                     r"\| tozsamosc \(prog 0\): zdjete z kies (?P<taken>\d+) - przelane (?P<given>\d+) - zwrocone po wyjatku (?P<undo>\d+) \((?P<undon>\d+)\) = (?P<diff>-?\d+) "
                     r"\| kontrola \(prog 0\): klasy ponizej zapasu po sakiewce (?P<below>\d+) \| koszt (?P<ms>\d+\.\d+) ms/dobe "
                     r"\| potkniecia dzis (?P<stum>\d+) \(od wczytania (?P<stumall>\d+)\)\.$")
NTS_EV = re.compile(r"Sakiewka turniejowa \(f8\): (?P<town>.+?): lud W (?P<w>\d+) / R (?P<r>\d+) / P (?P<p>\d+) = (?P<x>\d+) -> (?P<rec>.*?) \((?P<who>gracz|glowa rodu)\) "
                    r"\(zwyciezca (?P<win>.*?); oferta dnia ludu (?P<off>\d+) x dni (?P<days>\d+\.\d+), minimum (?P<min>\d+)\); przelane (?P<got>-?\d+), roznica (?P<diff>-?\d+)(?P<warn>.*)\.$")
NTS_ERR = ("ERROR in TourneyFolkPurse.", "ERROR in TownFolk.TourneyPurse")
NTS_PRIZE = re.compile(r"nagrody turniejow: gra chciala (\d+), zaplacili (\d+), uciete \d+ \((\d+) wyplat")
NTS_MS_MAX = 1.0   # koszt sluchacza (kilka turniejow na dobe, jedna osada kazdy) - najwyzej 1 ms na dobe
# recenzja f8: wpis linii "Obieg: dzien N" (rody dostaly [P]) - migawka TourneyFolkPurse.Daily tej samej doby (TourneyFolkPurse.ObiegNote)
NTS_OBG = re.compile(r", sakiewka turniejowa ludu \(f8\) kiesy ludu -> glowy rodow i gracz (?P<all>\d+) \(glowy rodow (?P<heads>\d+) w (?P<headsn>\d+) sakiewkach, "
                     r"gracz (?P<pl>\d+) w (?P<pln>\d+)\)")
NTS_OBG_DAY = re.compile(r"Obieg: dzien (-?\d+) ")


def nturniej_purse_rows(rep, tdays, tbad, tev, tevbad, n_err, prize, tobg=0):
    """f8-sakiewka: wiersze TS-0..TS-11 grupy nturniej (opis w naglowku pliku, --grupa nturniej). tdays / tev - slowniki rozpoznanych linii doby i sakiewek,
    tbad / tevbad - nierozpoznane, n_err - ERROR paczki, prize - (nalezne, zaplacone, wyplat) nagrod turniejow AI z linii Szczelnosc (164a) - INFO,
    tobg - liczba linii "Obieg" z wpisem "sakiewka turniejowa ludu (f8)"; wpis przypiety do linii doby sakiewki tej samej doby jako g["_obg"] (TS-11, recenzja f8;
    brak - INFO). Bez wyjatku."""
    if not tdays and not tbad and not tev and not tevbad:
        rep.add("TS-0: linie 'Sakiewka turniejowa (f8)'", "brak w logu", "INFO (log sprzed paczki f8-sakiewka albo klucz Tourney Folk Purse WYLACZONY)", None)
        if n_err:
            rep.add("TS-8: ERROR paczki (TourneyFolkPurse.*, TownFolk.TourneyPurse*)", f"ERROR {n_err}", "0", False)
        return
    rep.add("TS-0: linie paczki", f"doby {len(tdays)}, sakiewki {len(tev)}", "linia doby przy kluczu tak (INFO)", None)
    rep.add("TS-1: linie doby i sakiewek rozpoznane", f"doby: nierozpoznane {len(tbad)}, sakiewki: nierozpoznane {len(tevbad)}"
            + (f" (np. {(tbad or tevbad)[0][:160]})" if tbad or tevbad else ""), "0 / 0", not tbad and not tevbad)

    def i(g, k):
        return int(g[k])
    if tdays:
        dd = [g for g in tdays if i(g, "diff") != 0 or i(g, "taken") != i(g, "given") + i(g, "undo")]
        ed = [g for g in tev if i(g, "diff") != 0 or i(g, "x") != i(g, "got")]
        rep.add("TS-2: tozsamosc zamknietego pieniadza: zdjete z kies ludu = przelane odbiorcom + zwrocone (kazda doba i kazda sakiewka)",
                f"doby z roznica {len(dd)} z {len(tdays)}, sakiewki z roznica {len(ed)} z {len(tev)}"
                + (f" (np. dzien {dd[0]['day']}: {dd[0]['diff']})" if dd else (f" (np. {ed[0]['town']}: {ed[0]['diff']})" if ed else "")), "0 / 0", not dd and not ed)
        bd = [g for g in tdays if i(g, "w") + i(g, "r") + i(g, "p") != i(g, "sum") or i(g, "heads") + i(g, "pl") != i(g, "given") or i(g, "sum") != i(g, "taken")
              or i(g, "headsn") + i(g, "pln") != i(g, "k")]
        be = [g for g in tev if i(g, "w") + i(g, "r") + i(g, "p") != i(g, "x")]
        rep.add("TS-3: rachunek sakiewek (W + R + P = suma = zdjete; glowy + gracz = przelane; sakiewki = odbiorcy)", f"doby niespojne {len(bd)}, sakiewki niespojne {len(be)}",
                "0 / 0", not bd and not be)
        cn = [g for g in tdays if i(g, "n") != i(g, "k") + i(g, "none") + i(g, "undon")
              or i(g, "none") != sum(i(g, k) for k in ("notown", "noks", "nolive", "nohero", "norec", "nofolk", "stale", "nooffer", "noroom", "belowmin"))]
        rep.add("TS-4: turnieje = sakiewki + bez sakiewki (suma powodow) + zwrocone po wyjatku", f"doby niespojne {len(cn)} z {len(tdays)}" + (f" (np. dzien {cn[0]['day']})" if cn else ""), "0", not cn)
        below = sum(i(g, "below") for g in tdays)
        warn = sum(1 for g in tev if "UWAGA" in g["warn"])
        rep.add("TS-5: kiesa klasy ponizej zapasu dni po sakiewce (suma dob; sakiewki z UWAGA)", f"{below}; {warn}", "0 / 0", below == 0 and warn == 0)
        over = [g for g in tev if i(g, "x") > int(float(g["days"]) * i(g, "off")) + 3]
        rep.add("TS-6: sakiewka najwyzej oferta dnia ludu x dni (rozmiar wedlug zamoznosci miasta)", f"ponad oferte {len(over)} z {len(tev)}"
                + (f" (np. {over[0]['town']}: {over[0]['x']} > {over[0]['off']} x {over[0]['days']})" if over else ""), "0", not over)
        ksd = [g for g in tdays if g["ks"] == "zastosowany" and g["folk"] == "czynna"]
        hero_ks = sum(i(g, "n") - i(g, "notown") - i(g, "nohero") - i(g, "norec") for g in ksd)
        paid_ks = sum(i(g, "k") for g in ksd)
        poor = sum(i(g, "nooffer") + i(g, "noroom") + i(g, "belowmin") for g in ksd)
        if len(ksd) >= 7 and hero_ks >= 5:
            rep.add("TS-7: pod KS z czynna kiesa ludu sakiewki naprawde ida (doby KS >= 7, turnieje z bohaterem >= 5)",
                    f"dob KS {len(ksd)}, turnieje z odbiorca {hero_ks}, sakiewki {paid_ks} ({100.0 * paid_ks / max(1, hero_ks):.0f}%), bez nadwyzki / zajeta / ponizej minimum {poor}, "
                    f"bez swiezej doby ludu {sum(i(g, 'stale') for g in ksd)}, miasto bez kiesy {sum(i(g, 'nofolk') for g in ksd)}", "sakiewki > 0", paid_ks > 0)
        else:
            rep.add("TS-7: sakiewki pod KS", f"dob KS z czynna kiesa {len(ksd)}, turnieje z odbiorca {hero_ks}, sakiewki {paid_ks}; KS niezastosowany w "
                    f"{sum(i(g, 'noks') for g in tdays)} turniejach", "INFO (za malo dob KS albo turniejow - KS nie zastosowany w tym biegu?)", None)
        stum = sum(i(g, "stum") for g in tdays)
        rep.add("TS-8: potkniecia (suma dob) i ERROR paczki (TourneyFolkPurse.*, TownFolk.TourneyPurse*)", f"potkniecia {stum}, ERROR {n_err}", "0 / 0", stum == 0 and n_err == 0)
        ms = sorted(float(g["ms"]) for g in tdays)
        rep.add("TS-9: koszt sluchacza turniejow (ms/dobe)", f"najwiecej {ms[-1]:.3f}, mediana {ms[len(ms) // 2]:.3f}", f"najwiecej <= {NTS_MS_MAX}", ms[-1] <= NTS_MS_MAX)

        def tot(k):
            return sum(i(g, k) for g in tdays)
        mx = max(tdays, key=lambda g: i(g, "max"))
        pr = f"; nagrody turniejow AI (164a): gra chciala {prize[0]}, zaplacili {prize[1]} ({prize[2]} wyplat)" if prize[2] else ""
        rep.add("TS-10: sakiewki (suma dob)", f"turnieje {tot('n')}, sakiewki {tot('k')} na sume {tot('sum')} (lud W {tot('w')}, R {tot('r')}, P {tot('p')}) -> glowy rodow {tot('heads')} "
                f"({tot('headsn')}), gracz {tot('pl')} ({tot('pln')}); najwieksza {mx['max']} ({mx['maxtown']}, dzien {mx['day']}); bez sakiewki: KS niezastosowany {tot('noks')}, "
                f"kiesa nieczynna {tot('nolive')}, nie bohater {tot('nohero')}, bez odbiorcy {tot('norec')}, bez kiesy {tot('nofolk')}, bez swiezej doby {tot('stale')}, "
                f"bez nadwyzki {tot('nooffer')}, zajeta {tot('noroom')}, ponizej minimum {tot('belowmin')}{pr}", "INFO", None)
        # TS-11 (recenzja f8): wpis linii "Obieg" (rody dostaly) = glowy rodow + gracz z linii doby sakiewki tej samej doby
        pairs = [(g, g["_obg"]) for g in tdays if "_obg" in g]
        if pairs:
            bad = [(g, o) for g, o in pairs if int(o["heads"]) != i(g, "heads") or int(o["pl"]) != i(g, "pl") or int(o["headsn"]) != i(g, "headsn")
                   or int(o["pln"]) != i(g, "pln") or int(o["all"]) != int(o["heads"]) + int(o["pl"])]
            rep.add("TS-11: wpis linii Obieg (rody dostaly) 'sakiewka turniejowa ludu (f8)' = glowy rodow + gracz z linii doby sakiewki",
                    f"dob porownanych {len(pairs)} z {len(tdays)}, niezgodnych {len(bad)}"
                    + (f" (np. dzien {bad[0][0]['day']}: Obieg glowy {bad[0][1]['heads']} / gracz {bad[0][1]['pl']}, linia doby {bad[0][0]['heads']} / {bad[0][0]['pl']})" if bad else ""),
                    "0", not bad)
        else:
            rep.add("TS-11: wpis linii Obieg 'sakiewka turniejowa ludu (f8)'", f"brak wpisu w dobach linii sakiewki (linii Obieg z wpisem {tobg})",
                    "INFO (Obieg bez wpisu - DLL sprzed recenzji f8 albo ksiega pieniadza wylaczona)", None)
    else:
        rep.add("TS-2..10: linie doby sakiewki", f"brak linii doby (sakiewek {len(tev)})", "INFO (sesja krotsza niz doba)", None)
        if n_err:
            rep.add("TS-8: ERROR paczki (TourneyFolkPurse.*, TownFolk.TourneyPurse*)", f"ERROR {n_err}", "0", False)


def nturniej_main(logp):
    """nturniej (16.10; Armoury/src/TourneyPay.cs, klucze TourneyPayerChain / TourneyDebts / TourneySeagardCatchUp): nagroda turnieju, wygrana zakladu, areny
    i planszy lancuchem platnikow (kasa osady -> gospodarz -> panujacy), reszta jako dlug osady wobec gracza splacany co dobe; wyrownanie Seagard 16.10.
    Wejscie: log Armoury (strumieniowo). TP-0 linia startu sesji (klucze), TP-1 linia doby rozpoznana (wszystkie linie "dzien"), TP-2 rachunek dlugow
    w kazdej dobie: poczatek + nowe - splaty = koniec (roznica 0), TP-3 rod po wyplacie ponizej rezerwy 0, TP-4 potkniecia i ERROR paczki 0 (NTU_ERR),
    TP-5 wyplaty lancuchem i splaty (INFO), TP-6 dlugi na koniec logu i wyrownanie Seagard (INFO). Log bez paczki: INFO, bez wyjatku."""
    rep = Report()
    if not logp or not os.path.isfile(logp):
        rep.add("TP-0: log Armoury", f"brak pliku {logp}", "podaj <Armoury-*.log>", None)
        rep.show()
        return 0
    sess, days, bad, pays, reps = [], [], [], 0, 0
    n_err = 0
    tdays, tbad, tev, tevbad, ts_err, prize = [], [], [], [], 0, [0, 0, 0]   # f8-sakiewka (wiersze TS)
    tobg = 0   # recenzja f8 (TS-11): linie "Obieg" z wpisem "sakiewka turniejowa ludu (f8)" (wpis przypiety do linii doby sakiewki tej samej doby)
    with open(logp, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\n"))
            s = m.group(2) if m else ln.rstrip("\n")
            if s.startswith(NTS_HEAD):
                if s.startswith(NTS_HEAD + "dzien "):
                    mm = NTS_DAY.match(s)
                    (tdays if mm else tbad).append(mm.groupdict() if mm else s)
                else:
                    mm = NTS_EV.match(s)
                    (tev if mm else tevbad).append(mm.groupdict() if mm else s)
                continue
            if s.startswith(NTS_ERR):
                ts_err += 1
                continue
            if s.startswith("Obieg: dzien ") and "sakiewka turniejowa ludu (f8)" in s:
                mo, md = NTS_OBG.search(s), NTS_OBG_DAY.match(s)
                if mo and md:
                    tobg += 1
                    od_ = int(md.group(1))
                    # linia doby sakiewki biegnie w tym samym ticku przed "Obieg" (TourneyFolkPurse.Daily przed MoneyLedger.Daily) - przypnij do ostatniej
                    # linii tej doby bez wpisu (wczytanie zapisu i powtorzona doba - kazda para osobno)
                    for g_ in reversed(tdays):
                        if int(g_["day"]) == od_:
                            if "_obg" not in g_:
                                g_["_obg"] = mo.groupdict()
                            break
                continue
            if s.startswith("Szczelnosc (164a): dzien") and "nagrody turniejow: gra chciala" in s:
                mm = NTS_PRIZE.search(s)
                if mm:
                    prize[0] += int(mm.group(1)); prize[1] += int(mm.group(2)); prize[2] += int(mm.group(3))
            if s.startswith(NTU_HEAD):
                if s.startswith(NTU_HEAD + "start sesji"):
                    sess.append(s)
                elif s.startswith(NTU_HEAD + "dzien "):
                    mm = NTU_DAY.match(s)
                    if mm:
                        days.append(mm.groupdict())
                    else:
                        bad.append(s)
                elif s.startswith(NTU_HEAD + "wyplata"):
                    pays += 1
                elif s.startswith(NTU_HEAD + "splata"):
                    reps += 1
            elif s.startswith(NTU_ERR):
                n_err += 1
    print(f"plik: {logp} | linii startu sesji {len(sess)}, doby {len(days)}, nierozpoznanych linii doby {len(bad)}, wyplat lancuchem {pays}, splat {reps}"
          f" | sakiewka mieszczan (f8): doby {len(tdays)} (nierozpoznane {len(tbad)}), sakiewki {len(tev)} (nierozpoznane {len(tevbad)})")
    if not sess and not days and not bad:
        rep.add("TP-0: linie 'Turniej-platnik (TP)'", "brak w logu", "INFO (log sprzed paczki TP)", None)
        nturniej_purse_rows(rep, tdays, tbad, tev, tevbad, ts_err, prize, tobg)
        rep.show()
        return 0
    if sess:
        s0 = sess[-1]
        off = [k for k in ("Tourney Payer Chain", "Tourney Debts", "Tourney Seagard Catch Up") if k + " WYLACZONE" in s0]
        rep.add("TP-0: linia startu sesji - klucze", s0[len(NTU_HEAD):][:240], "trzy klucze tak (WYLACZONE - INFO)", None if off else True)
    else:
        rep.add("TP-0: linia startu sesji", "brak (sa inne linie TP)", "linia przy kazdym starcie sesji", False)
    rep.add("TP-1: linie doby rozpoznane", f"rozpoznane {len(days)}, nierozpoznane {len(bad)}" + (f" (np. {bad[0][:160]})" if bad else ""), "nierozpoznane 0", not bad)
    if days:
        diff = [g for g in days if int(g["diff"]) != 0]
        rep.add("TP-2: rachunek dlugow w dobie (poczatek + nowe - splaty = koniec)", f"dob {len(days)}, z roznica {len(diff)}" + (f" (np. dzien {diff[0]['day']}: {diff[0]['diff']})" if diff else ""),
                "0", not diff)
        below = sum(int(g["below"]) for g in days)
        rep.add("TP-3: rod po wyplacie ponizej rezerwy R (suma dob)", str(below), "0", below == 0)
        stum = sum(int(g["stum"]) for g in days)
        rep.add("TP-4: potkniecia (suma dob) i ERROR paczki (TourneyPay.*, SyncData.arm_tp_debts, PlayerFees8 TP, PendingChestOf)", f"potkniecia {stum}, ERROR {n_err}", "0 / 0",
                stum == 0 and n_err == 0)

        def tot(k):
            return sum(int(g[k]) for g in days)
        rep.add("TP-5: wyplaty lancuchem i splaty dlugow (suma dob)",
                f"wyplat {tot('chn')} (niepelne {tot('chshort')}): kasa osady {tot('ctown')}, gospodarz {tot('chost')}, panujacy {tot('cruler')}, w dlug {tot('cdebt')}, "
                f"przepadlo {tot('clost')} (osada gracza {tot('cown')}); splat {tot('rn')}: {tot('rsum')} (kasa {tot('rtown')}, gospodarz {tot('rhost')}, panujacy {tot('rruler')}), "
                f"czeka na pokoj {tot('war')}, osada nieznana {tot('unk')}, drobna splata czeka {tot('small')}; nowe dlugi {tot('nn')}: {tot('nsum')}; "
                f"rody z rezerwa wedlug zapisu budzetu {tot('old')}",
                "INFO", None)
        last = days[-1]
        rep.add("TP-6: dlugi osad wobec gracza na koniec logu i wyrownanie Seagard", f"dzien {last['day']}: {last['dn']} na sume {last['dsum']}{last['dlist'][:200]}; wyrownanie: {last['catch']}",
                "INFO", None)
    else:
        rep.add("TP-2: linie doby", "brak linii doby", "INFO (sesja krotsza niz doba)", None)
    nturniej_purse_rows(rep, tdays, tbad, tev, tevbad, ts_err, prize, tobg)   # f8-sakiewka: wiersze TS-0..TS-11
    rep.show()
    return 0


# ------------------------------------------------------------ ndrogi (noc 17/18.10, Jeff "szybsze poruszanie po drogach"; galaz w-toku/sw-drogi, Armoury/src/MapRoads.cs)
