NZC0_KGPP = (0.885, 0.02)
NZC0_FIELD = (76.6, 2.0)


def nzc0_f(x):
    try:
        return float(x)
    except (TypeError, ValueError):
        return None


def nzc0_csv_path(logp):
    d, f = os.path.split(logp)
    stem = os.path.splitext(f)[0].replace("Armoury-", "")
    for p in (os.path.join(d, stem, "stany-dostatek.csv"), os.path.join(d, "Logs", stem, "stany-dostatek.csv")):
        if os.path.isfile(p):
            return p
    return None


def nzc0_goods(path):
    """Produkcja ksiegi towarow wedlug doby (linia 'Towary (bilans)') - do porownania z biegiem bazowym."""
    out = {}
    if not path or not os.path.isfile(path):
        return out
    pat = re.compile(r"Towary \(bilans\): dzien (-?\d+) - .*?; produkcja (\d+) szt\.")
    with open(path, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            if "Towary (bilans): dzien" not in ln:
                continue
            m = pat.search(ln)
            if m:
                out[int(m.group(1))] = int(m.group(2))
    return out


def nzc0_main(logp, bdp=None, until=120):
    """nzc0 (16.10; Armoury/src/DailyLife*.cs, klucze DailyLifeMeasure / DailyLifeMarketScale): ZC0 - stany, koszyki w kg, Spizarnia, Dostatek NA SUCHO
    (gra bez zmian). Wejscie: log Armoury (strumieniowo), opcjonalnie --baza-doby <log Armoury biegu bazowego> (ksiega towarow +-2%).
    Progi projektu rozdz. 14 (ZC0): NZC0-0 linia startu sesji (klucz tak, sigma), NZC0-1 linie 'Zycie (ZC0)' i 'Spizarnia (ZC)' kazdej doby (bez luk, nierozpoznane 0),
    NZC0-2 ksiega bez konta niewolnych (wsie + miasta) = linia 'Ludnosc' tej samej doby (PopulationLaw, ten sam takt) +-0.5% (kazda doba; bez linii - INFO),
    NZC0-2b suma stanow ksiegi = ksiega (INFO - z budowy, udzialy sumuja sie do 1), NZC0-3 udzialy swiata +-1 pkt od rozdz. 5.3 (ostatnia doba),
    NZC0-4 kontrola glodu: Spizarnia z pola + z targu = potrzeba +-5% (kazda doba; rowne z arytmetyki poza glodem ze spichlerzy), NZC0-5 D policzone dla
    wszystkich osad i kazde miasto z wlasnym D (miasto bez liczb kiesy ludu = bez wlasnego D; kazda doba), NZC0-6 czas bloku: mediana <= 5 ms na dobe,
    NZC0-7 potkniecia i ERROR paczki 0, NZC0-8 sigma stala w calym logu, NZC0-9 stany-dostatek.csv: kazda doba, ktora linia zglosila jako zapisana
    ('stany-dostatek.csv N wierszy'), jest w pliku z N roznymi osadami (pary doba, osada_id - wczytanie w tym samym procesie nie dubluje), D w kazdym
    wierszu, 0 dob 'NIE ZAPISANY', NZC0-10 ksiega towarow +-2% bazy (z --baza-doby; bez - INFO), NZC0-11..13 INFO (Dostatek i dochod na glowe stanow -
    wielkie rody 1:1 brutto, wielkie rody i New Ibbish, Spizarnia), NZC0-14..16 potrzeba wobec audytu rozdz. 7.1 (ostatnia doba; DECYZJA, gdy poza
    progiem): 45 904 t/d +-3%, 0.885 kg/os +-0.02, z pola i domu 76.6% +-2 pkt, NZC0-17 zapis wczytany ponownie (ta sama doba policzona dwa razy w logu):
    Dostatek swiata +-3% przy sredniej >= 14 dob (bez powtorzonej doby - INFO).
    Log bez paczki: INFO, bez wyjatku."""
    rep = Report()
    if not logp or not os.path.isfile(logp):
        rep.add("NZC0-0: log Armoury", f"brak pliku {logp}", "podaj <Armoury-*.log>", None)
        rep.show()
        return 0
    sess, days, bad, pdays, pbad, kings = [], {}, [], {}, [], 0
    lud, dups = {}, []
    n_err = 0
    with open(logp, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\n"))
            s = m.group(2) if m else ln.rstrip("\n")
            if s.startswith(NZC0_HEAD):
                if s.startswith(NZC0_HEAD + "start sesji"):
                    sess.append(s)
                elif s.startswith(NZC0_HEAD + "dzien "):
                    mm = NZC0_DAY.match(s)
                    if mm:
                        d = int(mm.group("day"))
                        if d in days:
                            dups.append((d, days[d], mm.groupdict()))
                        days[d] = mm.groupdict()
                    elif "| czeka na kalibracje" in s or "| WYLACZONY" in s:
                        pass
                    else:
                        bad.append(s)
            elif s.startswith(NZC0_PHEAD + "dzien "):
                mm = NZC0_PDAY.match(s)
                if mm:
                    pdays[int(mm.group("day"))] = mm.groupdict()
                else:
                    pbad.append(s)
            elif s.startswith(NZC0_KING):
                kings += 1
            elif s.startswith("Ludnosc: dzien "):
                mm = NZC0_LUD.match(s)
                if mm:
                    lud[int(mm.group("day"))] = float(mm.group("mln"))
            elif s.startswith(NZC0_ERR):
                n_err += 1
    print(f"plik: {logp} | linii startu sesji {len(sess)}, doby Zycie {len(days)} (nierozpoznanych {len(bad)}), Spizarnia {len(pdays)} (nierozpoznanych {len(pbad)}), krolestw {kings}"
          f", doby Ludnosc {len(lud)}, doby powtorzone {len(dups)}")
    if not sess and not days and not bad and not pdays and not pbad:
        rep.add("NZC0-0: linie 'Zycie (ZC0)'", "brak w logu", "INFO (log sprzed paczki ZC0)", None)
        rep.show()
        return 0
    # NZC0-0
    if sess:
        mm = NZC0_START.match(sess[-1])
        ok = bool(mm) and mm.group("k1") == "tak"
        rep.add("NZC0-0: linia startu sesji (klucz, sigma)", sess[-1][len(NZC0_HEAD):][:300], "Daily Life Measure tak, sigma ustalona", True if ok else (None if mm and mm.group("k1") == "WYLACZONE" else False))
    else:
        rep.add("NZC0-0: linia startu sesji", "brak", "linia przy kazdym starcie sesji", False)
    # NZC0-1
    dd = sorted(days)
    both = [d for d in dd if d in pdays]
    if dd:
        span = dd[-1] - dd[0] + 1
        gaps = [d for d in range(dd[0], dd[-1] + 1) if d not in days or d not in pdays]
        rep.add("NZC0-1: linie 'Zycie (ZC0)' i 'Spizarnia (ZC)' kazdej doby", f"doby z obiema liniami {len(both)}/{span} (dzien {dd[0]}-{dd[-1]}), luki {len(gaps)}"
                + (f" (np. {gaps[:5]})" if gaps else "") + f", nierozpoznane {len(bad)} + {len(pbad)}" + (f" (np. {(bad or pbad)[0][:160]})" if bad or pbad else "")
                + (f"; dob w logu mniej niz {until} (bieg krotszy)" if span < until else ""),
                f"{span}/{span}, luki 0, nierozpoznane 0 (bieg {until} dob: {until}/{until})", not gaps and not bad and not pbad)
    else:
        rep.add("NZC0-1: linie doby", f"brak rozpoznanych linii doby (nierozpoznane {len(bad)})" + (f": {bad[0][:200]}" if bad else ""), "linia kazdej doby", False)
        rep.show()
        return 0
    last = days[dd[-1]]
    # NZC0-2: ksiega bez konta niewolnych wobec linii "Ludnosc" tego samego taktu (doba Ludnosc = doba Zycie + 1)
    pairs = [(d, (int(days[d]["vil"]) + int(days[d]["town"])) / 1e6, lud.get(d + 1)) for d in dd]
    have = [(d, b, l) for d, b, l in pairs if l is not None and l > 0]
    if have:
        badl = [(d, b, l) for d, b, l in have if abs(b - l) > 0.005 * l + 0.05]   # +-0.5% i zaokraglenie linii Ludnosc do 0.1 mln
        worst = max(have, key=lambda x: abs(x[1] - x[2]) / x[2])
        rep.add("NZC0-2: ksiega (wsie + miasta, bez konta niewolnych) = linia 'Ludnosc' tego samego taktu", f"doby porownane {len(have)} z {len(dd)}, poza progiem {len(badl)}"
                + (f" (np. dzien {badl[0][0]}: ksiega {badl[0][1]:.2f} mln, Ludnosc {badl[0][2]:.1f} mln)" if badl else "")
                + f"; najwieksza roznica dzien {worst[0]}: {worst[1]:.2f} / {worst[2]:.1f} mln ({100 * (worst[1] / worst[2] - 1):+.2f}%)",
                "+-0.5% (+ 0.05 mln zaokraglenia) kazdej doby", not badl)
    else:
        rep.add("NZC0-2: ksiega wobec linii 'Ludnosc'", f"brak linii 'Ludnosc: dzien N+1' do {len(dd)} dob Zycie (renty krain wylaczone?)", "INFO (+-0.5% z linia Ludnosc)", None)
    diffs = [(d, nzc0_f(days[d]["diff"])) for d in dd]
    badd = [(d, x) for d, x in diffs if x is None or abs(x) > 0.5]
    rep.add("NZC0-2b: suma stanow ksiegi = ksiega (arytmetyka - udzialy sumuja sie do 1)", f"doby z roznica > 0.5 czlowieka {len(badd)} z {len(dd)}"
            + (f" (np. dzien {badd[0][0]}: {badd[0][1]})" if badd else f"; ostatnia doba ksiega {last['book']}, stany {last['est']}"), "INFO (z budowy +-0)", None)
    # NZC0-3
    sh = [nzc0_f(last["s%d" % i]) for i in range(6)]
    devs = [(NZC0_DOC[i][0], sh[i], NZC0_DOC[i][1]) for i in range(6)]
    off = [x for x in devs if x[1] is None or abs(x[1] - x[2]) > 1.0]
    rep.add("NZC0-3: udzialy stanow swiata wobec projektu rozdz. 5.3 (ostatnia doba)", ", ".join(f"{n} {v if v is not None else '-'} (projekt {p})" for n, v, p in devs)
            + f", wielkie rody {last['s6']}%", "+-1 pkt kazdego stanu", not off)
    # NZC0-4
    pd = sorted(pdays)
    if pd:
        pv = [(d, nzc0_f(pdays[d]["dpct"])) for d in pd]
        badp = [(d, x) for d, x in pv if x is None or abs(x) > 5.0]
        worst = max((abs(x) for d, x in pv if x is not None), default=None)
        rep.add("NZC0-4: kontrola glodu - Spizarnia z pola i domu + z targu = potrzeba", f"doby poza +-5%: {len(badp)} z {len(pd)}" + (f" (np. dzien {badp[0][0]}: {badp[0][1]}%)" if badp else "")
                + (f"; najwieksza roznica {worst:.2f}%" if worst is not None else "") + " (rowne z arytmetyki - odchylenie to glod ze spichlerzy)", "+-5% kazdej doby", not badp)
    else:
        rep.add("NZC0-4: Spizarnia", "brak linii 'Spizarnia (ZC)'", "linia kazdej doby", False)
    # NZC0-5
    badD = [d for d in dd if int(days[d]["dn"]) != int(days[d]["dall"]) or int(days[d]["dall"]) == 0 or int(days[d]["dnoearn"]) > 0]
    noearn = [d for d in dd if int(days[d]["dnoearn"]) > 0]
    rep.add("NZC0-5: D policzone dla wszystkich osad, miasta z wlasnym D", f"ostatnia doba {last['dn']}/{last['dall']} (wlasne {last['down']}, regionu {last['dreg']}, krolestwa {last['dking']}, "
            f"swiata {last['dworld']}, bez D {last['dnone']}; miasta bez liczb kiesy - bez wlasnego D {last['dnoearn']}); doby z brakiem {len(badD)} z {len(dd)}"
            + (f" (w tym z miastami bez wlasnego D {len(noearn)}, np. dzien {noearn[0]}: {days[noearn[0]]['dnoearn']})" if noearn else ""),
            "N/N kazdej doby (projekt: 798/798), miasta bez wlasnego D 0", not badD)
    # NZC0-6
    ms = [nzc0_f(days[d]["ms"]) for d in dd]
    ms = [x for x in ms if x is not None]
    med = st.median(ms) if ms else None
    rep.add("NZC0-6: czas bloku ZC na dobe (bez zapisu linii)", (f"mediana {med:.3f} ms, max {max(ms):.3f} ms z {len(ms)} dob" if ms else "brak"), "mediana <= 5 ms", (med is not None and med <= 5.0) if ms else None)
    # NZC0-7
    stum = sum(int(days[d]["st"]) for d in dd)
    rep.add("NZC0-7: potkniecia (suma dob) i ERROR paczki (DailyLife.*, SyncData.arm_dailylife)", f"potkniecia {stum} (od wczytania na koniec {last['sta']}), ERROR {n_err}",
            "0 / 0", stum == 0 and n_err == 0)
    # NZC0-8
    sigs = sorted(set(days[d]["sig"] for d in dd))
    rep.add("NZC0-8: skala targu sigma stala w calym logu", f"sigma {', '.join(sigs)} ({last['sigsrc']})", "jedna wartosc (projekt: 37)", len(sigs) == 1)
    # NZC0-9: doby zgloszone w linii jako zapisane - w pliku z tyloma roznymi osadami
    written, notw = {}, []
    for d in dd:
        c = days[d].get("csv") or ""
        mw = NZC0_CSVW.search(c)
        if mw:
            written[d] = int(mw.group(1))
        elif "NIE ZAPISANY" in c:
            notw.append(d)
    cp = nzc0_csv_path(logp)
    if cp:
        ids, nod, rd_err = {}, set(), None
        try:
            with open(cp, encoding="utf-8", errors="replace", newline="") as fh:
                rd = csv.DictReader(fh, delimiter=";", quoting=csv.QUOTE_NONE)
                for r in rd:
                    try:
                        d = int(r.get("dzien", ""))
                    except (TypeError, ValueError):
                        continue
                    oid = r.get("osada_id") or ""
                    ids.setdefault(d, set()).add(oid)
                    if (r.get("D") or "-") in ("-", ""):
                        nod.add((d, oid))
        except Exception as e:
            rd_err = e
        if rd_err is not None:
            rep.add("NZC0-9: stany-dostatek.csv", f"blad odczytu {rd_err}", "czytelny", False)
        elif written or notw:
            mism = [(d, n, len(ids.get(d, ()))) for d, n in sorted(written.items()) if len(ids.get(d, ())) != n]
            rep.add("NZC0-9: stany-dostatek.csv - doby z linii w pliku, osada raz, D w kazdym wierszu",
                    f"doby zapisane wedlug linii {len(written)} (wierszy ostatniej {written[max(written)] if written else '-'}), w pliku {len(ids)} dob; "
                    f"doby z inna liczba osad niz w linii {len(mism)}" + (f" (np. dzien {mism[0][0]}: linia {mism[0][1]}, plik {mism[0][2]})" if mism else "")
                    + f", wiersze bez D {len(nod)}, doby 'NIE ZAPISANY' {len(notw)}" + (f" (np. {notw[:3]})" if notw else ""),
                    "kazda doba z linii w pliku z N osadami, bez D 0, NIE ZAPISANY 0", not mism and not nod and not notw)
        else:
            rep.add("NZC0-9: stany-dostatek.csv", f"plik jest ({len(ids)} dob), ale zadna linia doby nie zglosila zapisu (bieg krotszy niz 7 dob albo rozgrzewka)", "INFO", None)
    elif notw:
        rep.add("NZC0-9: stany-dostatek.csv", f"brak pliku, linie: 'NIE ZAPISANY' w {len(notw)} dobach (np. {notw[:3]})", "plik w katalogu sesji", False)
    else:
        rep.add("NZC0-9: stany-dostatek.csv", f"brak pliku obok logu (katalog sesji); linie zglosily {len(written)} dob", "INFO (log bez katalogu sesji)", None)
    # NZC0-10
    if bdp:
        g1, g0 = nzc0_goods(logp), nzc0_goods(bdp)
        common = sorted(set(g1) & set(g0))
        if common:
            a, b = st.mean(g1[d] for d in common), st.mean(g0[d] for d in common)
            r = a / b - 1 if b else None
            rep.add("NZC0-10: ksiega towarow (produkcja na dobe) wobec biegu bazowego", f"bieg {a:.0f} szt./d, baza {b:.0f} szt./d ({len(common)} wspolnych dob), roznica "
                    + (f"{100 * r:+.2f}%" if r is not None else "-"), "+-2%", (abs(r) <= 0.02) if r is not None else None)
        else:
            rep.add("NZC0-10: ksiega towarow wobec bazy", "brak wspolnych dob linii 'Towary (bilans)'", "+-2%", None)
    else:
        rep.add("NZC0-10: ksiega towarow wobec bazy", "bez --baza-doby", "INFO (+-2% z logiem bazy)", None)
    # INFO
    rep.add("NZC0-11: Dostatek i dochod na glowe (ostatnia doba)", f"swiat D {last['dw']} (mediana chlopow wsi {last['dpeas']}, Westeros {last['dwest']}, Essos {last['dess']}); stany D: {last['dest']}; "
            f"dochod na glowe {last['inc']} zl/rok (Westeros {last['incw']}, Essos {last['ince']}), stany: {last['incest']}; koszyk przetrwania miasta {last['kt']}, wsie {last['kv']} zl/d; "
            f"regiony {last['nreg']}: D {last['rmin']} / {last['rmed']} / {last['rmax']} (bez wielkich rodow: mediana {last['rmed0']}); srednia: mediana osad {last['avg']} dob"
            + (" - ROZGRZEWKA" if last.get("warm") else "")
            + "; wielkie rody: D z dochodu rodu 1:1 BRUTTO / 3 x zywi bohaterowie - nieporownywalne z 'x20' projektu 6.1, nie do progow ZC6",
            "INFO (projekt rozdz. 9: chlopi 1.7-2.2, rzemieslnicy 2.5-4, kupcy 4-9, szlachta 6-12)", None)
    rep.add("NZC0-12: wielkie rody, pochylenie BK, New Ibbish (ostatnia doba)", f"wielkie rody {last['gh']} ({last['heroes']} bohaterow x 3 w {last['clans']} rodach; projekt ok. 10 tys.); "
            f"pochylenie BK {last['tilt']} osad (klasy BK {last['bk']}); wsie poza BoundVillages {last['nib']} ({last['nibp']} ludzi: {last['nibn']}), bez regionu {last['noreg']}, "
            f"bez miasta targowego {last['nomk']}; kultury spoza tabeli {last['unk']}; wejscia doby: {last['inflow'][:400]}", "INFO", None)
    if pd:
        lp = pdays[pd[-1]]
        rep.add("NZC0-13: Spizarnia (ostatnia doba)", f"potrzeba {lp['need']} t/d ({lp['kgpp']} kg/os), napoje {lp['drink']} tys. l, kcal {lp['kcal']}; z pola {lp['field']} t ({lp['fp']}%), "
                f"z targu {lp['mkt']} t ({lp['mp']}%); targ dzis {lp['act']} t, brak {lp['brak']} t ({lp['bp']}%); krolestw linii {kings}",
                "INFO (projekt rozdz. 7.1: 45.9 tys. t, 0.885 kg/os, z targu 23%, 2 315 kcal)", None)
        need, kgpp, fp = nzc0_f(lp["need"]), nzc0_f(lp["kgpp"]), nzc0_f(lp["fp"])
        rep.add("NZC0-14: potrzeba stale wobec audytu rozdz. 7.1 (ostatnia doba)", f"{lp['need']} t/d (audyt {NZC0_NEED[0]:.0f}" + (f", {100 * (need / NZC0_NEED[0] - 1):+.2f}%)" if need is not None else ")"),
                f"{NZC0_NEED[0]:.0f} t/d +-{100 * NZC0_NEED[1]:.0f}% (DECYZJA - ludnosc rozna od doby audytu)", (need is not None and abs(need / NZC0_NEED[0] - 1) <= NZC0_NEED[1]), decide=True)
        rep.add("NZC0-15: kg na osobe wobec audytu rozdz. 7.1 (ostatnia doba)", f"{lp['kgpp']} kg/os (audyt {NZC0_KGPP[0]})",
                f"{NZC0_KGPP[0]} +-{NZC0_KGPP[1]} (DECYZJA - mieszanka stanow i krain inna niz w audycie)", (kgpp is not None and abs(kgpp - NZC0_KGPP[0]) <= NZC0_KGPP[1]), decide=True)
        rep.add("NZC0-16: udzial z pola i domu wobec audytu rozdz. 7.1 (ostatnia doba)", f"{lp['fp']}% (audyt {NZC0_FIELD[0]}%; z targu {lp['mp']}%)",
                f"{NZC0_FIELD[0]}% +-{NZC0_FIELD[1]:.0f} pkt (DECYZJA - glod ze spichlerzy albo inna mieszanka)", (fp is not None and abs(fp - NZC0_FIELD[0]) <= NZC0_FIELD[1]), decide=True)
    # NZC0-17: ta sama doba policzona dwa razy (zapis wczytany ponownie w tym samym logu) - Dostatek swiata z sredniej z zapisu
    if dups:
        cmp_, skip = [], 0
        for d, a, b in dups:
            da, db_, na, nb = nzc0_f(a["dw"]), nzc0_f(b["dw"]), nzc0_f(a["avg"]), nzc0_f(b["avg"])
            if None in (da, db_, na, nb) or na < 14 or nb < 14 or da <= 0:
                skip += 1
                continue
            cmp_.append((d, da, db_, abs(db_ / da - 1), b["rest"]))
        if cmp_:
            badr = [x for x in cmp_ if x[3] > 0.03]
            w = max(cmp_, key=lambda x: x[3])
            rep.add("NZC0-17: zapis wczytany ponownie - ta sama doba, ten sam Dostatek swiata", f"doby powtorzone {len(dups)} (porownane {len(cmp_)}, pominiete przy sredniej < 14 dob {skip}); "
                    f"poza progiem {len(badr)}; najwieksza roznica dzien {w[0]}: D {w[1]:.2f} / {w[2]:.2f} ({100 * w[3]:.2f}%, po wczytaniu z zapisu {w[4]} osad)",
                    "+-3% (srednia z zapisu; dzien po wczytaniu rozni sie tylko o 1/28 doby)", not badr)
        else:
            rep.add("NZC0-17: zapis wczytany ponownie", f"doby powtorzone {len(dups)}, wszystkie przy sredniej < 14 dob", "INFO (+-3% przy sredniej >= 14 dob)", None)
    else:
        rep.add("NZC0-17: zapis wczytany ponownie", "brak doby policzonej dwa razy w logu (bez wczytania w tym samym procesie)", "INFO (+-3% Dostatku swiata)", None)
    rep.show()
    return 0

# ------------------------------------------------------------ nzc2 (16.10, zycie codzienne ZC2 - stany w ksiedze i w zapisie + widok; projekt ZC rozdz. 12, 14)
NZC2_HEAD = "Stany (ZC2): "
NZC2_START = re.compile(r"Stany \(ZC2\): start sesji \| klucz Daily Life Estates (?P<k>tak|WYLACZONE) \(Daily Life Measure (?P<m>tak|WYLACZONE)\)")
NZC2_DAY = re.compile(r"Stany \(ZC2\): dzien (?P<day>-?\d+) \| stany w ksiedze (?P<cov>\d+)/(?P<all>\d+) osad \(miasta (?P<tp>\d+)/(?P<t>\d+), wsie (?P<vp>\d+)/(?P<v>\d+) z udzialami; "
                      r"zamki (?P<c>\d+) - ludzie w ich wsiach; bez udzialow (?P<miss>\d+)\) "
                      r"\| zasiano dzis (?P<sd>\d+), od wczytania (?P<ss>\d+) \(pochylonych BK (?P<tilt>\d+), bez klas BK (?P<nobk>\d+)\), z zapisu (?P<fromsave>\d+) \(zle udzialy (?P<badp>\d+)\) "
                      r"\| swiat \(ksiega\): chlopi (?P<peas>\d+|-), mieszczanie (?P<burgh>\d+|-) \(biedota (?P<lab>\d+|-), rzemieslnicy (?P<craft>\d+|-), kupcy (?P<merch>\d+|-)\), "
                      r"szlachta (?P<gent>\d+|-), wielkie rody (?P<house>\d+|-), niewolni (?P<slave>\d+|-) "
                      r"\| suma kontrolna (?P<hash>[0-9A-F]{8}) "
                      r"\| pamiec Dostatku: tygodni (?P<weeks>\d+) \(ostatni dzien (?P<wday>-?\d+)\) "
                      r"\| widok od ostatniej linii: dymki osad (?P<tip>\d+) \(w tym zamki - region (?P<tipc>\d+)\), dymki wiosek pobocznych (?P<side>\d+), People of this land (?P<ppl>\d+), "
                      r"Look over the district (?P<dist>\d+), Realm ledger (?P<realm>\d+)(?:, Estates and livelihood (?P<est>\d+))? \| potkniecia widoku (?P<vst>\d+) \(od wczytania (?P<vsta>\d+)\)\.$")
NZC2_SEED = re.compile(r"Stany \(ZC2\): dzien (?P<day>-?\d+) \| zasiano (?P<n>\d+) osad \(miasta (?P<t>\d+), wsie (?P<v>\d+)\) z pasm x klasy BK \(pochylonych (?P<tilt>\d+), bez klas BK (?P<nobk>\d+)\)")
NZC2_SAVE = re.compile(r"Stany \(ZC2\): zapis \| dzien (?P<day>-?\d+) \| osad (?P<n>\d+) \(z udzialami (?P<np>\d+), z pamiecia Dostatku (?P<nr>\d+)\) \| (?P<kb>[\d.]+) KB "
                       r"\((?P<chars>\d+) znakow, kawalkow (?P<parts>\d+)\) \| suma kontrolna (?P<hash>[0-9A-F]{8})")
NZC2_LOAD = re.compile(r"Stany \(ZC2\): wczytanie \| format v[1234] \| osad (?P<n>\d+) \(z udzialami (?P<np>\d+), pominiete wpisy (?P<bad>\d+), zle udzialy - zasiew od nowa (?P<badp>\d+)\) "
                       r"\| pamiec Dostatku z dob (?P<rd>[-\d,]+) \| suma kontrolna (?P<hash>[0-9A-F]{8})(?:\.| \| v4: )")   # recenzja 16.10: v4 (kotwice dobrobytu, wolnosc, naglowek ZC)
NZC2_TIP = "Stany (ZC2): dymek osady - linie stanow i Dostatku wpiete w: "
NZC2_MENU = "Stany (ZC2): pozycja \"Realm ledger\""
NZC2_ERR = ("ERROR in DailyLife.", "ERROR in SyncData.arm_estates", "ERROR in PeopleMenu.Estates", "ERROR in DistrictMenu.Estates")
NZC2_ZC0ST = re.compile(r"Zycie \(ZC0\): dzien (?P<day>-?\d+) \|.* \| potkniecia dzis (?P<st>\d+) \(od wczytania (?P<sta>\d+)\)\.$")
NZC2_KB = 60.0              # projekt rozdz. 14 ZC2: zapis + <= 60 KB
NZC2_VIEW = ("DailyLife.View.cs", "PeopleMenu.cs", "DistrictMenu.cs")


def nzc2_src_scan():
    """Menu bez GameMenu.SwitchToMenu (CLAUDE.md 7): pliki widoku ZC2 w Armoury/src obok tools/ (repo, z ktorego biegnie skrypt)."""
    base = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "Armoury", "src")
    found, hits = [], []
    for f in NZC2_VIEW:
        p = os.path.join(base, f)
        if not os.path.isfile(p):
            continue
        found.append(f)
        with open(p, encoding="utf-8", errors="replace") as fh:
            for i, ln in enumerate(fh, 1):
                code = ln.split("//", 1)[0]
                if "SwitchToMenu(" in code:
                    hits.append(f"{f}:{i}")
    return found, hits


def nzc2_main(logp, bdp=None, until=120):
    """nzc2 (16.10; Armoury/src/DailyLife.Estates.cs, DailyLife.View.cs, klucz DailyLifeEstates): ZC2 - stany w ksiedze i w zapisie (arm_estates) i widok
    (dymki osad i wiosek pobocznych, People of this land, Look over the district, Realm ledger); bez skutku w ekonomii. Progi projektu rozdz. 14 (ZC2) i wspolne:
    NZC2-0 linia startu sesji (klucz tak), NZC2-0b dymek osady wpiety (TooltipRefresherCollection; z NavalDLC - oba), NZC2-0c pozycja Realm ledger wpieta,
    NZC2-1 linia 'Stany (ZC2): dzien N' w kazdej dobie z linia 'Zycie (ZC0)' (bez luk, nierozpoznane 0), NZC2-2 stany w ksiedze N/N osad kazdej doby
    (projekt: 798/798), NZC2-3 stary zapis zasiany w pierwszej dobie (wczytanie bez klucza -> pierwsza linia doby N/N, zasiano = miasta + wsie),
    NZC2-4 zapis + wczytanie: suma kontrolna udzialow przy wczytaniu = przy ostatnim zapisie przed nim (bez wczytania po zapisie - INFO), NZC2-5 zapis
    <= 60 KB (najwiekszy), NZC2-6 udzialy stoja (suma kontrolna stala poza dobami zasiewu - ZC2 nikogo nie przesuwa), NZC2-7 potkniecia (ZC0 + widok)
    i ERROR paczki 0, NZC2-8 menu bez SwitchToMenu (kod widoku w repo), NZC2-9 ksiega towarow +-2% bazy (z --baza-doby; bez - INFO), NZC2-10..11 INFO
    (swiat wedlug stanow, uzycie widoku - autotest nie najezdza dymkow).
    Log bez paczki: INFO, bez wyjatku."""
    rep = Report()
    if not logp or not os.path.isfile(logp):
        rep.add("NZC2-0: log Armoury", f"brak pliku {logp}", "podaj <Armoury-*.log>", None)
        rep.show()
        return 0
    sess, days, bad, seeds, saves, loads, loads_other, tips, menus = [], {}, [], [], [], [], [], [], []
    events = []      # (kolejnosc, rodzaj, dane) - zapis / wczytanie po kolei w logu
    zc6_moves = False   # ZC6 (16.10): linia startu ZC6 z kluczem ruchu albo wyzwolenia - udzialy rusza (NZC2-6 INFO)
    zc0 = {}
    n_err = 0
    with open(logp, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\n"))
            s = m.group(2) if m else ln.rstrip("\n")
            if s.startswith(NZC2_HEAD):
                if s.startswith(NZC2_HEAD + "start sesji"):
                    sess.append(s)
                elif s.startswith(NZC2_TIP):
                    tips.append(s)
                elif s.startswith(NZC2_MENU):
                    menus.append(s)
                elif s.startswith(NZC2_HEAD + "zapis"):
                    mm = NZC2_SAVE.match(s)
                    if mm:
                        saves.append(mm.groupdict()); events.append(("zapis", mm.groupdict()))
                    else:
                        bad.append(s)
                elif s.startswith(NZC2_HEAD + "wczytanie"):
                    mm = NZC2_LOAD.match(s)
                    if mm:
                        loads.append(mm.groupdict()); events.append(("wczytanie", mm.groupdict()))
                    else:
                        loads_other.append(s); events.append(("wczytanie-bez", {"text": s}))
                elif s.startswith(NZC2_HEAD + "dzien "):
                    if "| zasiano " in s and "| stany w ksiedze" not in s:
                        mm = NZC2_SEED.match(s)
                        if mm:
                            seeds.append(mm.groupdict())
                        else:
                            bad.append(s)
                    else:
                        mm = NZC2_DAY.match(s)
                        if mm:
                            days[int(mm.group("day"))] = mm.groupdict()
                        else:
                            bad.append(s)
                else:
                    bad.append(s)
            elif s.startswith("Zycie (ZC0): dzien "):
                mm = NZC2_ZC0ST.match(s)
                if mm:
                    zc0[int(mm.group("day"))] = (int(mm.group("st")), int(mm.group("sta")))
            elif s.startswith(NZC2_ERR):
                n_err += 1
            elif s.startswith("Awans (ZC6): start sesji") and ("Daily Life Mobility tak" in s or "Daily Life Freedom tak" in s):
                zc6_moves = True
            elif s.startswith("Blizna wojny (ZC7): start sesji") and "Daily Life War Scar tak" in s:
                zc6_moves = True   # ZC7 (16.10): blizna wojny przesuwa udzialy (ruina przy zlupieniu, rzemieslnicy wsi po najezdzie, powrot) - NZC2-6 INFO
            elif s.startswith("Niewola za dlugi (f8): start sesji") and "klucz Debt Slavery tak" in s and "nikt nie wpada" not in s:
                zc6_moves = True   # f8-niewola (18.10, recenzja): niewola za dlugi przesuwa udzialy (biedni wolni -> niewolni) - NZC2-6 INFO
    print(f"plik: {logp} | linii startu sesji {len(sess)}, doby Stany {len(days)} (nierozpoznanych {len(bad)}), zasiewow {len(seeds)}, zapisow {len(saves)}, "
          f"wczytan {len(loads)} (bez ksiegi stanow {len(loads_other)}), doby Zycie (ZC0) {len(zc0)}")
    if not sess and not days and not bad and not saves and not loads and not loads_other:
        rep.add("NZC2-0: linie 'Stany (ZC2)'", "brak w logu", "INFO (log sprzed paczki ZC2)", None)
        rep.show()
        return 0
    # NZC2-0
    if sess:
        mm = NZC2_START.match(sess[-1])
        ok = bool(mm) and mm.group("k") == "tak" and mm.group("m") == "tak"
        rep.add("NZC2-0: linia startu sesji (klucz Daily Life Estates)", sess[-1][len(NZC2_HEAD):][:320], "Daily Life Estates tak (z Daily Life Measure tak)",
                True if ok else (None if mm and (mm.group("k") == "WYLACZONE" or mm.group("m") == "WYLACZONE") else False))
    else:
        rep.add("NZC2-0: linia startu sesji", "brak", "linia przy kazdym starcie sesji", False)
    if tips:
        t = tips[-1][len(NZC2_TIP):]
        okt = "TooltipRefresherCollection" in t and "NIGDZIE" not in t
        rep.add("NZC2-0b: dymek osady wpiety (postfiks dymka gry i NavalDLC)", t[:200], "TooltipRefresherCollection (z NavalDLC - takze NavalTooltipRefresherCollection)", okt)
    else:
        rep.add("NZC2-0b: dymek osady wpiety", "brak linii wpiecia (log otwarty po menu glownym?)", "INFO (linia przy starcie gry)", None)
    rep.add("NZC2-0c: pozycje 'Realm ledger' i 'Estates and livelihood' w menu", (menus[-1][len(NZC2_HEAD):][:220] if menus else "brak linii"), "linia wpiecia przy starcie sesji", bool(menus))
    # NZC2-1
    dd = sorted(days)
    if not dd:
        rep.add("NZC2-1: linie 'Stany (ZC2): dzien N'", f"brak rozpoznanych linii doby (nierozpoznane {len(bad)})" + (f": {bad[0][:220]}" if bad else ""), "linia kazdej doby", False)
        rep.show()
        return 0
    zd = sorted(d for d in zc0 if dd[0] <= d <= dd[-1])
    miss = [d for d in zd if d not in days]
    span = dd[-1] - dd[0] + 1
    rep.add("NZC2-1: linia 'Stany (ZC2)' w kazdej dobie z linia 'Zycie (ZC0)'", f"doby Stany {len(dd)} (dzien {dd[0]}-{dd[-1]}), doby Zycie bez Stany {len(miss)}"
            + (f" (np. {miss[:5]})" if miss else "") + f", nierozpoznane {len(bad)}" + (f" (np. {bad[0][:200]})" if bad else "")
            + (f"; dob w logu mniej niz {until} (bieg krotszy)" if span < until else ""), "0 dob bez linii, nierozpoznane 0", not miss and not bad)
    last, first = days[dd[-1]], days[dd[0]]
    # NZC2-2
    badc = [d for d in dd if int(days[d]["cov"]) != int(days[d]["all"]) or int(days[d]["all"]) == 0]
    rep.add("NZC2-2: stany w ksiedze dla wszystkich osad (kazda doba)", f"ostatnia doba {last['cov']}/{last['all']} (miasta {last['tp']}/{last['t']}, wsie {last['vp']}/{last['v']}, zamki {last['c']}, "
            f"bez udzialow {last['miss']}); doby z brakiem {len(badc)} z {len(dd)}" + (f" (np. dzien {badc[0]}: {days[badc[0]]['cov']}/{days[badc[0]]['all']})" if badc else ""),
            "N/N kazdej doby (projekt: 798/798)", not badc)
    # NZC2-3: stary zapis zasiany w pierwszej dobie
    old_save = any("brak klucza arm_estates" in x["text"] for k, x in events if k == "wczytanie-bez")
    seeded = sum(int(x["n"]) for x in seeds)
    tv = int(first["t"]) + int(first["v"])
    if old_save or (not loads and seeds):
        ok3 = int(first["cov"]) == int(first["all"]) and seeded >= tv and int(first["ss"]) >= tv
        rep.add("NZC2-3: stary zapis (bez arm_estates) zasiany w pierwszej dobie", f"zasiano {seeded} osad w {len(seeds)} liniach (pierwsza: dzien {seeds[0]['day'] if seeds else '-'}, "
                f"pochylonych BK {seeds[0]['tilt'] if seeds else '-'}, bez klas BK {seeds[0]['nobk'] if seeds else '-'}); pierwsza doba linii {dd[0]}: {first['cov']}/{first['all']}, "
                f"od wczytania {first['ss']} (miasta + wsie {tv})", "pierwsza doba N/N, zasiano = miasta + wsie (projekt: 798/798)", ok3)
    elif loads:
        rep.add("NZC2-3: zapis z ksiega stanow", f"wczytano {loads[-1]['np']} osad z udzialami (zle udzialy {loads[-1]['badp']}); zasiano w biegu {seeded} (nowe osady)",
                "INFO (zasiew tylko starego zapisu - tu ksiega z zapisu)", None)
    else:
        rep.add("NZC2-3: zasiew", f"brak linii wczytania; zasiano {seeded}", "INFO", None)
    # NZC2-4: zapis + wczytanie - suma kontrolna przy wczytaniu = przy ostatnim zapisie przed nim
    pairs, last_save = [], None
    for k, x in events:
        if k == "zapis":
            last_save = x
        elif k == "wczytanie" and last_save is not None:
            pairs.append((last_save, x))
    if pairs:
        badh = [(a, b) for a, b in pairs if a["hash"] != b["hash"] or a["np"] != b["np"]]
        rep.add("NZC2-4: zapis + wczytanie - te same stany (suma kontrolna udzialow)", f"par zapis -> wczytanie {len(pairs)}, rozne {len(badh)}"
                + (f" (np. zapis dzien {badh[0][0]['day']}: {badh[0][0]['hash']} / {badh[0][0]['np']} osad, wczytanie {badh[0][1]['hash']} / {badh[0][1]['np']})" if badh
                   else f"; ostatnia para {pairs[-1][0]['hash']} = {pairs[-1][1]['hash']} ({pairs[-1][1]['np']} osad)"),
                "rowne kazdej pary", not badh)
    else:
        rep.add("NZC2-4: zapis + wczytanie", f"zapisow {len(saves)}, wczytan z ksiega stanow po zapisie 0 (bieg bez ponownego wczytania)", "INFO (rowne sumy kontrolne)", None)
    # NZC2-5
    if saves:
        kb = max(float(x["kb"]) for x in saves)
        w = max(saves, key=lambda x: float(x["kb"]))
        rep.add("NZC2-5: rozmiar ksiegi stanow w zapisie", f"najwiekszy {kb:.1f} KB (dzien {w['day']}, {w['n']} osad, {w['chars']} znakow w {w['parts']} kawalkach), zapisow {len(saves)}",
                f"<= {NZC2_KB:.0f} KB", kb <= NZC2_KB)
    else:
        rep.add("NZC2-5: rozmiar ksiegi stanow w zapisie", "brak linii zapisu (bieg bez zapisu gry)", f"INFO (<= {NZC2_KB:.0f} KB)", None)
    # NZC2-6: udzialy stoja - suma kontrolna stala poza dobami zasiewu
    changes, prev = [], None
    for d in dd:
        h = days[d]["hash"]
        if prev is not None and h != prev[1] and int(days[d]["sd"]) == 0:
            changes.append((d, prev[1], h))
        prev = (d, h)
    if zc6_moves:
        rep.add("NZC2-6: udzialy stanow (ZC6 - awans, spadek, wyzwolenia, przybysze)", f"zmiany sumy kontrolnej poza dobami zasiewu {len(changes)}; ostatnia {last['hash']}",
                "INFO (ZC6 / ZC7 przesuwaja udzialy - kontrola w --grupa nzc6 i nzc7)", None)
    else:
        rep.add("NZC2-6: udzialy stanow stoja (ZC2 bez awansu i spadku)", f"zmiany sumy kontrolnej poza dobami zasiewu {len(changes)}" + (f" (np. dzien {changes[0][0]}: {changes[0][1]} -> {changes[0][2]})" if changes else "")
                + f"; ostatnia {last['hash']}", "0", not changes)
    # NZC2-7
    stz = sum(zc0[d][0] for d in zd)
    vst = sum(int(days[d]["vst"]) for d in dd)
    rep.add("NZC2-7: potkniecia (doby ZC0 z ksiega stanow + widok) i ERROR paczki", f"potkniecia ZC0 {stz} (od wczytania na koniec {zc0[zd[-1]][1] if zd else '-'}), widoku {vst} (od wczytania {last['vsta']}), "
            f"ERROR {n_err}", "0 / 0 / 0", stz == 0 and vst == 0 and n_err == 0)
    # NZC2-8
    found, hits = nzc2_src_scan()
    if found:
        rep.add("NZC2-8: menu widoku bez GameMenu.SwitchToMenu (kod)", f"pliki {', '.join(found)}: wywolan SwitchToMenu {len(hits)}" + (f" ({', '.join(hits[:5])})" if hits else ""), "0 (CLAUDE.md 7 - ShowInquiry)", not hits)
    else:
        rep.add("NZC2-8: menu bez SwitchToMenu", "brak plikow widoku obok tools/ (skrypt poza repo)", "INFO", None)
    # NZC2-9
    if bdp:
        g1, g0 = nzc0_goods(logp), nzc0_goods(bdp)
        common = sorted(set(g1) & set(g0))
        if common:
            a, b = st.mean(g1[d] for d in common), st.mean(g0[d] for d in common)
            r = a / b - 1 if b else None
            rep.add("NZC2-9: ksiega towarow (produkcja na dobe) wobec biegu bazowego - bez skutku w ekonomii", f"bieg {a:.0f} szt./d, baza {b:.0f} szt./d ({len(common)} wspolnych dob), roznica "
                    + (f"{100 * r:+.2f}%" if r is not None else "-"), "+-2%", (abs(r) <= 0.02) if r is not None else None)
        else:
            rep.add("NZC2-9: ksiega towarow wobec bazy", "brak wspolnych dob linii 'Towary (bilans)'", "+-2%", None)
    else:
        rep.add("NZC2-9: ksiega towarow wobec bazy", "bez --baza-doby", "INFO (+-2% z logiem bazy)", None)
    # INFO
    rep.add("NZC2-10: swiat wedlug stanow (ostatnia doba, ksiega)", f"chlopi {last['peas']}, mieszczanie {last['burgh']} (biedota {last['lab']}, rzemieslnicy {last['craft']}, kupcy {last['merch']}), "
            f"szlachta {last['gent']}, wielkie rody {last['house']}, niewolni {last['slave']}; pamiec Dostatku tygodni {last['weeks']} (ostatni dzien {last['wday']}); "
            f"pochylonych BK przy zasiewie {last['tilt']}, bez klas BK {last['nobk']}", "INFO (udzialy swiata: grupa nzc0 NZC0-3)", None)
    tot = {k: sum(int(days[d][k] or 0) for d in dd) for k in ("tip", "tipc", "side", "ppl", "dist", "realm", "est")}
    rep.add("NZC2-11: uzycie widoku w biegu", f"dymki osad {tot['tip']} (zamki - region {tot['tipc']}), dymki wiosek pobocznych {tot['side']}, People of this land {tot['ppl']}, "
            f"Look over the district {tot['dist']}, Realm ledger {tot['realm']}, Estates and livelihood {tot['est']}",
            "INFO (autotest nie najezdza dymkow i nie otwiera menu - sprawdzenie w grze: okna Estates and livelihood i Realm ledger to listy przewijane, People of this land - 2 linie na gorze)", None)
    rep.show()
    return 0


# ------------------------------------------------------------ nzc6 (16.10, zycie codzienne ZC6 - Dostatek czynny: awans i spadek, wyzwolenie, dobrobyt; projekt ZC rozdz. 9, 10, 14)
NZC6_HEAD = "Awans (ZC6): "
NZC6_START = re.compile(r"Awans \(ZC6\): start sesji \| klucze: Daily Life Mobility (?P<m>tak|WYLACZONE), Daily Life Freedom (?P<f>tak|WYLACZONE), "
                        r"Daily Life Prosperity Link (?P<p>tak|WYLACZONE) \(Daily Life Estates (?P<e>tak|WYLACZONE), Daily Life Measure (?P<z>tak|WYLACZONE)\)")
NZC6_DAY = re.compile(r"Awans \(ZC6\): dzien (?P<day>-?\d+) \| klucze: ruch (?P<m>tak|nie), wyzwolenie (?P<f>tak|nie), dobrobyt (?P<p>tak|nie) "
                      r"\| od ostatniej linii (?P<dd>\d+) dob: przegladow osad (?P<seen>\d+) \(rozgrzewka - bez przegladu (?P<warm>\d+)\) \| ludzie \(ksiega\): (?P<tr>.*?) \| w gore ")
NZC6_ERR = ("ERROR in DailyLife.", "ERROR in TownFolk.ZcCarry", "ERROR in TownFolk.ZcPayLand")
NZC6_RANGE = (("chlopi", 1.3, 2.5), ("biedota", 1.4, 2.5), ("rzemieslnicy", 2.2, 4.5), ("kupcy", 4.0, 10.0), ("szlachta", 6.0, 15.0))
NZC6_ZC0REG = re.compile(r"Zycie \(ZC0\): dzien (?P<day>-?\d+) \|.*?; regiony (?P<n>\d+): D min (?P<mn>[-\d.]+) / mediana (?P<md>[-\d.]+) / max (?P<mx>[-\d.]+)")
NZC6_MOVE_TOL = 0.001      # % - zaokraglenie milionowej (najwyzej +1 ppm na przejscie) ponad 0.2%/tydz.
NZC6_PABS = 0.5            # recenzja 16.10 / projekt rozdz. 14 ZC6: srednie |czlon| dobrobytu <= 0.5/d (srednia ze znakiem - INFO: plus i minus sie znosza)
NZC6_PCAP = 10.0           # % warowni na suficie 2 pkt na dobe
NZC6_PDRIFT = 5.0          # % - dryf krainy (suma czlonow / dobrobyt bez czlonow), wszystkie krainy i rodzaje (takze 1-2 warownie)
NZC6_PRUN = 28             # dob - mediana czlonu krainy tego samego znaku bez malejacej |mediany| = brak zbieznosci
NZC6_FIELDS = (
    ("up", r"\| w gore (\d+), w dol \d+, netto"), ("down", r"\| w gore \d+, w dol (\d+), netto"),
    ("upS", r"od wczytania \(\d+ dob\): w gore (\d+)"), ("downS", r"od wczytania \(\d+ dob\): w gore \d+, w dol (\d+)"),
    ("daysS", r"od wczytania \((\d+) dob\)"), ("freedS", r", wyzwoleni (\d+), przybysze"), ("migS", r", przybysze (\d+), netto w gore"),
    ("netyr", r"netto w gore ([-\d.]+)% swiata na rok"),
    ("w2r", r"z ludzmi W->R (\d+)"), ("fee", r"oplaty cechowe (\d+)\)"), ("r2p", r", R->P (\d+)"), ("r2w", r", R->W (\d+)"), ("p2r", r", P->R (\d+);"),
    ("landT", r"ziemia do panow: miasta (\d+) \("), ("landTN", r"ziemia do panow: miasta \d+ \((\d+) kupna\)"),
    ("landV", r", wsie (\d+) \(\d+ kupna\)"), ("landVN", r", wsie \d+ \((\d+) kupna\)"),
    ("purseOut", r"kontrola obiegu: kiesy ludu -(\d+)"), ("vilOut", r", kiesy wsi -(\d+)"), ("lordIn", r", panowie \+(\d+)"), ("ctl", r", roznica (\d+)"),
    ("noPurse", r"zapas nieznany \(kiesa nieczynna\) (\d+)"), ("noLord", r"bez zywego pana (\d+)"), ("short", r"\(brak pieniedzy\) (\d+)"), ("war", r"oblezenie / najazd (\d+)"),
    ("capHit", r"osad z cieciem (\d+)"), ("maxMove", r"najwiekszy ruch ([-\d.]+)%"),
    ("bandCut", r"granice pasm: ciecia (\d+)"), ("outBand", r"osad poza pasmem (\d+)"), ("outFree", r"po wyzwoleniu przez zdobywce (\d+)[,)]"), ("freeSt", r"osad pod wladca bez niewoli (\d+)"),
    ("outMig", r"od przybyszy ze wsi (\d+)\)"), ("freeOld", r"zastane od wlaczenia - bez wyzwalania (\d+)\)"),
    ("backT", r"odkup ziemi przy spadku szlachty: miasta (\d+) \("), ("backV", r"odkupow\), wsie (\d+) \("), ("landNet", r"netto do panow (-?\d+)"),
    ("lordOut", r"; odkup: panowie -(\d+)"), ("purseIn", r", kiesy ludu \+(\d+)"), ("vilIn", r", kiesy wsi \+(\d+)"), ("landMsg", r"komunikaty gracza o ziemi (\d+)"),
    ("dPeas", r"mediany D stanow \(wazone ludzmi, osady z wlasnym D\): chlopi ([-\d.]+)"), ("dLab", r", biedota ([-\d.]+), rzemieslnicy"),
    ("dCraft", r", rzemieslnicy ([-\d.]+), kupcy"), ("dMerch", r", kupcy ([-\d.]+), szlachta"), ("dGent", r", szlachta ([-\d.]+) \| dobrobyt"),
    ("pN", r"warowni z czlonem (\d+) w"), ("pKr", r"warowni z czlonem \d+ w (\d+) krainach"), ("pNoD", r"\(bez D regionu (\d+)\)"),
    ("pMean", r"czlon srednio ([-\d.]+)/d"), ("pAbs", r"srednio \|czlon\| ([-\d.]+)/d"), ("pCap", r"na suficie 2 pkt (\d+)"),
    ("pCapPct", r"na suficie 2 pkt \d+ \(([-\d.]+)% warowni\)"), ("pAnch", r"kotwice nowe dzis (\d+)"), ("pReAnch", r"ponowne przy zmianie ZC7 (\d+)\)"),
    ("pDrift", r"dryf krain [^:]*: najwiekszy ([-\d.]+)% \("), ("pDriftExp", r"; z Dostatku krainy ([-\d.]+)%\)"), ("pDriftN", r"krain ponad 5%: (\d+) z"),
    ("pLands", r"krain ponad 5%: \d+ z (\d+)"), ("pRun", r"tego samego znaku najdluzsza (\d+) dob"), ("pRunA0", r"\|mediana\| na poczatku ([-\d.]+) ->"),
    ("pRunA1", r" -> dzis ([-\d.]+)\)"),
    ("pCalls", r"wywolan postfiksu (\d+)"), ("pStum", r"potkniec postfiksu (\d+)"), ("stum", r"potkniecia przegladu (\d+)\.$"),
)


def nzc6_parse(s):
    """Linia 'Awans (ZC6): dzien N' -> slownik (None przy nierozpoznanej glowie). Pola szukane osobno - nazwy osad i opis wpiecia dobrobytu maja nawiasy."""
    m = NZC6_DAY.match(s)
    if not m:
        return None
    d = m.groupdict()
    for k, pat in NZC6_FIELDS:
        mm = re.search(pat, s)
        v = None
        if mm:
            try:
                v = float(mm.group(1))
            except ValueError:
                v = None
        d[k] = v
    d["state"] = "liczony" if "dobrobyt (liczony" in s else ("rozgrzewka" if "dobrobyt (rozgrzewka" in s else ("wylaczony" if "dobrobyt (wylaczony" in s else "-"))
    mk = re.search(r"dryf krain [^:]*: najwiekszy [-\d.]+% \(([^;]*);", s)
    d["pDriftKey"] = mk.group(1) if mk else "-"
    mr = re.search(r"tego samego znaku najdluzsza \d+ dob \(([^;]*);", s)
    d["pRunKey"] = mr.group(1) if mr else "-"
    return d


def nzc6_main(logp, bdp=None, until=120):
    """nzc6 (16.10; Armoury/src/DailyLife.Mobility.cs, DailyLife.Prosperity.cs, klucze DailyLifeMobility / DailyLifeFreedom / DailyLifeProsperityLink): ZC6 - Dostatek czynny.
    Progi projektu rozdz. 14 (ZC6) i wspolne: NZC6-0 linia startu sesji (klucze), NZC6-0b postfiks dobrobytu wpiety (czynny model), NZC6-1 linia 'Awans (ZC6): dzien N'
    w kazdej dobie z linia 'Zycie (ZC0)' (nierozpoznane 0), NZC6-2 ruch <= 0.2% ludzi osady na tydzien (najwiekszy w kazdej linii), NZC6-3 swiat netto w gore 0.5-3%/rok
    (od wczytania; ponizej - DECYZJA, gdy mediany D stanow ponizej progow awansu: dochody stanow to ZC4), NZC6-4 mediany D stanow: chlopi 1.3-2.5, biedota 1.4-2.5,
    rzemieslnicy 2.2-4.5, kupcy 4-10, szlachta 6-15 (poza - DECYZJA: kalibracja dochodu stanow ZC4, projekt: ZC6 po 120 dobach ZC4), NZC6-5 max/min D regionow <= 8
    (linia ZC0; dzis ok. 90 - DECYZJA, ta sama przyczyna), NZC6-6 udzialy stanow w pasmach (osad poza pasmem 0; po wyzwoleniu przez zdobywce - INFO), NZC6-7 obieg
    zamkniety (roznica 0, kupno: kiesy ludu + kiesy wsi = panowie, odkup: panowie = kiesy ludu + kiesy wsi w kazdej linii), NZC6-8 srednie |czlon| dobrobytu <= 0.5/d,
    NZC6-8b warownie na suficie 2 pkt <= 10%, NZC6-8c srednia ze znakiem (INFO), NZC6-9 dryf krain +-5% (wszystkie krainy; wiecej w granicy rownowagi z Dostatku - DECYZJA),
    NZC6-9b zbieznosc (seria znaku mediany czlonu krainy <= 28 dob albo malejaca |mediana| - inaczej DECYZJA) - recenzja 16.10 (Prosperity Link domyslnie wylaczony:
    bez czlonu wiersze INFO), NZC6-10 potkniecia (przeglad, postfiks) i ERROR 0, NZC6-11..13 INFO (przejscia, pieniadze, blokady).
    Czas bloku - grupa nzc0 (NZC0-6, blok ZC zawiera ZC6); zapis + wczytanie udzialow - grupa nzc2 (NZC2-4). Log bez paczki: INFO, bez wyjatku."""
    rep = Report()
    if not logp or not os.path.isfile(logp):
        rep.add("NZC6-0: log Armoury", f"brak pliku {logp}", "podaj <Armoury-*.log>", None)
        rep.show()
        return 0
    sess, days, bad, zc0, zc0reg = [], {}, [], set(), {}
    n_err = 0
    with open(logp, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\n"))
            s = m.group(2) if m else ln.rstrip("\n")
            if s.startswith(NZC6_HEAD):
                if s.startswith(NZC6_HEAD + "start sesji"):
                    sess.append(s)
                elif s.startswith(NZC6_HEAD + "dzien "):
                    d = nzc6_parse(s)
                    if d is None:
                        bad.append(s)
                    else:
                        days[int(d["day"])] = d
                else:
                    bad.append(s)
            elif s.startswith("Zycie (ZC0): dzien "):
                mm = re.match(r"Zycie \(ZC0\): dzien (-?\d+) \|", s)
                if mm:
                    zc0.add(int(mm.group(1)))
                mr = NZC6_ZC0REG.match(s)
                if mr:
                    zc0reg[int(mr.group("day"))] = mr.groupdict()
            elif s.startswith(NZC6_ERR):
                n_err += 1
    print(f"plik: {logp} | linii startu sesji {len(sess)}, doby Awans {len(days)} (nierozpoznanych {len(bad)}), doby Zycie (ZC0) {len(zc0)}")
    if not sess and not days and not bad:
        rep.add("NZC6-0: linie 'Awans (ZC6)'", "brak w logu", "INFO (log sprzed paczki ZC6)", None)
        rep.show()
        return 0
    keys = None
    if sess:
        mm = NZC6_START.match(sess[-1])
        keys = mm.groupdict() if mm else None
        ok = bool(mm) and all(mm.group(k) == "tak" for k in ("m", "f", "e", "z"))
        rep.add("NZC6-0: linia startu sesji (klucze ZC6)", sess[-1][len(NZC6_HEAD):][:300], "Mobility, Freedom tak (z Estates i Measure); Prosperity Link domyslnie WYLACZONE - na test wlaczyc w MCM",
                True if ok else (None if mm else False))
        w = sess[-1].split("| dobrobyt: ", 1)[1] if "| dobrobyt: " in sess[-1] else ""
        okp = w.startswith("postfiks Last w ")
        prosp_on = keys is not None and keys["p"] == "tak" and keys["e"] == "tak" and keys["z"] == "tak"
        rep.add("NZC6-0b: postfiks dobrobytu na czynnym modelu", (w[:220] if w else "brak opisu wpiecia"), "postfiks Last w <klasa>.CalculateProsperityChange",
                okp if prosp_on else (None if not w or okp else False))
    else:
        rep.add("NZC6-0: linia startu sesji", "brak", "linia przy kazdym starcie sesji", False)
    dd = sorted(days)
    if not dd:
        rep.add("NZC6-1: linie 'Awans (ZC6): dzien N'", f"brak rozpoznanych linii doby (nierozpoznane {len(bad)})" + (f": {bad[0][:220]}" if bad else ""), "linia kazdej doby", False)
        rep.show()
        return 0
    zd = sorted(d for d in zc0 if dd[0] <= d <= dd[-1])
    miss = [d for d in zd if d not in days]
    span = dd[-1] - dd[0] + 1
    rep.add("NZC6-1: linia 'Awans (ZC6)' w kazdej dobie z linia 'Zycie (ZC0)'", f"doby Awans {len(dd)} (dzien {dd[0]}-{dd[-1]}), doby Zycie bez Awans {len(miss)}"
            + (f" (np. {miss[:5]})" if miss else "") + f", nierozpoznane {len(bad)}" + (f" (np. {bad[0][:200]})" if bad else "")
            + (f"; dob w logu mniej niz {until} (bieg krotszy)" if span < until else ""), "0 dob bez linii, nierozpoznane 0", not miss and not bad)
    last = days[dd[-1]]

    def vals(k):
        return [days[d][k] for d in dd if days[d].get(k) is not None]
    # NZC6-2
    mv = [(d, days[d]["maxMove"]) for d in dd if days[d].get("maxMove") is not None]
    worst = max(mv, key=lambda x: x[1]) if mv else None
    rep.add("NZC6-2: ruch w osadzie na tydzien (awans, spadek, wyzwolenia; bez zdobywcy)", (f"najwiekszy {worst[1]:.3f}% (dzien {worst[0]}), osad z cieciem limitu {int(sum(vals('capHit')))}" if worst else "brak liczb"),
            "<= 0.2% ludzi osady na tydzien", (worst[1] <= 0.2 + NZC6_MOVE_TOL) if worst else None)
    # NZC6-3
    ny = last.get("netyr")
    dpe = last.get("dPeas")
    if ny is None:
        rep.add("NZC6-3: swiat netto w gore na rok", "brak liczby (pierwsza doba albo bez ludzi)", "0.5-3%/rok", None)
    else:
        ok3 = 0.5 <= ny <= 3.0
        low_d = ny < 0.5 and (dpe is None or dpe < 2.5)
        rep.add("NZC6-3: swiat netto w gore na rok (od wczytania)", f"{ny:.3f}%/rok (w gore {last.get('upS') or 0:.0f}, w dol {last.get('downS') or 0:.0f} ludzi w {last.get('daysS') or 0:.0f} dobach); "
                f"mediana D chlopow {dpe if dpe is not None else '-'}" + ("; ponizej progu awansu chlopow 2.5 - dochody stanow z koszyka (ZC4) - do decyzji" if low_d else ""),
                "0.5-3%/rok", ok3, decide=low_d)
    # NZC6-4
    meds = {"chlopi": last.get("dPeas"), "biedota": last.get("dLab"), "rzemieslnicy": last.get("dCraft"), "kupcy": last.get("dMerch"), "szlachta": last.get("dGent")}
    outs = [f"{k} {meds[k] if meds[k] is not None else '-'} (prog {lo}-{hi})" for k, lo, hi in NZC6_RANGE if meds[k] is None or not (lo <= meds[k] <= hi)]
    rep.add("NZC6-4: mediany Dostatku stanow (ostatnia doba)", ", ".join(f"{k} {meds[k] if meds[k] is not None else '-'}" for k, _, _ in NZC6_RANGE)
            + (f"; poza progiem: {'; '.join(outs)} - kalibracja dochodu stanow (ZC4: koszyk i obrot targu od ludzi; projekt: ZC6 po 120 dobach ZC4)" if outs else ""),
            "chlopi 1.3-2.5, biedota 1.4-2.5, rzemieslnicy 2.2-4.5, kupcy 4-10, szlachta 6-15", not outs, decide=bool(outs))
    # NZC6-5
    zr = sorted(d for d in zc0reg if dd[0] <= d <= dd[-1])
    if zr:
        g = zc0reg[zr[-1]]
        try:
            mn, mx = float(g["mn"]), float(g["mx"])
            ratio = mx / mn if mn > 0 else None
        except ValueError:
            ratio = None
        rep.add("NZC6-5: rozrzut Dostatku regionow (max / min, linia ZC0)", f"dzien {zr[-1]}: regiony {g['n']}, D min {g['mn']} / mediana {g['md']} / max {g['mx']}"
                + (f" = {ratio:.1f} x" if ratio else "") + ("; dzis rozrzut z zoldu i glow BK w kiesie ludu (projekt rozdz. 2.4) - ZC4 / ZC8" if ratio and ratio > 8 else ""),
                "<= 8 (dzis ok. 90)", (ratio <= 8) if ratio else None, decide=bool(ratio and ratio > 8))
    else:
        rep.add("NZC6-5: rozrzut Dostatku regionow", "brak linii ZC0 z regionami", "<= 8", None)
    # NZC6-6
    ob, of, om = int(sum(vals("outBand"))), int(sum(vals("outFree"))), int(sum(vals("outMig")))
    rep.add("NZC6-6: udzialy stanow w pasmach (0.5-1.5 x pasma)", f"przegladow z osada poza pasmem {ob} (osobno: po wyzwoleniu przez zdobywce {of}, od przybyszy ze wsi {om} - etykieta migracji, "
            f"nie awans), ciec granica {int(sum(vals('bandCut')))}, osad pod wladca bez niewoli (ostatnia linia) {int(last.get('freeSt') or 0)}, zastanych bez wyzwalania {int(last.get('freeOld') or 0)}",
            "0 (bez wyzwolenia przez zdobywce i przybyszy)", ob == 0)
    # NZC6-7
    badc = [d for d in dd if (days[d].get("ctl") or 0) != 0 or (days[d].get("purseOut") or 0) + (days[d].get("vilOut") or 0) != (days[d].get("lordIn") or 0)
            or (days[d].get("lordOut") or 0) != (days[d].get("purseIn") or 0) + (days[d].get("vilIn") or 0)]
    po, vo, li = sum(vals("purseOut")), sum(vals("vilOut")), sum(vals("lordIn"))
    lo, pi, vi = sum(vals("lordOut")), sum(vals("purseIn")), sum(vals("vilIn"))
    rep.add("NZC6-7: obieg zamkniety (pieniadze z ludzmi, ziemia do panow i odkup od panow)", f"kupno: kiesy ludu -{po:.0f}, kiesy wsi -{vo:.0f}, panowie +{li:.0f}; odkup: panowie -{lo:.0f}, "
            f"kiesy ludu +{pi:.0f}, kiesy wsi +{vi:.0f}; netto do panow {li - lo:.0f}; dob z roznica {len(badc)}" + (f" (np. dzien {badc[0]})" if badc else ""),
            "roznica 0, kiesy = panowie w kazdej linii (kupno i odkup osobno)", not badc)
    # NZC6-8 (recenzja 16.10): srednie |czlon| i udzial warowni na suficie - srednia ze znakiem tylko INFO (plus i minus sie znosza)
    pd = [d for d in dd if (days[d].get("pN") or 0) > 0]
    hint = " (przy NIE: DailyLifeProsperityLink zostaje false - nie wlaczac)"
    if pd:
        wa = max(pd, key=lambda d: days[d].get("pAbs") or 0.0)
        a8 = days[wa].get("pAbs") or 0.0
        rep.add("NZC6-8: srednie |czlon| dobrobytu z Dostatku (najwieksze w linii)", f"{a8:.3f}/d (dzien {wa}); srednio w biegu {st.mean(days[d].get('pAbs') or 0.0 for d in pd):.3f}/d; "
                f"dob z czlonem {len(pd)}, kotwic nowych w biegu {int(sum(vals('pAnch')))} (ponownych przy zmianie ZC7 {int(sum(vals('pReAnch')))})", f"<= {NZC6_PABS}/d" + hint, a8 <= NZC6_PABS)
        cp = [(d, days[d].get("pCapPct")) for d in pd if days[d].get("pCapPct") is not None]
        wc = max(cp, key=lambda x: x[1]) if cp else None
        rep.add("NZC6-8b: warownie na suficie 2 pkt na dobe (najwiecej w linii)", (f"{wc[1]:.1f}% warowni (dzien {wc[0]}; {int(days[wc[0]].get('pCap') or 0)} z {int(days[wc[0]].get('pN') or 0)})" if wc else "brak liczb"),
                f"<= {NZC6_PCAP:.0f}%" + hint, (wc[1] <= NZC6_PCAP) if wc else None)
        wm = max(pd, key=lambda d: abs(days[d].get("pMean") or 0.0))
        rep.add("NZC6-8c: srednia zmiana dobrobytu ze znakiem", f"najwieksza |srednia| {(days[wm].get('pMean') or 0.0):+.3f}/d (dzien {wm})", "INFO (plus i minus sie znosza - progi wyzej)", None)
    else:
        rep.add("NZC6-8: czlon dobrobytu z Dostatku", f"brak dob z czlonem (stan ostatniej linii: {last.get('state')})",
                "INFO (klucz Prosperity Link wylaczony - domyslnie; test z kluczem wlaczonym przed wlaczeniem w grze)", None)
    # NZC6-9 (recenzja 16.10): dryf krain - wszystkie krainy i rodzaje (takze 1-2 warownie); serie znaku mediany czlonu (brak zbieznosci)
    if pd:
        wd = max(pd, key=lambda d: abs(days[d].get("pDrift") or 0.0))
        dr, ex = days[wd].get("pDrift") or 0.0, days[wd].get("pDriftExp") or 0.0
        nover = int(last.get("pDriftN") or 0)
        explained = abs(dr) > NZC6_PDRIFT and dr * ex > 0 and abs(dr) <= abs(ex) + 0.5
        rep.add("NZC6-9: dryf krain (suma czlonow od kotwicy / dobrobyt bez czlonow)", f"najwiekszy {dr:+.2f}% ({days[wd].get('pDriftKey')}, dzien {wd}); rownowaga z Dostatku tej krainy {ex:+.2f}%; "
                f"krain ponad 5% (ostatnia linia) {nover} z {int(last.get('pLands') or 0)}"
                + ("; dryf idzie za prawdziwa zmiana Dostatku krainy (np. wojna) - do decyzji, czy tak ma byc" if explained else ""),
                f"+-{NZC6_PDRIFT:.0f}% (wiecej, ale w granicy rownowagi z Dostatku - DECYZJA)" + hint, abs(dr) <= NZC6_PDRIFT, decide=explained)
        wr = max(pd, key=lambda d: days[d].get("pRun") or 0)
        rl = int(days[wr].get("pRun") or 0)
        a0, a1 = days[wr].get("pRunA0") or 0.0, days[wr].get("pRunA1") or 0.0
        conv = rl <= NZC6_PRUN or a1 < a0
        rep.add("NZC6-9b: zbieznosc - seria mediany czlonu krainy tego samego znaku", f"najdluzsza {rl} dob ({days[wr].get('pRunKey')}, dzien {wr}; |mediana| na poczatku {a0:.3f} -> {a1:.3f})"
                + ("" if conv else "; mediana nie maleje - brak zbieznosci (D regionow krainy idzie w jedna strone albo petla sie rozbujala)"),
                f"<= {NZC6_PRUN} dob albo |mediana| maleje (inaczej DECYZJA)", True if conv else False, decide=not conv)
    else:
        rep.add("NZC6-9: dryf krain i zbieznosc", "brak dob z czlonem", "INFO (klucz Prosperity Link wylaczony)", None)
    # NZC6-10
    stum, pst = int(sum(vals("stum"))), int(sum(vals("pStum")))
    rep.add("NZC6-10: potkniecia ZC6 i ERROR", f"przeglad {stum}, postfiks dobrobytu {pst}, ERROR (DailyLife, ZcCarry, ZcPayLand) {n_err}", "0 / 0 / 0", stum == 0 and pst == 0 and n_err == 0)
    # INFO
    rep.add("NZC6-11: przejscia od wczytania (ostatnia linia)", f"w gore {last.get('upS')}, w dol {last.get('downS')}, wyzwoleni {last.get('freedS')}, przybysze ze wsi do biedoty {last.get('migS')}; "
            f"ostatnia linia: {last.get('tr', '')[:300]}", "INFO", None)
    rep.add("NZC6-12: pieniadze (suma linii, zl gry)", f"W->R {sum(vals('w2r')):.0f} (oplaty cechowe {sum(vals('fee')):.0f}), R->P {sum(vals('r2p')):.0f}, R->W {sum(vals('r2w')):.0f}, "
            f"P->R {sum(vals('p2r')):.0f}; ziemia: miasta {sum(vals('landT')):.0f} ({sum(vals('landTN')):.0f} kupna), wsie {sum(vals('landV')):.0f} ({sum(vals('landVN')):.0f} kupna); "
            f"odkup od panow: miasta {sum(vals('backT')):.0f}, wsie {sum(vals('backV')):.0f}; netto do panow {sum(vals('landNet')):.0f}; komunikaty gracza o ziemi {sum(vals('landMsg')):.0f}", "INFO", None)
    rep.add("NZC6-13: blokady (suma linii)", f"zapas nieznany {sum(vals('noPurse')):.0f}, bez zywego pana {sum(vals('noLord')):.0f}, brak pieniedzy na ziemie {sum(vals('short')):.0f}, "
            f"oblezenie / najazd {sum(vals('war')):.0f}; przegladow osad {sum(int(days[d]['seen']) for d in dd)}, w rozgrzewce {sum(int(days[d]['warm']) for d in dd)}; "
            f"wywolan postfiksu dobrobytu {sum(vals('pCalls')):.0f}", "INFO (czas bloku - nzc0 NZC0-6; zapis + wczytanie - nzc2 NZC2-4)", None)
    rep.show()
    return 0


# ------------------------------------------------------------ nzc7 (16.10, zycie codzienne ZC7 - wojna i blizna; projekt ZC rozdz. 11, 14)
NZC7_HEAD = "Blizna wojny (ZC7): "
NZC7_START = re.compile(r"Blizna wojny \(ZC7\): start sesji \| klucz Daily Life War Scar (?P<w>tak|WYLACZONE) \(Daily Life Estates (?P<e>tak|WYLACZONE), "
                        r"Daily Life Measure (?P<z>tak|WYLACZONE)\)")
NZC7_DAY = re.compile(r"Blizna wojny \(ZC7\): dzien (?P<day>-?\d+) \| klucz (?P<k>tak|nie) \| od ostatniej linii (?P<dd>\d+) dob \| najazdy: ")
NZC7_SACK = re.compile(r"Blizna wojny \(ZC7\): zlupienie \| dzien (?P<day>-?\d+) \| osada (?P<id>\S+) .*?\| (?P<kind>grabiez|spustoszenie) (?P<share>[\d.]+)% "
                       r"\| kupcy (?P<m0>\d+) -> (?P<m1>\d+) ppm \(-(?P<mp>[\d.]+)%\)(?P<cutm> \[granica pasma\])?, rzemieslnicy (?P<c0>\d+) -> (?P<c1>\d+) ppm "
                       r"\(odeszlo -(?P<cp>[\d.]+)%\)(?P<cutc> \[granica pasma\])?")
NZC7_ERR = ("ERROR in DailyLife.", "ERROR in CitySack.ZcScarPost", "ERROR in Devastation.Strike(ZC7)", "ERROR in TownFolk.ZcCarry")
NZC7_D7 = re.compile(r"(?P<id>\S+) (?P<kind>najazd|grabiez|spustoszenie) od (?P<from>-?\d+) F (?P<f>[\d.]+)% D (?P<d0>[-\d.]+)->(?P<d1>[-\d.]+) \((?P<ch>[-+\d.]+%|-)\)")
NZC7_BACK = re.compile(r"(?P<id>\S+) (?P<kind>najazd|grabiez|spustoszenie) od (?P<from>-?\d+) \(wiek (?P<age>\d+), spokoj (?P<quiet>\d+)\) D (?P<d0>[-\d.]+)/(?P<dmin>[-\d.]+)/(?P<d1>[-\d.]+) "
                       r"powrot (?P<rec>[-\d.]+)%")
NZC7_FIELDS = (
    ("raidV", r"\| najazdy: wsi (\d+) \("), ("strikes", r"\(uderzen (\d+)\), trafieni"), ("struck", r"\), trafieni (\d+) \(zabici"), ("dead", r"\(zabici (\d+)\), udzial"),
    ("fMed", r"z ludzi w domu: mediana ([-\d.]+)%"), ("fMax", r"%, max ([-\d.]+)%; rzemieslnicy wsi"), ("craftV", r"rzemieslnicy wsi -> chlopi (\d+) ludzi"),
    ("cut", r"ucieta trafionym: wsi (\d+);"), ("noBook", r"; bez ksiegi stanow (\d+) \|"),
    ("sack", r"\| zlupienia: miast (\d+) \("), ("sackPill", r"\(grabiez (\d+), spustoszenie"), ("sackDev", r", spustoszenie (\d+)\), pominiete"),
    ("mercy", r"pominiete: laska (\d+)"), ("castle", r", zamki (\d+), bez zdobycia"), ("noCap", r", bez zdobycia (\d+), bez ksiegi"), ("sackNoBook", r", bez ksiegi (\d+), klucz wylaczony"),
    ("sackM", r"; kupcy -> rzemieslnicy (\d+) ludzi"), ("sackC", r", rzemieslnicy -> biedota (\d+) ludzi"), ("p2r", r"pieniadze z ludzmi P->R (\d+)"), ("r2w", r", R->W (\d+), kiesa nieczynna"),
    ("noPurse", r"kiesa nieczynna (\d+) \|"), ("bandCut", r"\| granice pasm: ciecia (\d+)"),
    ("ruinT", r"spadki x4\): miast teraz (\d+)"), ("ruinDown", r"spadki w oknie (\d+) ludzi"),
    ("backV", r"chlopi->rzemieslnicy wsi (\d+)"), ("backC", r", biedota->rzemieslnicy (\d+), rzemieslnicy->kupcy"), ("backM", r", rzemieslnicy->kupcy (\d+); pieniadze W->R"),
    ("bw2r", r"; pieniadze W->R (\d+), R->P"), ("br2p", r", R->P (\d+); bez Dostatku"), ("backNoD", r"bez Dostatku do powrotu (\d+)"),
    ("debtV", r"\| dlug blizny: wsie (\d+) \("), ("debtVp", r"\| dlug blizny: wsie \d+ \((\d+) ludzi\)"), ("debtT", r", miasta (\d+) \(kupcy"),
    ("debtTm", r"\(kupcy (\d+), rzemieslnicy \d+\) \|"), ("debtTc", r"\(kupcy \d+, rzemieslnicy (\d+)\) \|"),
    ("awayV", r"\| uchodzcy w mianowniku Dostatku: wsi (\d+), ludzie"), ("awayP", r"Dostatku: wsi \d+, ludzie (\d+) \("), ("awayPct", r"ludzie \d+ \(([-\d.]+)% ludzi tych wsi"),
    ("epi", r"\| epizody wojny w ksiedze (\d+) \("), ("epiNew", r"nowe od ostatniej linii (\d+)\)"), ("ctl", r"\| kontrola kies roznica (\d+) \|"),
    ("saveFlush", r"\| rozliczenie przy zapisie (\d+) \|"), ("msg", r"\| komunikaty gracza (\d+) \|"), ("stum", r"\| potkniecia (\d+)\.$"),
    ("offN", r"\| dlug odpisany: ponizej progu (\d+) \("), ("offP", r"ponizej progu \d+ \((\d+) ludzi\)"), ("forgetN", r"po 2 latach spokoju (\d+) osad"),
    ("holdV", r"liczniki spadku wsi stoja \d+ dob: przegladow (\d+)\)"), ("sackLate", r"zlupienia przed pierwszym switem po wczytaniu (\d+)"),
)
NZC7_DROP = (30.0, 60.0)    # projekt rozdz. 14 ZC7: po najezdzie D okregu -30-60% w 7 dob
NZC7_FBIG = 20.0            # zdarzenie na skale okregu: trafieni >= 20% ludzi w domu (spadek D idzie za udzialem trafionych)
NZC7_SACKP = (10.0, 20.0)   # po zlupieniu: kupcy -10-20% w miescie (grabiez 10%, spustoszenie 20%)


def nzc7_parse(s):
    """Linia 'Blizna wojny (ZC7): dzien N' -> slownik (None przy nierozpoznanej glowie): pola, zdarzenia d+7 i powrot epizodow."""
    m = NZC7_DAY.match(s)
    if not m:
        return None
    d = m.groupdict()
    for k, pat in NZC7_FIELDS:
        mm = re.search(pat, s)
        v = None
        if mm:
            try:
                v = float(mm.group(1))
            except ValueError:
                v = None
        d[k] = v
    d7, back = [], []
    if "| zdarzenia d+7 (D przed -> teraz): " in s:
        part = s.split("| zdarzenia d+7 (D przed -> teraz): ", 1)[1].split(" | ", 1)[0]
        lst = part.split("]: ", 1)[1] if "]: " in part else ""
        for e in lst.split("; "):
            mm = NZC7_D7.match(e.strip())
            if mm:
                d7.append(mm.groupdict())
    if "| powrot (>= 60 dob od poczatku" in s:
        part = s.split("| powrot (>= 60 dob od poczatku", 1)[1].split(" | ", 1)[0]
        lst = part.split("): ", 1)[1] if "): " in part else ""
        lst = lst.split(": ", 1)[1] if ": " in lst else ""
        for e in lst.split("; "):
            mm = NZC7_BACK.match(e.strip())
            if mm:
                back.append(mm.groupdict())
    d["d7"], d["back"] = d7, back
    return d


def nzc7_main(logp, bdp=None, until=120):
    """nzc7 (16.10; Armoury/src/DailyLife.War.cs, CitySack.People.cs ZcScarPost, Devastation.Hit -> NoteStrike, klucz DailyLifeWarScar): ZC7 - wojna i blizna.
    Progi projektu rozdz. 14 (ZC7) i wspolne: NZC7-0 linia startu sesji (klucz tak z Estates i Measure), NZC7-1 linia 'Blizna wojny (ZC7): dzien N' w kazdej dobie
    z linia 'Zycie (ZC0)' (nierozpoznane 0), NZC7-2 po zlupieniu kupcy -10-20% w miescie (linie zdarzenia; granica pasma - DECYZJA), NZC7-3 po najezdzie D okregu
    -30-60% w 7 dob (epizody z trafionymi >= 20% ludzi w domu; same male najazdy - DECYZJA: spadek idzie za udzialem trafionych), NZC7-4 >= 50% powrotu w rok
    bez wojny (epizody ze spokojem >= 364 dob; krotszy bieg - INFO z powrotem czesciowym), NZC7-5 obieg zamkniety (kontrola kies 0 w kazdej linii), NZC7-6 potkniecia
    i ERROR 0, NZC7-7..12 INFO (najazdy, zlupienia i okno ruiny, powrot blizny i dlug, uchodzcy w mianowniku, komunikaty gracza, zapis v3). Granice pasm - grupa nzc6
    (NZC6-6), zapis + wczytanie - grupa nzc2 (NZC2-4), czas bloku - grupa nzc0 (NZC0-6). Log bez paczki: INFO, bez wyjatku."""
    rep = Report()
    if not logp or not os.path.isfile(logp):
        rep.add("NZC7-0: log Armoury", f"brak pliku {logp}", "podaj <Armoury-*.log>", None)
        rep.show()
        return 0
    sess, days, bad, sacks, zc0, loads = [], {}, [], [], set(), []
    n_err = 0
    with open(logp, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\n"))
            s = m.group(2) if m else ln.rstrip("\n")
            if s.startswith(NZC7_HEAD):
                if s.startswith(NZC7_HEAD + "start sesji"):
                    sess.append(s)
                elif s.startswith(NZC7_HEAD + "zlupienie"):
                    mm = NZC7_SACK.match(s)
                    if mm:
                        sacks.append(mm.groupdict())
                    else:
                        bad.append(s)
                elif s.startswith(NZC7_HEAD + "dzien "):
                    d = nzc7_parse(s)
                    if d is None:
                        bad.append(s)
                    else:
                        days[int(d["day"])] = d
                else:
                    bad.append(s)
            elif s.startswith("Zycie (ZC0): dzien "):
                mm = re.match(r"Zycie \(ZC0\): dzien (-?\d+) \|", s)
                if mm:
                    zc0.add(int(mm.group(1)))
            elif s.startswith("Stany (ZC2): wczytanie | format "):
                loads.append(s[len("Stany (ZC2): wczytanie | format "):][:2])
            elif s.startswith(NZC7_ERR):
                n_err += 1
    print(f"plik: {logp} | linii startu sesji {len(sess)}, doby Blizna {len(days)} (nierozpoznanych {len(bad)}), zlupien {len(sacks)}, doby Zycie (ZC0) {len(zc0)}")
    if not sess and not days and not bad and not sacks:
        rep.add("NZC7-0: linie 'Blizna wojny (ZC7)'", "brak w logu", "INFO (log sprzed paczki ZC7)", None)
        rep.show()
        return 0
    if sess:
        mm = NZC7_START.match(sess[-1])
        ok = bool(mm) and all(mm.group(k) == "tak" for k in ("w", "e", "z"))
        rep.add("NZC7-0: linia startu sesji (klucz ZC7)", sess[-1][len(NZC7_HEAD):][:300], "Daily Life War Scar tak (z Estates i Measure)", True if ok else (None if mm else False))
    else:
        rep.add("NZC7-0: linia startu sesji", "brak", "linia przy kazdym starcie sesji", False)
    dd = sorted(days)
    if not dd:
        rep.add("NZC7-1: linie 'Blizna wojny (ZC7): dzien N'", f"brak rozpoznanych linii doby (nierozpoznane {len(bad)})" + (f": {bad[0][:220]}" if bad else ""), "linia kazdej doby", False)
        rep.show()
        return 0
    zd = sorted(d for d in zc0 if dd[0] <= d <= dd[-1])
    miss = [d for d in zd if d not in days]
    span = dd[-1] - dd[0] + 1
    rep.add("NZC7-1: linia 'Blizna wojny (ZC7)' w kazdej dobie z linia 'Zycie (ZC0)'", f"doby Blizna {len(dd)} (dzien {dd[0]}-{dd[-1]}), doby Zycie bez Blizna {len(miss)}"
            + (f" (np. {miss[:5]})" if miss else "") + f", nierozpoznane {len(bad)}" + (f" (np. {bad[0][:200]})" if bad else "")
            + (f"; dob w logu mniej niz {until} (bieg krotszy)" if span < until else ""), "0 dob bez linii, nierozpoznane 0", not miss and not bad)
    last = days[dd[-1]]

    def vals(k):
        return [days[d][k] for d in dd if days[d].get(k) is not None]
    # NZC7-2: zlupienia - kupcy -10-20%
    if sacks:
        mp = [float(x["mp"]) for x in sacks]
        cut = [x for x in sacks if x.get("cutm")]
        lo, hi = NZC7_SACKP
        outs = [x for x in sacks if not x.get("cutm") and not (lo - 0.05 <= float(x["mp"]) <= hi + 0.05)]
        rep.add("NZC7-2: po zlupieniu kupcy w miescie (linie zdarzenia)", f"zlupien {len(sacks)} (grabiez {sum(1 for x in sacks if x['kind'] == 'grabiez')}, spustoszenie "
                f"{sum(1 for x in sacks if x['kind'] == 'spustoszenie')}): kupcy -{min(mp):.2f}% .. -{max(mp):.2f}%, rzemieslnicy odeszlo -{min(float(x['cp']) for x in sacks):.2f}% .. "
                f"-{max(float(x['cp']) for x in sacks):.2f}%; ciete granica pasma {len(cut)}" + (f"; poza progiem: {', '.join(x['id'] + ' ' + x['mp'] + '%' for x in outs[:5])}" if outs else ""),
                f"-{lo:.0f}..-{hi:.0f}% (granica pasma - do decyzji)", not outs and not cut, decide=bool(cut) and not outs)
    else:
        rep.add("NZC7-2: po zlupieniu kupcy w miescie", f"brak zlupien zdobytych miast w biegu (pominiete w liniach: laska {sum(vals('mercy')):.0f}, zamki {sum(vals('castle')):.0f}, "
                f"bez zdobycia {sum(vals('noCap')):.0f})", f"INFO (-{NZC7_SACKP[0]:.0f}..-{NZC7_SACKP[1]:.0f}% przy zlupieniu)", None)
    # NZC7-3: najazdy - D okregu -30-60% w 7 dob (epizody na skale okregu)
    ev = {}
    for d in dd:
        for e in days[d]["d7"]:
            ev[(e["id"], e["from"])] = e
    raids = [e for e in ev.values() if e["kind"] == "najazd"]

    def drop(e):
        try:
            return -float(e["ch"].rstrip("%")) if e["ch"] != "-" else None
        except ValueError:
            return None
    big = [e for e in raids if float(e["f"]) >= NZC7_FBIG and drop(e) is not None]
    allr = [e for e in raids if drop(e) is not None]
    if big:
        mdrop = st.median(drop(e) for e in big)
        rep.add("NZC7-3: po najezdzie Dostatek okregu w 7 dob (trafieni >= 20% ludzi w domu)", f"epizodow {len(big)}: mediana spadku {mdrop:.1f}% (mediana F {st.median(float(e['f']) for e in big):.1f}%); "
                f"wszystkie najazdy d+7: {len(allr)}" + (f", mediana spadku {st.median(drop(e) for e in allr):.1f}%" if allr else ""),
                f"-{NZC7_DROP[0]:.0f}..-{NZC7_DROP[1]:.0f}%", NZC7_DROP[0] <= mdrop <= NZC7_DROP[1])
    elif allr:
        mf = st.median(float(e["f"]) for e in allr)
        md = st.median(drop(e) for e in allr)
        ratio = [drop(e) / float(e["f"]) for e in allr if float(e["f"]) > 0.05]
        rep.add("NZC7-3: po najezdzie Dostatek okregu w 7 dob", f"najazdow d+7 {len(allr)}, zaden na skale okregu (F >= {NZC7_FBIG:.0f}%): mediana F {mf:.2f}%, mediana spadku D {md:.2f}%"
                + (f", spadek / F mediana {st.median(ratio):.2f}" if ratio else "") + " - najazd AI trafia czesc okregu (osada po osadzie), Dostatek spada o udzial trafionych; "
                "prog projektu (-30-60%) dla najazdu na caly okreg - do decyzji", f"-{NZC7_DROP[0]:.0f}..-{NZC7_DROP[1]:.0f}%", False, decide=True)
    else:
        rep.add("NZC7-3: po najezdzie Dostatek okregu w 7 dob", f"brak epizodow najazdu z wiekiem 7-13 dob w liniach (najazdow wsi w liniach {sum(vals('raidV')):.0f})",
                f"INFO (-{NZC7_DROP[0]:.0f}..-{NZC7_DROP[1]:.0f}%)", None)
    # NZC7-4: powrot >= 50% w rok bez wojny
    bk = {}
    for d in dd:
        for e in days[d]["back"]:
            bk[(e["id"], e["from"])] = e
    year = [e for e in bk.values() if int(e["quiet"]) >= 364]
    if year:
        okn = [e for e in year if float(e["rec"]) >= 50.0]
        rep.add("NZC7-4: powrot Dostatku w rok bez wojny", f"epizodow ze spokojem >= 364 dob {len(year)}: z powrotem >= 50% {len(okn)} (mediana {st.median(float(e['rec']) for e in year):.1f}%)",
                ">= 50% (kazdy)", len(okn) == len(year))
    elif bk:
        rep.add("NZC7-4: powrot Dostatku w rok bez wojny", f"bieg krotszy niz rok spokoju - epizodow >= 60 dob ze spokojem >= 30 dob {len(bk)}: powrot mediana "
                f"{st.median(float(e['rec']) for e in bk.values()):.1f}% (najdluzszy spokoj {max(int(e['quiet']) for e in bk.values())} dob)", "INFO (>= 50% po roku spokoju)", None)
    else:
        rep.add("NZC7-4: powrot Dostatku w rok bez wojny", "brak epizodow >= 60 dob ze spokojem w liniach", "INFO (>= 50% po roku spokoju)", None)
    # NZC7-5: obieg zamkniety
    badc = [d for d in dd if (days[d].get("ctl") or 0) != 0]
    rep.add("NZC7-5: obieg zamkniety (oszczednosci z ludzmi miedzy kiesami miasta)", f"P->R {sum(vals('p2r')):.0f}, R->W {sum(vals('r2w')):.0f}, powrot W->R {sum(vals('bw2r')):.0f}, "
            f"R->P {sum(vals('br2p')):.0f} zl gry; dob z roznica kontroli {len(badc)}" + (f" (np. dzien {badc[0]})" if badc else ""), "roznica 0 w kazdej linii", not badc)
    # NZC7-6: potkniecia i ERROR
    stum = int(sum(vals("stum")))
    rep.add("NZC7-6: potkniecia ZC7 i ERROR", f"potkniecia linii {stum}, ERROR (DailyLife, ZcScarPost, Strike ZC7, ZcCarry) {n_err}", "0 / 0", stum == 0 and n_err == 0)
    # INFO
    rep.add("NZC7-7: najazdy (suma linii)", f"wsi {sum(vals('raidV')):.0f} (uderzen {sum(vals('strikes')):.0f}), trafieni {sum(vals('struck')):.0f} (zabici {sum(vals('dead')):.0f}), "
            f"F max {max(vals('fMax') or [0]):.2f}%, rzemieslnicy wsi -> chlopi {sum(vals('craftV')):.0f}, bez ksiegi stanow {sum(vals('noBook')):.0f}, ciecia granica pasma {sum(vals('bandCut')):.0f}",
            "INFO", None)
    rep.add("NZC7-8: zlupienia i okno ruiny (suma linii)", f"miast {sum(vals('sack')):.0f} (grabiez {sum(vals('sackPill')):.0f}, spustoszenie {sum(vals('sackDev')):.0f}), kupcy -> rzemieslnicy "
            f"{sum(vals('sackM')):.0f}, rzemieslnicy -> biedota {sum(vals('sackC')):.0f}; spadki ZC6 w oknie ruiny (x4) {sum(vals('ruinDown')):.0f} ludzi; kiesa nieczynna {sum(vals('noPurse')):.0f}",
            "INFO", None)
    rep.add("NZC7-9: powrot blizny i dlug (ostatnia linia)", f"powrot (suma): wsie {sum(vals('backV')):.0f}, biedota->rzemieslnicy {sum(vals('backC')):.0f}, rzemieslnicy->kupcy {sum(vals('backM')):.0f}, "
            f"bez Dostatku do powrotu {sum(vals('backNoD')):.0f}; dlug: wsie {last.get('debtV')} ({last.get('debtVp')} ludzi), miasta {last.get('debtT')} (kupcy {last.get('debtTm')}, "
            f"rzemieslnicy {last.get('debtTc')}); epizodow w ksiedze {last.get('epi')}", "INFO (25%/rok po 30 dobach spokoju)", None)
    rep.add("NZC7-10: uchodzcy w mianowniku Dostatku (ostatnia linia)", f"wsi {last.get('awayV')}, ludzie {last.get('awayP')} ({last.get('awayPct')}% ludzi tych wsi w domu)",
            "INFO (okreg biedniejszy o udzial ludzi w ucieczce)", None)
    rep.add("NZC7-11: komunikaty gracza (suma linii)", f"{sum(vals('msg')):.0f}", "INFO (najazd na wies rodu gracza / najazd gracza, zlupienie z udzialem gracza)", None)
    rep.add("NZC7-12: zapis arm_estates v4", f"wczytania: {', '.join(loads) if loads else 'brak'}; rozliczenia uderzen przy zapisie {sum(vals('saveFlush')):.0f}; "
            f"dlug odpisany ponizej progu {sum(vals('offN')):.0f} ({sum(vals('offP')):.0f} ludzi), po 2 latach spokoju {sum(vals('forgetN')):.0f} osad; "
            f"liczniki spadku wsi wstrzymane po wlaczeniu ZC7 (przegladow) {sum(vals('holdV')):.0f}; zlupienia przed pierwszym switem po wczytaniu {sum(vals('sackLate')):.0f}",
            "INFO (wczytanie v1/v2/v3/v4; zapis + wczytanie - nzc2 NZC2-4, rozmiar - NZC2-5)", None)
    rep.show()
    return 0


# ------------------------------------------------------------ nniewola (18.10, paczka f8-niewola - decyzja Jeffa "6 tak": niewola za dlugi tylko w kulturach z niewola,
# 1%/rok przy Dostatku < 0.8 bez zapasu; Armoury/src/DailyLife.Debt.cs, DailyLife.Mobility.cs przejscie TDebtSl, klucz Debt Slavery)
NNW_HEAD = "Niewola za dlugi (f8): "
NNW_CULT = ("ghiscari", "lyseni", "myrish", "norvos", "qartheen", "qohorik", "tyroshi", "valyrian", "volantine")
NNW_START = re.compile(r"Niewola za dlugi \(f8\): start sesji \| klucz Debt Slavery (?P<k>tak|WYLACZONE) \(Daily Life Estates (?P<e>tak|WYLACZONE), "
                       r"Daily Life Measure (?P<z>tak|WYLACZONE)(?:, Daily Life Mobility (?P<mo>tak|WYLACZONE))?\).*?\| kultury: (?P<cul>[a-z, ]+?) \(")
NNW_DAY = re.compile(r"Niewola za dlugi \(f8\): dzien (?P<day>-?\d+) \| klucz (?P<k>tak|nie) \| od ostatniej linii (?P<dd>\d+) dob: przegladow osad kultur z niewola (?P<seen>\d+) "
                     r"\(biednych (?P<poor>\d+); pominiete: bez KS (?P<noks>\d+), wladca bez niewoli (?P<fr>\d+), D >= [\d.]+ (?P<rich>\d+), zapas >= [\d.]+ dni (?P<sav>\d+), "
                     r"zapas nieznany (?P<nop>\d+), D nieznane (?P<nod>\d+), bez ludzi stanu (?P<empty>\d+)\) \| do niewoli (?P<mv>-?\d+|-) ludzi \(wsie chlopi (?P<v>-?\d+|-), "
                     r"miasta biedota (?P<t>-?\d+|-)\) w (?P<moves>\d+) przegladach, granice pasm / limit ciecia (?P<band>\d+), najwiekszy ruch (?P<max>[-\d.]+|-)% \(")
NNW_FIELDS = (
    ("cul", r"\| wedlug kultur: (.*?) \| od wczytania", str),
    ("daysS", r"\| od wczytania \((\d+) dob\): do niewoli", int),
    ("mvS", r"dob\): do niewoli (-?\d+|-) \(wsie", float),
    ("vS", r"dob\): do niewoli (?:-?\d+|-) \(wsie (-?\d+|-), miasta", float),
    ("tS", r"\(wsie (?:-?\d+|-), miasta (-?\d+|-)\), biedni w przegladach", float),
    ("poorS", r"biedni w przegladach (-?\d+|-), tempo", float),
    ("rate", r"tempo ([-\d.]+|-)% na rok", float),
    ("freeS", r"wolni stanu zrodlowego w przegladach (-?\d+|-) \(na rok", float),
    ("freeRate", r"\(na rok ([-\d.]+|-)% wolnych\)", float),
    ("culS", r"\| wedlug kultur od wczytania: (.*?) \| ludzie", str),
    ("out", r"ludzie \(ksiega stanow\): z wolnych -([-\d.]+), do niewolnych", float),
    ("inn", r"ludzie \(ksiega stanow\): z wolnych -[-\d.]+, do niewolnych \+([-\d.]+), roznica", float),
    ("pdiff", r"do niewolnych \+[-\d.]+, roznica ([-\d.]+); od wczytania", float),
    ("outS", r"; od wczytania z wolnych -([-\d.]+), do niewolnych", float),
    ("inS", r"; od wczytania z wolnych -[-\d.]+, do niewolnych \+([-\d.]+)", float),
    ("pdiffS", r"; od wczytania z wolnych -[-\d.]+, do niewolnych \+[-\d.]+, roznica ([-\d.]+);", float),
    ("sumBad", r"osad z suma udzialow != 1000000 (\d+)", int),
    ("badCul", r"ruchy poza kulturami z niewola (\d+)", int),
    ("W", r"pieniadze \(zl gry\): kiesa W -(-?\d+)", int),
    ("R", r", wierzyciele R \+(-?\d+)", int),
    ("P", r", wierzyciele R \+-?\d+, P \+(-?\d+)", int),
    ("mdiff", r", P \+-?\d+, roznica (-?\d+), kontrola kies", int),
    ("ctl", r"kontrola kies ludu (-?\d+);", int),
    ("WS", r"; od wczytania W -(-?\d+)", int),
    ("RS", r"; od wczytania W -\d+, R \+(-?\d+)", int),
    ("PS", r"; od wczytania W -\d+, R \+\d+, P \+(-?\d+)", int),
    ("ctlS", r", kontrola (-?\d+) \(wsie", int),
    ("ms", r"\| czas ([-\d.]+|-) ms", float),
    ("msd", r" ms \(([-\d.]+|-) ms/dobe\)", float),
    ("stum", r"\| potkniecia (\d+) \(sesja", int),
    ("stumS", r"\(sesja (\d+)\)\.\s*$", int),
)
NNW_ZC6 = re.compile(r"Awans \(ZC6\): dzien (-?\d+) \|.*?niewola za dlugi \(biedni wolni->niewolni\) (-?\d+|-)(?:,| \| w gore )")
NNW_ZC6DAY = re.compile(r"Awans \(ZC6\): dzien (-?\d+) \|")
NNW_ERR = ("ERROR in DailyLife.NiewolaZaDlugi", "ERROR in DailyLife.DebtSl")
NNW_RATE_TOL = 1.25        # tempo od wczytania <= 1%/rok x 1.25 (ulamek milionowej w malych osadach; limit 0.2%/tydz. i granice pasm tylko obnizaja)
NNW_RATE_MINPOOR = 50000   # biednych w przegladach (ludzie x przeglady) - ponizej tempo INFO (za malo prob)
NNW_MS_DAY = 2.0           # ms na dobe kodu paczki (przeplyw w przegladzie + przelew kiesy) - najwyzej w kazdej linii
NNW_MOVE_CAP = 0.2 + 0.001 # % ludzi osady na przeglad (limit ZC6 0.2%/tydz. + ulamek milionowej)
NNW_GAME_LOGS = r"C:\Program Files (x86)\Steam\steamapps\common\Mount & Blade II Bannerlord\Modules\Armoury\Logs"


def _nnw_val(x, cast):
    if x is None:
        return None
    if cast is str:
        return x
    if x == "-":
        return None
    try:
        return cast(x)
    except ValueError:
        return None


def _nnw_cul(txt):
    """'ghiscari 12, volantine 3' -> {kultura: ludzie}; '-' -> {}."""
    out = {}
    if not txt or txt.strip() == "-":
        return out
    for part in txt.split(","):
        bits = part.strip().rsplit(" ", 1)
        if len(bits) != 2:
            out[part.strip()] = None
            continue
        try:
            out[bits[0]] = float(bits[1]) if bits[1] != "-" else None
        except ValueError:
            out[bits[0]] = None
    return out


def _nnw_csv_path(logp, csvp):
    """stany-dostatek.csv biegu: --csv (plik albo katalog obok), uklad archiwum / gry (nzc0_csv_path), katalog Logs gry."""
    if csvp:
        if os.path.basename(csvp).lower() == "stany-dostatek.csv" and os.path.isfile(csvp):
            return csvp
        q = os.path.join(os.path.dirname(csvp), "stany-dostatek.csv")
        if os.path.isfile(q):
            return q
    p = nzc0_csv_path(logp)
    if p:
        return p
    stem = os.path.splitext(os.path.basename(logp))[0].replace("Armoury-", "")
    q = os.path.join(NNW_GAME_LOGS, stem, "stany-dostatek.csv")
    return q if os.path.isfile(q) else None


def _nnw_csv(path):
    """Udzial niewolnych ksiegi stanow (niewolni - konto NIEWOLNI ksiegi) / ludzie ksiegi: pierwsza i ostatnia doba pliku na osade (miasta i wsie)."""
    first, last, days = {}, {}, set()
    with open(path, encoding="utf-8", errors="replace", newline="") as fh:
        for r in csv.DictReader(fh, delimiter=";"):
            try:
                d = int(r["dzien"]); L = float(r["ludzie_ksiega"]); s = float(r["niewolni"]) - float(r.get("konto_niewolnych") or 0)
            except (KeyError, TypeError, ValueError):
                continue
            if r.get("rodzaj") == "zamek" or L <= 0:
                continue
            days.add(d)
            k = r.get("osada_id") or "?"
            rec = (d, s / L, L, r.get("kultura") or "?", r.get("osada") or k, s)
            if k not in first or d < first[k][0]:
                first[k] = rec
            if k not in last or d > last[k][0]:
                last[k] = rec
    return first, last, sorted(days)


def nniewola_main(logp, csvp=None):
    """nniewola (18.10, paczka f8-niewola): niewola za dlugi (DailyLife.Debt.cs, klucz Debt Slavery) - linie 'Niewola za dlugi (f8)', krzyzowo z linia 'Awans (ZC6)'
    i stany-dostatek.csv (obok logu, w ukladzie gry albo --csv). Progi NNW-0..NNW-12 - opis w naglowku pliku (--grupa nniewola). Log bez paczki: INFO, bez wyjatku."""
    rep = Report()
    if not logp or not os.path.isfile(logp):
        rep.add("NNW-0: log Armoury", f"brak pliku {logp}", "podaj <Armoury-*.log>", None)
        rep.show()
        return 0
    starts, days, bad, zc6, zc6days, errs = [], {}, [], {}, set(), []
    with open(logp, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\r\n"))
            s = m.group(2) if m else ln.rstrip("\r\n")
            if s.startswith("ERROR in ") and any(s.startswith(e) for e in NNW_ERR):
                errs.append(s[:200])
                continue
            if s.startswith("Awans (ZC6): dzien "):
                md = NNW_ZC6DAY.match(s)
                if md:
                    zc6days.add(int(md.group(1)))
                mz = NNW_ZC6.match(s)
                if mz:
                    zc6[int(mz.group(1))] = None if mz.group(2) == "-" else float(mz.group(2))
                continue
            if not s.startswith(NNW_HEAD):
                continue
            if s.startswith(NNW_HEAD + "start sesji"):
                ms_ = NNW_START.match(s)
                starts.append(ms_.groupdict() if ms_ else {"k": "?", "e": "?", "z": "?", "mo": "?", "cul": ""})
                continue
            md = NNW_DAY.match(s)
            if not md:
                bad.append(s[:220])
                continue
            d = {k: (v if k == "k" else _nnw_val(v, float)) for k, v in md.groupdict().items()}
            for k, pat, cast in NNW_FIELDS:
                mm = re.search(pat, s)
                d[k] = _nnw_val(mm.group(1), cast) if mm else None
            days[int(d["day"])] = d
    dd = sorted(days)
    # klucz czynny: Debt Slavery, Estates i Measure tak, a Daily Life Mobility tak albo linia sprzed recenzji (bez tego pola) - DebtSlOn wymaga ruchu ZC6
    keyon = [x for x in starts if x.get("k") == "tak" and x.get("e") in ("tak", "?") and x.get("z") in ("tak", "?") and x.get("mo") in (None, "tak", "?")]
    print(f"plik: {logp} | linii startu {len(starts)} (klucz tak {len(keyon)}) | linii doby {len(dd)}" + (f" (dzien {dd[0]}-{dd[-1]})" if dd else "")
          + f" | nieczytelnych {len(bad)} | linii Awans (ZC6) {len(zc6days)} (z wpisem niewoli {len(zc6)}) | ERROR paczki {len(errs)}")
    # ---- NNW-0 start sesji: klucz i lista kultur
    if starts:
        cul_bad = [x.get("cul") for x in starts if tuple(sorted(c.strip() for c in (x.get("cul") or "").split(",") if c.strip())) != NNW_CULT]
        rep.add("NNW-0: start sesji (klucz Debt Slavery, kultury z niewola znajace pieniadz)",
                f"linii {len(starts)}, klucz: {', '.join(sorted(set(x.get('k', '?') for x in starts)))} (Daily Life Mobility: {', '.join(sorted(set(x.get('mo') or '-' for x in starts)))}); lista kultur inna niz {len(NNW_CULT)} oczekiwanych w {len(cul_bad)}"
                + (f" (np. '{cul_bad[0]}')" if cul_bad else ""), f"lista = {', '.join(NNW_CULT)} (bez sturgia i khuzait)", len(cul_bad) == 0)
    else:
        rep.add("NNW-0: start sesji (klucz Debt Slavery)", "brak linii startu", "INFO (log sprzed paczki f8-niewola)", None)
    if bad:
        rep.add("NNW-0b: linie 'Niewola za dlugi (f8): dzien N' nieczytelne", f"{len(bad)} (np. {bad[0][:160]})", "0", False)
    if not dd:
        why = "klucz wylaczony - linii doby nie ma" if starts and not keyon else "log sprzed paczki albo bez dob z linia ZC"
        rep.add("NNW-1..9: linie doby niewoli za dlugi", f"brak linii doby ({why})", "INFO", None)
    else:
        # ---- NNW-1 linia w kazdej dobie z linia ZC6 (przy kluczu)
        miss = [x for x in sorted(zc6days) if x not in days and x >= dd[0]]
        rep.add("NNW-1: linia 'Niewola za dlugi (f8)' w kazdej dobie z linia 'Awans (ZC6)' (od pierwszej linii paczki)",
                f"linii {len(dd)}, doby ZC6 bez linii f8 {len(miss)}" + (f" (np. {miss[:5]})" if miss else ""), "0", len(miss) == 0)
        # ---- NNW-2 tylko kultury z niewola
        badc = sum((days[x]["badCul"] or 0) for x in dd)
        foreign = sorted({c for x in dd for c in list(_nnw_cul(days[x].get("cul")).keys()) + list(_nnw_cul(days[x].get("culS")).keys()) if c not in NNW_CULT})
        rep.add("NNW-2: ruchy tylko w kulturach z niewola (Westeros, Zelazne Wyspy, Dothrakowie i kultury bez niewoli nietkniete)",
                f"ruchy poza kulturami z niewola (suma linii) {badc}; kultury w liniach spoza listy: {', '.join(foreign) if foreign else '-'}",
                "0 / brak", badc == 0 and not foreign)
        # ---- NNW-3 tozsamosc ludzi
        b3 = []
        for x in dd:
            r = days[x]
            cs = _nnw_cul(r.get("cul"))
            csum = sum(v for v in cs.values() if v is not None)
            ok = r["pdiff"] is not None and abs(r["pdiff"]) <= 0.15 and (r["sumBad"] or 0) == 0
            if r["mv"] is not None:
                ok = ok and abs(csum - r["mv"]) <= 0.5 * max(1, len(cs)) + 1 and r["v"] is not None and r["t"] is not None and abs(r["v"] + r["t"] - r["mv"]) <= 1.5
            if not ok:
                b3.append(x)
        lastr = days[dd[-1]]
        rep.add("NNW-3: tozsamosc ludzi (z wolnych = do niewolnych, suma udzialow osady = 1 000 000, kultury = razem, wsie + miasta = razem)",
                f"niezgodne {len(b3)} z {len(dd)} linii" + (f" (doby {b3[:5]})" if b3 else "") + f"; od wczytania z wolnych -{lastr.get('outS')}, do niewolnych +{lastr.get('inS')}, "
                f"roznica {lastr.get('pdiffS')}", "0 (roznica <= 0.15 czlowieka - zaokraglenie linii)", len(b3) == 0 and lastr.get("pdiffS") is not None and abs(lastr["pdiffS"]) <= 0.15)
        # ---- NNW-4 tempo 1%/rok biednych
        rate, poorS, mvS = lastr.get("rate"), lastr.get("poorS"), lastr.get("mvS")
        if not poorS:
            rep.add("NNW-4: tempo niewoli za dlugi <= 1%/rok biednych (od wczytania)", f"biednych w przegladach 0, do niewoli {mvS}",
                    "INFO (brak biednych z D < 0.8 bez zapasu w kulturach z niewola pod KS - regula spi)", None)
        elif poorS < NNW_RATE_MINPOOR:
            rep.add("NNW-4: tempo niewoli za dlugi <= 1%/rok biednych (od wczytania)", f"tempo {rate}% na rok, biednych w przegladach {poorS:.0f}, do niewoli {mvS}",
                    f"INFO (mniej niz {NNW_RATE_MINPOOR} ludzio-przegladow - za malo prob)", None)
        else:
            rep.add("NNW-4: tempo niewoli za dlugi <= 1%/rok biednych (od wczytania)", f"tempo {rate}% na rok, biednych w przegladach {poorS:.0f}, do niewoli {mvS}",
                    f"<= {NNW_RATE_TOL:.2f}% (cel 1%; limit 0.2%/tydz. i pasma tylko obnizaja)", rate is not None and rate <= NNW_RATE_TOL)
        # ---- NNW-5 pieniadze: kiesa W = R + P, kontrola kies 0
        b5 = [x for x in dd if days[x]["mdiff"] is None or days[x]["mdiff"] != 0 or (days[x]["ctl"] or 0) != 0]
        WS, RS, PS = lastr.get("WS") or 0, lastr.get("RS") or 0, lastr.get("PS") or 0
        rep.add("NNW-5: pieniadze zamkniete (kiesa W -x = wierzyciele R + P, suma kies ludu miasta bez zmian)",
                f"niezgodne {len(b5)} z {len(dd)} linii" + (f" (doby {b5[:5]})" if b5 else "") + f"; od wczytania W -{WS}, R +{RS}, P +{PS}, kontrola {lastr.get('ctlS')}"
                + (f"; udzial R {100.0 * RS / (RS + PS):.1f}%" if RS + PS > 0 else ""), "0 (co do zlotowki; wsie - kiesa wspolna, bez przelewu)",
                len(b5) == 0 and WS == RS + PS and (lastr.get("ctlS") or 0) == 0)
        # ---- NNW-6 limit ruchu w osadzie
        mx = [(days[x]["max"] or 0.0, x) for x in dd]
        worst = max(mx) if mx else (0.0, None)
        rep.add("NNW-6: najwiekszy ruch niewoli za dlugi w osadzie na przeglad <= 0.2% (limit ZC6)", f"najwiecej {worst[0]:.3f}% (dzien {worst[1]})", f"<= {NNW_MOVE_CAP:.3f}%",
                worst[0] <= NNW_MOVE_CAP)
        # ---- NNW-7 krzyzowo z linia ZC6
        both = [x for x in dd if x in zc6]
        b7 = [x for x in both if days[x]["mv"] is not None and zc6[x] is not None and abs(days[x]["mv"] - zc6[x]) > 1.0]
        if both:
            rep.add("NNW-7: 'do niewoli' linii f8 = 'niewola za dlugi' linii 'Awans (ZC6)' tej samej doby", f"niezgodne {len(b7)} z {len(both)} dob" + (f" (doby {b7[:5]})" if b7 else ""),
                    "0 (+-1 czlowiek zaokraglenia)", len(b7) == 0)
        else:
            rep.add("NNW-7: krzyzowo z linia 'Awans (ZC6)'", "brak wpisu niewoli w liniach ZC6", "INFO", None)
        # ---- NNW-8 potkniecia i ERROR
        st = sum((days[x]["stum"] or 0) for x in dd)
        rep.add("NNW-8: potkniecia paczki i ERROR DailyLife.NiewolaZaDlugi / DebtSl", f"potkniecia (suma linii) {st}, sesja {lastr.get('stumS')}, ERROR {len(errs)}"
                + (f" (np. {errs[0][:120]})" if errs else ""), "0 / 0", st == 0 and not errs)
        # ---- NNW-9 czas
        msd = [days[x]["msd"] for x in dd if days[x]["msd"] is not None]
        rep.add("NNW-9: czas kodu paczki na dobe (przeplyw w przegladzie + przelew kiesy)", f"najwiecej {max(msd):.3f} ms/dobe, srednio {sum(msd) / len(msd):.3f}" if msd else "brak liczb",
                f"<= {NNW_MS_DAY} ms/dobe", (max(msd) <= NNW_MS_DAY) if msd else None)
        # ---- NNW-11 / 12 INFO: kultury, wolni, powody
        rep.add("NNW-11: do niewoli od wczytania wedlug kultur (ostatnia linia)", f"{lastr.get('culS') or '-'}; razem {mvS} (wsie {lastr.get('vS')}, miasta {lastr.get('tS')}) w "
                f"{lastr.get('daysS')} dobach; na rok {lastr.get('freeRate')}% wolnych stanu zrodlowego (wolni w przegladach {lastr.get('freeS')})", "INFO", None)
        sums = {k: sum((days[x][k] or 0) for x in dd) for k in ("seen", "poor", "noks", "fr", "rich", "sav", "nop", "nod", "empty", "band", "moves")}
        rep.add("NNW-12: przeglady osad kultur z niewola i powody bez ruchu (suma linii)",
                f"przegladow {sums['seen']:.0f}, biednych {sums['poor']:.0f} (z ruchem {sums['moves']:.0f}); bez KS {sums['noks']:.0f}, wladca bez niewoli {sums['fr']:.0f}, "
                f"D >= 0.8 {sums['rich']:.0f}, zapas >= 7 dni {sums['sav']:.0f}, zapas nieznany {sums['nop']:.0f}, D nieznane {sums['nod']:.0f}, bez ludzi stanu {sums['empty']:.0f}; "
                f"granice pasm / limit {sums['band']:.0f}", "INFO", None)
    # ---- NNW-10 stany-dostatek.csv: udzial niewolnych ksiegi stanow poza kulturami z niewola nie rosnie
    cp = _nnw_csv_path(logp, csvp)
    if not cp:
        rep.add("NNW-10: stany-dostatek.csv - niewolni ksiegi stanow poza kulturami z niewola nie rosna", "brak pliku (obok logu, Logs/<znacznik>/ ani --csv)", "INFO", None)
    else:
        try:
            first, last, cdays = _nnw_csv(cp)
            up_out, up_in, n_out, add_in = [], 0, 0, 0.0
            for k, a in first.items():
                b = last.get(k)
                if b is None or b[0] <= a[0]:
                    continue
                if a[3] in NNW_CULT:
                    if b[1] > a[1] + 2.0 / max(1.0, b[2]) + 1e-6:
                        up_in += 1
                        add_in += max(0.0, b[1] - a[1]) * b[2]
                    continue
                n_out += 1
                if b[1] > a[1] + 2.0 / max(1.0, b[2]) + 1e-6:
                    up_out.append(f"{b[4]} ({b[3]}) {100 * a[1]:.3f}% -> {100 * b[1]:.3f}%")
            rep.add("NNW-10: stany-dostatek.csv - udzial niewolnych ksiegi stanow (bez konta NIEWOLNI) poza kulturami z niewola nie rosnie",
                    f"doby {cdays[0] if cdays else '-'}-{cdays[-1] if cdays else '-'}, osad poza lista {n_out}, z udzialem w gore {len(up_out)}" + (f" (np. {up_out[:3]})" if up_out else "")
                    + f"; w kulturach z niewola osad z udzialem w gore {up_in} (ok. +{add_in:.0f} ludzi wobec pierwszej doby - INFO)", "0 (tylko TDebtSl dodaje niewolnych; 2 ludzi zaokraglenia)",
                    len(up_out) == 0 if cdays and len(cdays) > 1 else None)
        except Exception as e:   # plik w nieznanym ukladzie - INFO, bez wyjatku
            rep.add("NNW-10: stany-dostatek.csv", f"blad odczytu {cp}: {e}", "INFO", None)
    rep.show()
    return 0


# ------------------------------------------------------------ nzc1 (16.10, projekt ZYCIE CODZIENNE paczka ZC1 "drogi towarow"; Armoury/src/GoodsPaths.cs i pliki z naglowkiem ZC1)
NZ1_HEAD = "Towary (ZC1): "
NZ1_FOOD = ("Egg", "WhaleMeat", "apple", "beer", "bread", "butter", "carrot", "cheese", "date_fruit", "fish", "grain", "grape", "honey", "meat", "olives", "orange", "pie")
NZ1_GOODS = re.compile(r"^Towary: dzien (?P<day>-?\d+) - (?P<id>\S+) \(\d+ d\): zapas (?P<stock>\d+) .*?\| produkcja (?P<p>\d+) \[(?P<src>.*?)\] \| zuzycie (?P<c>\d+) \[(?P<sink>.*?)\] \| bez wyjasnienia")
NZ1_GOODS_IDS = ("cotton", "silver", "mead", "grain", "planks", "WhaleMeat", "meat")
NZ1_TICK = re.compile(r"inne ticki dobowe (\d+)")
NZ1_REMOVED = re.compile(r"przepadlo z partiami usunietymi bez zniszczenia \(RemoveParty\) (\d+)")
NZ1_FOLK = re.compile(r"(?:^|; )mieszczanie (\d+)")
NZ1_EXTRA = re.compile(r"\| mnoznik BK rzemieslnikow \+(\d+)")
NZ1_RAMP = re.compile(r"\| przejscia \(\d+ dob\): (?P<r>[^|]*)")
NZ1_VELVET = re.compile(r"aksamit: miast (?P<n>\d+), z indeksem < 10 (?P<low>\d+) ")
NZ1_GRAIN = re.compile(r"indeks zboza srednio (?P<gi>[-\d.]+)")
NZ1_CRAFT = re.compile(r"jedwab (?:tak|nie) - miast z zapasem (?P<st>\d+), zapas (?P<sr>\d+) szt\., polki (?P<ss>\d+), polka <= zapas (?P<sl>\d+); ruda srebra (?:tak|nie) - "
                       r"miast z zapasem (?P<vt>\d+), zapas (?P<vr>\d+) szt\., polki (?P<vs>\d+), polka <= zapas (?P<vl>\d+)")
NZ1_SALT = re.compile(r"woz za cena celu \(Cart Price By Destination (?P<key>tak|nie)\): sol (?P<n>\d+) szt\. - woz dostal (?P<got>[-\d.]+) d/szt\., cena miasta przy wjezdzie (?P<first>[-\d.]+) "
                      r"\(stosunek [-\d.]+; stara regula [-\d.]+\); zelazo (?P<in>\d+) szt\. - (?P<igot>[-\d.]+) / (?P<ifirst>[-\d.]+) .*?"
                      r"odtworzeniem niewiernym \(poza licznikami\) (?P<mis>\d+); kasy miast targowych wsi solnych (?P<stn>\d+) miast (?P<stg>-?\d+) zl")
NZ1_SIDE = re.compile(r"marmur zdjety kopalniom srebra (?P<mcut>[\d.]+), glinanki dostaly (?P<mgive>\d+) \(budzet na jutro [\d.]+ na (?P<mines>\d+) glinanek z tickiem\); "
                      r"miod pitny drwali \(model\) (?P<mbase>[\d.]+), miast (?P<mtown>\d+), zdjety drwalom (?P<mead>[\d.]+) \(czesc jutro [\d.]+\), miod lesny (?P<honey>\d+), "
                      r"indeks miodu pitnego srednio (?P<mi>[-\d.]+)")
NZ1_DTE = re.compile(r"konwoje DTE \(Dte Convoy No Free Food (?:tak|nie)\) (?P<conv>\d+), zdjete (?P<food>\d+) szt\., konwoj je \(zostawione\) (?P<eats>\d+); partie BK "
                     r"\(Bk Caravan No Free Food (?:tak|nie)\) bez daru (?P<bk>\d+) karawan, partia je \(dar zostal\) (?P<bkeats>\d+) \[(?P<kinds>[^\]]*)\], inne partie BK, ktore jedza "
                     r"(?P<oth>\d+); do spichlerzy celow karawan zywnosci nie dojdzie (?P<gran>\d+) szt\. \(cele (?P<ft>\d+), bez zapasu dzis (?P<fh>\d+)\)")
NZ1_BKKIND = re.compile(r"(?P<name>[a-z][a-zA-Z ]*?) (?P<n>\d+) x, (?P<u>\d+) szt\. warte (?P<v>\d+) zl")
NZ1_WHALE = re.compile(r"wyrob warsztatow WhaleMeat -> meat \(losowania cyklu, takze cykle bez wyrobu\) (?P<swap>\d+) szt\., wielorybnicy: ryby z ticku (?P<fish>\d+), z tego mieso wieloryba (?P<made>\d+)")
NZ1_COAL = re.compile(r"drwale wypalili (?P<wood>\d+) ladunkow drewna na (?P<coal>\d+) bryl")
NZ1_INGOT = re.compile(r"sztaby z polek \(Iron Ingots Off Shelf (?:tak|nie)\): osad (?P<towns>\d+), sztab (?P<pcs>\d+) warte (?P<val>\d+) zl -> zelaza (?P<iron>\d+)")
NZ1_BEER = re.compile(r"drugie piwo z cyklu (?P<extra>\d+), niesprzedane \(kasa bez nadwyzki\) (?P<unsold>\d+)")
NZ1_STUM = re.compile(r"\| potkniecia (?P<st>\d+) \(sesja \d+\), czas ticku wsi (?P<tick>[\d.]+) ms, linia (?P<line>[\d.]+) ms\.$")
NZ1_CTL = re.compile(r"kontrola z ksiega rudy i drewna: ruda (?P<ore>ZGODNA|NIEZGODNA).*?drewno (?P<wood>ZGODNA|NIEZGODNA)")
# fix-ksiega (noc 17/18.10): liczby kontroli (towary / ruda) - kolumna "przetwory miast" tylko przy kluczu OreLedgerTownCraftsColumn
NZ1_CTLN = re.compile(r"(?P<g>ruda|drewno) (?P<ok>ZGODNA|NIEZGODNA) \(wsie (\d+)/(\d+), las (\d+)/(\d+), zbrojne (\d+)/(\d+), linie (\d+)/(\d+), budowy (\d+)/(\d+)"
                      r"(?:, przetwory miast (?P<ca>\d+)/(?P<cb>\d+))?, zapas (\d+)/(\d+)")
NZ1_ZC5IRON = re.compile(r"^Przetwory miast \(ZC5\): dzien (?P<day>-?\d+) .*?zelazo -> narzedzia \d+ szt\. \(wsad (?P<iron>\d+);")
NZ1_VELREC = re.compile(r"velvet_weavery cotton->velvet (\d+):(\d+)")
# f25-sprawdz (decyzja Jeffa 3c): srednia indeksu aksamitu w miastach z tkalnia (linia 'Zbytki ludu (P3-P5)', MakerPrices) i lista tkalni (tygodniowa 'Warsztaty zbytkow (P1)')
NZ1_MKV = re.compile(r"cena u wytworcy \([^)]*\): [^|]*?\bvelvet ([\d.]+|-) w (\d+)")
NZ1_VELW = re.compile(r"(?:; |: )velvet: miast (\d+), linii produkcji \d+ \(([^)]*)\)")
# n20-drobne (PRZEKAZANIE-2026-10-19 p. 6): linia "Aksamit wedlug miasta (ZC1-4o): dzien N" (Armoury GoodsPaths.VelvetTowns, klucz Velvet Town Log, co 7 dob)
NZ1_VELTOWN_HEAD = "Aksamit wedlug miasta (ZC1-4o): dzien "
NZ1_VELTOWN_ROW = re.compile(r"(?:: |; )(?P<id>[^\s;|]+) (?P<ring>[WSR]) ix=(?P<ix>[\d.]+) c=(?P<c>-?\d+) z=(?P<z>\d+) d=(?P<d>[\d.]+|-)")
# fix-ksiega recenzja: stan reguly "rzemioslo pierwsze" jedwabiu (SilkToWeavers) z linii doby ZC1 - tak/nie, miast z zapasem, polka <= zapas
NZ1_SILKON = re.compile(r"jedwab (tak|nie) - miast z zapasem (\d+), zapas \d+ szt\., polki \d+, polka <= zapas (\d+)")
NZ1_K4F = re.compile(r"; jedzenie (\d+) z wlasnym limitem \d+, ponad limit (\d+)\)")
NZ1_ND = re.compile(r"budzet mieszczan (\d+) d \(przy dzisiejszych polkach do (\d+) d\)")
NZ1_RESZTA = re.compile(r"\+ reszta ([+-]?\d+) \[R\]")
NZ1_DAY = re.compile(r"dzien (-?\d+)")
NZ1_ERR = ("ERROR in GoodsPaths.", "ERROR in GoodsRates.SideStep", "ERROR in SyncData.arm_zc1", "ERROR in MarketCarts.Absorb", "ERROR in MarketCarts.AbsAdd")


def _nz1_wagon(s, gid):
    m = re.search(r"(?:\| |; )" + re.escape(gid) + r" (\d+) szt\. (\d+) d \(", s)
    return (int(m.group(1)), int(m.group(2))) if m else (0, 0)


def _nz1_scan(path, full):
    """Jeden przebieg logu: linie wspolne z biegiem bazowym (Towary, utarg wozow, Ceny surowcow, bilans pieniadza) i - przy full - linie paczki ZC1."""
    D = {"hooks": [], "days": [], "bad": [], "goods": {}, "ctl": [], "unknown_food": 0, "horses": 0, "n_err": 0, "k4f": [], "wagon": {}, "nd": {}, "reszta": {}, "fishauth": "", "a17f2": [],
         "ctln": [], "zc5iron": {}, "velrec": None,   # fix-ksiega: liczby kontroli wedlug doby, wsad zelaza ZC5 wedlug doby, receptura aksamitu KS
         "veltown": {},   # n20-drobne: doba -> [(miasto, pas W/S/R, indeks, cena, zapas, odleglosc)] z linii "Aksamit wedlug miasta (ZC1-4o)"
         "mkv": {}, "velw": None}   # f25-sprawdz: srednia indeksu aksamitu w miastach z tkalnia wedlug doby (M, N), ostatnia lista tkalni aksamitu (N, nazwy)
    with open(path, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\n"))
            s = m.group(2) if m else ln.rstrip("\n")
            if full and s.startswith(NZ1_HEAD):
                if s.startswith(NZ1_HEAD + "latki przy starcie gry"):
                    D["hooks"].append(s)
                elif s.startswith(NZ1_HEAD + "dzien "):
                    if NZ1_STUM.search(s) and NZ1_SALT.search(s) and NZ1_VELVET.search(s) and NZ1_SIDE.search(s) and NZ1_DTE.search(s) and NZ1_RAMP.search(s) and NZ1_CRAFT.search(s):
                        D["days"].append(s)
                    else:
                        D["bad"].append(s)
            elif s.startswith("Towary: dzien "):
                mm = NZ1_GOODS.match(s)
                if mm:
                    D["goods"].setdefault(int(mm.group("day")), {})[mm.group("id")] = (int(mm.group("p")), mm.group("src"), mm.group("sink"), s, int(mm.group("stock")), int(mm.group("c")))
            elif s.startswith("Towary (utarg wozow): dzien "):
                md = NZ1_DAY.search(s)
                if md:
                    D["wagon"][int(md.group(1))] = {g: _nz1_wagon(s, g) for g in ("cotton", "silver")}
            elif s.startswith("Ceny surowcow: dzien "):
                md = NZ1_DAY.search(s)
                if md:
                    D["nd"][int(md.group(1))] = sum(int(a.group(1)) - int(a.group(2)) for a in NZ1_ND.finditer(s))
            elif s.startswith("Pieniadz swiata (bilans): dzien "):
                md, mr = NZ1_DAY.search(s), NZ1_RESZTA.search(s)
                if md and mr:
                    D["reszta"][int(md.group(1))] = int(mr.group(1))
            elif not full:
                continue
            elif s.startswith("Towary (bilans): dzien "):
                mm = NZ1_CTL.search(s)
                if mm:
                    D["ctl"].append((mm.group("ore"), mm.group("wood")))
                    md = NZ1_DAY.search(s)
                    row = {"day": int(md.group(1)) if md else None}
                    for mc in NZ1_CTLN.finditer(s):   # fix-ksiega: (towary, ruda) dla kazdej kolumny
                        n = [int(x) for x in mc.groups()[2:12]]
                        row[mc.group("g")] = {"ok": mc.group("ok"), "wsie": (n[0], n[1]), "las": (n[2], n[3]), "zbrojne": (n[4], n[5]), "linie": (n[6], n[7]), "budowy": (n[8], n[9]),
                                              "przetwory": (int(mc.group("ca")), int(mc.group("cb"))) if mc.group("ca") is not None else None}
                    D["ctln"].append(row)
            elif s.startswith("Przetwory miast (ZC5): dzien "):
                mm = NZ1_ZC5IRON.match(s)
                if mm:
                    D["zc5iron"][int(mm.group("day"))] = int(mm.group("iron"))
            elif s.startswith("KS: receptury jedzenia wedlug wagi"):
                mm = NZ1_VELREC.search(s)
                if mm:
                    D["velrec"] = f"{mm.group(1)}:{mm.group(2)}"
            elif s.startswith("Towary (inne ticki dobowe): dzien "):
                for f in NZ1_FOOD:
                    mm = re.search(r"(?:^|; |: )" + re.escape(f) + r" \[([^\]]*)\]", s)
                    if mm and "(nieznany)" in mm.group(1):
                        D["unknown_food"] += 1
                mm = NZ1_K4F.search(s)
                if mm:
                    D["k4f"].append((int(mm.group(1)), int(mm.group(2))))
                mm = re.search(r"(?:: |; )fish \[([^\]]*)\]", s)   # A17 F2 (noc 17/18.10): autorzy ryb w tickach (ostatnia doba)
                if mm:
                    D["fishauth"] = mm.group(1)
            elif s.startswith("Ryby z niczego (A17 F2): dzien "):
                D["a17f2"].append(s)
            elif s.startswith("Towary (konie jako kapital, ZC1): dzien "):
                D["horses"] += 1
            elif s.startswith("Zbytki ludu (P3-P5): dzien "):
                mm, md = NZ1_MKV.search(s), NZ1_DAY.search(s)
                if mm and md:
                    D["mkv"][int(md.group(1))] = (float(mm.group(1)) if mm.group(1) != "-" else None, int(mm.group(2)))
            elif s.startswith("Warsztaty zbytkow (P1): dzien "):
                mm = NZ1_VELW.search(s)
                if mm:
                    D["velw"] = (int(mm.group(1)), mm.group(2))
            elif s.startswith(NZ1_VELTOWN_HEAD):
                md = NZ1_DAY.search(s)
                tail = s.split(" | miasta ", 1)[1] if " | miasta " in s else ""
                rows = [(m.group("id"), m.group("ring"), float(m.group("ix")), int(m.group("c")), int(m.group("z")), m.group("d")) for m in NZ1_VELTOWN_ROW.finditer(tail)]
                if md and rows:
                    D["veltown"][int(md.group(1))] = rows
            elif s.startswith(NZ1_ERR):
                D["n_err"] += 1
    return D


def _nz1_ramp(s, name):
    m = NZ1_RAMP.search(s)
    if not m:
        return None
    mm = re.search(r"(?:^|, )" + re.escape(name) + r" ([\d.]+)", m.group("r"))
    return float(mm.group(1)) if mm else None


def _nz1_mean(v):
    v = [x for x in v if x is not None]
    return sum(v) / len(v) if v else None


def _nz1_ceil(v):
    """f25-sprawdz: sufit liczby (bez modulu math), z tolerancja 1e-9 (5.0000000001 -> 5)."""
    return -int(-(v - 1e-9) // 1)


def _nz1_ctl_fix(rep, D):
    """fix-ksiega (noc 17/18.10): ZC1-8a kolumna 'przetwory miast' kontroli (wsad rzemiosla miasta - przetwory ZC5 i rzemioslo 148 - w obu ksiegach), ZC1-8b diagnoza
    NIEZGODNA - ile dob roznica to sam wsad zelaza ZC5 liczony przez ksiege rudy w 'linie' (stara DLL / klucz OreLedgerTownCraftsColumn wylaczony)."""
    rows = [r for r in D["ctln"][1:] if r.get("ruda") and r.get("drewno")]
    withc = [r for r in rows if r["ruda"]["przetwory"] is not None and r["drewno"]["przetwory"] is not None]
    if withc:
        badk = [r["day"] for r in withc if r["ruda"]["przetwory"][0] != r["ruda"]["przetwory"][1] or r["drewno"]["przetwory"][0] != r["drewno"]["przetwory"][1]]
        oa = sum(r["ruda"]["przetwory"][0] for r in withc); ob = sum(r["ruda"]["przetwory"][1] for r in withc)
        wa = sum(r["drewno"]["przetwory"][0] for r in withc); wb = sum(r["drewno"]["przetwory"][1] for r in withc)
        zc5 = sum(D["zc5iron"].get(r["day"], 0) for r in withc)
        rep.add("ZC1-8a: kontrola - przetwory miast (ZC5/148) w ksiedze towarow i w ksiedze rudy (fix-ksiega, bez pierwszej linii)",
                f"dob z kolumna {len(withc)} z {len(rows)}, z roznica {len(badk)}" + (f" (np. doba {badk[0]})" if badk else "")
                + f"; ruda {oa}/{ob} (wsad zelaza z linii ZC5 {zc5}), drewno {wa}/{wb}",
                "0 dob z roznica (jeden ruch = jedna pozycja w obu ksiegach)", not badk)
    else:
        rep.add("ZC1-8a: kontrola - przetwory miast (ZC5/148)", "brak kolumny 'przetwory miast' w kontroli",
                "INFO (DLL sprzed fix-ksiega albo klucz Ore Ledger Town Crafts Column wylaczony)", None)
    bad = [r for r in rows if r["ruda"]["ok"] != "ZGODNA" or r["drewno"]["ok"] != "ZGODNA"]
    if not bad:
        rep.add("ZC1-8b: NIEZGODNA wyjasnione wsadem zelaza ZC5 (diagnoza)", "brak dob NIEZGODNA", "INFO", None)
        return
    keys = ("wsie", "las", "zbrojne", "linie", "budowy")
    zc5only = 0
    other = []
    for r in bad:
        o, w = r["ruda"], r["drewno"]
        diff = [k for k in keys if o[k][0] != o[k][1]]
        wdiff = [k for k in keys if w[k][0] != w[k][1]]
        if diff == ["linie"] and not wdiff and w["ok"] == "ZGODNA" and o["linie"][1] - o["linie"][0] == D["zc5iron"].get(r["day"], -1):
            zc5only += 1
        else:
            other.append(r["day"])
    rep.add("ZC1-8b: NIEZGODNA wyjasnione wsadem zelaza ZC5 (diagnoza)",
            f"{zc5only} z {len(bad)} dob NIEZGODNA: roznica tylko w 'linie' rudy = wsad zelaza ZC5 tej doby (ksiega rudy - linie towarowe, ksiega towarow - rzemioslo miasta)"
            + (f"; inne przyczyny {len(other)} (np. doba {other[0]})" if other else ""),
            "INFO (przyczyna naprawiona kluczem Ore Ledger Town Crafts Column - fix-ksiega; inne przyczyny do zbadania)", None)


def _nz1_sinkn(text, name):
    """Liczba pozycji ujscia/zrodla linii 'Towary:' (np. 'mieszczanie 41', 'linie warsztatow 6', 'pola mieszczan (KS) 9'); 0 - brak."""
    m = re.search(r"(?:^|; )" + re.escape(name) + r" (\d+)", text or "")
    return int(m.group(1)) if m else 0


def _nz1_silk_rule(D):
    """fix-ksiega recenzja: stan reguly 'rzemioslo pierwsze' jedwabiu (Silk To Weavers) z ostatniej linii doby ZC1; brak linii - napis 'brak linii doby ZC1'."""
    for s in reversed(D["days"]):
        m = NZ1_SILKON.search(s)
        if m:
            if m.group(1) == "nie":
                return "rzemioslo pierwsze jedwabiu (Silk To Weavers) nie - tkalnie i mieszczanie biora z tej samej polki bez kolejnosci"
            return f"rzemioslo pierwsze jedwabiu (Silk To Weavers) tak - miast z zapasem {m.group(2)}, polka <= zapas {m.group(3)} (ostatnia doba)"
    return "rzemioslo pierwsze jedwabiu - brak linii doby ZC1"


def _nz1_share(a, b):
    """Udzial a w (a + b) jako procent; oba 0 - '-'."""
    return f"{a / (a + b):.0%}" if (a + b) > 0 else "-"


def _nz1_market_info(rep, D):
    """fix-ksiega (noc 17/18.10): INFO z przyczyna rynkowa trzech progow ZC1 (aksamit, miod pitny, jedwab) - same liczby ksiegi towarow, bez progow."""
    goods = D["goods"]
    ds = sorted(goods)[1:]
    if len(ds) < 14:
        rep.add("ZC1-4b/9e/16c: przyczyny rynkowe aksamitu, miodu pitnego i jedwabiu", f"dob ksiegi {len(ds)} (za malo)", "INFO", None)
        return
    first, last = ds[:7], ds[-28:]

    def avg(gid, f, dd):
        v = [f(goods[d][gid]) for d in dd if gid in goods[d]]
        return sum(v) / len(v) if v else 0.0

    def vp(g):
        return g[0]

    def cons(name):
        return lambda g: _nz1_sinkn(g[2], name)
    # aksamit: wyrob (warsztaty), wsad tkalni, jedwab mieszczan, receptura KS
    rep.add("ZC1-4b: aksamit - wyrob na dobe, jedwab tkalni i mieszczan (7 pierwszych / 28 ostatnich dob ksiegi)",
            f"aksamit {avg('velvet', vp, first):.1f} -> {avg('velvet', vp, last):.1f}/d; jedwab tkalni {avg('cotton', cons('linie warsztatow'), first):.1f} -> "
            f"{avg('cotton', cons('linie warsztatow'), last):.1f}/d, jedwab mieszczan {avg('cotton', cons('mieszczanie'), first):.1f} -> {avg('cotton', cons('mieszczanie'), last):.1f}/d; "
            f"receptura tkalni przy KS {D['velrec'] or '- (gry)'} (jedwab:aksamit); {_nz1_silk_rule(D)}; tkalnie dostaja "
            f"{_nz1_share(avg('cotton', cons('linie warsztatow'), last), avg('cotton', cons('mieszczanie'), last))} jedwabiu zuzytego przez tkalnie i mieszczan (28 ostatnich dob)",
            "INFO (luka projektu, nie blad ksiegi - osobna paczka: tkalnie przegrywaja jedwab z mieszczanami; przy Silk To Weavers wylaczonym (od 16.10) polka nie ma "
            "kolejnosci, przy wlaczonym zapas tkalni na polce liczy sie do podazy, a wsad tkalni nie jest popytem ceny; przy KS receptura 6:5 i 6 szt. naraz; "
            "indeks < 10 nie doszedl w zadnym biegu od 16.10, takze bez KS)", None)
    # miod pitny: zapas, produkcja, zuzycie wedlug ujscia
    mk = [d for d in ds if "mead" in goods[d]]
    if mk:
        rep.add("ZC1-9e: miod pitny - zapas swiata, produkcja i zuzycie wedlug ujscia (7 pierwszych / 28 ostatnich dob)",
                f"zapas {goods[mk[0]]['mead'][4]} -> {goods[mk[-1]]['mead'][4]}; produkcja {avg('mead', vp, first):.0f} -> {avg('mead', vp, last):.0f}/d; zuzycie "
                f"{avg('mead', lambda g: g[5], first):.0f} -> {avg('mead', lambda g: g[5], last):.0f}/d (mieszczanie {avg('mead', cons('mieszczanie'), first):.0f} -> "
                f"{avg('mead', cons('mieszczanie'), last):.0f}, dwory {avg('mead', cons('dwory (E3-P1)'), first):.0f} -> {avg('mead', cons('dwory (E3-P1)'), last):.0f}, "
                f"wsie {avg('mead', cons('wsie (zakupy w miescie, E5/B1)'), first):.0f} -> {avg('mead', cons('wsie (zakupy w miescie, E5/B1)'), last):.0f})",
                "INFO (indeks rosnie, gdy zapas startowy schodzi do rownowagi - takze bez KS)", None)
    # jedwab: czesc z pol mieszczan KS (bez wozu wsi), wozy (szt./d i cena), polki miast
    pa, pb = avg("cotton", vp, first), avg("cotton", vp, last)
    fld = lambda g: _nz1_sinkn(g[1], "pola mieszczan (KS)")
    fa, fb = avg("cotton", fld, first), avg("cotton", fld, last)

    def shelf(g):
        m = re.search(r"posiadacze \[miasta (\d+)", g[3])
        return int(m.group(1)) if m else 0
    wg = D["wagon"]
    wf = [wg[d]["cotton"] for d in first if d in wg]
    wl = [wg[d]["cotton"] for d in last if d in wg]

    def wav(v):
        u = sum(x[0] for x in v); g = sum(x[1] for x in v)
        return (u / len(v) if v else 0.0), (g / u if u else 0.0)
    (ua, ga), (ub, gb) = wav(wf), wav(wl)
    rep.add("ZC1-16c: jedwab - z pol mieszczan KS (bez wozu wsi), wozy wsi i polki miast (7 pierwszych / 28 ostatnich dob)",
            f"produkcja {pa:.1f} -> {pb:.1f}/d, z pol mieszczan {fa:.1f} -> {fb:.1f}/d ({(fb / pb if pb else 0):.0%}), wsie {pa - fa:.1f} -> {pb - fb:.1f}/d"
            f" ({((pb - fb) / (pa - fa) - 1 if pa - fa > 0 else 0):+.0%}); wozy wsi {ua:.1f} -> {ub:.1f} szt./d po {ga:.0f} -> {gb:.0f} d/szt.; "
            f"polki miast {avg('cotton', shelf, first):.0f} -> {avg('cotton', shelf, last):.0f} szt.",
            "INFO (przy KS czesc jedwabiu rosnie na polach mieszczan - prosto na polke miasta, bez utargu wozow wsi; ZC1-16b porownuje z dobami 2-29 biegu (f16-ks; krotki bieg - najmniej 2-8))", None)


def nzc1_main(logp, bdp=None):
    """nzc1 (16.10; projekt docs/PROJEKT-ZYCIE-CODZIENNE-2026-10-16.md rozdz. 13-14, paczka ZC1; Armoury/src/GoodsPaths.cs): drogi towarow. Wejscie: log Armoury
    (strumieniowo), opcjonalnie --baza-doby <log biegu bazowego bez ZC1> (progi "nie gorzej niz baza"; bez bazy - wobec poczatku biegu albo INFO).
    ZC1-0 latki, ZC1-1 linie doby, ZC1-2 potkniecia i ERROR 0, ZC1-3 mieso wieloryba <= 10% miesa, ZC1-4 indeks aksamitu < 10 w >= 50% miast z tkalnia aksamitu
    (f25-sprawdz, decyzja Jeffa 3c: dolna granica ze sredniej indeksu tych miast, mediana 28 dob; ZC1-4a wszystkie miasta - INFO; ZC1-4o okolica tkalni >= 50% tanich z linii 'Aksamit wedlug miasta (ZC1-4o)', bez niej INFO),
    ZC1-5 sol: cena wozu / cena miasta 0.6-1.2 (doby z przejsciem woza 1.00; bez nich - INFO), ZC1-5c kasy miast targowych wsi solnych (7 ostatnich dob >= 0.8 x 7
    pierwszych), ZC1-6/7 jedzenie "bez nazwy" i RemoveParty <= 2 szt./d na towar, ZC1-8 kontrola z ksiega rudy i drewna, ZC1-9a marmur 0.7-1.3, ZC1-9b miod lesny
    0.7-1.3, ZC1-9c produkcja miodu pitnego >= 80% bazy, ZC1-9d indeks miodu pitnego nie wyzszy niz baza (x1.10), ZC1-10 konwoje DTE i karawany BK (je 0),
    ZC1-10c cele karawan zywnosci bez zapasu <= 10% celodob, ZC1-11 czas <= 5 ms, ZC1-14 slady K4 jedzenia ponad limit 0, ZC1-15 zboze (zapas wobec bazy),
    ZC1-16 zapas jedwabiu i rudy srebra (przyrost <= 10% produkcji w 28 dobach; wyjatek - odbicie po spadku: poprzednie 28 dob bez przyrostu, 56 dob <= 10%, polki miast i wsie <= 10%; zawsze <= 25%; n22f-ruda), ZC1-16b utarg wozow jedwabiu i rudy srebra >= 0.8 x baza x czesc produkcji wsi bez pol mieszczan KS (f25-sprawdz, decyzja Jeffa 2a; bez bazy: doby 2-29 biegu, f16-ks; sam stosunek - INFO), ZC1-17 'nie do wydania' <= 1.05 x baza,
    ZC1-18 reszta bilansu pieniadza wobec bazy, ZC1-19 mieszczanie bez desek po przejsciu, reszta INFO. Log bez paczki: INFO, bez wyjatku."""
    rep = Report()
    if not logp or not os.path.isfile(logp):
        rep.add("ZC1-0: log Armoury", f"brak pliku {logp}", "podaj <Armoury-*.log>", None)
        rep.show()
        return 0
    D = _nz1_scan(logp, True)
    B = _nz1_scan(bdp, False) if bdp and os.path.isfile(bdp) else None
    hooks, days, bad, goods, ctl = D["hooks"], D["days"], D["bad"], D["goods"], D["ctl"]
    print(f"plik: {logp} | linii latek {len(hooks)}, doby ZC1 {len(days)} (nierozpoznanych {len(bad)}), dob ksiegi towarow {len(goods)}, linii bilansu z kontrola {len(ctl)}"
          + (f" | baza: {bdp} (dob ksiegi {len(B['goods'])})" if B else " | bez bazy (--baza-doby)"))
    if not hooks and not days and not bad:
        rep.add("ZC1-0: linie 'Towary (ZC1)'", "brak w logu", "INFO (log sprzed paczki ZC1)", None)
        rep.show()
        return 0
    if hooks:
        h = hooks[-1]
        need = ("tick produkcji wsi", "konwoje DTE", "karawany 2/2", "dar GiveFood", "wyroby cyklu", "wsad z targu", "wsad z magazynu", "koszt wsadu")
        miss = [k for k in need if k not in h]
        rep.add("ZC1-0: latki przy starcie gry", h[len(NZ1_HEAD):][:240] + (f" (brak: {', '.join(miss)})" if miss else ""),
                "wyroby cyklu, wsad z targu i magazynu, koszt wsadu, tick wsi, konwoje DTE, partie BK (karawany 2/2, dar GiveFood)", not miss)
    else:
        rep.add("ZC1-0: latki przy starcie gry", "brak linii (log bez startu gry?)", "INFO", None)
    rep.add("ZC1-1: linie doby rozpoznane", f"doby {len(days)}, nierozpoznane {len(bad)}" + (f" (np. {bad[0][:160]})" if bad else ""), "nierozpoznane 0", not bad)
    stum = sum(int(NZ1_STUM.search(s).group("st")) for s in days)
    rep.add("ZC1-2: potkniecia (suma dob) i ERROR paczki (GoodsPaths.*, GoodsRates.SideStep, SyncData.arm_zc1, MarketCarts.Absorb/AbsAdd)", f"potkniecia {stum}, ERROR {D['n_err']}", "0 / 0",
            stum == 0 and D["n_err"] == 0)
    gd = sorted(goods)
    use = gd[1:] if len(gd) > 1 else []

    def gser(G, gid, k):   # k: 4 zapas, 0 produkcja, 5 zuzycie
        return {d: G[d][gid][k] for d in sorted(G) if gid in G[d]}

    # ZC1-3 mieso wieloryba wobec calego miesa (produkcja ksiegi, bez pierwszej doby sesji)
    if use:
        wp = sum(goods[d].get("WhaleMeat", (0,))[0] for d in use)
        mp = sum(goods[d].get("meat", (0,))[0] for d in use)
        share = wp / (wp + mp) if wp + mp > 0 else 0.0
        rep.add("ZC1-3: mieso wieloryba w produkcji miesa (ksiega towarow, doby 2..)", f"WhaleMeat {wp}, meat {mp} -> {share:.1%}", "<= 10%", share <= 0.10)
    else:
        rep.add("ZC1-3: mieso wieloryba", "za malo dob ksiegi towarow", "INFO", None)
    # ZC1-4 aksamit (f25-sprawdz, decyzja Jeffa 3c z 19.10: "aksamit ma byc tani w miastach z tkalnia i w ich okolicy, dalej drogi jak luksus - w grze nic sie
    # nie zmienia, tylko pomiar"). Prog na miastach z tkalnia aksamitu. Log podaje dla nich tylko SREDNIA indeksu: linia 'Zbytki ludu (P3-P5)', pole 'cena u
    # wytworcy ... velvet M w N' (TownFolk.Luxury MakerPrices - ten sam Town.GetItemCategoryPriceIndex co licznik linii ZC1). Indeks >= 0, a miasto drogie
    # (nie tanie) ma indeks >= 9.99 (GoodsPaths: tanie = ix < 9.99), wiec N x M >= (N - c) x 9.99, czyli tanich c >= N x (1 - M / 9.99); M w linii zaokraglone
    # do 0.01 - liczymy z M + 0.005. To DOLNA granica: prog zalicza tylko, gdy sama srednia dowodzi >= 50% tanich miast z tkalnia. Drogi aksamit w miescie z
    # tkalnia (indeks ~10) podnosi M i obniza granice - wiersz nie jest slepy. Koszt ostroznosci: tanie miasta z tkalnia, ale tylko lekko tanie (indeks 5-9),
    # tez obnizaja granice (prog moze odrzucic bieg, w ktorym naprawde jest 50% - nigdy nie zaliczy biegu, w ktorym jest mniej). Gorna granica - min(N, tanich
    # w calym swiecie tej doby z linii ZC1).
    # Okolica tkalni: log nie ma indeksu aksamitu wedlug miasta ani odleglosci miast (ks-miasta.csv - tylko 'kraina', region kultury) - ZC1-4o INFO.
    vday = {}
    for s in days:
        md, mv = NZ1_DAY.search(s), NZ1_VELVET.search(s)
        if md and mv:
            vday[int(md.group(1))] = (int(mv.group("n")), int(mv.group("low")))
    mkd = [d for d in sorted(D["mkv"]) if D["mkv"][d][0] is not None and D["mkv"][d][1] > 0]
    vrow = None
    if mkd:
        vrows = []
        for d in mkd[-28:]:
            m, n = D["mkv"][d]
            lo = min(n, max(0, _nz1_ceil(n * (1.0 - (m + 0.005) / 9.99))))
            hi = max(lo, min(n, vday[d][1])) if d in vday else n   # linia ZC1 i 'Zbytki ludu' licza o innej porze doby - gorna nie ponizej dolnej
            vrows.append((lo / n, m, n, lo, hi, d))
        vmed = st.median([r[0] for r in vrows])
        vrow = vrows[-1]
        vw = D["velw"]
        rep.add("ZC1-4: aksamit tani (indeks < 10) w miastach z tkalnia aksamitu - decyzja Jeffa 3c (19.10); dolna granica ze sredniej indeksu, mediana ostatnich do 28 dob",
                f"co najmniej {vmed:.0%} (ostatnia doba: srednia indeksu {vrow[1]:.2f} w {vrow[2]} miastach z tkalnia -> tanich co najmniej {vrow[3]}, najwyzej {vrow[4]})"
                + (f"; tkalnie aksamitu (ostatni tydzien): {vw[1]}" if vw else ""),
                ">= 50% miast z tkalnia (okolica tkalni - ZC1-4o)", vmed >= 0.5)
    else:
        rep.add("ZC1-4: aksamit tani w miastach z tkalnia aksamitu (decyzja Jeffa 3c)", "brak pola 'cena u wytworcy ... velvet M w N' w linii 'Zbytki ludu (P3-P5)'",
                "INFO (log bez paczki P3-P5 albo swiat bez tkalni aksamitu)", None)
    vel = [int(NZ1_VELVET.search(s).group("low")) / int(NZ1_VELVET.search(s).group("n")) for s in days if int(NZ1_VELVET.search(s).group("n")) > 0]
    if vel:
        med = st.median(vel[-28:])
        rep.add("ZC1-4a: indeks aksamitu < 10 we wszystkich miastach (czesc miast, mediana ostatnich do 28 dob)", f"{med:.0%} (pierwsza doba {vel[0]:.0%}, ostatnia {vel[-1]:.0%})",
                "INFO (dawny prog >= 50% miast; decyzja 3c: poza tkalniami i ich okolica aksamit ma zostac drogi)", None)
    vt = D.get("veltown") or {}
    if vt:
        # n20-drobne: dokladny pomiar miasto po miescie (linia "Aksamit wedlug miasta (ZC1-4o)", co 7 dob) - pas W (tkalnia), S (3 najblizsze miasta bez tkalni
        # kazdego miasta z tkalnia), R (reszta); tanie = indeks < 9.99 (jak licznik linii ZC1). Mediana ostatnich do 4 linii (4 tygodnie).
        vdays = sorted(vt)[-4:]
        def ring_share(rg):
            sh = []
            for d in vdays:
                r = [x for x in vt[d] if x[1] == rg]
                if r:
                    sh.append(sum(1 for x in r if x[2] < 9.99) / len(r))
            return (st.median(sh) if sh else None), len(sh)
        lw = vt[vdays[-1]]
        def cnt(rg):
            r = [x for x in lw if x[1] == rg]
            return len(r), sum(1 for x in r if x[2] < 9.99), (st.median([x[2] for x in r]) if r else None)
        (vwn, vwc, vwm), (vsn, vsc, vsm), (vrn, vrc, vrm) = cnt("W"), cnt("S"), cnt("R")
        vws, _ = ring_share("W"); vss, vsl = ring_share("S"); vrs, _ = ring_share("R")
        vf2 = lambda v: "-" if v is None else f"{v:.2f}"
        vf0 = lambda v: "-" if v is None else f"{v:.0%}"
        rep.add("ZC1-4w: aksamit tani w miastach z tkalnia - dokladnie, miasto po miescie (linia 'Aksamit wedlug miasta', mediana ostatnich do 4 linii)",
                f"{vf0(vws)} (ostatnia linia d{vdays[-1]}: {vwc} z {vwn}, mediana indeksu {vf2(vwm)})", "INFO (prog - ZC1-4; tu bez dolnej granicy ze sredniej)", None)
        rep.add("ZC1-4o: aksamit tani w okolicy tkalni (3 najblizsze miasta bez tkalni kazdego miasta z tkalnia) - decyzja Jeffa 3c (19.10)",
                f"{vf0(vss)} (ostatnia linia d{vdays[-1]}: {vsc} z {vsn}, mediana indeksu {vf2(vsm)}; linii {vsl})",
                ">= 50% miast okolicy", (vss >= 0.5) if vss is not None else None)
        rep.add("ZC1-4r: aksamit poza tkalniami i okolica (decyzja 3c: dalej drogi jak luksus)", f"tanich {vf0(vrs)} (ostatnia linia: {vrc} z {vrn}, mediana indeksu {vf2(vrm)})",
                "INFO", None)
    elif vrow is not None and vrow[5] in vday:
        tn, tk = vday[vrow[5]]
        rest = tn - vrow[2]
        a0, a1 = max(0, tk - vrow[4]), max(0, tk - vrow[3])
        rep.add("ZC1-4o: aksamit w okolicy tkalni (ostatnia doba)",
                f"nie do zmierzenia z logu - brak indeksu aksamitu wedlug miasta i odleglosci miast (linia ZC1: tylko liczba tanich w swiecie, 'Zbytki ludu': tylko srednia "
                f"miast z tkalnia, ks-miasta.csv: tylko 'kraina' - region kultury); poza {vrow[2]} miastami z tkalnia ({rest}): tanich od {min(a0, rest)} do {min(a1, rest)}, "
                f"drogich (indeks >= 9.99) od {max(0, rest - a1)} do {max(0, rest - a0)} - czy tanie leza przy tkalniach, log nie mowi",
                "INFO (okolica - potrzebne pole w logu gry: indeks aksamitu w miastach z tkalnia i w ich sasiadach; osobna paczka kodu, decyzja Jeffa)", None)
    # ZC1-5 sol: cena wozu / cena miasta przy wjezdzie - doby z pelnym przejsciem woza
    full_d = [s for s in days if (_nz1_ramp(s, "woz") or 0.0) >= 0.999]
    for label, sel, judge in (("doby z przejsciem woza 1.00", full_d, True), ("wszystkie doby", days, False)):
        sn = sf = sg = 0.0
        for s in sel:
            mm = NZ1_SALT.search(s)
            n = int(mm.group("n"))
            if n > 0 and mm.group("got") != "-":
                sn += n; sg += n * float(mm.group("got")); sf += n * float(mm.group("first"))
        if sn > 0 and sf > 0:
            r = sg / sf
            rep.add(f"ZC1-5{'' if judge else 'a'}: sol - cena wozu / cena miasta przy wjezdzie ({label}, {len(sel)})", f"{r:.2f} ({sn:.0f} szt., woz {sg / sn:.2f} d/szt., miasto {sf / sn:.2f})",
                    "0.6-1.2" if judge else "INFO (w przejsciu 60 dob)", (0.6 <= r <= 1.2) if judge else None)
        elif judge:
            rep.add("ZC1-5: sol - sprzedaze wozow po przejsciu", f"brak (dob z przejsciem woza 1.00: {len(full_d)})", "INFO (bieg krotszy niz przejscie albo bez soli)", None)
    inn = ifr = ig = 0.0
    for s in (full_d or days):
        mm = NZ1_SALT.search(s)
        ni = int(mm.group("in"))
        if ni > 0 and mm.group("igot") != "-":
            inn += ni; ig += ni * float(mm.group("igot")); ifr += ni * float(mm.group("ifirst"))
    if inn > 0 and ifr > 0:
        rep.add("ZC1-5b: lupa zelaza - cena wozu / cena miasta przy wjezdzie (koszyk: zuzycie kowali i dymarek miasta)", f"{ig / ifr:.2f} ({inn:.0f} szt.; dotad ok. 0.57)", "INFO", None)
    sg_ = [int(NZ1_SALT.search(s).group("stg")) for s in days]
    if len(sg_) >= 14:
        a, b = _nz1_mean(sg_[:7]), _nz1_mean(sg_[-7:])
        rep.add("ZC1-5c: kasy miast targowych wsi solnych (srednia 7 ostatnich dob / 7 pierwszych)", f"{b:.0f} / {a:.0f} = {b / a:.2f}" if a else f"{b:.0f} / 0",
                ">= 0.8 (woz za cena celu bez naglego odplywu z kas)", (b >= 0.8 * a) if a and a > 0 else None)
    else:
        rep.add("ZC1-5c: kasy miast targowych wsi solnych", f"dob {len(sg_)} (za malo)", "INFO", None)
    mis = sum(int(NZ1_SALT.search(s).group("mis")) for s in days)
    rep.add("ZC1-5d: sprzedaze wozow z odtworzeniem niewiernym (poza licznikami ZC1-5)", f"{mis} ({mis / max(1, len(days)):.1f}/d)", "INFO", None)
    # ZC1-6 / ZC1-7 zrodla i ujscia bez nazwy w jedzeniu
    if use:
        over_src, over_rm = [], []
        for f in NZ1_FOOD:
            src = rm = 0
            for d in use:
                g = goods[d].get(f)
                if not g:
                    continue
                mm = NZ1_TICK.search(g[1])
                if mm:
                    src += int(mm.group(1))
                mm = NZ1_REMOVED.search(g[2])
                if mm:
                    rm += int(mm.group(1))
            if src / len(use) > 2.0:
                over_src.append(f"{f} {src / len(use):.1f}")
            if rm / len(use) > 2.0:
                over_rm.append(f"{f} {rm / len(use):.1f}")
        rep.add("ZC1-6: zrodla 'bez nazwy' w jedzeniu (inne ticki dobowe, srednio na dobe)", f"towarow ponad 2/d: {len(over_src)}" + (f" ({', '.join(over_src)})" if over_src else ""),
                "0 (kazde jedzenie <= 2 szt./d)", not over_src)
        rep.add("ZC1-7: ujscie RemoveParty w jedzeniu (srednio na dobe)", f"towarow ponad 2/d: {len(over_rm)}" + (f" ({', '.join(over_rm)})" if over_rm else ""),
                "0 (kazde jedzenie <= 2 szt./d)", not over_rm)
        # A17 F2 (noc 17/18.10): zrodlo ryb "inne ticki dobowe" - autor nazwany (NavalDLC Night Raider, porty BK) i linia "Ryby z niczego (A17 F2)" (progi w --grupa na17)
        f2n = sum(int(m.group(1)) for m in (re.search(r"razem ryby z niczego (\d+)", x) for x in D["a17f2"]) if m)
        # recenzja stare-a17 (3): poza KS ryby z niczego ida do grupy "ryby z niczego poza KS (A17 F2)" (nazwane - ZC1-6 ich nie liczy) - tu suma, progi w na17 NA17-2f
        ffr = 0
        for d in use:
            g = goods[d].get("fish")
            mm = re.search(r"ryby z niczego poza KS \(A17 F2\) (\d+)", g[1]) if g else None
            if mm:
                ffr += int(mm.group(1))
        rep.add("ZC1-6b: ryby - autorzy zrodla 'inne ticki dobowe' (K4, ostatnia doba) i ryby z niczego z linii A17 F2 (suma dob)",
                f"K4: {D['fishauth'][:220] or '-'}; A17 F2: dob {len(D['a17f2'])}, z niczego {f2n}; grupa ksiegi 'ryby z niczego poza KS (A17 F2)' {ffr / len(use):.1f}/d",
                "INFO (progi: --grupa na17 NA17-2a/2b/2e/2f)", None)
        extra = sum(int(NZ1_EXTRA.search(g[3]).group(1)) for d in use for g in goods[d].values() if NZ1_EXTRA.search(g[3]))
        rep.add("ZC1-12: mnoznik BK rzemieslnikow ponad recepture x cykle (suma dob, wszystkie towary)", f"{extra} szt. ({extra / len(use):.0f}/d)", "INFO (dotad ok. 1 460/d - liczone na jeden cykl)", None)
    if ctl:
        badc = [c for c in ctl[1:] if c[0] != "ZGODNA" or c[1] != "ZGODNA"]
        rep.add("ZC1-8: kontrola ksiegi towarow z ksiega rudy i drewna (bez pierwszej linii)", f"NIEZGODNA {len(badc)} z {max(0, len(ctl) - 1)}", "0", not badc)
        _nz1_ctl_fix(rep, D)
    # ZC1-9 przejscie BK: marmur, miod pitny
    sides = [NZ1_SIDE.search(s) for s in days]
    mcut = sum(float(m.group("mcut")) for m in sides); mgive = sum(float(m.group("mgive")) for m in sides)
    mead = sum(float(m.group("mead")) for m in sides); honey = sum(float(m.group("honey")) for m in sides)
    if mcut > 20:
        rm_ = mgive / mcut
        rep.add("ZC1-9a: marmur oddany glinankom / zdjety kopalniom srebra (suma dob; rozdanie dzien pozniej, reszta przechodzi)", f"{rm_:.2f} ({mgive:.0f} / {mcut:.1f})", "0.7-1.3", 0.7 <= rm_ <= 1.3)
    else:
        rep.add("ZC1-9a: marmur - przejscie", f"zdjete {mcut:.1f} (za malo do oceny)", "INFO", None)
    if mead > 20:
        rh = honey / (0.5 * mead)
        rep.add("ZC1-9b: miod lesny / (0.5 x miod pitny zdjety drwalom)", f"{rh:.2f} ({honey:.0f} / {0.5 * mead:.1f})", "0.7-1.3", 0.7 <= rh <= 1.3)
    else:
        mt = sum(float(m.group("mtown")) for m in sides)
        rep.add("ZC1-9b: miod pitny - przejscie", f"zdjete drwalom {mead:.1f}, miasta zrobily {mt:.0f} (drwale tna tylko o tyle, ile zrobia miasta)", "INFO", None)
    mp_ = gser(goods, "mead", 0)
    mk_ = sorted(mp_)
    if len(mk_) >= 14:
        if B:
            bm = gser(B["goods"], "mead", 0)
            com = [d for d in mk_[-28:] if d in bm]
            a, b = _nz1_mean([bm[d] for d in com]), _nz1_mean([mp_[d] for d in com])
            how = f"baza tych samych dob ({len(com)})"
        else:
            a, b = _nz1_mean([mp_[d] for d in mk_[1:8]]), _nz1_mean([mp_[d] for d in mk_[-28:]])
            how = "doby 2-8 tego biegu"
        if a:
            rep.add("ZC1-9c: produkcja miodu pitnego (ksiega towarow, srednia 28 ostatnich dob) wobec bazy", f"{b:.1f} / {a:.1f} = {b / a:.2f} ({how})", ">= 0.80", b >= 0.8 * a)
        else:
            rep.add("ZC1-9c: produkcja miodu pitnego", "baza 0 albo brak", "INFO", None)
    else:
        rep.add("ZC1-9c: produkcja miodu pitnego", f"dob ksiegi {len(mk_)} (za malo)", "INFO", None)
    mi = [float(m.group("mi")) for m in sides if m.group("mi") != "-"]
    if len(mi) >= 14:
        a, b = st.median(mi[:7]), st.median(mi[-28:])
        rep.add("ZC1-9d: indeks miodu pitnego w miastach (mediana 28 ostatnich dob / 7 pierwszych)", f"{b:.2f} / {a:.2f}", "<= 1.10 x poczatek (+0.05)", b <= 1.10 * a + 0.05)
    else:
        rep.add("ZC1-9d: indeks miodu pitnego", f"dob {len(mi)} (za malo)", "INFO", None)
    # ZC1-10 konwoje DTE i partie BK
    dte = [NZ1_DTE.search(s) for s in days]
    conv = sum(int(m.group("conv")) for m in dte); food = sum(int(m.group("food")) for m in dte); eats = sum(int(m.group("eats")) for m in dte)
    bk = sum(int(m.group("bk")) for m in dte); bkeats = sum(int(m.group("bkeats")) for m in dte)
    rep.add("ZC1-10: konwoje DTE i karawany BK bez jedzenia z niczego", f"konwojow {conv}, zdjete jedzenie {food} szt., konwoj je {eats}; karawany BK bez daru {bk}, partia je {bkeats}",
            "konwoj je 0, partia je 0", eats == 0 and bkeats == 0)
    kinds = {}
    for m in dte:
        for k in NZ1_BKKIND.finditer(m.group("kinds")):
            a = kinds.setdefault(k.group("name"), [0, 0, 0])
            a[0] += int(k.group("n")); a[1] += int(k.group("u")); a[2] += int(k.group("v"))
    gran = sum(int(m.group("gran")) for m in dte); oth = sum(int(m.group("oth")) for m in dte)
    rep.add("ZC1-10b: dar BK zdjety wedlug rodzaju partii (suma dob), do spichlerzy celow karawan zywnosci nie doszlo",
            "; ".join(f"{k} {v[0]} x / {v[1]} szt. / {v[2]} zl" for k, v in kinds.items()) + f"; spichlerze celow -{gran} szt.; inne partie BK, ktore jedza {oth}", "INFO", None)
    ft = sum(int(m.group("ft")) for m in dte); fh_ = sum(int(m.group("fh")) for m in dte)
    if ft > 0:
        rep.add("ZC1-10c: cele karawan zywnosci BK bez zapasu (celodoby)", f"{fh_} z {ft} ({fh_ / ft:.1%})", "<= 10%", fh_ <= 0.10 * ft)
    else:
        rep.add("ZC1-10c: cele karawan zywnosci BK", "brak karawan zywnosci w biegu", "INFO", None)
    # ZC1-11 czas
    if days:
        tm = [float(NZ1_STUM.search(s).group("tick")) + float(NZ1_STUM.search(s).group("line")) for s in days]
        rep.add("ZC1-11: czas bloku ZC1 (tick wsi + linia doby, mediana)", f"{st.median(tm):.2f} ms (najwiecej {max(tm):.1f})", "<= 5 ms", st.median(tm) <= 5.0)
    # INFO
    sw = fishw = made = beer = unsold = wood = coal = itowns = ipcs = iiron = 0
    for s in days:
        mm = NZ1_WHALE.search(s)
        if mm:
            sw += int(mm.group("swap")); fishw += int(mm.group("fish")); made += int(mm.group("made"))
        mm = NZ1_BEER.search(s)
        if mm:
            beer += int(mm.group("extra")); unsold += int(mm.group("unsold"))
        mm = NZ1_COAL.search(s)
        if mm:
            wood += int(mm.group("wood")); coal += int(mm.group("coal"))
        mm = NZ1_INGOT.search(s)
        if mm:
            itowns += int(mm.group("towns")); ipcs += int(mm.group("pcs")); iiron += int(mm.group("iron"))
    nd_ = max(1, len(days))
    rep.add("ZC1-13: wieloryb, piwo x2, wegiel, sztaby (suma dob)", f"WhaleMeat -> meat {sw} ({sw / nd_:.0f}/d), wielorybnicy ryby {fishw} -> mieso wieloryba {made}; drugie piwo {beer}, "
            f"niesprzedane {unsold}; wegiel {coal} bryl z {wood} ladunkow; sztaby {ipcs} szt. w {itowns} osadodobach -> zelaza {iiron}", "INFO", None)
    # ZC1-14 slady K4 jedzenia ponad limit (autor ryb "(nieznany)")
    k4 = D["k4f"]
    if k4:
        over = [x for x in k4 if x[1] > 0]
        rep.add("ZC1-14: slady K4 jedzenia ponad limit doby (wlasny limit jedzenia, konie bez sladow)", f"dob ponad limitem {len(over)} z {len(k4)}" + (f" (najwiecej {max(x[1] for x in over)})" if over else ""),
                "0", not over)
    else:
        rep.add("ZC1-14: slady K4 jedzenia", "brak linii 'Towary (inne ticki dobowe)' z sladami jedzenia (klucz GoodsLedgerTickAuthors / ciche logi)", "INFO", None)
    rep.add("ZC1-14b: autorzy K4 '(nieznany)' w jedzeniu, linie koni", f"{D['unknown_food']} wpisow, linii 'Towary (konie jako kapital, ZC1)' {D['horses']}",
            "INFO (ryby: zrodlo otwarte do nazwania autora)", None)
    # ZC1-15 zboze: zapas wobec bazy, indeks
    gi = [float(NZ1_GRAIN.search(s).group("gi")) for s in days if NZ1_GRAIN.search(s) and NZ1_GRAIN.search(s).group("gi") != "-"]
    gs = gser(goods, "grain", 4)
    if B and gs:
        bs = gser(B["goods"], "grain", 4)
        com = [d for d in sorted(gs) if d in bs]
        if com:
            d = com[-1]
            rep.add("ZC1-15: zapas zboza (ksiega towarow) wobec bazy - ostatnia wspolna doba", f"{gs[d]} / {bs[d]} = {gs[d] / max(1, bs[d]):.2f} (doba {d})", ">= 0.95", gs[d] >= 0.95 * bs[d])
        else:
            rep.add("ZC1-15: zapas zboza wobec bazy", "brak wspolnych dob", "INFO", None)
    else:
        ks = sorted(gs)
        rep.add("ZC1-15: zapas zboza (bez bazy)", f"{gs[ks[0]]} -> {gs[ks[-1]]}" if ks else "brak", "INFO (z --baza-doby: >= 0.95 x baza)", None)
    if len(gi) >= 14:
        rep.add("ZC1-15b: indeks zboza w miastach (mediana 28 ostatnich / 7 pierwszych dob)", f"{st.median(gi[-28:]):.2f} / {st.median(gi[:7]):.2f}", "INFO (piwo x2 zjada zboze - przejscie 60 dob)", None)
    # ZC1-16 jedwab i ruda srebra: zapas (przyrost <= 10% produkcji), utarg wozow
    for gid, nm in (("cotton", "jedwab"), ("silver", "ruda srebra")):
        sk, pr = gser(goods, gid, 4), gser(goods, gid, 0)
        ks = sorted(sk)[-28:]
        if len(ks) >= 14:
            slope = (sk[ks[-1]] - sk[ks[0]]) / max(1, ks[-1] - ks[0])
            pm = _nz1_mean([pr.get(d) for d in ks]) or 0.0
            # n22f-ruda (20.10, po recenzjach): wyjatek "odbicie po spadku" - przyrost 28 dob ponad 10% produkcji nie jest zalewem, gdy (1) poprzednie 28 dob
            # zapas nie rosl (<= +0.5/d), (2) w 56 dobach przyrost <= 10% produkcji, (3) polki miast i wsie (posiadacze "miasta" + "wsie") w 28 dobach
            # urosly <= 10% produkcji - przybylo w drodze (wozy, karawany), nie na polkach - i (4) przyrost 28 dob <= 25% produkcji. Poza tym prog 28 dob jak dotad.
            # Skad wahania (nie cykl - log): zapas rudy w ksiedze to w 2/3 towar w drodze (karawany 2 800-5 700 szt.), zuzycie tygodniowe skacze (r2160 108-321/d,
            # n22a160 145-246/d), a regale KS co 28 dob podnosza rece przy kopalniach srebra o 10% (indeks srebra ok. 3-3.9 > 1.2 przez caly bieg - tylko w gore,
            # do sufitu bloku): w ostatnich 56 dobach P rosnie w drugiej polowce we wszystkich 4 biegach 160 dob. n22a160: P 192.2 -> 206.7, C 198.5 -> 181.2,
            # zapas 5061 -> 4834 -> 5564 (spadek, potem +27.0/206.7 = 13%), polki miast i wsie 1527 -> 994, karawany +678, wozy +532 - wyjatek: TAK.
            # Okna 28 dob od doby 56 (biegi 160 dob, ruda srebra): stary prog NIE 13/106 (r2160), 1, 0, 2 (n22a160); z wyjatkiem 1, 1, 0, 0. Jedwab i nowa
            # kampania (r2/r3/n21/n22a nowa) - ostatnie okno bez zmiany werdyktu (r3nowa ruda NIE zostaje: zapas rosl w obu polowkach, +13.8 i +20.1/d).
            # Przepuszcza: zalew w samej drodze (karawany, wozy) 10-25% produkcji krotszy niz ok. 5-6 tygodni po spadku zapasu; zalew polek ponad 10% - NIE.
            k56 = sorted(sk)[-56:]
            s56 = pm56 = sA = None
            if len(k56) >= 56:
                s56 = (sk[k56[-1]] - sk[k56[0]]) / max(1, k56[-1] - k56[0])
                pm56 = _nz1_mean([pr.get(d) for d in k56]) or 0.0
                sA = (sk[k56[28]] - sk[k56[0]]) / max(1, k56[28] - k56[0])

            def _z16_shelf(d):
                g = goods.get(d, {}).get(gid)
                mm = re.search(r"posiadacze \[([^\]]*)\]", g[3]) if g else None
                if not mm:
                    return None
                h = dict((a.strip(), int(v)) for a, v in re.findall(r"([a-z ]+?) (\d+)(?:,|$)", mm.group(1)))
                return h.get("miasta", 0) + h.get("wsie", 0) if ("miasta" in h or "wsie" in h) else None
            h0, h1 = _z16_shelf(ks[0]), _z16_shelf(ks[-1])
            sh28 = (h1 - h0) / max(1, ks[-1] - ks[0]) if h0 is not None and h1 is not None else None
            hi28 = slope > 0.10 * pm + 0.5
            rebound = (s56 is not None and sA <= 0.5 and s56 <= 0.10 * pm56 + 0.5 and sh28 is not None and sh28 <= 0.10 * pm + 0.5)
            bad = slope > 0.25 * pm + 0.5 or (hi28 and not rebound)
            rep.add(f"ZC1-16: zapas - {nm} (przyrost na dobe, ostatnie {len(ks)} dob) wobec produkcji", f"{slope:+.1f}/d przy produkcji {pm:.1f}/d (zapas {sk[ks[0]]} -> {sk[ks[-1]]})"
                    + (f"; polki miast i wsie {h0} -> {h1} ({sh28:+.1f}/d)" if sh28 is not None else "; polki - brak posiadaczy w linii")
                    + (f"; 56 dob {s56:+.1f}/d przy {pm56:.1f}/d (zapas {sk[k56[0]]} -> {sk[k56[28]]} -> {sk[k56[-1]]})" if s56 is not None else "; 56 dob - za krotki bieg")
                    + ("; wyjatek: odbicie po spadku, przybylo w drodze" if hi28 and rebound and not bad else ""),
                    "<= 10% produkcji w 28 dobach; wyjatek - odbicie po spadku: poprzednie 28 dob bez przyrostu, 56 dob <= 10%, polki miast i wsie <= 10%, i zawsze"
                    " <= 25% w 28 dobach (rzemioslo pierwsze bez zalewu polek; n22f-ruda)", not bad)
        else:
            rep.add(f"ZC1-16: zapas - {nm}", f"dob {len(ks)} (za malo)", "INFO", None)
        wg = {d: v[gid][1] for d, v in D["wagon"].items()}
        wk = sorted(wg)

        def vprod(G, dd):
            # f24-rynek: czesc produkcji, ktora rodza WSIE (ksiega towarow: (produkcja - "pola mieszczan (KS)") / produkcja tych dob - jedwab z pol rosnie
            # przy miescie i idzie prosto na polke, bez wozu wsi); None - brak dob ksiegi albo produkcja 0
            p = [G[d][gid][0] for d in dd if d in G and gid in G[d]]
            f = [_nz1_sinkn(G[d][gid][1], "pola mieszczan (KS)") for d in dd if d in G and gid in G[d]]
            return (sum(p) - sum(f)) / sum(p) if p and sum(p) > 0 else None
        if len(wk) >= 14:
            bw = {d: v[gid][1] for d, v in B["wagon"].items()} if B and B["wagon"] else {}
            com = [d for d in wk[-28:] if d in bw]
            if com:
                a, b = _nz1_mean([bw[d] for d in com]), _nz1_mean([wg[d] for d in com])
                va, vb = vprod(B["goods"], com), vprod(goods, com)
                how = f"baza tych samych dob ({len(com)})"
            else:
                # f16-ks (18.10): bez biegu bazowego albo bez wspolnych dob z 28 ostatnimi (bieg bazowy krotszy - np. 16.10 121 dob przy biegu 160 dob; dotad
                # wyjatek TypeError, b = None) - baza z tego biegu. Baza = srednia tylu dob od doby 2, ile ma okno porownania (28), a nie 7. Utarg wozow jedwabiu i srebra to kilka wozow na dobe
                # (woz wiezie zbior wielu dob - fin93 doba 109082: jeden przyjazd 128 szt. jedwabiu za 121509 d = 37% bazy 2-8), a pierwszy tydzien sesji
                # sprzedaje wozy i zapasy wsi sprzed wczytania: w 4 z 4 biegow (16.10, fin91, fin92, fin93) baza 2-8 > baza 2-29 dla jedwabiu i srebra
                # (jedwab 50898/40788, 35689/33627, 36941/35397, 46479/37974). Krotki bieg (< 36 dob) - najmniej 7 dob jak dotad.
                nb = max(7, min(28, len(wk) - 29))
                a, b = _nz1_mean([wg[d] for d in wk[1:1 + nb]]), _nz1_mean([wg[d] for d in wk[-28:]])
                va, vb = vprod(goods, wk[1:1 + nb]), vprod(goods, wk[-28:])
                how = f"doby 2-{1 + nb} tego biegu"
            # f25-sprawdz (decyzja Jeffa 2a z 19.10: "w porzadku - zmieniam tylko pomiar"): prog na bazie x czesc produkcji wsi (bez "pola mieszczan (KS)")
            # - przy KS czesc jedwabiu rosnie na polach mieszczan i idzie prosto na polke miasta, bez wozu wsi; wsie jedwabne sprzedaja mniej, bo mniej rodza,
            # nie dlatego, ze traca rynek (fin97: wsie 37.7 -> 27.3/d, pola 0 -> 8.3/d). Sam stosunek utargu do bazy (dawny prog f16-ks / f24-rynek) i ZC1-16c
            # (produkcja samych wsi) - INFO. Wsie traca rynek przy tej samej produkcji -> utarg spada wobec bazy x czesc -> NIE (wiersz nie jest slepy).
            # Brak ksiegi towarow albo czesc bez zmiany (ruda srebra, bieg bez KS) - baza bez przeliczenia, jak dotad
            per = va is not None and vb is not None and va > 0 and vb > 0 and a and a > 0 and abs(vb - va) >= 0.005
            ab, info = a, ""
            if per:
                ab = a * vb / va
                info = (f" = {b / ab:.2f}; INFO: sam stosunek {b:.0f} / {a:.0f} = {b / a:.2f} (dawny prog), czesc produkcji wsi (bez pol mieszczan KS) {vb:.2f} / {va:.2f}"
                        " - decyzja Jeffa 2a: jedwab z pol mieszczan KS nie jest strata rynku wsi")
            rep.add(f"ZC1-16b: utarg wozow wsi - {nm} (srednia 28 ostatnich dob, d/d) wobec bazy x czesc produkcji wsi",
                    (f"{b:.0f} / {ab:.0f} ({how}{' x czesc produkcji wsi' if per else ''})" if a else f"{b:.0f} / 0") + info,
                    ">= 0.80 x baza x czesc produkcji wsi (wsie jedwabne i kopalnie srebra nie traca rynku)", (b >= 0.8 * ab) if a and a > 0 else None)
    _nz1_market_info(rep, D)   # fix-ksiega: ZC1-4b, ZC1-9e, ZC1-16c (INFO - przyczyny rynkowe)
    # ZC1-17 'nie do wydania' mieszczan
    nd = {d: v for d, v in D["nd"].items() if v > 0}
    if len(nd) >= 14:
        ks = sorted(nd)
        end = _nz1_mean([nd[d] for d in ks[-10:]])
        if B and B["nd"]:
            bk_ = sorted(d for d in B["nd"] if B["nd"][d] > 0)
            base = _nz1_mean([B["nd"][d] for d in bk_[-10:]]) if bk_ else None
            how = "baza, 10 ostatnich dob"
        else:
            base = _nz1_mean([nd[d] for d in ks[:10]])
            how = "10 pierwszych dob tego biegu"
        rep.add("ZC1-17: 'nie do wydania' mieszczan (suma 'Ceny surowcow', 10 ostatnich dob)", f"{end:.0f} / {base:.0f} ({how})" if base else f"{end:.0f}",
                "<= 1.05 x baza", (end <= 1.05 * base) if base else None)
    else:
        rep.add("ZC1-17: 'nie do wydania' mieszczan", f"dob {len(nd)} (za malo)", "INFO", None)
    # ZC1-18 reszta bilansu pieniadza swiata (zloto z niczego / w nicosc poza pomiarem) wobec bazy
    rs = D["reszta"]
    if rs:
        mn = _nz1_mean(list(rs.values()))
        if B and B["reszta"]:
            mb = _nz1_mean(list(B["reszta"].values()))
            tol = max(2000.0, 0.10 * abs(mb))
            rep.add("ZC1-18: reszta bilansu pieniadza swiata [R] (srednia dob) wobec bazy", f"{mn:+.0f} / baza {mb:+.0f} (roznica {mn - mb:+.0f})", f"|roznica| <= {tol:.0f} (ZC1 nie tworzy zlota)",
                    abs(mn - mb) <= tol)
        else:
            rep.add("ZC1-18: reszta bilansu pieniadza swiata [R] (srednia dob)", f"{mn:+.0f}", "INFO (z --baza-doby: wobec bazy)", None)
    # ZC1-19 deski: mieszczanie po pelnym przejsciu
    # f14-ksiega: linia "Towary (ZC1): dzien D" podaje przejscie JUTRA (GoodsPaths.Daily: day = Today() - 1, a Ramp(k) liczy od Today()), a mieszczanie doby D
    # kupowali w tickach miast doby D (FolkFactor = 1 - Ramp przy Today() = D) - przejscie w mocy w dobie D stoi w linii doby D-1. Dotad doba D z linia D = 1.00
    # liczyla sie jako pelna, choc mieszczanie mieli jeszcze 1/60 budzetu desek (fin92 d109135: mieszczanie 1 deska przy przejsciu 59/60).
    rp_ = {}
    for s in days:
        md_ = NZ1_DAY.search(s)
        rv_ = _nz1_ramp(s, "deski")
        if md_ and rv_ is not None:
            rp_[int(md_.group(1))] = rv_
    dd = sorted(d for d in rp_ if rp_.get(d - 1, 0.0) >= 0.999)
    if dd:
        folk = []
        for d in dd:
            g = goods.get(d, {}).get("planks")
            if g:
                mm = NZ1_FOLK.search(g[2])
                folk.append(int(mm.group(1)) if mm else 0)
        bad_ = [x for x in folk if x > 0]
        rep.add("ZC1-19: mieszczanie w ujsciach desek po pelnym przejsciu (doby)", f"dob z deskami u mieszczan {len(bad_)} z {len(folk)}" + (f" (najwiecej {max(bad_)})" if bad_ else ""), "0", not bad_)
    else:
        rep.add("ZC1-19: mieszczanie i deski", "przejscie desek jeszcze niepelne (bieg krotszy niz 60 dob z kluczem)", "INFO", None)
    rep.show()
    return 0



# ------------------------------------------------------------ nds (17.10, DANINY SREDNIOWIECZNE F1 wsie + korona; galaz w-toku/noc-ds, Armoury/src/DsVillage.cs, DsTowns.cs, DsSeason.cs)
NDS_HEAD = "Daniny wsi (DS): "
NDS_ERR = ("ERROR in DsVillage.", "ERROR in DsTowns.", "ERROR in DsSeason.", "ERROR in SyncData.arm_daniny", "ERROR in VillageTakings.DsDues", "ERROR in TownFolk.DsSurplus",
           "ERROR in TownFolk.TitheVillageAtCart", "ERROR in TownFolk.DsVillageDay", "ERROR in TownFolk.DsCartTitheZc", "ERROR in TownFolk.CrownLoans.Ant.",
           "ERROR in TownFolk.EarnDraw", "ERROR in TownFolk.DistrainCommune", "ERROR in TownFolk.DistrainUndo", "ERROR in KingdomTreasury.WageRefund(DS K5)", "ERROR in TownPurse.Ds",
           # recenzja 17.10: zastaw cla (stary SeizeCustoms i nowy SeizePledged / NotePledged), splata zaliczek (stara sciezka KlStumble i nowa AntRepayDay), czesc firmy z oszczednosci ludu
           "ERROR in CrownBorrow.SeizeCustoms", "ERROR in CrownBorrow.SeizePledged", "ERROR in CrownBorrow.NotePledged", "ERROR in TownFolk.CrownLoans.Pay(zaliczki)",
           "ERROR in TownFolk.AntRepayDay", "ERROR in TownFolk.DsFolkRate", "ERROR in TownFolk.DsFolkRateUndo")
_NI = r"(-?\d+)"
NDS_RX = {   # linia "Daniny wsi (DS): dzien N | ..." (DsVillage.Daily) - kazdy kawalek osobno (odporne na dopiski)
    "carts": re.compile(r"\| wozy: powrotow (\d+), oddane " + _NI + r", pan i majatki \(bez zmian\) " + _NI + r", czesc wsi " + _NI + r" \(bez przyrostu kiesy (\d+)\)"),
    "tithe": re.compile(r", dziesiecina " + _NI + r" \(przez kaplanow " + _NI + r": jalmuzna " + _NI + r", septy " + _NI),
    "tlist": re.compile(r"pominieta bez listy kaplanow doby (\d+) wozow"),
    "crown": re.compile(r", korona przy wozie " + _NI + r" \(g krolestw: 0 - (\d+), 1 - (\d+), 1\.5 - (\d+); wozow w pokoju (\d+), zwolnione: rabunek (\d+), oblezenie (\d+), glod (\d+)\)"),
    "sut": re.compile(r"\| markietani: czesc wsi w wojnie " + _NI + r", korona " + _NI + r" \((\d+) wplat, zwolnione (\d+)\)"),
    "rent": re.compile(r"\| czynsz: nalezny " + _NI + r" \((\d+) wsi\), zaplacony " + _NI + r" \(w tym zaleglosci " + _NI + r"\), nowa zaleglosc " + _NI + r", zaleglosci " + _NI
                       + r" u (\d+) wsi \(ponad 91 rat (\d+)\), darowane po roku " + _NI + r" \((\d+) wsi\), wstrzymane " + _NI + r" \((\d+): rabunek (\d+), oblezenie (\d+), glod (\d+)\)"),
    "chest": re.compile(r"\| skrzynia: wsi (\d+), kiesy " + _NI + r", cel skrzyni " + _NI + r", ponad skrzynia " + _NI + r", zbytki z nadwyzki " + _NI + r" \(P5 " + _NI
                        + r" - kupione " + _NI + r" / rynek BK " + _NI + r" odlozone"),
    "nomkt": re.compile(r"wsi bez rynku BK \(krok 5 caly na P5\) (\d+) - " + _NI),
    "bk": re.compile(r"ticki BK wsi DS (\d+): pulap stary na sztuke " + _NI + r", budzet nowy " + _NI + r", kupione " + _NI + r" \(w starym pulapie " + _NI + r"\)\)"),
    "bk0": re.compile(r"ticki BK wsi DS (\d+): budzet stary " + _NI + r" \+ nowy " + _NI + r", kupione " + _NI + r"\)"),   # format sprzed poprawki 17.10 (model)
    "ramp": re.compile(r"rampa ([\d.]+) \(od doby (-?\d+)\)"),
    "old": re.compile(r"stare pobory wsi DS \(oczekiwane 0 po rampie\): danina " + _NI + r" \((\d+) wsi\), podatek od nadwyzki " + _NI + r" \((\d+) wsi\), W7 " + _NI
                      + r" \((\d+) zrodel\), 15%/d nadwyzki na stara liste \(chciane\) " + _NI + r", stara drabina P5 \(chciane\) " + _NI),
    "w4": re.compile(r"\| korona: W4 do wplywu dnia \(LeviesToday\) " + _NI + r", czeka w skarbcach do nastepnego Levies " + _NI),
    "ctl": re.compile(r"\| kontrola: platnicy - odbiorcy = " + _NI),
    "stum": re.compile(r"\| potkniecia (\d+) \(w sesji (\d+)\)"),
    # recenzja 17.10 (poprawki): czynsz przepadly (rampa ksiegi / bez ksiegi), krok 5 wydany (towar, roboty gminy, niewydane), K5 przy samym F1
    "rlost": re.compile(r", przepadlo \((?:rampa ksiegi|bez ksiegi)\) " + _NI),
    "works": re.compile(r"\| krok 5 wydany: towar " + _NI + r", roboty gminy " + _NI + r" \((\d+) wsi: place ludu miast targowych " + _NI + r" \+ material do kas " + _NI
                        + r"\), niewydane " + _NI + r" \((\d+) wsi\)"),
    "k5": re.compile(r"brak zwrotu zoldu ze skarbca ponad zapas wojny \(K5, bez firm F3\) " + _NI + r" \((\d+) krolestw\)"),
    # r4-bkwies (recenzja): czesc P5, ktora zostaje w kiesie wsi, bo potrzeba pokryta (krok 5 do potrzeby, wies z koszykiem ZC4, plotno K2) - tylko gdy > 0
    "kept": re.compile(r", zostalo w kiesie \(potrzeba pokryta\) " + _NI + r" \((\d+) wsi\)"),
}


NDS_AK = "Akumulator kies (ds-akumulator): "
NDS_GRANT = re.compile(r"^(.*?) (przelaczenie|kwartal|po rampie|pokoj \d+ dob|nowa wojna \d+ dob|skarbiec do zapasu): g ([\d.]+) -> ([\d.]+)(?: \(War Tax \+krok\))?"   # f14-miary (NDS-7b)
                       r"(?:, potrzeba (-?\d+), zwykle wplywy (-?\d+), brak (-?\d+), plon nadania przy g=1 (-?\d+))?")
NDS_GROW = re.compile(r"^(.*?): g ([\d.]+)( \(pokoj\))?, firmy ")   # poprawka recenzji f14-miary (NDS-7b): wiersz krolestwa w linii "Daniny korony (DS)" - g teraz, pokoj
NDS_AKMED = re.compile(r"mediana kiesy (\d+), mediana skrzyni (\d+), mediana kiesa / skrzynia ([\d.]+|-)")
_NDS_KSPLIT = re.compile(r", (?=[^,]*? -?\d+\+-?\d+(?: |,|$))")
_NDS_KPART = re.compile(r"^(.*?) (-?\d+)\+(-?\d+)(?: |$)")


def _nds_kmeas(seg):
    """ds-akumulator: wplyw dnia na krolestwo z linii 165 ("Dorne 1218874+2205 (184 ...) zwrot ..., Riverlands ..."): {nazwa: wplyw dnia (bez 1/450)}.
    Podzial tylko na ", " przed kawalkiem z "N+M" (nazwy z przecinkiem, np. "House Targaryen, Aegon", sklejane z kawalkiem bez liczb)."""
    out = {}
    seg = seg.split(" | ")[0].rstrip(".")
    pend = ""
    for part in _NDS_KSPLIT.split(seg):
        mm = _NDS_KPART.match(part)
        if not mm:
            pend = (pend + ", " if pend else "") + part
            continue
        name = ((pend + ", ") if pend else "") + mm.group(1)
        pend = ""
        out[name.strip()] = int(mm.group(2))
    return out


def _nds_windfall(incK, times=3.0, ring=28, nmin=7, floor=1000):
    """ds-akumulator (NDS-7b / NDS-9 bez jednorazowych): na krolestwo wplyw dnia ponad times x max(mediana jego wplywu z ostatnich `ring` dob, wplyw doby
    poprzedniej) (ujemne jako 0, od nmin probek) - skok jednej doby, nie nowy poziom (wojna, trybut: od drugiej doby poprzednia doba podnosi prog); suma nadwyzek
    krolestw na dobe (zl). Ta sama regula co CrownWindfallToReserve w grze (tam na 'inne')."""
    hist, wf = {}, {}
    for d in sorted(incK):
        tot = 0
        for k, v in incK[d].items():
            h = hist.setdefault(k, [])
            if len(h) >= nmin:
                med = st.median([max(0, x) for x in h[-ring:]])
                cap = times * max(med, max(0, h[-1]))
                if v > cap and v - cap >= floor:
                    tot += v - cap
            h.append(v)
        wf[d] = tot
    return wf


def _nds_scan(path, full):
    """Jeden przebieg po logu: linie DS i linie niezalezne (stare pobory, ksiegi, korona, Bank, kiesy wsi, koszt). full=False (baza) - tylko liczby odniesienia."""
    D = {"ds": {}, "dsbad": [], "start": [], "off": [], "n_err": 0, "err1": None, "inc": {}, "refund": {}, "bankkd": {}, "kd": {}, "D": {}, "takt": {}, "bank": {}, "bil": {},
         "vil": {}, "hv": {}, "vkor": {}, "w7v": {}, "extra": {}, "titheold": {}, "tithedsrest": {}, "ut": {}, "utbez": {}, "tw1": {}, "fee": {}, "firmy": {}, "zal": {}, "korona": {},
         "incK": {}, "ksend": None, "akmed": {},   # ds-akumulator: wplyw dnia na krolestwo (jednorazowe), koniec rampy KS (NDS-3a), mediany kiesa / skrzynia (NDS-3c)
         "f6cut": {}, "f7kept": {}, "b166": {}, "bsuch": {},   # f14-miary: roznica zwrotu f6 i renty zatrzymane f7 (czynne), budzet 166 i linia na sucho (NDS-9c)
         "gcap": {}, "gk": {}, "gm": 2.0}   # f14-miary (NDS-7b): pojemnosc nadania wojennego DS tej doby - suma (g max - g) x plon przy g=1 krolestw w wojnie z linii doby;
                                            # gk - plon przy g=1 z ostatniej sesji krolestwa, gm - g max siatki
    if not path or not os.path.isfile(path):
        return D
    with open(path, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            m = TS.match(ln.rstrip("\n"))
            s = m.group(2) if m else ln.rstrip("\n")
            if s.startswith("ERROR in "):
                if any(s.startswith(e) for e in NDS_ERR):
                    D["n_err"] += 1
                    D["err1"] = D["err1"] or s[:200]
                continue
            c0 = s[:1]
            if c0 not in "DPKSUFRVAB":   # f14-miary: B - linie "Budzet rodow" (NDS-9c)
                continue
            day = num(r"dzien (\d+)", s[:90])
            if D["ksend"] is None and s.startswith("KS: rampa dzien"):
                v = num(r"koniec popytu (-?\d+)\)", s)
                if v is not None:
                    D["ksend"] = v
                continue
            if s.startswith(NDS_AK):
                if "(Ds Works Real Material) tak" in s:
                    D["akworks"] = True
                if day is not None:
                    mm = NDS_AKMED.search(s)
                    if mm:
                        D["akmed"][day] = (float(mm.group(1)), float(mm.group(2)), None if mm.group(3) == "-" else float(mm.group(3)))
                continue
            if s.startswith(NDS_HEAD):
                if "| WYLACZONE" in s:
                    D["off"].append((day, s)); continue
                if s.startswith(NDS_HEAD + "start"):
                    D["start"].append(s); continue
                if day is None:
                    continue
                r = {}
                for key, rx in NDS_RX.items():
                    mm = rx.search(s)
                    if mm:
                        r[key] = tuple(float(x) for x in mm.groups())
                if all(k in r for k in ("carts", "tithe", "crown", "sut", "rent", "chest", "ramp", "old", "w4", "ctl")):
                    D["ds"][day] = r
                else:
                    D["dsbad"].append(s[:220])
                continue
            if day is None:
                continue
            if s.startswith("Korona: wplywy dnia (165)"):
                a = num(r"wplywy dnia (-?\d+) \(nasze", s); b = num(r"zapasu ponad \d+ (-?\d+)", s)
                if a is not None:
                    D["inc"][day] = a + (b or 0)
                g = num(r"zwrot zoldu (-?\d+) \(nalezny", s); n = num(r"zwrot zoldu -?\d+ \(nalezny (-?\d+)", s)
                if g is not None and n is not None:
                    D["refund"][day] = (g, n)
                i = s.find("na krolestwo (wplywy+zapas, wydatki): ")
                if i > 0:
                    D["incK"][day] = _nds_kmeas(s[i + len("na krolestwo (wplywy+zapas, wydatki): "):])
                if i > 0:
                    seg = s[i:]
                    nk = len(re.findall(r"zwrot \d+/(\d+)", seg)); nb = len(re.findall(r"kredyt186 \+\d+", seg))
                    nk_due = sum(1 for x in re.findall(r"zwrot \d+/(\d+)", seg) if int(x) > 0)
                    D["bankkd"][day] = (nb, nk_due)
            elif s.startswith("Korona: nadanie wojenne (DS)"):
                # f14-miary (NDS-7b): nadanie wojenne (K2 - pomoc od sprzedazy, 184, dziesiata, W4) idzie za potrzeba korony; o ile wiecej mogloby zebrac przy wiekszej
                # potrzebie (pelny zwrot) - najwyzej do g max: (g max - g) x plon przy g=1, krolestwo po krolestwie. Tu tylko plon przy g=1 z ostatniej sesji krolestwa
                # (sesja pokoju - 0); poprawka recenzji: pojemnosc liczy linia doby "Daniny korony (DS)" - tylko krolestwa z wierszem tej doby (bez wyeliminowanych)
                # i bez "(pokoj)" (koniec wojny przed sesja pokoju po Ds Session Days), g z tego wiersza - nie stan z ostatniej sesji, ktory trwal do konca logu
                D["gm"] = num(r"siatka g co [\d.]+ do ([\d.]+)", s, float) or 2.0
                i = s.find(") | ")
                for seg in (s[i + 4:].rstrip(".").split(" ; ") if i > 0 else []):
                    mm = NDS_GRANT.match(seg.strip())
                    if mm:
                        D["gk"][mm.group(1)] = float(mm.group(8)) if mm.group(8) else 0.0
            elif s.startswith("Korona: zwrot wedlug potrzeby (f6)"):
                # f14-miary (decyzja Jeffa 18.10 "zwrot wedlug potrzeby"): roznica zwrotu tylko przy czynnym kluczu ("; zwrot mniejszy o"; na sucho - "bylby mniejszy")
                v = num(r"; zwrot mniejszy o (\d+)", s)
                if v is not None:
                    D["f6cut"][day] = v
            elif s.startswith("Korona: renty wedlug potrzeby (f7)"):
                # f14-miary (decyzja Jeffa 18.10 "renty wedlug potrzeby ... reszta zostaje w skarbcu krolestwa"): zatrzymane tylko przy czynnym kluczu (na sucho - "zatrzymane bylyby")
                v = num(r"; zatrzymane w skarbcach (\d+) zl/d", s)
                if v is not None:
                    D["f7kept"][day] = v
            elif s.startswith("Budzet rodow (166): dzien"):
                # f14-miary NDS-9c: zold naliczony wobec pulapu, zwolnieni, nowe partie wstrzymane (czy renty wedlug potrzeby nie gloduja wojska)
                cp = num(r"pulap zoldu razem (\d+), zold naliczony", s); wg = num(r"zold naliczony \(partie \+ zalogi \+ karawany\) (\d+)", s)
                if cp is not None and wg is not None:
                    D["b166"][day] = (wg, cp, num(r"zwolnieni: do wsi (\d+) ludzi", s) or 0, num(r"nowe partie wstrzymane (\d+)", s) or 0)
            elif s.startswith("Budzet rodow (na sucho): dzien"):
                br = num(r"ponizej rezerwy wojny R: (\d+) rodow", s); un = num(r"zalegly zold: (\d+) partii i zalog z \d+", s); pd = num(r"zalegly zold: \d+ partii i zalog z (\d+)", s)
                if br is not None or un is not None:
                    D["bsuch"][day] = (br, un, pd)
            elif s.startswith("D staly (169c)"):
                v = num(r"90% -?\d+, razem (-?\d+)", s)
                if v is not None:
                    D["D"][day] = v
            elif s.startswith("Profil doby (E8/0): dzien"):
                v = num(r"takt doby ([\d.]+) ms", s, float)
                if v is not None:
                    D["takt"][day] = v
            elif s.startswith("Kredyt korony (186)"):
                dl = num(r"dlug razem (-?\d+)", s); kp = num(r"Bank: kapital (-?\d+)", s); za = num(r"w zaleglosci (\d+)", s)
                if dl is not None:
                    D["bank"][day] = (dl, kp or 0, za or 0)
            elif s.startswith("Pieniadz swiata (bilans - przyczyny)"):
                v = num(r"\+ reszta ([-+]?\d+) \[R\]", s)
                if v is not None:
                    D["bil"][day] = v
            elif s.startswith("Pieniadz swiata: dzien"):
                v = num(r"\| razem (-?\d+)", s); kw = num(r"kiesy wsi (-?\d+)", s)
                if v is not None and kw is not None:
                    D["vil"].setdefault(day, {}).update(world=v)
            elif s.startswith("Przeplywy osad (kiesy wsi)"):
                st_ = num(r"\| stan (-?\d+)", s); md = num(r"mediana (-?\d+)", s); lo = num(r"ponizej 1000 zlota (\d+)", s); no = num(r"osad (\d+), min", s)
                kor = num(r"korona \(danina, clo, mennica\) ([-+]?\d+)", s)
                if st_ is not None:
                    D["vil"].setdefault(day, {}).update(stan=st_, med=md, lo=lo, n=no)
                if kor is not None:
                    D["vkor"][day] = kor
            elif s.startswith("Przeplywy osad (przyczyny)"):
                v = num(r"TW1=([-+]?\d+)", s)
                if v is not None:
                    D["tw1"][day] = v
            elif s.startswith("Podatek od nadwyzki wsi (obieg2)"):
                v = num(r"pobrano (\d+):", s)
                if v is not None:
                    D["hv"][day] = v
            elif s.startswith("Stawka wojenna pana (W7)"):
                v = num(r"ze wsi (\d+)\)", s)
                if v is not None:
                    D["w7v"][day] = v
            elif s.startswith("Kiesa ludu: dzien"):
                v = num(r"chciane z nadwyzka (\d+)", s)
                if v is not None:
                    D["extra"][day] = v
            elif s.startswith("Dziesiecina (E5/C3)"):
                v = num(r"= wsie (\d+)", s)
                if v is not None:
                    D["titheold"][day] = v
                    D["tithedsrest"][day] = num(r"wsie DS - utarg bez dziesieciny przy wozie (\d+)", s) or 0   # recenzja 17.10: VillageTithe bierze reszte po staremu
            elif s.startswith("Utarg wsi (112)"):
                v = num(r"oddane (\d+) =", s); b = num(r"bez odbiorcy razem \([^)]*\) (-?\d+)", s)
                if v is not None:
                    D["ut"][day] = v
                if b is not None:
                    D["utbez"][day] = b
            elif s.startswith("Prawa panskie (E5/B1)"):
                v = num(r"oplaty stale wsi (\d+)", s)
                if v is not None:
                    D["fee"][day] = v
            elif s.startswith("Firmy miast i zamkow (DS)"):
                v = num(r"\| kontrola: platnicy - odbiorcy = (-?\d+)", s)
                if v is not None:
                    D["firmy"][day] = v
            elif s.startswith("Pozyczki zaliczkowe (DS)"):
                mm = re.search(r"kontrola: dlug - \(wczoraj \+ zawarte \+ odsetki - splacone - przeniesione - przepadle\) (-?\d+|-)", s)
                if mm:
                    D["zal"][day] = None if mm.group(1) == "-" else int(mm.group(1))
            elif s.startswith("Daniny korony (DS)"):
                mm = re.search(r"\| zwrot (\d+)/(\d+) \([^)]*\), brak zwrotu pokryty: skarbiec ponad zapas (\d+), zaliczki mieszczan (\d+), Bank (\d+)", s)
                if mm:
                    D["korona"][day] = tuple(int(x) for x in mm.groups())
                if D["gk"]:   # f14-miary (NDS-7b, poprawka recenzji): pojemnosc nadania tej doby - krolestwa z wierszem, w wojnie, g teraz; przed pierwsza sesja - brak wpisu (0)
                    i = s.find("| na krolestwo: ")
                    if i > 0:
                        cap = 0.0
                        for row in s[i + len("| na krolestwo: "):].split(" ; "):
                            mr = NDS_GROW.match(row.strip())
                            if mr and not mr.group(3) and mr.group(1) in D["gk"]:
                                cap += max(0.0, D["gm"] - float(mr.group(2))) * D["gk"][mr.group(1)]
                        D["gcap"][day] = cap
    return D


def _nds_ref(B, D, key, days):
    """Liczby odniesienia: baza (--baza-doby) w tych samych dobach gry albo - bez bazy - pierwsze 7 dob DS tego biegu (rampa < 0.25). Zwraca (srednia, etykieta) albo (None, ...)."""
    if B is not None and B.get(key):
        v = [B[key][d] for d in days if d in B[key]]
        if len(v) >= max(3, len(days) // 2):
            return sum(v) / len(v), f"baza w tych samych dobach ({len(v)})"
    ds = sorted(D["ds"])
    first = [d for d in ds if D["ds"][d]["ramp"][0] < 0.25][:7]
    v = [D[key][d] for d in first if d in D[key]]
    if v:
        return sum(v) / len(v), f"pierwsze doby DS tego biegu, rampa < 0.25 ({len(v)}; bez bazy - slabe odniesienie)"
    return None, "brak odniesienia"


def _ds_f3_seen(logp):
    try:
        with open(logp, encoding='utf-8', errors='replace') as fh:
            for ln in fh:
                if 'Firmy miast i zamkow (DS)' in ln: return True
    except Exception:
        return False
    return False


# r4-koszyk (noc 17/18.10): tanszy koszyk (KsCheapBasket.cs) i place za brak rak (KsWageHands.cs) - linie dzienne gry
